    vehicleExpenseRows.value.filter((item) => item.plate === plate),
    "vehicleDetailExpenses"
  );
});

const selectedVehicleExpenseTotal = computed(() =>
  selectedVehicleExpenses.value.reduce((sum, item) => {
    if (item.currency === "港币") {
      sum.hkd += Number(item.amount || 0);
    } else {
      sum.rmb += Number(item.amount || 0);
    }
    return sum;
  }, { hkd: 0, rmb: 0 })
);

function vehicleExpenseTypeLabel(type) {
  return VEHICLE_EXPENSE_CONFIG_BY_TYPE[type]?.title || "车辆支出";
}

function vehicleExpenseAnnualStartDate(item = {}) {
  if (item.type !== "annual") return item.date || "";
  return String(item.startDate || item.start_date || item.date || (item.year ? `${item.year}-01-01` : "") || "").trim();
}

function vehicleExpenseAnnualEndDate(item = {}) {
  if (item.type !== "annual") return "";
  const explicitEndDate = String(item.endDate || item.end_date || "").trim();
  if (explicitEndDate) return explicitEndDate;
  const startDate = vehicleExpenseAnnualStartDate(item);
  if (startDate) return addInputYears(startDate, 1);
  const year = Number(item.year || String(startDate).slice(0, 4));
  return Number.isFinite(year) && year > 0 ? `${year}-12-31` : "";
}

function vehicleExpenseDateText(item = {}) {
  if (item.type !== "annual") return item.date || "-";
  const startDate = vehicleExpenseAnnualStartDate(item);
  const endDate = vehicleExpenseAnnualEndDate(item);
  if (startDate && endDate) return `${inputDateLabel(startDate)} 至 ${inputDateLabel(endDate)}`;
  return item.year ? `${item.year}年` : (startDate || endDate || "-");
}

function vehicleExpenseExpiryState(item = {}) {
  if (item.type !== "annual") return { text: "-", tone: "muted", days: null };
  const endDate = vehicleExpenseAnnualEndDate(item);
  const end = inputDateUtcValue(endDate);
  const today = inputDateUtcValue(todayInputValue());
  if (end === null || today === null) return { text: "-", tone: "muted", days: null };
  const days = Math.ceil((end - today) / 86400000);
  if (days < 0) return { text: "已到期", tone: "danger", days };
  if (days === 0) return { text: "今天到期", tone: "danger", days };
  if (days <= 30) return { text: `${days}天后到期`, tone: "warning", days };
  return { text: "正常", tone: "normal", days };
}

function vehicleExpenseExpiryText(item = {}) {
  return vehicleExpenseExpiryState(item).text;
}

function vehicleExpenseExpiryClass(item = {}) {
  return `is-${vehicleExpenseExpiryState(item).tone}`;
}

function vehicleExpenseAllocationText(item = {}) {
  if (item.type !== "annual") return "计入费用日期所在月份";
  return "按有效期分摊";
}

function roundVehicleExpenseFuelValue(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "";
  return Number(number.toFixed(1));
}

function syncVehicleExpenseFuelFields(source = vehicleExpenseFuelLastEdited.value) {
  if (vehicleExpenseForm.type !== "fuel") return;
  const liters = Number(vehicleExpenseForm.fuelLiters || 0);
  const price = Number(vehicleExpenseForm.fuelPricePerLiter || 0);
  const amount = Number(vehicleExpenseForm.amount || 0);
  const normalizedSource = ["liters", "amount", "price"].includes(source) ? source : vehicleExpenseFuelLastEdited.value;
  const hasLiters = Number.isFinite(liters) && liters > 0;
  const hasPrice = Number.isFinite(price) && price > 0;
  const hasAmount = Number.isFinite(amount) && amount > 0;

  if (normalizedSource === "price") {
    if (hasPrice && hasLiters) {
      vehicleExpenseForm.amount = roundVehicleExpenseFuelValue(liters * price);
    } else if (hasPrice && hasAmount) {
      vehicleExpenseForm.fuelLiters = roundVehicleExpenseFuelValue(amount / price);
    }
  } else if (normalizedSource === "amount") {
    if (hasAmount && hasLiters) {
      vehicleExpenseForm.fuelPricePerLiter = roundVehicleExpenseFuelValue(amount / liters);
    } else if (hasAmount && hasPrice) {
      vehicleExpenseForm.fuelLiters = roundVehicleExpenseFuelValue(amount / price);
    }
  } else if (normalizedSource === "liters") {
    if (hasLiters && hasAmount) {
      vehicleExpenseForm.fuelPricePerLiter = roundVehicleExpenseFuelValue(amount / liters);
    } else if (hasLiters && hasPrice) {
      vehicleExpenseForm.amount = roundVehicleExpenseFuelValue(liters * price);
    }
  }

  vehicleExpenseForm.fuelPricePerLiter = roundVehicleExpenseFuelValue(vehicleExpenseForm.fuelPricePerLiter);
  vehicleExpenseForm.fuelLiters = roundVehicleExpenseFuelValue(vehicleExpenseForm.fuelLiters);
  vehicleExpenseForm.amount = roundVehicleExpenseFuelValue(vehicleExpenseForm.amount);
  vehicleExpenseFuelLastEdited.value = normalizedSource;
}

function vehicleExpenseReceiptCategory() {
  return "车辆支出票据";
}

function resetVehicleExpenseReceiptState() {
  vehicleExpenseReceiptRows.value = [];
  vehicleExpenseReceiptUploading.value = false;
  clearVehicleExpenseReceiptUploadStatus();
}

async function loadVehicleExpenseReceiptFiles(expenseId = editingVehicleExpenseId.value) {
  vehicleExpenseReceiptRows.value = expenseId ? await loadFiles("vehicle_expense", String(expenseId)) : [];
}

function vehicleExpenseFormValidationMessage() {
  const type = String(vehicleExpenseForm.type || "").trim();
  if (!VEHICLE_EXPENSE_CONFIG_BY_TYPE[type]) return "请选择费用类型";
  if (!String(vehicleExpenseForm.plate || "").trim()) return "请选择车牌";
  if (type === "annual" && !String(vehicleExpenseForm.name || "").trim()) return "请选择费用类型";
  if (type === "other" && !String(vehicleExpenseForm.name || "").trim()) return "请填写支出名称";
  if (type === "fuel") {
    if (!Number(vehicleExpenseForm.fuelLiters || 0)) return "请填写加油升数";
    if (!Number(vehicleExpenseForm.fuelPricePerLiter || 0)) return "请填写每升单价";
    if (!Number(vehicleExpenseForm.odometerKm || 0)) return "请填写加油时公里数";
    if (!String(vehicleExpenseForm.fuelStation || "").trim()) return "请填写加油站";
  }
  if (type === "annual") {
    if (!parseInputDate(vehicleExpenseForm.startDate) || !parseInputDate(vehicleExpenseForm.endDate)) return "请选择正确的起止日期";
    if (String(vehicleExpenseForm.startDate || "") > String(vehicleExpenseForm.endDate || "")) return "开始日期不能晚于到期日期";
  }
  if (type !== "annual" && !/^\d{4}-\d{2}-\d{2}$/.test(String(vehicleExpenseForm.date || ""))) {
    return "请填写正确的费用日期";
  }
  const amount = Number(vehicleExpenseForm.amount);
  if (!Number.isFinite(amount) || amount <= 0) return "请填写大于 0 的费用金额";
  return "";
}

async function persistVehicleExpenseFromModal(options = {}) {
  if (vehicleExpenseForm.type === "fuel") {
    syncVehicleExpenseFuelFields(vehicleExpenseFuelLastEdited.value);
  }
  const validationMessage = vehicleExpenseFormValidationMessage();
  if (validationMessage) {
    options.form?.reportValidity?.();
    setVehicleExpenseReceiptUploadStatus(validationMessage, "error");
    notify(validationMessage);
    return null;
  }
  const currentExpenseId = editingVehicleExpenseId.value;
  if (options.statusMessage) {
    setVehicleExpenseReceiptUploadStatus(options.statusMessage, "busy");
  }
  vehicleExpenseSaving.value = true;
  try {
    const item = await vehiclesApi.saveVehicleExpense(currentExpenseId, vehicleExpenseForm);
    const rowExists = vehicleExpenseRows.value.some((row) => row.id === item.id);
    vehicleExpenseRows.value = currentExpenseId || rowExists
      ? vehicleExpenseRows.value.map((row) => row.id === item.id ? item : row)
      : [item, ...vehicleExpenseRows.value];
    selectedVehiclePlate.value = item.plate || selectedVehiclePlate.value;
    editingVehicleExpenseId.value = item.id;
    return item;
  } finally {
    vehicleExpenseSaving.value = false;
  }
}

async function ensureVehicleExpenseForReceiptUpload(form) {
  if (editingVehicleExpenseId.value) return editingVehicleExpenseId.value;
  const item = await persistVehicleExpenseFromModal({
    form,
    statusMessage: "正在保存费用记录，用于上传票据"
  });
  if (!item?.id) return "";
  setVehicleExpenseReceiptUploadStatus("费用已保存，开始上传票据", "success");
  notify(`已创建${vehicleExpenseTypeLabel(item.type)}，开始上传票据`);
  return item.id;
}

async function uploadVehicleExpenseReceiptFiles(expenseId, files = []) {
  if (!files.length) return { success: 0, failed: 0 };
  if (!expenseId) {
    setVehicleExpenseReceiptUploadStatus("请先保存费用，再上传票据", "error");
    return { success: 0, failed: files.length };
  }
  if (vehicleExpenseReceiptUploading.value) {
    notify("票据正在上传，请稍候");
    return { success: 0, failed: files.length };
  }

  const validFiles = [];
  let failed = 0;
  files.forEach((file) => {
    const validationMessage = uploadFileValidationMessage(file);
    if (validationMessage) {
      failed += 1;
      notify(`${file.name}：${validationMessage}`);
    } else {
      validFiles.push(file);
    }
  });
  if (!validFiles.length) {
    setVehicleExpenseReceiptUploadStatus("未上传，所选文件仅支持图片、PDF 或 Excel，且不能超过 8MB", "error");
    scheduleClearVehicleExpenseReceiptUploadStatus(7000);
    return { success: 0, failed };
  }

  vehicleExpenseReceiptUploading.value = true;
  let success = 0;

  try {
    for (const [index, file] of validFiles.entries()) {
      setVehicleExpenseReceiptUploadStatus(`正在上传票据 ${index + 1}/${validFiles.length}：${file.name}`, "busy");
      const uploaded = await uploadStoredFileFor(
        "vehicle_expense",
        String(expenseId),
        vehicleExpenseReceiptCategory(),
        file,
        vehicleExpenseReceiptRows,
        {
          missingEntityMessage: "请先保存费用，再上传票据",
          onStatus(message, tone) {
            setVehicleExpenseReceiptUploadStatus(message, tone);
          }
        }
      );
      if (uploaded) {
        success += 1;
      } else {
        failed += 1;
      }
    }
  } finally {
    vehicleExpenseReceiptUploading.value = false;
  }

  const tone = failed ? "error" : "success";
  const message = failed
    ? `已上传 ${success} 张，${failed} 张失败`
    : `已上传 ${success} 张票据`;
  setVehicleExpenseReceiptUploadStatus(message, tone);
  scheduleClearVehicleExpenseReceiptUploadStatus(failed ? 7000 : 4200);
  return { success, failed };
}

async function handleVehicleExpenseReceiptFiles(event) {
  const files = Array.from(event.target.files || []);
  event.target.value = "";
  if (!files.length) return;
  if (vehicleExpenseSaving.value || vehicleExpenseReceiptUploading.value) {
    notify("票据正在上传，请稍候");
    return;
  }
  try {
    const expenseId = await ensureVehicleExpenseForReceiptUpload(event.target.form);
    if (!expenseId) return;
    await uploadVehicleExpenseReceiptFiles(expenseId, files);
  } catch (error) {
    setVehicleExpenseReceiptUploadStatus(`票据上传失败：${error.message}`, "error");
    notify(error.message);
  }
}

function openVehicleExpenseReceiptUploadPanel(event) {
  if (vehicleExpenseSaving.value || vehicleExpenseReceiptUploading.value) {
    notify("票据正在上传，请稍候");
    return;
  }
  if (vehicleRows.value.length === 0) {
    notify("请先新增车辆，再上传票据");
    return;
  }
  const form = event?.currentTarget?.form || null;
  openUploadPanel({
    title: "上传车辆支出票据",
    description: "可一次上传多张票据，支持拖拽、选择文件和粘贴微信复制的图片。",
    accept: FILE_UPLOAD_ACCEPT,
    multiple: true,
    handler: async (files) => {
      try {
        const expenseId = await ensureVehicleExpenseForReceiptUpload(form);
        if (!expenseId) return false;
        const result = await uploadVehicleExpenseReceiptFiles(expenseId, files);
        return result.failed === 0;
      } catch (error) {
        setVehicleExpenseReceiptUploadStatus(`票据上传失败：${error.message}`, "error");
        notify(error.message);
        return false;
      }
    }
  });
}

function closeVehicleExpenseModal() {
  if (vehicleExpenseSaving.value || vehicleExpenseReceiptUploading.value) {
    notify("费用或票据正在保存，请稍候");
    return;
  }
  vehicleExpenseModalOpen.value = false;
  resetVehicleExpenseReceiptState();
}

const selectedVehicleOrders = computed(() => {
  if (!selectedVehicle.value) return [];
  return sortRowsByTable(orderRows.value.filter((item) =>
    item.plate === selectedVehicle.value.plate
    && isRelatedOrderDateMatch(item.date, vehicleRelatedOrderDateFilter.value)
  ), "relatedVehicleOrders");
});

const selectedDriverOrders = computed(() => {
  if (!selectedDriver.value) return [];
  return sortRowsByTable(orderRows.value.filter(
    (item) =>
      orderMatchesDriverForWage(item, selectedDriver.value)
      && isRelatedOrderDateMatch(item.date, driverRelatedOrderDateFilter.value)
  ), "relatedDriverOrders");
});

const selectedDriverMonthOrders = computed(() => {
  if (!selectedDriver.value) return [];
  return orderRows.value.filter(
    (item) =>
      orderMatchesDriverForWage(item, selectedDriver.value)
      && isRelatedOrderDateMatch(item.date, "month")
  );
});

const dispatchWorkDateOrders = computed(() =>
  orderRows.value.filter((order) =>
    order.date === dispatchDate.value
    && !order.deletedAt
    && orderHasTransportFieldsForOrder(order)
  )
);

function dispatchRowLiveOrder(row = {}) {
  const orderNo = String(row?.orderNo || "").trim();
  const dispatchNo = String(row?.dispatchNo || "").trim();
  return (orderNo ? orderRowsByNo.value.get(orderNo) : null)
    || (dispatchNo ? orderRowsByDispatchNo.value.get(dispatchNo) : null)
    || null;
}

function dispatchRowHasMissingOrder(row = {}) {
  return Boolean(String(row?.orderNo || "").trim() && !dispatchRowLiveOrder(row));
}

const dispatchPlannedOrderNos = computed(() =>
  new Set(dispatchPlanRows.value.map((row) => dispatchRowLiveOrder(row)?.no).filter(Boolean))
);

const dispatchPlanRowsByOrderNo = computed(() => {
  const map = new Map();
  dispatchPlanRows.value.forEach((row) => {
    const orderNo = String(row?.orderNo || "").trim() || dispatchRowLiveOrder(row)?.no || "";
    if (orderNo && !map.has(orderNo)) map.set(orderNo, row);
  });
  return map;
});

const dispatchUnplannedOrders = computed(() =>
  dispatchWorkDateOrders.value.filter((order) => !dispatchPlannedOrderNos.value.has(order.no))
);

const dispatchPlanDisplayRows = computed(() =>
  dispatchPlanRows.value
    .map((row, index) => {
      const order = dispatchRowLiveOrder(row);
      const hkDriverName = String(row.hkDriver || row.driver || "").trim();
      const mainlandDriverName = String(row.mainlandDriver || "").trim();
      return {
        ...row,
        createdByName: row.createdByName || row.createdByUsername || "",
        index,
        orderMissing: Boolean(row.orderNo && !order),
        order: order || {
          no: "",
          customer: row.customer || "",
          businessType: row.businessType || "",
          date: row.date || dispatchDate.value,
          port: row.port || "",
          direction: row.direction || "",
          needsWeighing: booleanFlag(row.needsWeighing, false),
          tonnage: row.tonnage || "",
          quantity: row.quantity || "",
	          weight: row.weight || "",
	          loading: row.loading || "",
	          loadingLocations: row.loadingLocations || [],
	          unloading: row.unloading || "",
	          unloadingLocations: row.unloadingLocations || [],
          vehicleSource: row.vehicleSource || "",
          supplier: row.supplier || ""
        },
        vehicle: vehicleRowsByPlate.value.get(String(row.plate || "").trim()) || null,
        hkDriverRow: hkDriverName ? driverRowsByName.value.get(hkDriverName) || null : null,
        mainlandDriverRow: mainlandDriverName ? driverRowsByName.value.get(mainlandDriverName) || null : null
      };
    })
    .sort(compareDispatchPlanRowsForAutoSort)
    .map((row, displayIndex) => ({ ...row, displayIndex }))
);

const dispatchCustomerFilterOptions = computed(() =>
  dispatchFilterOptionValues(dispatchPlanDisplayRows.value, dispatchCustomerFilterValues)
    .filter((customer) => customerNameMatchesCategory(customer, "运输客户"))
);

const dispatchPlateFilterOptions = computed(() =>
