);

const dispatchDriverFilterOptions = computed(() =>
  dispatchFilterOptionValues(dispatchPlanDisplayRows.value, dispatchDriverFilterValues)
);

const dispatchBusinessTypeFilterOptions = computed(() =>
  dispatchFilterOptionValues(dispatchPlanDisplayRows.value, dispatchBusinessTypeFilterValues)
);

const dispatchFilteredPlanRows = computed(() =>
  filterDispatchSearchRows(dispatchPlanDisplayRows.value)
);

const dispatchStatusPoolItems = computed(() =>
  [
    ...DISPATCH_STATUS_OPTIONS.map((status) => ({
      status,
      count: dispatchFilteredPlanRows.value.filter((row) => (row.status || DISPATCH_PLAN_DEFAULT_STATUS) === status).length
    })),
    {
      status: DISPATCH_STATUS_ALL,
      count: dispatchFilteredPlanRows.value.length
    }
  ]
);

const selectedDispatchPlanRows = computed(() => {
  return dispatchPlanDisplayRows.value.filter((row) => selectedDispatchPlanIdSet.value.has(String(row.id)));
});

const dispatchStatusPoolRows = computed(() => {
  if (activeDispatchStatusPool.value === DISPATCH_STATUS_ALL) return dispatchFilteredPlanRows.value;
  return dispatchFilteredPlanRows.value.filter((row) => (row.status || DISPATCH_PLAN_DEFAULT_STATUS) === activeDispatchStatusPool.value);
});

const allDispatchPlanRowsSelected = computed(() =>
  searchedDispatchPlanRows.value.length > 0 &&
  searchedDispatchPlanRows.value.every((row) => selectedDispatchPlanIdSet.value.has(String(row.id)))
);

const dispatchListDetailRows = computed(() =>
  selectedDispatchPlanRows.value.length ? selectedDispatchPlanRows.value : searchedDispatchPlanRows.value
);

const dispatchPlanWarnings = computed(() => {
  const warnings = [];
  const plateCounts = new Map();
  const driverCounts = new Map();
  dispatchPlanDisplayRows.value.forEach((row) => {
    if (row.plate) plateCounts.set(row.plate, (plateCounts.get(row.plate) || 0) + 1);
    [row.driver, row.hkDriver, row.mainlandDriver].filter(Boolean).forEach((name) => {
      driverCounts.set(name, (driverCounts.get(name) || 0) + 1);
    });
  });
  plateCounts.forEach((count, plate) => {
    if (count > 1) warnings.push(`车牌 ${plate} 在当天安排了 ${count} 次`);
  });
  driverCounts.forEach((count, name) => {
    if (count > 1) warnings.push(`司机 ${name} 在当天安排了 ${count} 次`);
  });
  dispatchPlanDisplayRows.value.forEach((row) => {
    if (dispatchRowHasMissingOrder(row)) {
      warnings.push(`${row.dispatchNo || "未编号排车单"} 关联订单 ${row.orderNo} 不存在或已删除`);
    }
    if (row.vehicle && row.vehicle.status !== "正常") warnings.push(`${row.plate} 车辆状态：${row.vehicle.status}`);
    if (row.vehicle?.mainlandInsuranceDate && parseInputDate(row.vehicle.mainlandInsuranceDate) < parseInputDate(dispatchDate.value)) warnings.push(`${row.plate} 大陆保险已过期`);
    if (row.vehicle?.hkInsuranceDate && parseInputDate(row.vehicle.hkInsuranceDate) < parseInputDate(dispatchDate.value)) warnings.push(`${row.plate} 香港保险已过期`);
    [row.hkDriverRow, row.mainlandDriverRow].filter(Boolean).forEach((driver) => {
      if (driver.status !== "正常") warnings.push(`${driver.name} 司机状态：${driver.status}`);
      if (driver.expireAt && parseInputDate(driver.expireAt) < parseInputDate(dispatchDate.value)) warnings.push(`${driver.name} 证件已过期`);
    });
  });
  return warnings;
});

function normalizeDispatchPlanStatus(status, row = {}) {
  if (status === "待预排" || status === "已预排") return DISPATCH_PLAN_DEFAULT_STATUS;
  if (status === "完成结算") return "已签收";
  return DISPATCH_STATUS_OPTIONS.includes(status) ? status : DISPATCH_PLAN_DEFAULT_STATUS;
}

function normalizeOptionalDispatchPlanStatus(status) {
  const text = String(status || "").trim();
  if (!text) return "";
  if (text === "待预排" || text === "已预排") return DISPATCH_PLAN_DEFAULT_STATUS;
  if (text === "完成结算") return "已签收";
  return DISPATCH_STATUS_OPTIONS.includes(text) ? text : "";
}

function normalizeDispatchPlanRows(rows = [], date = dispatchDate.value) {
  const normalizedRows = [];
  rows.forEach((row) => {
    const status = normalizeDispatchPlanStatus(row.status, row);
    const previousStatus = normalizeOptionalDispatchPlanStatus(row.previousStatus);
    const createdAt = dispatchRowCreatedAt(row) || timestampInputValueFromRowId(row) || normalizeTimestampInputValue(date);
    const loadingLocations = normalizeStructuredDispatchLocationEntries("loading", row.loadingLocations, row.loading, { includeBlank: false });
    const unloadingLocations = normalizeStructuredDispatchLocationEntries("unloading", row.unloadingLocations, row.unloading, { includeBlank: false });
    normalizedRows.push({
      ...row,
      date: row.date || date,
      createdAt,
      dispatchNo: row.dispatchNo || generateDispatchNo(date, normalizedRows),
      driver: row.driver || "",
      loading: composeDispatchLocationEntriesText(loadingLocations) || row.loading || "",
      loadingLocations,
      unloading: composeDispatchLocationEntriesText(unloadingLocations) || row.unloading || "",
      unloadingLocations,
      loadTime: row.loadTime || "",
      status,
      previousStatus: previousStatus && previousStatus !== status ? previousStatus : ""
    });
  });
  return normalizedRows;
}

function cloneDispatchPlanRows(rows = []) {
  return JSON.parse(JSON.stringify(Array.isArray(rows) ? rows : []));
}

function setDispatchPlanBaseRows(date, rows = [], updatedAt = "") {
  if (!date) return;
  dispatchPlanBaseRowsByDate[date] = cloneDispatchPlanRows(rows);
  dispatchPlanUpdatedAtByDate[date] = updatedAt || "";
}

function updateDispatchPlanBaseFromRecord(record = {}, fallbackDate = dispatchDate.value) {
  const date = record.date || fallbackDate;
  const rows = normalizeDispatchPlanRows(Array.isArray(record.rows) ? record.rows : [], date);
  setDispatchPlanBaseRows(date, rows, record.updatedAt || "");
  return rows;
}

function dispatchRowRef(row = {}) {
  return {
    id: String(row.id || "").trim(),
    dispatchNo: String(row.dispatchNo || "").trim(),
    orderNo: String(row.orderNo || "").trim()
  };
}

function applyDispatchPlanRows(rows = [], date = dispatchDate.value, loadedDates = [date]) {
  const normalizedRows = normalizeDispatchPlanRows(rows, date);
  closeDispatchDriverPicker();
  dispatchPlanRows.value = normalizedRows;
  dispatchLoadedDates.value = loadedDates.length ? loadedDates : [date];
  selectedDispatchPlanIds.value = selectedDispatchPlanIds.value.filter((id) =>
    normalizedRows.some((row) => row.id === id)
  );
}

async function persistDispatchPlanRows(date = dispatchDate.value, rows = dispatchPlanRows.value) {
  const result = await dispatchApi.saveDispatchPlan(date, rows, {
    baseRows: dispatchPlanBaseRowsByDate[date] || [],
    updatedAt: dispatchPlanUpdatedAtByDate[date] || ""
  });
  updateDispatchPlanBaseFromRecord(result, date);
  return result;
}

async function readDispatchPlanRowsForDate(date = dispatchDate.value) {
  const result = await dispatchApi.getDispatchPlan(date);
  return updateDispatchPlanBaseFromRecord(result, date);
}

async function appendDispatchPlanRowsToDate(date, rowsToAppend = []) {
  const rows = await readDispatchPlanRowsForDate(date);
  const nextRows = normalizeDispatchPlanRows([...rows, ...rowsToAppend], date);
  await persistDispatchPlanRows(date, nextRows);
  return nextRows;
}

function dispatchRowText(row = {}, key = "") {
  return String(row?.[key] ?? "").trim();
}

function applyDispatchRowsToLocalOrders(rows = dispatchPlanRows.value) {
  if (!Array.isArray(rows) || !rows.length || !orderRows.value.length) return;
  const patches = new Map();
  rows.forEach((row) => {
    const orderNo = dispatchRowText(row, "orderNo");
    if (!orderNo) return;
    const currentOrder = patches.get(orderNo) || orderRows.value.find((order) => order.no === orderNo);
    if (!currentOrder) return;
    const transportMode = normalizeTransportMode(row.transportMode || currentOrder.transportMode || "") || currentOrder.transportMode || "";
    const isSingleDriver = transportMode === "单司机";
    const rowDriver = dispatchRowText(row, "driver");
    const rowHkDriver = dispatchRowText(row, "hkDriver");
    const rowMainlandDriver = dispatchRowText(row, "mainlandDriver");
    const isOutsourced = normalizeVehicleSource(row.vehicleSource || currentOrder.vehicleSource || "") === "外派车辆";
    patches.set(orderNo, {
      ...currentOrder,
      dispatchNo: dispatchRowText(row, "dispatchNo") || currentOrder.dispatchNo || "",
      vehicleSource: dispatchRowText(row, "vehicleSource") || currentOrder.vehicleSource || "",
      supplier: dispatchRowText(row, "vehicleSource") === "外派车辆" ? dispatchRowText(row, "supplier") : "",
      plate: dispatchRowText(row, "plate"),
      transportMode,
      driver: isOutsourced
        ? (rowDriver || currentOrder.driver || "")
        : (isSingleDriver
          ? (rowDriver || rowHkDriver || currentOrder.driver || "")
          : [rowHkDriver || rowDriver, rowMainlandDriver].filter(Boolean).join(" / ")),
	      hkDriver: isOutsourced ? "" : (isSingleDriver ? "" : (rowHkDriver || rowDriver)),
	      mainlandDriver: isOutsourced ? "" : (isSingleDriver ? "" : rowMainlandDriver),
	      loading: row.loading || currentOrder.loading || "",
	      loadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(row, "loading", currentOrder)),
	      unloading: row.unloading || currentOrder.unloading || "",
	      unloadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(row, "unloading", currentOrder)),
	      date: dispatchPlanDate(row),
      dispatchLoadDate: dispatchPlanDate(row),
      dispatchLoadTime: row.loadTime || currentOrder.dispatchLoadTime || ""
    });
  });
  if (!patches.size) return;
  orderRows.value = orderRows.value.map((order) => patches.get(order.no) || order);
}

async function loadDispatchPlan(date = dispatchDate.value) {
  if (!loggedIn.value || !canAccessModule("dispatchBoard")) {
    applyDispatchPlanRows([], date, [date]);
    return;
  }
  try {
    const result = await dispatchApi.getDispatchPlan(date);
    const rows = updateDispatchPlanBaseFromRecord(result, date);
    applyDispatchPlanRows(rows, date, [date]);
  } catch (error) {
    if (dispatchPlanRows.value.length === 0) selectedDispatchPlanIds.value = [];
    notify(error.message || "读取排车计划失败，请检查网络或服务器");
  }
}

async function loadDispatchPlansForCurrentFilter() {
  const activePeriodFilter = periodFilterValue("dispatchRange");
  const usePeriodRange = dispatchDateFilterMode.value === DATE_FILTER_MODE_PERIOD;
  const period = usePeriodRange
    ? (activePeriodFilter === "all" ? "all" : "custom")
    : normalizeDispatchDateFilterKey(dispatchPeriodFilter.value);
  const { start, end } = usePeriodRange
    ? periodFilterBounds(activePeriodFilter)
    : dispatchPeriodBounds(period);
  dispatchDate.value = usePeriodRange
    ? periodFilterDateValue(activePeriodFilter)
    : dispatchDateFilterDateValue(period);
  if (!loggedIn.value || !canAccessModule("dispatchBoard")) {
    applyDispatchPlanRows([], dispatchDate.value, start && end ? datesBetweenInputValues(start, end) : []);
    return;
  }
  try {
    const rowsByDate = await apiFetchListFrom(
      () => dispatchApi.listDispatchPlans({ period, start, end }),
      "排车计划"
    );
    rowsByDate.forEach((record) => updateDispatchPlanBaseFromRecord(record, record.date));
    const rows = rowsByDate.flatMap(({ date, rows }) =>
      normalizeDispatchPlanRows(rows, date)
    );
    const loadedDates = rowsByDate.map((item) => item.date).filter(Boolean);
    applyDispatchPlanRows(rows, dispatchDate.value, loadedDates);
  } catch (error) {
    notify(error.message || "读取排车计划失败");
  }
}

function dispatchPlanRowOrder(row = {}) {
  return dispatchRowLiveOrder(row) || row.order || {};
}

function dispatchPlanVehicleSource(row = {}) {
  const order = dispatchPlanRowOrder(row);
  return row.vehicleSource || order.vehicleSource || "";
}

function dispatchPlanSupplierGroup(row = {}) {
  const order = dispatchPlanRowOrder(row);
  return String(row.supplier || order.supplier || "未指定供应商").trim();
}

function dispatchPlanPlateGroup(row = {}) {
  const order = dispatchPlanRowOrder(row);
  return String(row.plate || order.plate || "未定车牌").trim();
}

function dispatchPlanTimeRank(value) {
  const text = String(value || "").trim();
  const match = text.match(/^(\d{1,2}):(\d{2})$/);
  if (!match) return 24 * 60 + 1;
  return Number(match[1]) * 60 + Number(match[2]);
}

function normalizeDispatchLoadTime(value) {
  const text = String(value || "").trim();
  const match = text.match(/^(\d{1,2}):(\d{2})$/);
  if (!match) return "";
  const hour = Math.min(23, Math.max(0, Number(match[1])));
  const minute = Math.min(59, Math.max(0, Number(match[2])));
  const total = Math.min(23 * 60 + 45, Math.round((hour * 60 + minute) / 15) * 15);
  const nextHour = Math.floor(total / 60);
  const nextMinute = total % 60;
  return `${String(nextHour).padStart(2, "0")}:${String(nextMinute).padStart(2, "0")}`;
}

function dispatchLoadTimePart(value = "", part = "hour") {
  const normalized = normalizeDispatchLoadTime(value);
  if (!normalized) return "";
  const [hour, minute] = normalized.split(":");
  return part === "minute" ? minute : hour;
}

function syncDispatchLoadHourDraft() {
  dispatchLoadHourDraft.value = dispatchLoadTimePart(dispatchForm.loadTime, "hour");
}

function setDispatchFormLoadHourInput(value = "") {
  const digits = String(value || "").replace(/\D/g, "").slice(0, 2);
  dispatchLoadHourDraft.value = digits;
  const currentMinute = dispatchLoadTimePart(dispatchForm.loadTime, "minute") || "00";
  if (!digits) {
    dispatchForm.loadTime = "";
    return;
  }
  dispatchForm.loadTime = `${digits}:${currentMinute}`;
}

function commitDispatchFormLoadHourInput() {
  const digits = String(dispatchLoadHourDraft.value || "").replace(/\D/g, "").slice(0, 2);
  if (!digits) {
    dispatchForm.loadTime = "";
    dispatchLoadHourDraft.value = "";
    return;
  }
  const hour = Math.min(23, Math.max(0, Number(digits)));
  const minute = dispatchLoadTimePart(dispatchForm.loadTime, "minute") || "00";
  dispatchForm.loadTime = normalizeDispatchLoadTime(`${hour}:${minute}`);
  syncDispatchLoadHourDraft();
}

function setDispatchFormLoadTimePart(part = "hour", value = "") {
  const currentHour = dispatchLoadTimePart(dispatchForm.loadTime, "hour");
  const currentMinute = dispatchLoadTimePart(dispatchForm.loadTime, "minute") || "00";
  if (part === "hour") {
    dispatchForm.loadTime = value ? normalizeDispatchLoadTime(`${value}:${currentMinute}`) : "";
    syncDispatchLoadHourDraft();
    return;
  }
  const draftHour = String(dispatchLoadHourDraft.value || currentHour || "").replace(/\D/g, "").slice(0, 2);
  if (!draftHour) return;
  dispatchForm.loadTime = normalizeDispatchLoadTime(`${draftHour}:${value || "00"}`);
  syncDispatchLoadHourDraft();
}

function setDispatchRowLoadTimePart(row, part = "hour", value = "") {
  const target = findDispatchPlanRowTarget(row);
  if (!target) return;
  const currentHour = dispatchLoadTimePart(target.loadTime, "hour");
  const currentMinute = dispatchLoadTimePart(target.loadTime, "minute") || "00";
  if (part === "hour") {
    const digits = String(value || "").replace(/\D/g, "").slice(0, 2);
    target.loadTime = digits ? `${digits}:${currentMinute}` : "";
  } else if (currentHour) {
    target.loadTime = normalizeDispatchLoadTime(`${currentHour}:${value || "00"}`);
  }
  queueDispatchPlanAutoSave();
}

function commitDispatchRowLoadHourInput(row) {
  const target = findDispatchPlanRowTarget(row);
  if (!target) return;
  target.loadTime = normalizeDispatchLoadTime(target.loadTime);
  queueDispatchPlanAutoSave();
}

function handleDispatchRowLoadTimeChange(row) {
  const target = findDispatchPlanRowTarget(row);
  if (!target) return;
  target.loadTime = normalizeDispatchLoadTime(target.loadTime);
  queueDispatchPlanAutoSave();
}

function handleDispatchPlateInput(row) {
  const target = dispatchPlanRows.value[row.index];
  if (!target) return;
  target.status = normalizeDispatchPlanStatus(target.status, target);
  saveDispatchPlan({ silent: true });
}

function handleDispatchFormLoadTimeChange() {
  dispatchForm.loadTime = normalizeDispatchLoadTime(dispatchForm.loadTime);
  syncDispatchLoadHourDraft();
}

function dispatchPlanSourceRank(row = {}) {
  const source = dispatchPlanVehicleSource(row);
  if (source === "汉业物流") return 0;
  if (source === "外派车辆") return 1;
  return 2;
}

function dispatchPlanGroupKey(row = {}) {
  return dispatchPlanSourceRank(row) === 1
    ? dispatchPlanSupplierGroup(row)
    : dispatchPlanPlateGroup(row);
}

function compareDispatchPlanRowsForAutoSort(left = {}, right = {}) {
  const leftGroup = dispatchPlanGroupKey(left);
  const rightGroup = dispatchPlanGroupKey(right);
  if (!leftGroup && rightGroup) return 1;
  if (!rightGroup && leftGroup) return -1;
  const groupCompare = leftGroup.localeCompare(rightGroup, "zh-Hans-CN", { numeric: true, sensitivity: "base" });
  if (groupCompare !== 0) return groupCompare;

  const dateCompare = compareSortValues(dispatchPlanDate(left), dispatchPlanDate(right));
  if (dateCompare !== 0) return dateCompare;

  const timeCompare = dispatchPlanTimeRank(left.loadTime) - dispatchPlanTimeRank(right.loadTime);
  if (timeCompare !== 0) return timeCompare;

  const noCompare = String(left.dispatchNo || "").localeCompare(String(right.dispatchNo || ""), "zh-Hans-CN", { numeric: true });
  if (noCompare !== 0) return noCompare;
  return (left.index ?? 0) - (right.index ?? 0);
}

function sortDispatchPlanRowsForDisplay() {
  dispatchPlanRows.value = [...dispatchPlanRows.value]
    .map((row, index) => ({ ...row, index }))
    .sort(compareDispatchPlanRowsForAutoSort)
    .map(({ index, ...row }) => row);
}

function dispatchPlanDate(row = {}) {
  return row.date || dispatchDate.value;
}

function dispatchRowCreatedAt(row = {}) {
  return normalizeTimestampInputValue(row.createdAt || row.created_at) || timestampInputValueFromRowId(row);
}

function dispatchRowCreatedDate(row = {}, fallbackDate = "") {
  const createdAt = dispatchRowCreatedAt(row);
  if (createdAt) return createdAt.slice(0, 10);
  const fallback = String(fallbackDate || row.date || dispatchDate.value || "").trim();
  return fallback.slice(0, 10);
}

function findDispatchPlanRowTarget(row = {}) {
  const refId = String(row?.id || "").trim();
  const refDispatchNo = String(row?.dispatchNo || "").trim();
  const refOrderNo = String(row?.orderNo || "").trim();
  return dispatchPlanRows.value.find((item) => {
    if (!item) return false;
    if (refId && String(item.id || "").trim() === refId) return true;
    if (refDispatchNo && String(item.dispatchNo || "").trim() === refDispatchNo) return true;
    if (refOrderNo && String(item.orderNo || "").trim() === refOrderNo) return true;
    return false;
  }) || dispatchPlanRows.value[row?.index];
}

function createDispatchPlanSaveSnapshot() {
  return {
    date: dispatchDate.value,
    loadedDates: [...(dispatchLoadedDates.value || [])],
    rows: cloneDispatchPlanRows(dispatchPlanRows.value)
  };
}

async function runDispatchPlanSave(options = {}, snapshot = createDispatchPlanSaveSnapshot()) {
  const {
    silent = false,
    throwOnError = false,
    retryOnConflict = true
  } = options || {};
  if (!canAccessModule("dispatchBoard")) {
    if (!silent) notify("当前账号无权保存排车计划");
    return false;
  }
  const snapshotRows = normalizeDispatchPlanRows(snapshot.rows || [], snapshot.date || dispatchDate.value)
    .sort(compareDispatchPlanRowsForAutoSort);
  localStorage.setItem("hanye_dispatch_date", snapshot.date || dispatchDate.value);
  const dates = new Set([...(snapshot.loadedDates || []), ...snapshotRows.map(dispatchPlanDate)]);
  const saveJobs = Array.from(dates).map((date) => {
    const rows = snapshotRows.filter((row) => dispatchPlanDate(row) === date);
    return persistDispatchPlanRows(date, rows);
  });
  try {
    await Promise.all(saveJobs);
    await syncDispatchNosToOrders(snapshotRows);
    applyDispatchRowsToLocalOrders(snapshotRows);
    if (!silent) notify("排车计划已保存");
    return true;
  } catch (error) {
    if (error?.status === 409) {
      const latest = error.payload?.latest;
      const conflictMessage = "排车计划刚刚有更新，我已帮你对齐到最新版本，请再保存一次";
      if (latest) {
        updateDispatchPlanBaseFromRecord(latest, latest.date || dispatchDate.value);
      }
      if (latest && retryOnConflict) {
        return runDispatchPlanSave({ ...options, retryOnConflict: false }, snapshot);
      }
      if (throwOnError) {
        const conflictError = new Error(conflictMessage);
        conflictError.status = 409;
        conflictError.payload = error.payload || {};
        throw conflictError;
      }
      notify(conflictMessage);
      return false;
    } else if (!silent) {
      notify(error.message || "排车计划保存到服务器失败");
    }
    if (throwOnError) throw error;
    return false;
  }
}

function saveDispatchPlan(options = {}) {
  const snapshot = createDispatchPlanSaveSnapshot();
  dispatchPlanSavePromise = dispatchPlanSavePromise
    .catch(() => {})
    .then(() => runDispatchPlanSave(options, snapshot));
  return dispatchPlanSavePromise;
}

function queueDispatchPlanAutoSave() {
  dispatchPlanAutoSavePromise = dispatchPlanAutoSavePromise
    .catch(() => {})
    .then(() => saveDispatchPlan({ silent: true }))
    .catch(() => false);
  return dispatchPlanAutoSavePromise;
}

function dispatchStatusOptionsForRow(row) {
  const currentStatus = dispatchStatusValueForRow(row);
  if (currentStatus === "预排") {
    return ["已派车"];
  }
  if (currentStatus === "已派车") {
    return ["通关中"];
  }
  if (currentStatus === DISPATCH_LOCKED_STATUS) {
    return [DISPATCH_LOCKED_STATUS];
  }
  if (currentStatus === "已签收") {
    return ["已签收"];
  }
  if (currentStatus === "异常滞留") {
    return ["已签收"];
  }
  return DISPATCH_STATUS_OPTIONS;
}

function isDispatchStatusSelectDisabled(row) {
  return [DISPATCH_LOCKED_STATUS, "已签收", "异常滞留"].includes(dispatchStatusValueForRow(row));
}

const DISPATCH_STATUS_FALLBACK_PREVIOUS = {
  已派车: "预排",
  通关中: "已派车",
  已签收: "通关中",
  异常滞留: "通关中"
};

function dispatchReturnStatusForRow(row = {}) {
  const currentStatus = dispatchStatusValueForRow(row);
  if (currentStatus === DISPATCH_PLAN_DEFAULT_STATUS) return "";
  const previousStatus = normalizeOptionalDispatchPlanStatus(row.previousStatus);
  if (previousStatus && previousStatus !== currentStatus) return previousStatus;
  return DISPATCH_STATUS_FALLBACK_PREVIOUS[currentStatus] || "";
}

function canReturnDispatchStatus(row = {}) {
  if ([DISPATCH_LOCKED_STATUS, "已签收", "异常滞留"].includes(dispatchStatusValueForRow(row))) return false;
  return Boolean(dispatchReturnStatusForRow(row));
}

function dispatchStatusReturnButtonTitle(row = {}) {
  const previousStatus = dispatchReturnStatusForRow(row);
  return previousStatus ? `返回到${previousStatus}` : "预排没有上一步状态";
}

function dispatchStatusValueForRow(row) {
  return normalizeDispatchPlanStatus(row?.status || DISPATCH_PLAN_DEFAULT_STATUS);
}

function dispatchStatusClass(status) {
  if (status === DISPATCH_STATUS_ALL) {
    return { "dispatch-status-all": true };
  }
  const normalizedStatus = normalizeDispatchPlanStatus(status);
  return {
    "dispatch-status-planned": normalizedStatus === "预排",
    "dispatch-status-dispatched": normalizedStatus === "已派车",
    "dispatch-status-crossing": normalizedStatus === "通关中",
    "dispatch-status-signed": normalizedStatus === "已签收",
    "dispatch-status-exception": normalizedStatus === "异常滞留"
  };
}

async function syncDispatchRowOrderStatus(row, status) {
  const orderStatus = DISPATCH_STATUS_TO_ORDER_STATUS[status];
  if (!orderStatus) return;
  const currentOrder = dispatchRowLiveOrder(row);
  if (!currentOrder) {
    if (dispatchRowHasMissingOrder(row)) return;
    return;
  }
  if (currentOrder?.status === orderStatus) return;
  const item = await ordersApi.updateOrderStatus(currentOrder.no, orderStatus);
  orderRows.value = orderRows.value.map((order) => order.no === item.no ? item : order);
}

async function syncDispatchNoToOrder(row = {}) {
  const dispatchNo = String(row.dispatchNo || "").trim();
  if (!dispatchNo) return;
  const currentOrder = dispatchRowLiveOrder(row);
  if (!currentOrder || String(currentOrder.dispatchNo || "").trim() === dispatchNo) return;
  const item = await ordersApi.updateOrder(currentOrder.no, { dispatchNo });
  orderRows.value = orderRows.value.map((order) => order.no === item.no ? item : order);
  if (row.order) row.order.dispatchNo = item.dispatchNo || dispatchNo;
}

async function syncDispatchNosToOrders(rows = dispatchPlanRows.value) {
  const seenOrderNos = new Set();
  for (const row of rows) {
    const orderNo = dispatchRowLiveOrder(row)?.no || "";
    if (!orderNo || seenOrderNos.has(orderNo)) continue;
    seenOrderNos.add(orderNo);
    await syncDispatchNoToOrder(row);
  }
}

async function refreshOrderRows() {
  if (!canAccessModule("orders")) return;
  orderRows.value = await apiFetchListFrom(ordersApi.listOrders, "订单");
}

async function syncDispatchDriverToOrder(row, driverName) {
  if (!driverName) return;
  const currentOrder = dispatchRowLiveOrder(row);
  if (!currentOrder) {
    if (dispatchRowHasMissingOrder(row)) return;
    return;
  }
  const isOutsourced = normalizeVehicleSource(currentOrder.vehicleSource || row.vehicleSource || "") === "外派车辆";
  const item = await ordersApi.updateOrder(currentOrder.no, {
    transportMode: isOutsourced ? (currentOrder.transportMode || row.transportMode || "") : "单司机",
    vehicleSource: currentOrder.vehicleSource || row.vehicleSource || "汉业物流",
    driver: driverName,
    hkDriver: "",
    mainlandDriver: ""
  });
  orderRows.value = orderRows.value.map((order) => order.no === item.no ? item : order);
}

async function handleDispatchDriverChange(row, driverName) {
  const target = dispatchPlanRows.value[row.index];
  if (!target) return;
  const previous = {
    driver: row.driver || "",
    hkDriver: row.hkDriver || "",
    mainlandDriver: row.mainlandDriver || "",
    transportMode: row.transportMode || ""
  };
  const nextDriverName = driverName === undefined
    ? String(target.driver || "").trim()
    : String(driverName || "").trim();
  closeDispatchDriverPicker();
  if (nextDriverName === String(target.driver || "").trim()) return;
  target.driver = nextDriverName;
  if (normalizeVehicleSource(target.vehicleSource || "") === "外派车辆") {
    target.hkDriver = "";
    target.mainlandDriver = "";
  } else if (nextDriverName) {
    target.transportMode = "单司机";
    target.hkDriver = nextDriverName;
    target.mainlandDriver = "";
  } else {
    target.hkDriver = "";
    target.mainlandDriver = "";
  }
  try {
    await saveDispatchPlan({ silent: true, throwOnError: true });
    await refreshOrderRows();
    if (nextDriverName && target.orderNo) notify("已同步订单司机");
  } catch (error) {
    Object.assign(target, previous);
    if (error?.status !== 409) await saveDispatchPlan({ silent: true });
    notify(error.message || "同步订单司机失败");
  }
}

async function handleDispatchStatusChange(row) {
  closeDispatchDriverPicker();
  const target = dispatchPlanRows.value[row.index];
  if (!target) return;
  const previousStatus = dispatchStatusValueForRow(row);
  const previousRecordedStatus = target.previousStatus || "";
  const currentStatusOptions = dispatchStatusOptionsForRow(row);
  const nextStatus = dispatchStatusValueForRow(target);
  if (previousStatus === DISPATCH_LOCKED_STATUS && nextStatus === "已派车") {
    target.status = DISPATCH_LOCKED_STATUS;
    notify("通关中的订单不能退回已派车");
    saveDispatchPlan({ silent: true });
    return;
  }
  if (previousStatus === "已签收" && ["已派车", "通关中"].includes(nextStatus)) {
    target.status = "已签收";
    notify("已签收的订单不能退回已派车或通关中");
    saveDispatchPlan({ silent: true });
    return;
  }
  if (!currentStatusOptions.includes(nextStatus)) {
    target.status = previousStatus;
    notify("当前排车状态不能直接切换到该状态");
    saveDispatchPlan({ silent: true });
    return;
  }
  try {
    if (nextStatus !== previousStatus) target.previousStatus = previousStatus;
    await saveDispatchPlan({ silent: true, throwOnError: true });
    await refreshOrderRows();
  } catch (error) {
    target.status = previousStatus;
    target.previousStatus = previousRecordedStatus;
    notify(error.message || "同步订单状态失败");
  }
}

async function returnDispatchRowStatus(row) {
  closeDispatchDriverPicker();
  const target = dispatchPlanRows.value[row.index];
  if (!target) return;
  const currentStatus = dispatchStatusValueForRow(target);
  const previousStatus = dispatchReturnStatusForRow(target);
  const previousRecordedStatus = target.previousStatus || "";
  if (!previousStatus) {
    notify("当前排车状态没有上一步可返回");
    return;
  }
  try {
    target.status = previousStatus;
    target.previousStatus = "";
    await saveDispatchPlan({ silent: true, throwOnError: true });
    await refreshOrderRows();
    activeDispatchStatusPool.value = previousStatus;
    notify(`排车状态已返回到${previousStatus}`);
  } catch (error) {
    target.status = currentStatus;
    target.previousStatus = previousRecordedStatus;
    notify(error.message || "排车状态返回失败");
  }
}

function closeDispatchModal(options = {}) {
  if (loading.value && !options.force) return;
  closeDispatchDriverPicker();
  clearAllDispatchLocationDrafts();
  clearDispatchRecognitionStatus();
  dispatchModalOpen.value = false;
  editingDispatchRowId.value = "";
  copyingDispatchRowId.value = "";
  if (loggedIn.value && (realtimePendingRefresh.database || realtimePendingRefresh.dispatch || realtimePendingRefresh.reminders)) {
    window.clearTimeout(realtimeRefreshTimer);
    realtimeRefreshTimer = window.setTimeout(() => {
      realtimeRefreshTimer = null;
      flushRealtimeRefresh();
    }, 0);
  }
}

function dispatchFormOwnSingleDriverMode() {
  const mode = normalizeTransportMode(dispatchForm.transportMode || "");
  return normalizeVehicleSource(dispatchForm.vehicleSource) === OWN_VEHICLE_SOURCE && (!mode || mode === "单司机");
}

function dispatchFormUsesManualDriverInput() {
  return normalizeVehicleSource(dispatchForm.vehicleSource) === "外派车辆" && Boolean(String(dispatchForm.supplier || "").trim());
}

function dispatchRowUsesManualDriverInput(row = {}) {
  return normalizeVehicleSource(row.vehicleSource) === "外派车辆" && Boolean(String(row.supplier || row.order?.supplier || "").trim());
}

function dispatchSingleDriverNameFromRow(row = {}, order = row.order || {}) {
  const mode = normalizeTransportMode(row.transportMode || order.transportMode || "");
  if (normalizeVehicleSource(row.vehicleSource || order.vehicleSource || "") === "外派车辆") {
    return String(row.driver || order.driver || row.hkDriver || order.hkDriver || "").trim();
  }
  if (mode && mode !== "单司机") return "";
  return String(row.driver || order.driver || row.hkDriver || order.hkDriver || "").trim();
}

function dispatchFormDriverFields(fallback = {}) {
  if (normalizeVehicleSource(dispatchForm.vehicleSource) !== OWN_VEHICLE_SOURCE) {
    const driver = String(dispatchForm.driver || fallback.driver || "").trim();
    return {
      transportMode: normalizeTransportMode(fallback.transportMode || dispatchForm.transportMode || "") || "",
      driver,
      hkDriver: "",
      mainlandDriver: ""
    };
  }
  if (!dispatchFormOwnSingleDriverMode()) {
    return {
      transportMode: normalizeTransportMode(fallback.transportMode || dispatchForm.transportMode || "") || fallback.transportMode || "",
      driver: fallback.driver || "",
      hkDriver: fallback.hkDriver || "",
      mainlandDriver: fallback.mainlandDriver || ""
    };
  }
  const driver = String(dispatchForm.driver || "").trim();
  return {
    transportMode: driver ? "单司机" : "",
    driver,
    hkDriver: driver,
    mainlandDriver: ""
  };
}

function resetDispatchForm() {
  clearAllDispatchLocationDrafts();
	  Object.assign(dispatchForm, {
    date: dispatchDate.value || offsetDateInputValue(1),
    customerId: "",
    customer: "",
    plate: "",
    port: "",
    needsWeighing: false,
    direction: "",
    tonnage: "",
    quantity: "",
    weight: "",
    loading: "",
    loadingLocations: [],
    unloading: "",
    unloadingLocations: [],
    loadTime: "",
    vehicleSource: "汉业物流",
    supplier: "",
    transportMode: "",
    driver: "",
    hkDriver: "",
    mainlandDriver: "",
    note: ""
  });
  editingDispatchRowId.value = "";
  copyingDispatchRowId.value = "";
  dispatchCustomerKeyword.value = "";
  dispatchLoadHourDraft.value = "";
  dispatchCustomerPickerOpen.value = false;
  clearDispatchRecognitionStatus();
}

async function openDispatchModal() {
  await ensureReferenceDataLoaded();
  resetDispatchForm();
  dispatchModalOpen.value = true;
}

function fillDispatchFormFromPlanRow(row, fallbackDate = dispatchDate.value || offsetDateInputValue(1)) {
  clearAllDispatchLocationDrafts();
  const order = row.order || {};
  const customerName = order.customer || row.customer || "";
  const customer = findPartnerByTypedLabel(customerName, "客户");
  const planDate = row.date || order.date || fallbackDate || dispatchDate.value || offsetDateInputValue(1);
  const transportMode = normalizeTransportMode(row.transportMode || order.transportMode || "");
  Object.assign(dispatchForm, {
    date: planDate,
    customerId: order.customerId || row.customerId || customer?.id || "",
    customer: customerName,
    plate: row.plate || order.plate || "",
    port: order.port || row.port || "",
    needsWeighing: booleanFlag(row.needsWeighing, false),
    direction: order.direction || row.direction || "",
    tonnage: order.tonnage || row.tonnage || "",
    quantity: order.quantity || row.quantity || "",
    weight: order.weight || row.weight || "",
    loading: order.loading || row.loading || "",
    unloading: order.unloading || row.unloading || "",
    loadTime: row.loadTime || order.loadTime || "",
    vehicleSource: normalizeVehicleSource(order.vehicleSource || row.vehicleSource || OWN_VEHICLE_SOURCE),
    supplier: order.supplier || row.supplier || "",
    transportMode,
    driver: dispatchSingleDriverNameFromRow(row, order),
    hkDriver: row.hkDriver || order.hkDriver || "",
    mainlandDriver: row.mainlandDriver || order.mainlandDriver || "",
	    note: row.note || order.remark || ""
	  });
	  setDispatchFormLocationEntriesFromRecord("loading", row, order);
	  setDispatchFormLocationEntriesFromRecord("unloading", row, order);
	  dispatchCustomerKeyword.value = partnerDisplayLabel(customerName, "客户") || customerName;
  syncDispatchLoadHourDraft();
  dispatchCustomerPickerOpen.value = false;
}

async function openEditDispatchPlanRow(row) {
  if (!row?.id) return;
  await ensureReferenceDataLoaded();
  closeDispatchDetail();
  fillDispatchFormFromPlanRow(row);
  editingDispatchRowId.value = row.id;
  copyingDispatchRowId.value = "";
  dispatchModalOpen.value = true;
}

async function openCopyDispatchPlanRow(row) {
  if (!row?.id) return;
  await ensureReferenceDataLoaded();
  fillDispatchFormFromPlanRow(row);
  editingDispatchRowId.value = "";
  copyingDispatchRowId.value = row.id;
  dispatchModalOpen.value = true;
}

function businessNoDateKey(date = todayInputValue()) {
  const text = String(date || todayInputValue()).trim().slice(0, 10);
  const normalized = /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : todayInputValue();
  return normalized.replaceAll("-", "");
}

function generateBusinessNo(prefix, date = todayInputValue(), rows = []) {
  const fullPrefix = `${prefix}${businessNoDateKey(date)}`;
  let max = 0;
  rows.forEach((row) => {
    const no = String(row.no || row.dispatchNo || row.dispatch_no || "");
    if (!no.startsWith(fullPrefix)) return;
    const sequence = Number(no.slice(fullPrefix.length));
    if (Number.isFinite(sequence)) max = Math.max(max, sequence);
  });
  return `${fullPrefix}${String(max + 1).padStart(3, "0")}`;
}

function generateOrderNo(date = todayInputValue(), extraRows = []) {
  return generateBusinessNo("HY", date, [...orderRows.value, ...extraRows]);
}

function generateDispatchNo(date = dispatchDate.value, extraRows = []) {
  const rows = [
    ...dispatchPlanRows.value,
    ...orderRows.value.map((order) => ({ dispatchNo: order.dispatchNo })),
    ...extraRows
  ];
  return generateBusinessNo("PC", date, rows);
}

function createManualDispatchPlanRow() {
  const isOutsourced = dispatchForm.vehicleSource === "外派车辆";
  const driverFields = dispatchFormDriverFields();
  const loadingPayload = dispatchLocationPayload("loading");
  const unloadingPayload = dispatchLocationPayload("unloading");
  const planDate = dispatchForm.date || dispatchDate.value;
  const createdAt = currentTimestampInputValue();
  return {
    id: `dispatch-manual-${Date.now()}`,
    createdAt,
    date: planDate,
    dispatchNo: generateDispatchNo(planDate),
    orderNo: "",
    customer: dispatchForm.customer,
    plate: dispatchForm.plate,
    port: dispatchForm.port,
    needsWeighing: booleanFlag(dispatchForm.needsWeighing, false),
    direction: dispatchForm.direction,
    tonnage: dispatchForm.tonnage,
    quantity: dispatchForm.quantity,
    weight: dispatchForm.weight,
    ...loadingPayload,
    ...unloadingPayload,
    loadTime: dispatchForm.loadTime,
    vehicleSource: dispatchForm.vehicleSource,
    supplier: isOutsourced ? dispatchForm.supplier : "",
    ...driverFields,
    status: DISPATCH_PLAN_DEFAULT_STATUS,
    previousStatus: "",
    ...currentCreatorFields(),
    note: dispatchForm.note
  };
}

async function saveEditedDispatchPlanRow() {
  commitDispatchFormLoadHourInput();
  normalizeDispatchLocationFormValuesForSave();
  normalizeDispatchFormTextValuesForSave();
  const targetIndex = dispatchPlanRows.value.findIndex((row) => row.id === editingDispatchRowId.value);
  if (targetIndex < 0) {
    notify("找不到要编辑的排车单");
    return;
  }
  if (!dispatchForm.customer.trim()) {
    notify("请选择或输入客户");
    return;
  }
  const matchedCustomer = (dispatchForm.customerId ? customerRowsById.value.get(String(dispatchForm.customerId || "").trim()) : null)
    || findPartnerByTypedLabel(dispatchForm.customer.trim(), "客户");
  if (!matchedCustomer) {
    notify("请选择客户资料中的有效客户");
    return;
  }
  const invalidLocation = invalidDispatchLocationMessage("loading") || invalidDispatchLocationMessage("unloading");
  if (invalidLocation) {
    notify(invalidLocation);
    return;
  }

  const originalRow = dispatchPlanRows.value[targetIndex];
  const originalPlanDate = dispatchPlanDate(originalRow);
  const planDate = dispatchForm.date || originalPlanDate || dispatchDate.value;
	  const isOutsourced = dispatchForm.vehicleSource === "外派车辆";
	  const originalOrder = dispatchRowLiveOrder(originalRow) || {};
	  const driverFields = dispatchFormDriverFields({
    ...originalRow,
    transportMode: originalRow.transportMode || originalOrder.transportMode || "",
    driver: originalRow.driver || originalOrder.driver || "",
    hkDriver: originalRow.hkDriver || originalOrder.hkDriver || "",
	    mainlandDriver: originalRow.mainlandDriver || originalOrder.mainlandDriver || ""
	  });
	  const loadingPayload = dispatchLocationPayload("loading");
	  const unloadingPayload = dispatchLocationPayload("unloading");
	  const updatedRow = {
    ...originalRow,
    date: planDate,
    customer: matchedCustomer.name,
    plate: dispatchForm.plate,
    port: dispatchForm.port,
    needsWeighing: booleanFlag(dispatchForm.needsWeighing, false),
    direction: dispatchForm.direction,
    tonnage: dispatchForm.tonnage,
    quantity: dispatchForm.quantity,
    weight: dispatchForm.weight,
	    ...loadingPayload,
	    ...unloadingPayload,
    loadTime: dispatchForm.loadTime,
    vehicleSource: dispatchForm.vehicleSource,
    supplier: isOutsourced ? dispatchForm.supplier : "",
    ...driverFields,
    note: dispatchForm.note
  };

  try {
    loading.value = true;
    if (updatedRow.orderNo) {
      const currentOrder = dispatchRowLiveOrder(updatedRow);
      if (currentOrder) {
        const item = await ordersApi.updateOrder(currentOrder.no, {
          ...currentOrder,
          customerId: matchedCustomer.id,
          customer: matchedCustomer.name,
          port: updatedRow.port,
          needsWeighing: updatedRow.needsWeighing,
          direction: updatedRow.direction,
          tonnage: updatedRow.tonnage,
          quantity: updatedRow.quantity,
          weight: updatedRow.weight,
          vehicleSource: updatedRow.vehicleSource,
          supplier: updatedRow.supplier,
          plate: updatedRow.plate,
          transportMode: updatedRow.transportMode,
          driver: updatedRow.driver,
          hkDriver: updatedRow.hkDriver,
	          mainlandDriver: updatedRow.mainlandDriver,
	          loading: updatedRow.loading,
	          loadingLocations: updatedRow.loadingLocations || [],
	          unloading: updatedRow.unloading,
	          unloadingLocations: updatedRow.unloadingLocations || [],
          date: planDate,
          remark: updatedRow.note
        });
        orderRows.value = orderRows.value.map((order) => order.no === item.no ? item : order);
        updatedRow.customer = item.customer || updatedRow.customer;
      }
    }

    if (planDate !== originalPlanDate) {
      dispatchPlanRows.value.splice(targetIndex, 1);
      const deleteResult = await dispatchApi.deleteDispatchPlanRows(originalPlanDate, [dispatchRowRef(originalRow)]);
      if (deleteResult?.plan) updateDispatchPlanBaseFromRecord(deleteResult.plan, originalPlanDate);
      await saveDispatchPlan({ silent: true, throwOnError: true });
      await appendDispatchPlanRowsToDate(planDate, [updatedRow]);
      dispatchDate.value = planDate;
      await loadDispatchPlan(planDate);
    } else {
      dispatchPlanRows.value.splice(targetIndex, 1, updatedRow);
      await saveDispatchPlan({ silent: true, throwOnError: true });
    }
    selectedDispatchPlanIds.value = [updatedRow.id];
    closeDispatchModal({ force: true });
    notify("排车单已更新");
  } catch (error) {
    notify(error.message || "保存排车单失败");
  } finally {
    loading.value = false;
  }
}

async function saveManualDispatchPlanRow() {
  commitDispatchFormLoadHourInput();
  normalizeDispatchLocationFormValuesForSave();
  normalizeDispatchFormTextValuesForSave();
  if (editingDispatchRowId.value) {
    await saveEditedDispatchPlanRow();
    return;
  }
  if (!dispatchForm.customer.trim()) {
    notify("请选择或输入客户");
    return;
  }
  const matchedCustomer = (dispatchForm.customerId ? customerRowsById.value.get(String(dispatchForm.customerId || "").trim()) : null)
    || findPartnerByTypedLabel(dispatchForm.customer.trim(), "客户");
  if (!matchedCustomer) {
    notify("请选择客户资料中的有效客户");
    return;
  }
  const invalidLocation = invalidDispatchLocationMessage("loading") || invalidDispatchLocationMessage("unloading");
  if (invalidLocation) {
    notify(invalidLocation);
    return;
  }
  dispatchForm.customerId = matchedCustomer.id;
  dispatchForm.customer = matchedCustomer.name;
  const planDate = dispatchForm.date || dispatchDate.value;
  const row = createManualDispatchPlanRow();
  const isCopyingDispatch = Boolean(copyingDispatchRowId.value);
  try {
    loading.value = true;
    const createdAt = row.createdAt || currentTimestampInputValue();
    row.createdAt = createdAt;
    row.date = planDate;
    const item = await ordersApi.createOrder({
      customerId: matchedCustomer.id,
      customer: matchedCustomer.name,
      businessType: "运输",
      port: row.port,
      needsWeighing: row.needsWeighing,
      direction: row.direction,
      tonnage: row.tonnage,
      currency: "港币",
      quantity: row.quantity,
      weight: row.weight,
      vehicleSource: row.vehicleSource,
      supplier: row.supplier,
      plate: row.plate,
      transportMode: row.transportMode,
      driver: row.driver,
      hkDriver: row.hkDriver,
	      mainlandDriver: row.mainlandDriver,
	      loading: row.loading,
	      loadingLocations: row.loadingLocations || [],
	      unloading: row.unloading,
	      unloadingLocations: row.unloadingLocations || [],
      date: planDate,
      status: DISPATCH_STATUS_TO_ORDER_STATUS[row.status] || "预排",
      remark: row.note,
      fees: []
    });
    row.orderNo = item.no;
    row.customer = item.customer || row.customer;
    row.dispatchNo = item.dispatchNo || row.dispatchNo;
    orderRows.value = [item, ...orderRows.value.filter((order) => order.no !== item.no)];
    selectedCustomerId.value = item.customerId || matchedCustomer.id;
    activatePartnerContext(matchedCustomer);
    activeCustomerDetailTab.value = "订单管理";
    if (planDate !== dispatchDate.value) {
      await appendDispatchPlanRowsToDate(planDate, [row]);
      dispatchDate.value = planDate;
      await loadDispatchPlan(planDate);
    } else {
      dispatchPlanRows.value.push(row);
      await saveDispatchPlan({ silent: true, throwOnError: true });
    }
    closeDispatchModal({ force: true });
    notify(isCopyingDispatch ? `排车单已复制，并生成预排订单：${item.no}` : `排车单已创建，并生成预排订单：${item.no}`);
  } catch (error) {
    notify(error.message || "创建排车单失败");
  } finally {
    loading.value = false;
  }
}

