async function duplicateSelectedDispatchRows() {
  const rows = selectedDispatchPlanRows.value;
  if (!rows.length) {
    notify("请先勾选要复制的排车单");
    return;
  }
  if (rows.length > 1) {
    notify("一次只能复制一张排车单，请只勾选一张");
    return;
  }
  await openCopyDispatchPlanRow(rows[0]);
}

function closeDispatchDuplicateModal() {
  if (loading.value) return;
  dispatchDuplicateModalOpen.value = false;
  dispatchDuplicateDraftRows.value = [];
  if (loggedIn.value && (realtimePendingRefresh.database || realtimePendingRefresh.dispatch || realtimePendingRefresh.reminders)) {
    window.clearTimeout(realtimeRefreshTimer);
    realtimeRefreshTimer = window.setTimeout(() => {
      realtimeRefreshTimer = null;
      flushRealtimeRefresh();
    }, 0);
  }
}

function handleDispatchDuplicateLoadTimeChange(row) {
  row.loadTime = normalizeDispatchLoadTime(row.loadTime);
}

async function saveDuplicateDispatchRows() {
  const rows = dispatchDuplicateDraftRows.value;
  if (!rows.length) {
    notify("没有可复制的排车单");
    return;
  }

  try {
    loading.value = true;
    const duplicatedRows = [];
    for (const draft of rows) {
      const sourceRow = draft.sourceRow || {};
      const sourceOrder = draft.sourceOrder || sourceRow.order || {};
      const customerName = String(draft.customer || sourceOrder.customer || sourceRow.customer || "").trim();
      const matchedCustomer = (sourceOrder.customerId ? customerRowsById.value.get(String(sourceOrder.customerId || "").trim()) : null)
        || findPartnerByTypedLabel(customerName, "客户");
      if (!matchedCustomer) {
        notify(`找不到客户：${customerName || "未填写"}`);
        return;
      }

      const note = String(draft.note || "").trim() || String(sourceRow.note || "").trim();
      const createdAt = currentTimestampInputValue();
      const dispatchNo = generateDispatchNo(dispatchDate.value, duplicatedRows);
      const item = await ordersApi.createOrder({
        dispatchNo,
        customerId: matchedCustomer.id,
        customer: matchedCustomer.name,
        businessType: sourceOrder.businessType || "运输",
        port: draft.port || sourceOrder.port || sourceRow.port || "",
        needsWeighing: booleanFlag(draft.needsWeighing ?? sourceRow.needsWeighing, false),
        direction: draft.direction || sourceOrder.direction || sourceRow.direction || "",
        tonnage: draft.tonnage || sourceOrder.tonnage || sourceRow.tonnage || "",
        currency: sourceOrder.currency || "港币",
        quantity: draft.quantity || sourceOrder.quantity || sourceRow.quantity || "",
        weight: draft.weight || sourceOrder.weight || sourceRow.weight || "",
        vehicleSource: draft.vehicleSource || sourceOrder.vehicleSource || sourceRow.vehicleSource || "",
        supplier: draft.supplier || sourceOrder.supplier || sourceRow.supplier || "",
        plate: draft.plate || sourceRow.plate || sourceOrder.plate || "",
        transportMode: draft.transportMode || sourceRow.transportMode || sourceOrder.transportMode || "",
        driver: draft.driver || sourceRow.driver || sourceOrder.driver || "",
        hkDriver: draft.hkDriver || sourceRow.hkDriver || sourceOrder.hkDriver || "",
	        mainlandDriver: draft.mainlandDriver || sourceRow.mainlandDriver || sourceOrder.mainlandDriver || "",
	        loading: draft.loading || sourceOrder.loading || sourceRow.loading || "",
	        loadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(draft, "loading", sourceOrder)),
	        unloading: draft.unloading || sourceOrder.unloading || sourceRow.unloading || "",
	        unloadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(draft, "unloading", sourceOrder)),
        loadTime: draft.loadTime || sourceRow.loadTime || sourceOrder.loadTime || "",
        date: dispatchDate.value,
        status: "预排",
        remark: note,
        tripNoEnabled: sourceOrder.tripNoEnabled || 0,
        tripNo: sourceOrder.tripNo || "",
        sixSheetEnabled: sourceOrder.sixSheetEnabled || 0,
        sixSheetNo: sourceOrder.sixSheetNo || "",
        fees: []
      });

      const duplicatedRow = {
        ...sourceRow,
        id: `dispatch-copy-${Date.now()}-${duplicatedRows.length}`,
        createdAt,
        date: dispatchDate.value,
        dispatchNo,
        orderNo: item.no,
        customer: item.customer || matchedCustomer.name,
        plate: draft.plate || sourceRow.plate || "",
        transportMode: draft.transportMode || sourceRow.transportMode || "",
        driver: draft.driver || sourceRow.driver || "",
        hkDriver: draft.hkDriver || sourceRow.hkDriver || "",
	        mainlandDriver: draft.mainlandDriver || sourceRow.mainlandDriver || "",
	        loading: draft.loading || sourceOrder.loading || sourceRow.loading || "",
	        loadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(draft, "loading", sourceOrder)),
	        unloading: draft.unloading || sourceOrder.unloading || sourceRow.unloading || "",
	        unloadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(draft, "unloading", sourceOrder)),
	        needsWeighing: booleanFlag(draft.needsWeighing ?? sourceRow.needsWeighing, false),
        loadTime: draft.loadTime || sourceRow.loadTime || "",
        status: DISPATCH_PLAN_DEFAULT_STATUS,
        previousStatus: "",
        ...currentCreatorFields(),
        note
      };
      delete duplicatedRow.index;
      delete duplicatedRow.order;
      delete duplicatedRow.vehicle;
      delete duplicatedRow.hkDriverRow;
      delete duplicatedRow.mainlandDriverRow;
      duplicatedRows.push(duplicatedRow);
      orderRows.value = [item, ...orderRows.value.filter((order) => order.no !== item.no)];
    }

    dispatchPlanRows.value.push(...duplicatedRows);
    selectedDispatchPlanIds.value = duplicatedRows.map((row) => row.id);
    saveDispatchPlan({ silent: true });
    dispatchDuplicateModalOpen.value = false;
    dispatchDuplicateDraftRows.value = [];
    notify(`已复制 ${duplicatedRows.length} 张排车单`);
  } catch (error) {
    notify(error.message || "复制排车单失败");
  } finally {
    loading.value = false;
  }
}

function bindableDispatchRowsForCustomer(customerName = "") {
  const normalizedName = String(customerName || "").trim();
  if (!normalizedName) return [];
  return dispatchPlanRows.value.filter(
    (row) => (!row.orderNo || dispatchRowHasMissingOrder(row)) && String(row.customer || "").trim() === normalizedName
  );
}

function applyDispatchRowToOrderForm(row) {
  if (!row) return;
  const rowVehicleSource = normalizeVehicleSource(row.vehicleSource || "");
  const matchedCustomer = (row.customerId ? customerRowsById.value.get(String(row.customerId || "").trim()) : null)
    || findPartnerByTypedLabel(row.customer || "", "客户", "运输客户");
  Object.assign(orderForm, {
    dispatchNo: row.dispatchNo || orderForm.dispatchNo,
    customerId: matchedCustomer?.id || orderForm.customerId,
    customer: row.customer || orderForm.customer,
    businessType: orderForm.businessType || "运输",
    port: row.port || "",
    needsWeighing: booleanFlag(row.needsWeighing, false),
    direction: row.direction || "",
    tonnage: row.tonnage || "",
    quantity: row.quantity || "",
    weight: row.weight || "",
    vehicleSource: row.vehicleSource || "",
    supplier: row.supplier || "",
    plate: row.plate || "",
    transportMode: normalizeTransportMode(row.transportMode || orderForm.transportMode || (rowVehicleSource === OWN_VEHICLE_SOURCE ? "单司机" : "")),
    driver: row.driver || row.hkDriver || orderForm.driver,
	    hkDriver: row.hkDriver || "",
	    mainlandDriver: row.mainlandDriver || "",
	    loading: row.loading || "",
	    loadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(row, "loading")),
	    unloading: row.unloading || "",
	    unloadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(row, "unloading")),
    date: dispatchPlanDate(row),
    status: DISPATCH_STATUS_TO_ORDER_STATUS[row.status] || orderForm.status,
    remark: [orderForm.remark, row.note ? `排车备注：${row.note}` : ""].filter(Boolean).join("\n")
  });
  ensureOrderFreightCurrency();
  if (rowVehicleSource === OWN_VEHICLE_SOURCE) {
    orderForm.supplier = "";
    ensureOrderTransportModeDefault();
  }
  if (row.vehicleSource === "外派车辆") {
    orderForm.plate = "";
    orderForm.driver = "";
    orderForm.hkDriver = "";
    orderForm.mainlandDriver = "";
    orderForm.transportMode = "";
  }
  pendingDispatchBindId.value = row.id;
  applyOrderRequiredFieldDefaults({ force: true });
}

async function removeDispatchPlanRow(index) {
  const row = dispatchPlanRows.value[index];
  if (!row) return;
  const linkedOrder = linkedOrderForDispatchRow(row);
  const planDate = dispatchPlanDate(row);
  if (linkedOrder) {
    try {
      await ordersApi.deleteOrder(linkedOrder.no);
      orderRows.value = orderRows.value.filter((item) => item.no !== linkedOrder.no);
      removeDispatchRowsByOrderRefs([linkedOrder]);
      notify(`排车单 ${row.dispatchNo || ""} 及关联订单 ${linkedOrder.no} 已删除`);
      return;
    } catch (error) {
      const message = String(error?.message || "");
      if (message.includes("不存在或已删除")) {
        orderRows.value = orderRows.value.filter((item) => item.no !== linkedOrder.no);
        removeDispatchRowsByOrderRefs([linkedOrder]);
        const deleteResult = await dispatchApi.deleteDispatchPlanRows(planDate, [dispatchRowRef(row)]);
        if (deleteResult?.plan) updateDispatchPlanBaseFromRecord(deleteResult.plan, planDate);
        return;
      }
      notify(error.message);
      return;
    }
  }
  try {
    const deleteResult = await dispatchApi.deleteDispatchPlanRows(planDate, [dispatchRowRef(row)]);
    if (deleteResult?.plan) updateDispatchPlanBaseFromRecord(deleteResult.plan, planDate);
  } catch (error) {
    notify(error.message || "排车单删除失败");
    return;
  }
  dispatchPlanRows.value.splice(index, 1);
  selectedDispatchPlanIds.value = selectedDispatchPlanIds.value.filter((id) =>
    dispatchPlanRows.value.some((row) => row.id === id)
  );
  notify(`排车单 ${row.dispatchNo || ""} 已移入回收站`);
}

function moveDispatchPlanRow(index, offset) {
  const target = index + offset;
  if (target < 0 || target >= dispatchPlanRows.value.length) return;
  const [row] = dispatchPlanRows.value.splice(index, 1);
  dispatchPlanRows.value.splice(target, 0, row);
  saveDispatchPlan({ silent: true });
}

function toggleDispatchPlanSelection(id, checked) {
  if (!id) return;
  selectedDispatchPlanIds.value = checked
    ? [...new Set([...selectedDispatchPlanIds.value, id])]
    : selectedDispatchPlanIds.value.filter((item) => item !== id);
}

function toggleAllDispatchPlanSelection(checked) {
  selectedDispatchPlanIds.value = checked
    ? searchedDispatchPlanRows.value.map((row) => row.id)
    : [];
}

function linkedOrderForDispatchRow(row = {}) {
  return dispatchRowLiveOrder(row);
}

function removeDispatchRowsByOrderRefs(orderRefs = []) {
  const orderNos = new Set();
  const dispatchNos = new Set();
  orderRefs.forEach((order) => {
    const orderNo = String(order?.no || order?.orderNo || "").trim();
    const dispatchNo = String(order?.dispatchNo || "").trim();
    if (orderNo) orderNos.add(orderNo);
    if (dispatchNo) dispatchNos.add(dispatchNo);
  });
  if (!orderNos.size && !dispatchNos.size) return;
  dispatchPlanRows.value = dispatchPlanRows.value.filter((row) => {
    const rowOrderNo = String(row?.orderNo || "").trim();
    const rowDispatchNo = String(row?.dispatchNo || "").trim();
    return !orderNos.has(rowOrderNo) && !dispatchNos.has(rowDispatchNo);
  });
  selectedDispatchPlanIds.value = selectedDispatchPlanIds.value.filter((id) =>
    dispatchPlanRows.value.some((row) => row.id === id)
  );
  if (dispatchPlanRows.value.length === 0) {
    selectedDispatchPlanIds.value = [];
  }
}

function dispatchSummarizeLocationEntries(value = "") {
  const entries = splitDispatchLocationEntriesText(value)
    .map((entry) => {
      const parts = splitLocationParts(entry);
      const city = String(parts.city || "").trim();
      const district = String(parts.district || "").trim();
      const detail = String(parts.detail || "").trim();
      const text = city && district
        ? [city, district].join(" / ")
        : city || district || detail || String(entry || "").trim();
      return { city, district, text };
    })
    .filter((item) => item.text);
  if (!entries.length) return "";
  const segments = [];
  let lastCity = "";
  entries.forEach((item) => {
    const city = item.city;
    if (city && lastCity && normalizeLocationText(city) === normalizeLocationText(lastCity)) {
      segments.push(item.district || item.text);
      return;
    }
    segments.push(item.text);
    lastCity = city || "";
  });
  return segments.join(" + ");
}

function dispatchSummarizeStructuredLocationEntries(entries = []) {
  const normalized = normalizeStructuredDispatchLocationEntries("", entries, "", { includeBlank: false })
    .map((entry) => {
      const city = String(entry.city || "").trim();
      const district = String(entry.district || "").trim();
      const detail = String(entry.detail || "").trim();
      const text = city && district
        ? [city, district].join(" / ")
        : city || district || detail;
      return { city, district, text };
    })
    .filter((item) => item.text);
  if (!normalized.length) return "";
  const segments = [];
  let lastCity = "";
  normalized.forEach((item) => {
    const city = item.city;
    if (city && lastCity && normalizeLocationText(city) === normalizeLocationText(lastCity)) {
      segments.push(item.district || item.text);
      return;
    }
    segments.push(item.text);
    lastCity = city || "";
  });
  return segments.join(" + ");
}

function dispatchShortLocation(value = "") {
  return dispatchSummarizeLocationEntries(value);
}

function dispatchShortLocationForRecord(record = {}, target = "", fallbackRecord = {}) {
  const entries = recordDispatchLocationEntries(record, target, fallbackRecord);
  return dispatchSummarizeStructuredLocationEntries(entries) || dispatchShortLocation(record?.[target] || fallbackRecord?.[target]);
}

function dispatchOrderRouteText(order) {
  const loading = dispatchShortLocationForRecord(order, "loading");
  const unloading = dispatchShortLocationForRecord(order, "unloading");
  return [loading, unloading].filter(Boolean).join(" → ") || "-";
}

function dispatchExportShortLocation(value = "") {
  return dispatchSummarizeLocationEntries(value);
}

function dispatchExportRouteSummary(row = {}) {
  const order = row.order || {};
  const loading = dispatchShortLocationForRecord(order, "loading", row) || dispatchExportShortLocation(order.loading || row.loading);
  const unloading = dispatchShortLocationForRecord(order, "unloading", row) || dispatchExportShortLocation(order.unloading || row.unloading);
  return [loading, unloading].filter(Boolean).join(" → ");
}

function dispatchExportSpacingMode() {
  if (dispatchDateFilterMode.value === DATE_FILTER_MODE_QUICK) return "day";
  if (dispatchDateFilterMode.value === DATE_FILTER_MODE_PERIOD && dispatchRangePeriodMode.value === "day") return "day";
  return "default";
}

function spreadsheetHardWrapLine(value = "", maxWidth = 34) {
  const text = String(value || "");
  if (spreadsheetTextWidth(text) <= maxWidth) return text;
  const lines = [];
  let current = "";
  Array.from(text).forEach((char) => {
    const next = `${current}${char}`;
    if (current && spreadsheetTextWidth(next) > maxWidth) {
      lines.push(current);
      current = char;
    } else {
      current = next;
    }
  });
  if (current) lines.push(current);
  return lines.join("\n");
}

function spreadsheetHardWrapText(value = "", maxWidth = 34) {
  return String(value || "")
    .split(/\r?\n/)
    .map((line) => spreadsheetHardWrapLine(line, maxWidth))
    .join("\n");
}

function dispatchExportRouteText(row = {}) {
  const order = row.order || {};
  const record = {
	    ...order,
	    loading: order.loading || row.loading || "",
	    loadingLocations: order.loadingLocations || row.loadingLocations || [],
	    loadingContact: order.loadingContact || row.loadingContact || "",
	    loadingPhone: order.loadingPhone || row.loadingPhone || "",
	    unloading: order.unloading || row.unloading || "",
	    unloadingLocations: order.unloadingLocations || row.unloadingLocations || [],
    unloadingContact: order.unloadingContact || row.unloadingContact || "",
    unloadingPhone: order.unloadingPhone || row.unloadingPhone || ""
  };
  return [
    dispatchLocationBlock("装货地", record, "loading"),
    dispatchLocationBlock("卸货地", record, "unloading")
  ].filter(Boolean).map((block) => spreadsheetHardWrapText(block, 38)).join("\n");
}

function spreadsheetWrappedRowHeight(value = "", base = 20, perLine = 18, max = 180) {
  const lines = String(value || "").split(/\r?\n/).length;
  return Math.min(max, Math.max(base, lines * perLine));
}

function dispatchVehicleSourceText(row) {
  const order = row?.order || {};
  if (order.vehicleSource === "外派车辆") return supplierDisplayLabel(order.supplier) || "外派供应商";
  if (normalizeVehicleSource(order.vehicleSource) === OWN_VEHICLE_SOURCE) return OWN_VEHICLE_SOURCE;
  return order.vehicleSource || "-";
}

function dispatchSupplierText(row = {}) {
  const order = row.order || {};
  if (order.vehicleSource === "外派车辆") return supplierDisplayLabel(order.supplier || row.supplier || "") || "外派供应商";
  return "-";
}

function dispatchWeighingText(value) {
  return booleanFlag(value, false) ? "过磅" : "不用过磅";
}

function dispatchDirectionText(value = "") {
  const text = String(value || "").trim();
  if (text === "进口") return "进口";
  if (text === "出口") return "出口";
  return text || "-";
}

function dispatchMessageText(rows = dispatchPlanDisplayRows.value) {
  if (!rows.length) return "";
  return rows.map((row) => {
    const order = row.order || {};
	    const record = {
	      ...order,
	      loading: order.loading || row.loading,
	      loadingLocations: order.loadingLocations || row.loadingLocations || [],
	      unloading: order.unloading || row.unloading,
	      unloadingLocations: order.unloadingLocations || row.unloadingLocations || []
	    };
    const date = dispatchPlanDate(row) || "-";
    const time = row.loadTime || order.loadingTime || "-";
    const direction = order.direction || row.direction || "";
    return [
      `装货时间：${date}   ${time}  ${dispatchWeighingText(row.needsWeighing)} ${dispatchDirectionText(direction)} 口岸：${order.port || row.port || "-"}`,
      `车牌：${row.plate || order.plate || "-"} 吨位：${order.tonnage || row.tonnage || "-"}    板数：${order.quantity || row.quantity || "-"}`,
      "",
      dispatchLocationBlock("装货地", record, "loading"),
      "",
      dispatchLocationBlock("卸货地", record, "unloading"),
      "",
      `备注：${row.note || order.remark || "-"}`
    ].filter((line) => line !== null && line !== undefined).join("\n");
  }).join("\n\n");
}

async function copyDispatchPlanText() {
  const selectedRows = selectedDispatchPlanRows.value;
  const rows = selectedRows.length ? selectedRows : searchedDispatchPlanRows.value;
  const text = dispatchMessageText(rows);
  if (!text) {
    notify("暂无排车内容");
    return;
  }
  const copied = await copyTextToClipboard(text);
  notify(copied
    ? (selectedRows.length ? `已复制 ${selectedRows.length} 单派车信息` : "排车信息已复制")
    : "复制失败，请手动选中文本复制"
  );
}

async function exportDispatchPlanRows() {
  const selectedRows = selectedDispatchPlanRows.value;
  const rows = selectedRows.length ? selectedRows : dispatchStatusPoolRows.value;
  if (!rows.length) {
    notify("暂无可导出的排车数据");
    return;
  }
  try {
    loading.value = true;
    const response = await fetch(`${API_BASE}/dispatch-plans/export/xlsx`, {
      method: "POST",
      headers: apiRequestHeaders({ "Content-Type": "application/json" }),
      body: JSON.stringify({
        date: dispatchDate.value,
        scope: selectedRows.length ? "已选" : "全部",
        exportSpacing: dispatchExportSpacingMode(),
        rows: rows.map((row) => ({
          id: row.id,
          date: dispatchPlanDate(row),
          dispatchNo: row.dispatchNo,
          orderNo: row.orderNo,
          customer: row.customer,
          customerShortName: customerShortDisplay(findPartnerByTypedLabel(row.order?.customer || row.customer || "", "客户")),
          plate: row.plate,
          port: row.port,
          direction: row.direction,
          tonnage: row.tonnage,
          quantity: row.quantity,
	          route: dispatchExportRouteSummary(row),
	          loading: row.loading,
	          loadingLocations: row.loadingLocations || row.order?.loadingLocations || [],
	          unloading: row.unloading,
	          unloadingLocations: row.unloadingLocations || row.order?.unloadingLocations || [],
          loadTime: row.loadTime,
          vehicleSource: row.vehicleSource,
          supplier: row.supplier,
          driver: row.driver,
          hkDriver: row.hkDriver,
          mainlandDriver: row.mainlandDriver,
          note: row.note,
          order: row.order || {}
        }))
      })
    });
    if (!response.ok) {
      throw new Error(await apiDownloadErrorMessage(response, "排车表 Excel 导出失败"));
    }
    const blob = await response.blob();
    downloadBlob(blob, `排车表_${dispatchDate.value}_${selectedRows.length ? "已选" : "全部"}${rows.length}单.xlsx`);
    notify(selectedRows.length ? `已导出已选 ${rows.length} 单` : `已导出当前列表 ${rows.length} 单`);
  } catch (error) {
    notify(error.message || "排车表 Excel 导出失败");
  } finally {
    loading.value = false;
  }
}

async function applyDispatchPlanToOrders() {
  if (!dispatchPlanRows.value.length) {
    notify("暂无可同步的排车计划");
    return;
  }
  try {
    loading.value = true;
    for (const row of dispatchPlanRows.value) {
      const order = dispatchRowLiveOrder(row);
      if (!order) continue;
      const normalizedMode = normalizeTransportMode(row.transportMode || order.transportMode || "单司机") || "单司机";
      const nextVehicleSource = order.vehicleSource || (row.plate ? "汉业物流" : "");
      const nextOrder = {
        ...order,
        dispatchNo: row.dispatchNo || order.dispatchNo || "",
        vehicleSource: nextVehicleSource,
        plate: row.plate || order.plate || "",
        transportMode: normalizedMode,
        driver: normalizedMode === "单司机"
          ? (row.driver || row.hkDriver || order.driver || "")
          : [row.hkDriver || row.driver || "", row.mainlandDriver || ""].filter(Boolean).join(" / "),
	        hkDriver: normalizedMode === "单司机" ? "" : (row.hkDriver || row.driver || ""),
	        mainlandDriver: normalizedMode === "单司机" ? "" : (row.mainlandDriver || ""),
	        loading: row.loading || order.loading || "",
	        loadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(row, "loading", order)),
	        unloading: row.unloading || order.unloading || "",
	        unloadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(row, "unloading", order))
	      };
      const item = await ordersApi.updateOrder(order.no, nextOrder);
      orderRows.value = orderRows.value.map((current) => current.no === item.no ? item : current);
    }
    saveDispatchPlan({ silent: true });
    notify("排车计划已同步到订单");
  } catch (error) {
    notify(error.message || "同步排车计划失败");
  } finally {
    loading.value = false;
  }
}

function orderIncludesDriver(order, driver) {
  if (!order || !driver?.name) return false;
  const driverNames = [
    order.driver,
    order.hkDriver,
    order.mainlandDriver,
    ...String(order.driver || "").split("/")
  ].map((value) => String(value || "").trim()).filter(Boolean);
  return driverNames.includes(driver.name);
}

function isMainlandRiderDriver(driver = {}) {
  return normalizeCostCenterSourceLabel(driver?.type || "") === "大陆骑师";
}

function orderIsDoubleDriverMode(order = {}) {
  return (normalizeTransportMode(order?.transportMode || "") || "单司机") === "双司机";
}

function orderHasMainlandRiderCostAndWage(order = {}, driver = null) {
  if (!isMainlandRiderDriver(driver)) return false;
  return normalizeVehicleSource(order?.vehicleSource) === OWN_VEHICLE_SOURCE
    && orderIsDoubleDriverMode(order)
    && String(order?.mainlandDriver || "").trim() === String(driver?.name || "").trim();
}

function orderMatchesDriverForWage(order, driver) {
  if (!order || !driver?.name) return false;
  if (isMainlandRiderDriver(driver)) return orderHasMainlandRiderCostAndWage(order, driver);
  return orderIncludesDriver(order, driver) || (order.plate && order.plate === driver.boundPlate);
}

function orderCustomerForDriverPay(order) {
  const customerId = String(order?.customerId || "").trim();
  const customerName = String(order?.customer || "").trim();
  return (customerId ? customerRowsById.value.get(customerId) : null)
    || (customerName ? customerRowsByName.value.get(customerName) : null)
    || null;
}

function orderDriverWageCity(order, driver = null) {
  const location = order?.direction === "进口" ? order?.unloading : order?.loading;
  return driverWageCityValue(location);
}

function orderDriverWageRule(order, driver = selectedDriver.value) {
  if (!order || !driver) return null;
  const city = orderDriverWageCity(order, driver);
  const mode = normalizeTransportMode(order.transportMode || "单司机") || "单司机";
  const exactDriverRules = driverWageRuleRows.value.filter((rule) => rule.driverId === driver.id);
  const sharedRules = driverWageRuleRows.value.filter((rule) => !rule.driverId);
  const matches = (rule) =>
    (!rule.city || driverWageCityValue(rule.city) === city)
    && (!rule.transportMode || normalizeTransportMode(rule.transportMode) === mode);
  const direction = String(order.direction || "").trim();
  const matchesDirection = (rule) => matches(rule) && rule.direction === direction;
  const matchesSharedDirection = (rule) => matches(rule) && (!rule.direction || rule.direction === SHARED_DIRECTION);
  return exactDriverRules.find(matchesDirection)
    || exactDriverRules.find(matchesSharedDirection)
    || sharedRules.find(matchesDirection)
    || sharedRules.find(matchesSharedDirection)
    || exactDriverRules.find(matches)
    || sharedRules.find(matches)
    || null;
}

function driverBaseTripFeeBreakdown(order, driver = selectedDriver.value) {
  const rule = orderDriverWageRule(order, driver);
  if (!rule) return { hkd: 0, rmb: 0 };
  return {
    hkd: Number(rule.baseHKD || 0),
    rmb: Number(rule.baseRMB || 0)
  };
}

function legacyDriverBaseTripFeeBreakdown(order, driver = selectedDriver.value) {
  return driverBaseTripFeeBreakdown(order, driver);
}

function legacyDriverBaseTripFee(order, driver = selectedDriver.value) {
  return driverBaseTripFeeBreakdown(order, driver).hkd;
}

function driverBaseTripFee(order, driver = selectedDriver.value) {
  return driverBaseTripFeeBreakdown(order, driver).hkd;
}

function driverRouteAdjustMatches(order, rule, driver = selectedDriver.value) {
  if (!order || !rule || normalizeVehicleSource(order.vehicleSource) !== OWN_VEHICLE_SOURCE) return false;
  const ruleDriverIds = Array.isArray(rule.driverIds)
    ? rule.driverIds.map((id) => Number(id)).filter(Boolean)
    : [];
  if (ruleDriverIds.length && !ruleDriverIds.includes(Number(driver?.id || 0))) return false;
  const ruleDriverId = Number(rule.driverId || 0);
  if (!ruleDriverIds.length && ruleDriverId && Number(driver?.id || 0) !== ruleDriverId) return false;
  const ruleDriverName = String(rule.driverName || "").trim();
  if (!ruleDriverIds.length && !ruleDriverId && ruleDriverName && ruleDriverName !== String(driver?.name || "").trim()) return false;
  const ruleMode = normalizeTransportMode(rule.transportMode || "");
  if (ruleMode && ruleMode !== normalizeTransportMode(order.transportMode || "单司机")) return false;
  const customerName = String(rule.customerName || "").trim();
  if (customerName && customerName !== String(order.customer || "").trim()) return false;
  const orderLoading = supplierCostRuleAreaValue(order.loading);
  const orderUnloading = supplierCostRuleAreaValue(order.unloading);
  const ruleLoading = supplierCostRuleAreaValue(rule.loading);
  const ruleUnloading = supplierCostRuleAreaValue(rule.unloading);
  if (ruleLoading && ruleLoading !== orderLoading) return false;
  if (ruleUnloading && ruleUnloading !== orderUnloading) return false;
  return true;
}

function driverRouteAdjustBreakdown(order, driver = selectedDriver.value) {
  return driverRouteAdjustRules.value
    .filter((rule) => driverRouteAdjustMatches(order, rule, driver))
    .reduce((sum, rule) => ({
      hkd: sum.hkd + Number(rule.amountHKD || 0),
      rmb: sum.rmb + Number(rule.amountRMB || 0)
    }), { hkd: 0, rmb: 0 });
}

function driverCustomerTripAdjustBreakdown(order, driver = selectedDriver.value) {
  if (isMainlandRiderDriver(driver) && !orderHasMainlandRiderCostAndWage(order, driver)) {
    return { hkd: 0, rmb: 0 };
  }
  const routeAdjust = driverRouteAdjustBreakdown(order, driver);
  return {
    hkd: routeAdjust.hkd,
    rmb: routeAdjust.rmb
  };
}

function driverCustomerTripAdjust(order, driver = selectedDriver.value) {
  return driverCustomerTripAdjustBreakdown(order, driver).hkd;
}

function driverCostCenterSourceForDriver(driver = {}) {
  return isMainlandRiderDriver(driver)
    ? "大陆骑师"
    : "香港司机";
}

function driverCostCenterRuleMatchesOrder(rule = {}, order = {}, driver = null) {
  if (!rule || !order || !driver?.name) return false;
  if (isMainlandRiderDriver(driver) && !orderHasMainlandRiderCostAndWage(order, driver)) return false;
  if (normalizeCostCenterSourceLabel(rule.source) !== driverCostCenterSourceForDriver(driver)) return false;
  const ruleEntityId = String(rule.entityId || rule.entity_id || "").trim();
  const driverId = String(driver.id || "").trim();
  const ruleEntityName = String(rule.entityName || rule.entity_name || "").trim();
  const driverName = String(driver.name || "").trim();
  if (!((ruleEntityId && driverId && ruleEntityId === driverId) || ruleEntityName === driverName)) return false;
  const originScore = costCenterRouteMatchScore(rule.origin, order.loading);
  const destinationScore = costCenterRouteMatchScore(rule.destination, order.unloading);
  return originScore >= 0 && destinationScore >= 0;
}

function driverCostCenterRuleForOrder(order = {}, driver = null) {
  if (!order || !driver?.name) return null;
  const candidates = costCenterRateRows.value
    .filter((rule) => driverCostCenterRuleMatchesOrder(rule, order, driver))
    .filter((rule) => priceRuleAppliesToOrderDate(rule, order))
    .map((rule) => ({
      rule,
      score: costCenterRouteMatchScore(rule.origin, order.loading)
        + costCenterRouteMatchScore(rule.destination, order.unloading)
    }))
    .sort((left, right) =>
      right.score - left.score
      || priceEffectiveDate(right.rule).localeCompare(priceEffectiveDate(left.rule))
      || priceUpdatedTime(right.rule) - priceUpdatedTime(left.rule)
      || Number(left.rule.id || 0) - Number(right.rule.id || 0)
    );
  return candidates[0]?.rule || null;
}

function driverCostCenterOrderFeeRows(order = {}) {
  const fees = (Array.isArray(order?.fees) ? order.fees : [])
    .filter((fee) => !isAdvanceFee(fee))
    .filter((fee) => String(fee?.name || "").trim());
  if (fees.length) return fees;
  const fallback = [];
  if (Number(order.receivableHKD || 0)) {
    fallback.push({
      name: "基础运费",
      currency: "港币",
      quantity: 1,
      unitPrice: Number(order.receivableHKD || 0),
      amount: Number(order.receivableHKD || 0)
    });
  }
  if (Number(order.receivableRMB || 0)) {
    fallback.push({
      name: "基础运费",
      currency: "人民币",
      quantity: 1,
      unitPrice: Number(order.receivableRMB || 0),
      amount: Number(order.receivableRMB || 0)
    });
  }
  return fallback;
}

function driverCostCenterFeeValueKeys(fee = {}, item = {}) {
  const currency = currencyCodeDisplay(item.currency || fee.currency || "港币") || "HKD";
  return [
    costCenterFeeValueKey(item),
    item.id,
    item.name,
    `${item.name} ${currency}`,
    fee.feeItemId,
    fee.fee_item_id,
    fee.name,
    `${fee.name} ${currency}`
  ].map((key) => String(key || "").trim()).filter(Boolean);
}

function driverCostCenterFeeCostForRule(rule = null, fee = {}, driver = null) {
  const item = feeItemForFee(fee);
  const source = driverCostCenterSourceForDriver(driver);
  if (!rule || !item || item.category === "代垫" || isCompanyCoveredFeeItem(item) || !feeItemIncludesCostSource(item, source)) {
    return {
      item,
      matched: false,
      unitCost: 0,
      quantity: feeCostQuantity(fee),
      amount: 0,
      currency: item?.currency || fee.currency || "港币",
      rule: rule || null
    };
  }
  const values = parseCostCenterValues(rule.costValues);
  const matchedKey = driverCostCenterFeeValueKeys(fee, item)
    .find((key) => Object.prototype.hasOwnProperty.call(values, key));
  const costValue = normalizeCostCenterValue(
    matchedKey ? values[matchedKey] : 0,
    item.currency || fee.currency || "港币"
  );
  const unitCost = Number(costValue.amount || 0);
  const quantity = feeCostQuantity(fee);
  return {
    item,
    matched: Boolean(matchedKey),
    unitCost,
    quantity,
    amount: Number((unitCost * quantity).toFixed(2)),
    currency: costValue.currency,
    rule
  };
}

function driverCostCenterFeeBreakdown(order = {}, driver = null) {
  if (isMainlandRiderDriver(driver) && !orderHasMainlandRiderCostAndWage(order, driver)) {
    return {
      hkd: 0,
      rmb: 0,
      matchedCount: 0,
      missingCount: 0,
      details: []
    };
  }
  const rule = driverCostCenterRuleForOrder(order, driver);
  return driverCostCenterOrderFeeRows(order)
    .reduce((sum, fee) => {
      const detail = driverCostCenterFeeCostForRule(rule, fee, driver);
      if (
        !detail.item
        || detail.item.category === "代垫"
        || isCompanyCoveredFeeItem(detail.item)
        || !feeItemIncludesCostSource(detail.item, driverCostCenterSourceForDriver(driver))
      ) {
        return sum;
      }
      const value = Number(detail.amount || 0);
      const isRmb = currencyCodeDisplay(detail.currency || "港币") === "RMB";
      sum.details.push({
        ...detail,
        fee,
        name: detail.item.name || fee.name || "费用"
      });
      if (detail.matched) {
        sum.matchedCount += 1;
      } else {
        sum.missingCount += 1;
      }
      if (isRmb) sum.rmb += value;
      else sum.hkd += value;
      return sum;
    }, {
      hkd: 0,
      rmb: 0,
      matchedCount: 0,
      missingCount: 0,
      details: []
    });
}

function driverFinanceAdvanceBreakdown(order = {}, driver = null) {
  if (isMainlandRiderDriver(driver) && !orderHasMainlandRiderCostAndWage(order, driver)) {
    return { hkd: 0, rmb: 0 };
  }
  if (!orderAdvanceFeeBelongsToDriverRow(order, driver)) {
    return { hkd: 0, rmb: 0 };
  }
  return orderAdvanceFeeBreakdown(order, driver);
}

function driverFinanceWageOrderBreakdown(order = {}, driver = null) {
  const costCenter = driverCostCenterFeeBreakdown(order, driver);
  const advance = driverFinanceAdvanceBreakdown(order, driver);
  const adjust = driverCustomerTripAdjustBreakdown(order, driver);
  return {
    hkd: costCenter.hkd + advance.hkd + adjust.hkd,
    rmb: costCenter.rmb + advance.rmb + adjust.rmb,
    costCenterHKD: costCenter.hkd,
    costCenterRMB: costCenter.rmb,
    costCenterMatchedCount: costCenter.matchedCount,
    costCenterMissingCount: costCenter.missingCount,
    advanceHKD: advance.hkd,
    advanceRMB: advance.rmb,
    adjustmentsHKD: adjust.hkd,
    adjustmentsRMB: adjust.rmb,
    costCenterDetails: costCenter.details
  };
}

const DRIVER_EXTRA_FEE_KEYWORDS = {
  loadPerBoard: ["装货"],
  unloadPerBoard: ["卸货"],
  crossSeaFee: ["过海"],
  addPointFee: ["加点"],
  waitingPerHour: ["等候"]
};

const DRIVER_EXTRA_FIELD_LABELS = {
  loadPerBoard: "装货费",
  unloadPerBoard: "卸货费",
  crossSeaFee: "过海费",
  addPointFee: "加点费",
  waitingPerHour: "装货等候费"
};

const DRIVER_EXTRA_RULE_FIELDS = Object.keys(DRIVER_EXTRA_FIELD_LABELS);
const DRIVER_QUANTITY_EXTRA_FIELDS = ["loadPerBoard", "unloadPerBoard"];
const DRIVER_FIXED_EXTRA_FIELDS = ["crossSeaFee", "addPointFee", "waitingPerHour"];

function orderHasActualDriverExtraFee(order, field) {
  const keywords = DRIVER_EXTRA_FEE_KEYWORDS[field] || [];
  if (!keywords.length) return false;
  const fees = Array.isArray(order?.fees) ? order.fees : [];
  return fees.some((fee) => {
    if (isAdvanceFee(fee)) return false;
    const name = String(fee?.name || "");
    const amount = Number(fee?.amount || 0);
    return amount !== 0 && keywords.some((keyword) => name.includes(keyword));
  });
}

function orderDriverExtraQuantity(order, field) {
  const keywords = DRIVER_EXTRA_FEE_KEYWORDS[field] || [];
  const fees = Array.isArray(order?.fees) ? order.fees : [];
  const matchedFee = fees.find((fee) => {
    if (isAdvanceFee(fee)) return false;
    const name = String(fee?.name || "");
    return Number(fee?.amount || 0) !== 0 && keywords.some((keyword) => name.includes(keyword));
  });
  const feeQuantity = quantityNumber(matchedFee?.quantity);
  if (feeQuantity > 0) return feeQuantity;
  return 0;
}

function driverRuleAmountForField(order, field, driver = selectedDriver.value) {
  const rule = orderDriverWageRule(order, driver);
  return Number(rule?.[field] || 0);
}

function driverExtraTripFeeApplies(order, field, driver = selectedDriver.value) {
  const amount = driverRuleAmountForField(order, field, driver);
  if (!amount) return false;
  if (!orderHasActualDriverExtraFee(order, field)) return false;
  if (DRIVER_QUANTITY_EXTRA_FIELDS.includes(field)) return orderDriverExtraQuantity(order, field) > 0;
  return DRIVER_FIXED_EXTRA_FIELDS.includes(field) || orderHasActualDriverExtraFee(order, field);
}

function driverExtraTripFee(order, field, driver = selectedDriver.value) {
  const rule = orderDriverWageRule(order, driver);
  if (!rule) return 0;
  const amount = Number(rule[field] || 0);
  if (!driverExtraTripFeeApplies(order, field, driver)) return 0;
  if (DRIVER_QUANTITY_EXTRA_FIELDS.includes(field)) {
    return orderDriverExtraQuantity(order, field) * amount;
  }
  return amount;
}

function driverExtraTripFeeTotal(order, driver = selectedDriver.value) {
  const rule = orderDriverWageRule(order, driver);
  const dynamicTotal = advanceFeeRateTotalForOrder(order, rule?.advanceFeeRates);
  const fixedTotal = DRIVER_EXTRA_RULE_FIELDS
    .reduce((sum, field) => sum + driverExtraTripFee(order, field, driver), 0);
  return fixedTotal + dynamicTotal;
}

function driverPayableTripFee(order, driver = selectedDriver.value) {
  return driverFinanceWageOrderBreakdown(order, driver).hkd;
}

function driverPayableTripFeeBreakdown(order, driver = selectedDriver.value) {
  return driverFinanceWageOrderBreakdown(order, driver);
}

function driverByName(name = "") {
  const target = String(name || "").trim();
  return target ? driverRowsByName.value.get(target) || null : null;
}

const orderDriverWagePreviewRows = computed(() => {
  if (!orderHasTransportFields.value || !orderUsesOwnVehicle.value) return [];
  const order = { ...orderForm, transportMode: normalizeTransportMode(orderForm.transportMode || "单司机") || "单司机" };
  const roleRows = orderUsesRelayDrivers.value
    ? (isDomesticTransferMode(order.transportMode) ? [
      { role: "香港司机", name: orderForm.hkDriver }
    ] : [
      { role: "香港司机", name: orderForm.hkDriver },
      { role: "大陆骑师", name: orderForm.mainlandDriver }
    ])
    : [{ role: "香港司机", name: orderForm.driver }];
  return roleRows.map((row) => {
    const driver = driverByName(row.name);
    const rule = driver ? orderDriverWageRule(order, driver) : null;
    const baseFee = driver && rule ? driverBaseTripFee(order, driver) : 0;
    const extraFee = driver && rule ? driverExtraTripFeeTotal(order, driver) : 0;
    const adjust = driver ? driverCustomerTripAdjust(order, driver) : 0;
    return {
      ...row,
      driver,
      city: orderDriverWageCity(order, driver) || "-",
      rule,
      baseFee,
      extraFee,
      adjust,
      payable: driver && rule ? baseFee + extraFee + adjust : 0
    };
  });
});

function driverPayableOrderTotals(orders = [], driver = selectedDriver.value) {
  return orders.reduce((sum, order) => {
    const amount = driverPayableTripFeeBreakdown(order, driver);
    return {
      hkd: sum.hkd + Number(amount.hkd || 0),
      rmb: sum.rmb + Number(amount.rmb || 0)
    };
  }, { hkd: 0, rmb: 0 });
}

const selectedDriverTripFeeTotal = computed(() => driverPayableOrderTotals(selectedDriverOrders.value));

const selectedDriverMonthTripFeeTotal = computed(() => driverPayableOrderTotals(selectedDriverMonthOrders.value));

function outsourcedCostRuleForOrder(order) {
  if (!order || order.vehicleSource !== "外派车辆" || !order.supplier) return null;
  const area = supplierCostRuleAreaValue(order.direction === "进口" ? order.unloading : order.loading);
  const candidates = supplierCostRuleRows.value.filter((item) =>
    item.supplier === order.supplier
    && supplierCostRuleDirectionMatches(item.direction, order.direction)
    && (!item.city || supplierCostRuleAreaMatches(item.city, area))
    && (!item.tonnage || item.tonnage === order.tonnage)
    && (!item.currency || item.currency === order.currency)
  );
  return candidates.find((item) => supplierCostRuleDirection(item.direction) === order.direction)
    || candidates.find((item) => supplierCostRuleDirection(item.direction) === SUPPLIER_COST_SHARED_DIRECTION)
    || null;
}

function outsourcedCostAmountForOrder(order) {
  return supplierCostRuleAmount(outsourcedCostRuleForOrder(order), order);
}

const COMPANY_SELF_PAY_CATEGORY = "公司自费";
const COMPANY_SELF_PAY_DEFAULT_REMARK = "公司自费成本由公司承担，客户对账单按本项目报价正常展示，不计入供应商或司机对账。";
const COMPANY_SELF_PAY_TOOLTIP = "公司自费项目会计入客户对账单，但不计入供应商或司机对账。";
const OTHER_EXPENSE_COST_SOURCE = "其他支出";
const OTHER_EXPENSE_DEFAULT_REMARK = "其他支出由公司承担成本，客户对账单按本项目报价正常展示，不计入供应商或司机对账，用于公司内部成本和利润核算。";
const OTHER_EXPENSE_TOOLTIP = "其他支出会计入客户对账单，但不计入供应商或司机对账，由公司承担成本并计入公司利润。";
const COMPANY_COVERED_COST_SOURCES = new Set([COMPANY_SELF_PAY_CATEGORY, OTHER_EXPENSE_COST_SOURCE]);
const COMPANY_SELF_PAY_DEFAULT_REMARKS = [
  COMPANY_SELF_PAY_DEFAULT_REMARK,
  COMPANY_SELF_PAY_TOOLTIP,
  "公司自费，不计入客户对账单，只用于内部成本和利润计算",
  "公司自费项目仅参与内部成本与利润核算，不计入客户对账单。",
  "公司自费：不向客户收费，但由公司实际承担的成本",
  "公司自费",
  "用于国内转货、货拉拉、国内车转运及其他平台支出等公司自费成本，仅参与内部成本与利润核算，不计入客户对账单。"
];
const COMPANY_COVERED_DEFAULT_REMARKS = [
  ...COMPANY_SELF_PAY_DEFAULT_REMARKS,
  OTHER_EXPENSE_DEFAULT_REMARK,
  OTHER_EXPENSE_TOOLTIP,
  "其他支出"
];

function isCompanyCoveredCostSource(source = "") {
  return COMPANY_COVERED_COST_SOURCES.has(String(source || "").trim());
}

function feeItemCompanyCoveredCostSources(item = {}) {
  if (!item) return [];
  const sources = normalizeFeeItemCostSources(item.costSources || item.costSource || item.cost_source)
    .filter(isCompanyCoveredCostSource);
  if (String(item.category || "").trim() === COMPANY_SELF_PAY_CATEGORY && !sources.includes(COMPANY_SELF_PAY_CATEGORY)) {
    sources.unshift(COMPANY_SELF_PAY_CATEGORY);
  }
  return sources;
}

function isCompanySelfPayFeeItem(item = {}) {
  if (!item) return false;
  if (String(item.category || "").trim() === COMPANY_SELF_PAY_CATEGORY) return true;
  return normalizeFeeItemCostSources(item.costSources || item.costSource || item.cost_source)
    .includes(COMPANY_SELF_PAY_CATEGORY);
}

function isCompanySelfPayFee(fee = {}) {
  if (!fee) return false;
  if (String(fee.category || "").trim() === COMPANY_SELF_PAY_CATEGORY) return true;
  return isCompanySelfPayFeeItem(feeItemForFee(fee));
}

function isOtherExpenseCostFeeItem(item = {}) {
  return feeItemCompanyCoveredCostSources(item).includes(OTHER_EXPENSE_COST_SOURCE);
}

function isOtherExpenseCostFee(fee = {}) {
  return isOtherExpenseCostFeeItem(feeItemForFee(fee));
}

function isCompanyCoveredFeeItem(item = {}) {
  return feeItemCompanyCoveredCostSources(item).length > 0;
}

function isCompanyCoveredFee(fee = {}) {
  if (!fee) return false;
  if (String(fee.category || "").trim() === COMPANY_SELF_PAY_CATEGORY) return true;
  return isCompanyCoveredFeeItem(feeItemForFee(fee));
}

function isCompanySelfPayDefaultRemark(value = "") {
  const remark = String(value || "").trim();
  return COMPANY_COVERED_DEFAULT_REMARKS.includes(remark);
}

function companyCoveredFeeDefaultRemark(fee = {}, item = null) {
  const targetItem = item || feeItemForFee(fee);
  if (isOtherExpenseCostFeeItem(targetItem)) return OTHER_EXPENSE_DEFAULT_REMARK;
  if (isCompanySelfPayFeeItem(targetItem) || String(fee.category || "").trim() === COMPANY_SELF_PAY_CATEGORY) {
    return COMPANY_SELF_PAY_DEFAULT_REMARK;
  }
  return "";
}

function companyCoveredFeeTooltip(fee = {}, item = null) {
  const targetItem = item || feeItemForFee(fee);
  if (isOtherExpenseCostFeeItem(targetItem)) return OTHER_EXPENSE_TOOLTIP;
  if (isCompanySelfPayFeeItem(targetItem) || String(fee.category || "").trim() === COMPANY_SELF_PAY_CATEGORY) {
    return COMPANY_SELF_PAY_TOOLTIP;
  }
  return "";
}

function syncCompanySelfPayFeeRemark(fee, item = null) {
  if (!fee) return fee;
  const defaultRemark = companyCoveredFeeDefaultRemark(fee, item);
  const current = String(fee.remark || "").trim();
  if (defaultRemark) {
    if (!current || isCompanySelfPayDefaultRemark(current)) {
      fee.remark = defaultRemark;
    }
    return fee;
  }
  if (isCompanySelfPayDefaultRemark(current)) fee.remark = "";
  return fee;
}

function isAdvanceFee(fee = {}) {
  const category = String(fee.category || "").trim();
  if (category === COMPANY_SELF_PAY_CATEGORY) return false;
  if (category === "代垫") return true;
  return feeItemForFee(fee)?.category === "代垫";
}

function orderFeeCategoryValue(value = "正常") {
  return String(value || "").trim() === "代垫" ? "代垫" : "正常";
}

function feeCategoryLabel(fee = {}) {
  return orderFeeCategoryValue(feeItemForFee(fee)?.category || fee.category || "正常");
}

function orderFeeBadgeLabel(fee = {}) {
  return feeCategoryLabel(fee);
}

function orderFeeBadgeClass(fee = {}) {
  return {
    advance: feeCategoryLabel(fee) === "代垫"
  };
}

function orderFeeAdvanceAddress(fee = {}) {
  return String(fee.advanceAddress || fee.advance_address || "").trim();
}

function orderFeeStatementAmountText(fee = {}) {
  const name = String(fee.name || "").trim() || "费用";
  const currency = currencyCodeDisplay(fee.currency || "港币") || "";
  return [name, currency, money(fee.amount || 0)].filter(Boolean).join(" ");
}

function orderFeeAdvanceAddressStatementDisplay(fee = {}) {
  return normalizeUserText(orderFeeAdvanceAddress(fee), {
    singleLine: true,
    compactCjkSpacing: true
  });
}

function orderFeeStatementText(fee = {}) {
  if (isAdvanceFee(fee)) {
    const address = orderFeeAdvanceAddressStatementDisplay(fee);
    const amountText = money(fee.amount || 0);
    if (address && amountText) return `${address}：${amountText}`;
  }
  const amountText = orderFeeStatementAmountText(fee);
  if (!isAdvanceFee(fee)) return amountText;
  return [orderFeeAdvanceAddressStatementDisplay(fee), amountText].filter(Boolean).join(" ");
}

function feeAmountHKD(fee = {}) {
  const currency = String(fee.currency || "港币").toUpperCase();
  if (currency === "人民币" || currency === "RMB") return 0;
  return Number(fee.amount || 0);
}

function feeAmountRMB(fee = {}) {
  const currency = String(fee.currency || "港币").toUpperCase();
  if (currency === "人民币" || currency === "RMB") return Number(fee.amount || 0);
  return 0;
}

function feeItemForFee(fee = {}) {
  const feeItemId = String(fee.feeItemId || fee.fee_item_id || "").trim();
  const feeName = String(fee.name || "").trim();
  return (feeItemId ? feeItemRowsById.value.get(feeItemId) : null)
    || (feeName ? feeItemRowsByName.value.get(feeName) : null)
    || null;
}

function orderCustomerReceivableBreakdown(order = {}) {
  const fees = Array.isArray(order?.fees) ? order.fees : [];
  const namedFees = fees.filter((fee) => String(fee?.name || "").trim());
  if (!namedFees.length) {
    return {
      hkd: Number(order.receivableHKD || 0),
      rmb: Number(order.receivableRMB || 0)
    };
  }
  return namedFees
    .reduce((sum, fee) => ({
      hkd: sum.hkd + feeAmountHKD(fee),
      rmb: sum.rmb + feeAmountRMB(fee)
    }), { hkd: 0, rmb: 0 });
}

function customerStatementOrderSnapshot(order = {}) {
  const totals = orderCustomerReceivableBreakdown(order);
  return {
    ...order,
    receivableHKD: totals.hkd,
    receivableRMB: totals.rmb,
    chargedAt: order.chargedAt || "",
    fees: Array.isArray(order.fees) ? order.fees : []
  };
}

function isChargedOrder(order = {}) {
  return Boolean(String(order?.chargedAt || "").trim());
}

function customerStatementOrderIncludedInTotals(order = {}) {
  return !isChargedOrder(order);
}

function customerStatementOrderDisplayChargeNote(order = {}) {
  const chargedAt = String(order?.chargedAt || "").trim();
  if (!chargedAt) return "";
  const matched = chargedAt.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!matched) return "";
  return `于${matched[1]}年${matched[2]}月${matched[3]}日已收费`;
}

function orderDriverNameByRole(order, role = "") {
  const normalizedRole = String(role || "").trim();
  if (normalizedRole === "香港司机") return String(order?.hkDriver || order?.driver || "").trim();
  if (normalizedRole === "大陆骑师") return orderIsDoubleDriverMode(order) ? String(order?.mainlandDriver || "").trim() : "";
  if (normalizedRole === "跟随订单司机") return String(order?.driver || order?.hkDriver || order?.mainlandDriver || "").trim();
  return "";
}

function feeAssignedDriverName(order, fee = {}) {
  if (!order || !fee) return "";
  if (fee.driverName) return String(fee.driverName || "").trim();
  const explicitRole = String(fee.driverRole || fee.driver_role || "").trim();
  if (explicitRole && explicitRole !== "手动指定") return orderDriverNameByRole(order, explicitRole);
  const defaultRole = feeItemForFee(fee)?.defaultDriverRole || "";
  if (defaultRole && defaultRole !== "手动指定") return orderDriverNameByRole(order, defaultRole);
  if (normalizeTransportMode(order.transportMode || "单司机") === "单司机") {
    return String(order.driver || order.hkDriver || order.mainlandDriver || "").trim();
  }
  return "";
}

function crossBorderFreightDriverRoles(order = orderForm, fee = {}) {
  if (!isCrossBorderFreightFee(fee)) return [];
  const mode = normalizeTransportMode(order.transportMode || "单司机") || "单司机";
  if (mode === "双司机") return ["香港司机", "大陆骑师"];
  if (mode === "单司机" || isDomesticTransferMode(mode)) return ["香港司机"];
  return ["香港司机"];
}

function orderFeeDriverRoleDisplay(fee = {}) {
  const freightRoles = crossBorderFreightDriverRoles(orderForm, fee);
  const names = freightRoles
    .map((role) => orderDriverNameByRole(orderForm, role))
    .filter(Boolean);
  return names.length ? names.join("、") : "-";
}

function orderFeeDriverRoleTitle(fee = {}) {
  const freightRoles = crossBorderFreightDriverRoles(orderForm, fee);
  if (!freightRoles.length) return "";
  return freightRoles
    .map((role) => `${role}：${orderDriverNameByRole(orderForm, role) || "未选择"}`)
    .join(" / ");
}

function orderFeeAutoDriverRole(fee = {}, order = orderForm) {
  if (isCrossBorderFreightFee(fee)) {
    const roles = crossBorderFreightDriverRoles(order, fee);
    return roles.length === 1 ? roles[0] : (roles.length > 1 ? "跟随订单司机" : "");
  }
  return String(feeItemForFee(fee)?.defaultDriverRole || fee.driverRole || "").trim();
}

function normalizeOrderFeeAssigneeText(value = "") {
  return normalizeUserText(value, { singleLine: true, compactCjkSpacing: true });
}

function orderFeeHasManualAssignee(fee = {}) {
  return Boolean(fee._manualAssignee)
    || String(fee.driverRole || fee.driver_role || "").trim() === "手动指定"
    || Boolean(normalizeOrderFeeAssigneeText(fee.driverName || fee.driver_name));
}

function normalizeOrderFeeManualAssigneeFlag(fee = {}) {
  return orderFeeHasManualAssignee(fee);
}

function orderFeeDisplayAssigneeName(value = "", order = orderForm) {
  const text = normalizeOrderFeeAssigneeText(value);
  if (!text) return "";
  return normalizeVehicleSource(order?.vehicleSource) === "外派车辆"
    ? (supplierDisplayLabel(text) || text)
    : text;
}

function orderFeeDefaultAssigneeNames(fee = {}, order = orderForm) {
  if (isCompanyCoveredFee(fee)) return ["公司承担"];
  if (normalizeVehicleSource(order?.vehicleSource) === "外派车辆") return uniqueOrderCostNames([supplierDisplayLabel(order.supplier)]);
  if (normalizeVehicleSource(order?.vehicleSource) !== OWN_VEHICLE_SOURCE) return [];
  const mode = normalizeTransportMode(order.transportMode || "单司机") || "单司机";
  const driver = String(order.driver || "").trim();
  const hkDriver = String(order.hkDriver || driver || "").trim();
  const mainlandDriver = String(order.mainlandDriver || "").trim();
  const role = orderFeeAutoDriverRole(fee, order);
  if (role === "香港司机") return uniqueOrderCostNames([hkDriver, driver]);
  if (role === "大陆骑师") return mode === "双司机" ? uniqueOrderCostNames([mainlandDriver]) : [];
  if (role === "跟随订单司机") {
    return mode === "双司机"
      ? uniqueOrderCostNames([driver, hkDriver, mainlandDriver, ...driver.split("/")])
      : uniqueOrderCostNames([driver, hkDriver, ...driver.split("/")]);
  }
  if (mode === "双司机" && isCrossBorderFreightFee(fee)) {
    return uniqueOrderCostNames([hkDriver, mainlandDriver]);
  }
  return uniqueOrderCostNames([hkDriver, driver]);
}

function orderFeeAssigneeNames(fee = {}, order = orderForm) {
  if (isCompanyCoveredFee(fee)) return ["公司承担"];
  const manualName = normalizeOrderFeeAssigneeText(fee.driverName || fee.driver_name);
  if (orderFeeHasManualAssignee(fee)) return manualName ? uniqueOrderCostNames([manualName]) : [];
  return orderFeeDefaultAssigneeNames(fee, order);
}

function orderFeeAssigneeDisplay(fee = {}) {
  return orderFeeAssigneeNames(fee).join("、") || "-";
}

function orderFeeAssigneeInputValue(fee = {}) {
  const manualName = normalizeOrderFeeAssigneeText(fee.driverName || fee.driver_name);
  return orderFeeHasManualAssignee(fee) ? manualName : orderFeeAssigneeDisplay(fee);
}

function orderFeeAssigneeTitle(fee = {}) {
  const names = orderFeeAssigneeNames(fee);
  if (isCompanyCoveredFee(fee)) return names.length ? names.join("、") : "公司承担";
  if (orderFeeHasManualAssignee(fee)) return names.length ? `手动归属：${names.join("、")}` : "手动归属";
  if (normalizeVehicleSource(orderForm.vehicleSource) === "外派车辆") return names.length ? `外派供应商：${names.join("、")}` : "未选择外派供应商";
  if (normalizeVehicleSource(orderForm.vehicleSource) === OWN_VEHICLE_SOURCE) return names.length ? `归属：${names.join("、")}` : "未选择香港司机";
  return "";
}

function resetOrderFeeAssignee(fee = {}) {
  if (!fee || isCompanyCoveredFee(fee)) return;
  fee._manualAssignee = false;
  fee.driverName = "";
  fee.driverRole = orderFeeAutoDriverRole(fee);
  scheduleOrderFeeCostSync();
}

function handleOrderFeeAssigneeInput(fee = {}, event = null) {
  if (!fee || orderReadOnlyMode.value || isCompanyCoveredFee(fee)) return;
  const value = normalizeOrderFeeAssigneeText(event?.target?.value ?? "");
  fee._manualAssignee = true;
  fee.driverRole = "手动指定";
  fee.driverName = value;
  scheduleOrderFeeCostSync();
}

function syncCrossBorderFreightDriverRole(fee = {}) {
  if (!isCrossBorderFreightFee(fee)) return;
  if (orderFeeHasManualAssignee(fee)) return;
  const roles = crossBorderFreightDriverRoles(orderForm, fee);
  fee.driverRole = roles.length === 1 ? roles[0] : (roles.length > 1 ? "跟随订单司机" : "");
  fee.driverName = "";
}

function syncCrossBorderFreightDriverRoles() {
  orderFees.value.forEach((fee) => syncCrossBorderFreightDriverRole(fee));
}

function orderFeeDriverOptions() {
  const names = [
    orderForm.hkDriver,
    orderForm.mainlandDriver,
    orderForm.driver
  ].map((value) => String(value || "").trim()).filter(Boolean);
  return Array.from(new Set(names));
}

function advanceFeesForOrder(order, driver = null) {
  if (driver && isMainlandRiderDriver(driver) && !orderHasMainlandRiderCostAndWage(order, driver)) return [];
  return (Array.isArray(order?.fees) ? order.fees : [])
    .filter(isAdvanceFee)
    .filter((fee) => !driver || feeAssignedDriverName(order, fee) === driver.name);
}

function orderAdvanceFeeBreakdown(order, driver = null) {
  return advanceFeesForOrder(order, driver)
    .reduce((sum, fee) => ({
      hkd: sum.hkd + feeAmountHKD(fee),
      rmb: sum.rmb + feeAmountRMB(fee)
    }), { hkd: 0, rmb: 0 });
}

function orderAdvanceFeeDetailBreakdown(order) {
  return orderAdvanceFeeBreakdown(order);
}

function orderAdvanceFeeHKD(order) {
  return orderAdvanceFeeBreakdown(order).hkd;
}

function orderAdvanceFeeRMB(order) {
  return orderAdvanceFeeBreakdown(order).rmb;
}

function orderAdvanceFeeBelongsToDriver(order) {
  return normalizeVehicleSource(order?.vehicleSource) === OWN_VEHICLE_SOURCE;
}

function orderAdvanceFeeBelongsToDriverRow(order, driver) {
  return orderAdvanceFeeBelongsToDriver(order) && Boolean(driver) && advanceFeesForOrder(order, driver).length > 0;
}

function orderAdvanceFeeBelongsToSupplier(order) {
  return order?.vehicleSource === "外派车辆";
}

const FINANCE_STAT_APPROVED_ORDER_STATUS = "已审核";

function isFinanceStatEligibleOrder(order = {}) {
  return String(order?.status || "").trim() === FINANCE_STAT_APPROVED_ORDER_STATUS;
}

function isFinanceStatVisibleOrder(order = {}) {
  return isFinanceStatEligibleOrder(order) && isOrderVisibleInOrderManagement(order);
}

function isFinanceDateMatch(dateValue) {
  return dateMatchesPeriodFilter(dateValue, financePeriodFilter.value);
}

const financeOrderRows = computed(() =>
  orderRows.value.filter((order) =>
    isFinanceStatVisibleOrder(order) &&
    isFinanceDateMatch(order.date)
  )
);

const financeAdjustmentRows = computed(() =>
  driverAdjustmentRows.value.filter((item) => isFinanceDateMatch(item.date))
);

function customsBusinessCustomFieldName(field = {}) {
  return String(field?.name ?? field?.label ?? field?.key ?? "").trim();
}

function isFixedCustomsBusinessFieldName(name = "") {
  return ["舱单费", ...Object.values(CUSTOMER_CUSTOMS_FEE_FIELD_NAMES)].includes(String(name || "").trim());
}

function normalizeCustomsCustomerDefaultFields(fields = []) {
  return normalizeCustomsBusinessCustomFields(fields)
    .filter((field) => !isFixedCustomsBusinessFieldName(field.name));
}

function customsBusinessIntegerValue(value) {
  const number = Number(value || 0);
  if (!Number.isFinite(number) || number < 0) return 0;
  return Math.round(number);
}

function preventCustomsBusinessDecimalInput(event) {
  if ([".", "e", "E", "+", "-"].includes(event?.key)) {
    event.preventDefault();
  }
}

function normalizeCustomsBusinessIntegerInput(target, key, event) {
  if (!target || !key) return;
  const rawValue = event?.target?.value ?? target[key];
  if (String(rawValue ?? "") === "") {
    target[key] = "";
    return;
  }
  const nextValue = customsBusinessIntegerValue(rawValue);
  target[key] = nextValue;
  if (event?.target && event.target.value !== String(nextValue)) {
    event.target.value = String(nextValue);
  }
}

function normalizeCustomsBusinessFormIntegers() {
  [
    "itemCount",
    "pageCount",
    "customsFee",
    "pageFee",
    "manifestFee",
    "inspectionFee",
    "checkFee",
    "verificationFee",
    "fajian3cFee",
    "otherFee"
  ].forEach((key) => {
    customsBusinessForm[key] = customsBusinessIntegerValue(customsBusinessForm[key]);
  });
  if (Array.isArray(customsBusinessForm.customFields)) {
    customsBusinessForm.customFields.forEach((field) => {
      field.value = customsBusinessIntegerValue(field.value);
    });
  }
}

function customsBusinessCustomFieldAmount(field = {}) {
  const amount = Number(field?.value ?? field?.amount ?? field?.fee ?? 0);
  return Number.isFinite(amount) ? amount : 0;
}

function customsBusinessCustomFieldsForSave(fields = [], fixedFee = 0) {
  const normalizedFields = normalizeCustomsBusinessCustomFields(fields)
    .filter((field) => customsBusinessCustomFieldName(field) !== CUSTOMS_BUSINESS_FIXED_FEE_NAME);
  return normalizeCustomsBusinessCustomFields([
    {
      name: CUSTOMS_BUSINESS_FIXED_FEE_NAME,
      value: customsBusinessIntegerValue(fixedFee)
    },
    ...normalizedFields
  ]);
}

function normalizeCustomsBusinessCustomFields(fields = []) {
  if (!Array.isArray(fields)) return [];
  const fieldsByName = new Map();
  fields.forEach((field) => {
    const name = customsBusinessCustomFieldName(field);
    if (!name) return;
    fieldsByName.set(name, {
      name,
      value: (fieldsByName.get(name)?.value || 0) + customsBusinessCustomFieldAmount(field)
    });
  });
  return Array.from(fieldsByName.values()).slice(0, 40);
}

function customBusinessHasIncompleteCustomField() {
  return Array.isArray(customsBusinessForm.customFields)
    && customsBusinessForm.customFields.some((field) =>
      !customsBusinessCustomFieldName(field) && customsBusinessCustomFieldAmount(field) !== 0
    );
}

function customerHasIncompleteCustomsCustomField() {
  return Array.isArray(customerForm.customsCustomFields)
    && customerForm.customsCustomFields.some((field) =>
      !customsBusinessCustomFieldName(field) && customsBusinessCustomFieldAmount(field) !== 0
    );
}

function addCustomsBusinessCustomField() {
  if (!Array.isArray(customsBusinessForm.customFields)) {
    customsBusinessForm.customFields = [];
  }
  customsBusinessForm.customFields.push(createBlankCustomsBusinessCustomField());
}

function removeCustomsBusinessCustomField(index) {
  if (!Array.isArray(customsBusinessForm.customFields)) return;
  customsBusinessForm.customFields.splice(index, 1);
}

function addCustomerCustomsCustomField() {
  if (!Array.isArray(customerForm.customsCustomFields)) {
    customerForm.customsCustomFields = [];
  }
  customerForm.customsCustomFields.push(createBlankCustomsBusinessCustomField());
}

function removeCustomerCustomsCustomField(index) {
  if (!Array.isArray(customerForm.customsCustomFields)) return;
  customerForm.customsCustomFields.splice(index, 1);
}

const customsBusinessFormTotal = computed(() =>
  Number(customsBusinessForm.pageFee || 0)
  + Number(customsBusinessForm.customsFee || 0)
  + Number(customsBusinessForm.manifestFee || 0)
  + Number(customsBusinessForm.inspectionFee || 0)
  + Number(customsBusinessForm.checkFee || 0)
  + (customsBusinessShowsVerificationFee.value ? Number(customsBusinessForm.verificationFee || 0) : 0)
  + Number(customsBusinessForm.fajian3cFee || 0)
  + normalizeCustomsBusinessCustomFields(customsBusinessForm.customFields)
    .reduce((sum, field) => sum + customsBusinessCustomFieldAmount(field), 0)
);

const customsBusinessCustomerOptions = computed(() =>
  customerRows.value
    .filter((item) =>
      item.type === "客户"
      && customerCategoryValue(item) === "报关客户"
      && String(item.name || "").trim()
    )
    .slice()
    .sort((left, right) =>
      String(left.name || "").localeCompare(String(right.name || ""), "zh-Hans-CN", {
        numeric: true,
        sensitivity: "base"
      })
    )
);

const customsBusinessFilteredCustomerOptions = computed(() => {
  const keyword = normalizedCustomsBusinessSearchText(customsBusinessCompanySearch.value);
  const selectedCompany = String(customsBusinessForm.company || "").trim();
  const filtered = customsBusinessCustomerOptions.value.filter((customer) => {
    const name = String(customer.name || "").trim();
    const shortName = customerShortDisplay(customer);
    const customerType = String(customer.customsCustomerType || "").trim();
    if (!keyword) return true;
    return normalizedCustomsBusinessSearchText([name, shortName, customerType, customer.id].join(" ")).includes(keyword);
  });
  if (selectedCompany && !filtered.some((customer) => String(customer.name || "").trim() === selectedCompany)) {
    const selected = customsBusinessCustomerOptions.value.find((customer) => String(customer.name || "").trim() === selectedCompany);
    if (selected) filtered.unshift(selected);
  }
  return filtered;
});

function findCustomsBusinessCustomerByName(company = customsBusinessForm.company) {
  const target = String(company || "").trim();
  if (!target) return null;
  return customsBusinessCustomerOptions.value.find((customer) =>
    String(customer.name || "").trim() === target
    || String(customer.shortName || customer.short_name || "").trim() === target
  ) || null;
}

function customsBusinessCompanySelectedFromCustomers(company = customsBusinessForm.company) {
  return Boolean(findCustomsBusinessCustomerByName(company));
}

function openCustomsBusinessCompanyPicker() {
  customsBusinessCompanyPickerOpen.value = true;
}

function closeCustomsBusinessCompanyPicker() {
  customsBusinessCompanyPickerOpen.value = false;
  const selectedCompany = String(customsBusinessForm.company || "").trim();
  if (selectedCompany) {
    const selectedCustomer = findCustomsBusinessCustomerByName(selectedCompany);
    const displayName = customerShortDisplay(selectedCustomer) || selectedCompany;
    if (customsBusinessCompanySearch.value !== displayName) {
      customsBusinessCompanySearch.value = displayName;
    }
  }
}

function handleCustomsBusinessCompanyInput(event) {
  const value = String(event?.target?.value || "").trim();
  customsBusinessCompanySearch.value = value;
  customsBusinessCompanyPickerOpen.value = true;
  const exactCustomer = findCustomsBusinessCustomerByName(value);
  customsBusinessForm.company = exactCustomer ? exactCustomer.name : "";
  if (exactCustomer) applyCustomsBusinessCustomerDefaultFields(exactCustomer);
}

function selectCustomsBusinessCompany(customer) {
  const company = String(customer?.name || "").trim();
  customsBusinessForm.company = company;
  customsBusinessCompanySearch.value = customerShortDisplay(customer) || company;
  applyCustomsBusinessCustomerDefaultFields(customer);
  customsBusinessCompanyPickerOpen.value = false;
}

function applyCustomsBusinessCustomerDefaultFields(customer = customsBusinessSelectedCustomer.value) {
  if (!customer || editingCustomsBusinessId.value || copyingCustomsBusinessId.value) return;
  const defaults = normalizeCustomsCustomerDefaultFields(customer.customsCustomFields);
  customsBusinessForm.customFields = defaults.map((field) => ({
    name: field.name,
    value: customsBusinessIntegerValue(field.value)
  }));
}

function clearCustomsBusinessCompany() {
  customsBusinessForm.company = "";
  customsBusinessCompanySearch.value = "";
  customsBusinessCompanyPickerOpen.value = true;
}

function confirmFirstCustomsBusinessCompanyOption() {
  const [firstCustomer] = customsBusinessFilteredCustomerOptions.value;
  if (firstCustomer) selectCustomsBusinessCompany(firstCustomer);
}

const customsBusinessSelectedCustomer = computed(() =>
  findCustomsBusinessCustomerByName(customsBusinessForm.company)
);

function customsBusinessNeedsVerificationFee(direction = customsBusinessForm.direction) {
  return ["金二进口", "金二出口"].includes(String(direction || "").trim());
}

const customsBusinessShowsVerificationFee = computed(() =>
  customsBusinessNeedsVerificationFee()
);

function customsBusinessDirectionFeeType(direction = customsBusinessForm.direction) {
  const text = String(direction || "").trim();
  if (text.includes("进口")) return "import";
  if (text.includes("出口")) return "export";
  return "";
}

function nonNegativeCustomsConfigNumber(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : fallback;
}

function positiveCustomsConfigNumber(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : fallback;
}

const customsBusinessPageUnitFee = computed(() => {
  const customer = customsBusinessSelectedCustomer.value;
  const feeType = customsBusinessDirectionFeeType();
  if (!customer || !feeType) return 0;
  const key = feeType === "import" ? "customsImportPageFee" : "customsExportPageFee";
  return Number(customer[key] ?? 0) || 0;
});

const customsBusinessDeclarationUnitFee = computed(() => {
  const customer = customsBusinessSelectedCustomer.value;
  const feeType = customsBusinessDirectionFeeType();
  if (!customer || !feeType) return 0;
  const key = feeType === "import" ? "customsImportDeclarationFee" : "customsExportDeclarationFee";
  return Number(customer[key] ?? 0) || 0;
});

function customsBusinessConfiguredVerificationFee() {
  if (!customsBusinessShowsVerificationFee.value) return 0;
  const customer = customsBusinessSelectedCustomer.value;
  return customsBusinessIntegerValue(customer?.customsVerificationFee ?? DEFAULT_CUSTOMS_CUSTOMER_CONFIG.customsVerificationFee);
}

function customsBusinessConfiguredManifestFee() {
  const customer = customsBusinessSelectedCustomer.value;
  return customsBusinessIntegerValue(customer?.customsManifestFee ?? DEFAULT_CUSTOMS_CUSTOMER_CONFIG.customsManifestFee);
}

const calculatedCustomsBusinessPageCount = computed(() => {
  const customer = customsBusinessSelectedCustomer.value;
  if (!customer) return 0;
  const itemCount = Math.max(0, Number(customsBusinessForm.itemCount || 0));
  const homeItemCount = nonNegativeCustomsConfigNumber(customer.customsHomeItemCount, DEFAULT_CUSTOMS_CUSTOMER_CONFIG.customsHomeItemCount);
  const pageItemCount = positiveCustomsConfigNumber(customer.customsPageItemCount, DEFAULT_CUSTOMS_CUSTOMER_CONFIG.customsPageItemCount);
  if (itemCount <= homeItemCount || pageItemCount <= 0) return 0;
  return Math.ceil((itemCount - homeItemCount) / pageItemCount);
});

const calculatedCustomsBusinessPageFee = computed(() =>
  calculatedCustomsBusinessPageCount.value * customsBusinessPageUnitFee.value
);

function calculatedCustomsBusinessChargeValues() {
  const feeType = customsBusinessDirectionFeeType();
  return {
    customsFee: feeType ? customsBusinessDeclarationUnitFee.value : 0,
    pageCount: feeType ? calculatedCustomsBusinessPageCount.value : 0,
    pageFee: feeType ? calculatedCustomsBusinessPageFee.value : 0,
    manifestFee: customsBusinessConfiguredManifestFee(),
    verificationFee: customsBusinessConfiguredVerificationFee()
  };
}

function setCustomsBusinessAutoChargeBaseline(values = {}) {
  customsBusinessAutoCharges.customsFee = customsBusinessIntegerValue(values.customsFee);
  customsBusinessAutoCharges.pageCount = customsBusinessIntegerValue(values.pageCount);
  customsBusinessAutoCharges.pageFee = customsBusinessIntegerValue(values.pageFee);
  customsBusinessAutoCharges.manifestFee = customsBusinessIntegerValue(values.manifestFee);
  customsBusinessAutoCharges.verificationFee = customsBusinessIntegerValue(values.verificationFee);
}

function maybeApplyCustomsBusinessAutoCharge(key, value, options = {}) {
  const nextValue = customsBusinessIntegerValue(value);
  const currentValue = customsBusinessIntegerValue(customsBusinessForm[key]);
  const previousAutoValue = customsBusinessIntegerValue(customsBusinessAutoCharges[key]);
  const shouldApply = options.force || currentValue === previousAutoValue;
  if (shouldApply && currentValue !== nextValue) {
    customsBusinessForm[key] = nextValue;
  }
  if (shouldApply) {
    customsBusinessAutoCharges[key] = nextValue;
  }
}

function syncCalculatedCustomsBusinessCharges(options = {}) {
  const calculated = calculatedCustomsBusinessChargeValues();
  maybeApplyCustomsBusinessAutoCharge("customsFee", calculated.customsFee, options);
  maybeApplyCustomsBusinessAutoCharge("manifestFee", calculated.manifestFee, options);
  maybeApplyCustomsBusinessAutoCharge("verificationFee", calculated.verificationFee, options);
  const feeType = customsBusinessDirectionFeeType();
  if (!feeType) {
    if (!String(customsBusinessForm.direction || "").trim()) {
      maybeApplyCustomsBusinessAutoCharge("pageCount", 0, options);
      maybeApplyCustomsBusinessAutoCharge("pageFee", 0, options);
    }
    return;
  }
  maybeApplyCustomsBusinessAutoCharge("pageCount", calculated.pageCount, options);
  maybeApplyCustomsBusinessAutoCharge("pageFee", calculated.pageFee, options);
}

watch(
  [
    () => customsBusinessForm.company,
    () => customsBusinessForm.direction,
    () => customsBusinessForm.itemCount,
    () => customsBusinessSelectedCustomer.value?.customsHomeItemCount,
    () => customsBusinessSelectedCustomer.value?.customsPageItemCount,
    () => customsBusinessSelectedCustomer.value?.customsImportDeclarationFee,
    () => customsBusinessSelectedCustomer.value?.customsExportDeclarationFee,
    () => customsBusinessSelectedCustomer.value?.customsImportPageFee,
    () => customsBusinessSelectedCustomer.value?.customsExportPageFee,
    () => customsBusinessSelectedCustomer.value?.customsManifestFee,
    () => customsBusinessSelectedCustomer.value?.customsVerificationFee
  ],
  syncCalculatedCustomsBusinessCharges,
  { immediate: true }
);

function normalizedCustomsBusinessSearchText(value = "") {
  return String(value || "").trim().toLowerCase();
}

function customsBusinessSearchValues(row = {}) {
  const customer = customsBusinessNameValues(row)
    .map((value) => findCustomsBusinessCustomerByName(value))
    .find(Boolean);
  return [
    row.company,
    row.customer,
    row.customerName,
    row.customer_name,
    customer?.shortName,
    customer?.customsCustomerType,
    row.declarationNo,
    row.sixSheetNo,
    row.direction,
    row.remark,
    row.date,
    ...normalizeCustomsBusinessCustomFields(row.customFields).flatMap((field) => [field.name, field.value])
  ];
}

function customsBusinessNameValues(row = {}) {
  return [row.company, row.customer, row.customerName, row.customer_name];
}

function customsBusinessMatchesFilters(row = {}) {
  const keyword = normalizedCustomsBusinessSearchText(customsBusinessSearchKeyword.value);
  if (keyword && !customsBusinessSearchValues(row).some((value) =>
    normalizedCustomsBusinessSearchText(value).includes(keyword)
  )) return false;

  if (customsBusinessCompanyFilter.value) {
    const companyValues = customsBusinessNameValues(row).map(normalizedOrderFilterText);
    if (!companyValues.includes(customsBusinessCompanyFilter.value)) return false;
  }

  if (customsBusinessDirectionFilter.value && row.direction !== customsBusinessDirectionFilter.value) return false;
  return true;
}

const filteredCustomsBusinessRows = computed(() =>
  customsBusinessRows.value.filter((row) => customsBusinessMatchesFilters(row))
);

const customsBusinessCustomColumns = computed(() => {
  const names = [];
  const seen = new Set();
  customsBusinessRows.value.forEach((row) => {
    normalizeCustomsBusinessCustomFields(row.customFields).forEach((field) => {
      if (seen.has(field.name)) return;
      seen.add(field.name);
      names.push(field.name);
    });
  });
  return names;
});

function customsBusinessCustomColumnKey(name = "") {
  return `custom:${String(name || "").trim()}`;
}

function customsBusinessCustomColumnName(key = "") {
  return String(key || "").startsWith("custom:") ? String(key).slice(7) : "";
}

const customsBusinessBaseColumns = computed(() => {
  const customColumns = customsBusinessCustomColumns.value.map((name) => ({
    key: customsBusinessCustomColumnKey(name),
    label: name,
    width: 112,
    amount: true,
    custom: true
  }));
  return [
    ...CUSTOMS_BUSINESS_PREFIX_COLUMNS,
    ...customColumns,
    ...CUSTOMS_BUSINESS_SUFFIX_COLUMNS
  ].map((column, index) => ({ ...column, defaultIndex: index }));
});

const orderedCustomsBusinessColumns = computed(() => {
  const columns = customsBusinessBaseColumns.value;
  const byKey = new Map(columns.map((column) => [column.key, column]));
  const savedKeys = Array.isArray(customsBusinessColumnOrder.value)
    ? customsBusinessColumnOrder.value.filter((key) => byKey.has(key) && key !== "actions")
    : [];
  const used = new Set(savedKeys);
  const ordered = savedKeys.map((key) => byKey.get(key));
  columns
    .filter((column) => column.key !== "actions" && !used.has(column.key))
    .forEach((column) => {
      const insertIndex = ordered.findIndex((item) => (item.defaultIndex ?? 999) > (column.defaultIndex ?? 999));
      if (insertIndex >= 0) ordered.splice(insertIndex, 0, column);
      else ordered.push(column);
    });
  const actionsColumn = byKey.get("actions");
  return actionsColumn ? [...ordered, actionsColumn] : ordered;
});

const customsBusinessExportColumns = computed(() =>
  orderedCustomsBusinessColumns.value
    .filter((column) => column.exportable !== false)
    .map((column) => ({
      key: column.key,
      label: column.label
    }))
);

const customsBusinessTableMinWidth = computed(() =>
  `${orderedCustomsBusinessColumns.value.reduce((sum, column) => sum + customsBusinessColumnWidth(column), 0)}px`
);

function customsBusinessTableStyle() {
  return {
    width: `max(100%, ${customsBusinessTableMinWidth.value})`,
    minWidth: customsBusinessTableMinWidth.value
  };
}

function customsBusinessCustomFieldEntry(row = {}, columnName = "") {
  const target = String(columnName || "").trim();
  if (!target) return null;
  return normalizeCustomsBusinessCustomFields(row.customFields)
    .find((field) => field.name === target) || null;
}

function customsBusinessCustomFieldDisplay(row = {}, columnName = "") {
  const field = customsBusinessCustomFieldEntry(row, columnName);
  return field ? money(field.value) : "";
}

function customsBusinessColumnStyle(column = {}) {
  const width = customsBusinessColumnWidth(column);
  return { width: `${width}px`, minWidth: `${width}px` };
}

function customsBusinessColumnWidth(column = {}) {
  return clampColumnWidth(column, Number(customsBusinessColumnWidths[column.key]));
}

function customsBusinessCellText(row = {}, column = {}) {
  if (column.custom) return customsBusinessCustomFieldDisplay(row, customsBusinessCustomColumnName(column.key));
  const values = {
    date: row.date || "",
    declarationNo: row.declarationNo || "",
    sixSheetNo: row.sixSheetNo || "",
    company: partnerDisplayLabel(row.company || "", "客户") || row.company || "",
    direction: row.direction || "",
    itemCount: row.itemCount || "",
    pageCount: row.pageCount || "",
    customsFee: money(row.customsFee),
    pageFee: money(row.pageFee),
    manifestFee: money(row.manifestFee),
    inspectionFee: money(row.inspectionFee),
    checkFee: money(row.checkFee),
    verificationFee: money(row.verificationFee),
    otherFee: money(row.otherFee),
    total: money(row.total),
    remark: row.remark || ""
  };
  return values[column.key] ?? "";
}

function saveCustomsBusinessColumnOrder(columns = orderedCustomsBusinessColumns.value) {
  const keys = columns
    .filter((column) => column.key !== "actions")
    .map((column) => column.key);
  customsBusinessColumnOrder.value = keys;
  saveStoredJson(CUSTOMS_BUSINESS_COLUMN_ORDER_KEY, keys);
  saveAccountTablePreferencesSoon();
}

function moveCustomsBusinessColumn(column = {}, offset = 0) {
  if (!column?.key || column.key === "actions") return;
  const columns = orderedCustomsBusinessColumns.value.filter((item) => item.key !== "actions");
  const fromIndex = columns.findIndex((item) => item.key === column.key);
  const toIndex = fromIndex + offset;
  if (fromIndex < 0 || toIndex < 0 || toIndex >= columns.length) return;
  const [moved] = columns.splice(fromIndex, 1);
  columns.splice(toIndex, 0, moved);
  saveCustomsBusinessColumnOrder(columns);
}

function startCustomsBusinessColumnDrag(column, event) {
  if (!column?.key || column.key === "actions") return;
  draggedCustomsBusinessColumnKey = column.key;
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData("text/plain", column.key);
}

function dropCustomsBusinessColumn(column) {
  if (!draggedCustomsBusinessColumnKey || !column?.key || column.key === "actions") return;
  const columns = orderedCustomsBusinessColumns.value.filter((item) => item.key !== "actions");
  const fromIndex = columns.findIndex((item) => item.key === draggedCustomsBusinessColumnKey);
  const toIndex = columns.findIndex((item) => item.key === column.key);
  if (fromIndex >= 0 && toIndex >= 0 && fromIndex !== toIndex) {
    const [moved] = columns.splice(fromIndex, 1);
    const nextTargetIndex = columns.findIndex((item) => item.key === column.key);
    columns.splice(nextTargetIndex, 0, moved);
    saveCustomsBusinessColumnOrder(columns);
  }
  draggedCustomsBusinessColumnKey = "";
}

function endCustomsBusinessColumnDrag() {
  draggedCustomsBusinessColumnKey = "";
}

function resetCustomsBusinessColumnOrder() {
  localStorage.removeItem(CUSTOMS_BUSINESS_COLUMN_ORDER_KEY);
  customsBusinessColumnOrder.value = [];
  saveAccountTablePreferencesSoon();
  notify("已恢复报关业务默认列顺序");
}

function resetCustomsBusinessColumnWidths() {
  resetDataTableColumnWidths(CUSTOMS_BUSINESS_TABLE_ID, orderedCustomsBusinessColumns.value, customsBusinessColumnWidths);
}

const customsBusinessCompanyFilterOptions = computed(() =>
  orderFilterOptionValues(customsBusinessRows.value, customsBusinessNameValues)
    .filter((company) => customerNameMatchesCategory(company, "报关客户"))
);

const customsBusinessDirectionFilterOptions = computed(() =>
  orderFilterOptionValues(customsBusinessRows.value, (row) => [row.direction])
);

const customsBusinessFiltersActive = computed(() =>
  Boolean(
    customsBusinessSearchKeyword.value.trim()
      || customsBusinessCompanyFilter.value
      || customsBusinessDirectionFilter.value
  )
);

function clearCustomsBusinessFilters() {
  customsBusinessSearchKeyword.value = "";
  customsBusinessCompanyFilter.value = "";
  customsBusinessDirectionFilter.value = "";
}

watch(customsBusinessCompanyFilterOptions, (options) => {
  if (customsBusinessCompanyFilter.value && !options.includes(customsBusinessCompanyFilter.value)) {
    customsBusinessCompanyFilter.value = "";
  }
});

watch(customsBusinessDirectionFilterOptions, (options) => {
  if (customsBusinessDirectionFilter.value && !options.includes(customsBusinessDirectionFilter.value)) {
    customsBusinessDirectionFilter.value = "";
  }
});

const customsBusinessSummary = computed(() => {
  const rows = filteredCustomsBusinessRows.value;
  return {
    count: rows.length,
    declarationCount: rows.filter((row) => row.declarationNo || row.sixSheetNo).length,
    revenue: rows.reduce((sum, row) => sum + Number(row.total || 0), 0),
    inspectionFee: rows.reduce((sum, row) => sum + Number(row.inspectionFee || 0), 0)
  };
});

function otherBusinessAmount(value) {
  const number = Number(value || 0);
  if (!Number.isFinite(number) || number < 0) return 0;
  return Number(number.toFixed(2));
}

function normalizeOtherBusinessAmountInput(target, key, event) {
  if (!target || !key) return;
  const rawValue = event?.target?.value ?? target[key];
  const nextValue = otherBusinessAmount(rawValue);
  target[key] = nextValue;
  if (event?.type === "input") {
    const text = String(rawValue ?? "");
    if (text === "" || /^\d+(?:\.\d{0,2})?$/.test(text)) return;
  }
  if (event?.target && event.target.value !== String(nextValue)) {
    event.target.value = String(nextValue);
  }
}

function otherBusinessCustomFieldName(field = {}) {
  return String(field?.name ?? field?.label ?? field?.key ?? "").trim();
}

function normalizeOtherBusinessCustomFields(fields = []) {
  if (!Array.isArray(fields)) return [];
  const fieldsByName = new Map();
  fields.forEach((field) => {
    const name = otherBusinessCustomFieldName(field);
    if (!name) return;
    const current = fieldsByName.get(name) || { name, income: 0, cost: 0 };
    current.income = otherBusinessAmount(current.income + otherBusinessAmount(field.income ?? field.revenue ?? field.amount ?? field.value));
    current.cost = otherBusinessAmount(current.cost + otherBusinessAmount(field.cost ?? field.expense));
    current.profit = Number((current.income - current.cost).toFixed(2));
    fieldsByName.set(name, current);
  });
  return Array.from(fieldsByName.values()).slice(0, 40);
}

function otherBusinessCustomFieldProfit(field = {}) {
  return Number((otherBusinessAmount(field.income) - otherBusinessAmount(field.cost)).toFixed(2));
}

function otherBusinessRowTotals(row = {}) {
  const customTotals = normalizeOtherBusinessCustomFields(row.customFields)
    .reduce((sum, field) => ({
      income: sum.income + otherBusinessAmount(field.income),
      cost: sum.cost + otherBusinessAmount(field.cost)
    }), { income: 0, cost: 0 });
  const totalIncome = otherBusinessAmount(otherBusinessAmount(row.income ?? row.revenue) + customTotals.income);
  const totalCost = otherBusinessAmount(otherBusinessAmount(row.cost ?? row.expense) + customTotals.cost);
  return {
    totalIncome,
    totalCost,
    profit: Number((totalIncome - totalCost).toFixed(2))
  };
}

function normalizeOtherBusinessFormAmounts() {
  otherBusinessForm.cost = otherBusinessAmount(otherBusinessForm.cost);
  otherBusinessForm.income = otherBusinessAmount(otherBusinessForm.income);
  if (Array.isArray(otherBusinessForm.customFields)) {
    otherBusinessForm.customFields.forEach((field) => {
      field.income = otherBusinessAmount(field.income);
      field.cost = otherBusinessAmount(field.cost);
    });
  }
}

function otherBusinessHasIncompleteCustomField() {
  return Array.isArray(otherBusinessForm.customFields)
    && otherBusinessForm.customFields.some((field) =>
      !otherBusinessCustomFieldName(field)
      && (otherBusinessAmount(field.income) !== 0 || otherBusinessAmount(field.cost) !== 0)
    );
}

function addOtherBusinessCustomField() {
  if (!Array.isArray(otherBusinessForm.customFields)) {
    otherBusinessForm.customFields = [];
  }
  otherBusinessForm.customFields.push(createBlankOtherBusinessCustomField());
}

function removeOtherBusinessCustomField(index) {
  if (!Array.isArray(otherBusinessForm.customFields)) return;
  otherBusinessForm.customFields.splice(index, 1);
}

const otherBusinessFormTotals = computed(() => {
  const customTotals = normalizeOtherBusinessCustomFields(otherBusinessForm.customFields)
    .reduce((sum, field) => ({
      income: sum.income + otherBusinessAmount(field.income),
      cost: sum.cost + otherBusinessAmount(field.cost)
    }), { income: 0, cost: 0 });
  const totalIncome = otherBusinessAmount(otherBusinessForm.income + customTotals.income);
  const totalCost = otherBusinessAmount(otherBusinessForm.cost + customTotals.cost);
  return {
    totalIncome,
    totalCost,
    profit: Number((totalIncome - totalCost).toFixed(2))
  };
});

const otherBusinessCustomerOptions = computed(() =>
  customerRows.value
    .filter((item) => item.type === "客户" && String(item.name || "").trim())
    .slice()
    .sort((left, right) =>
      String(left.name || "").localeCompare(String(right.name || ""), "zh-Hans-CN", {
        numeric: true,
        sensitivity: "base"
      })
    )
);

const otherBusinessFilteredCustomerOptions = computed(() => {
  const keyword = normalizedCustomsBusinessSearchText(otherBusinessCustomerSearch.value);
  const selectedCustomer = String(otherBusinessForm.customer || "").trim();
  const filtered = otherBusinessCustomerOptions.value.filter((customer) => {
    const name = String(customer.name || "").trim();
    const shortName = customerShortDisplay(customer);
    if (!keyword) return true;
    return normalizedCustomsBusinessSearchText([name, shortName, customer.id].join(" ")).includes(keyword);
  });
  if (selectedCustomer && !filtered.some((customer) => String(customer.name || "").trim() === selectedCustomer)) {
    const selected = otherBusinessCustomerOptions.value.find((customer) => String(customer.name || "").trim() === selectedCustomer);
    if (selected) filtered.unshift(selected);
  }
  return filtered;
});

function findOtherBusinessCustomerByName(customerName = otherBusinessForm.customer) {
  const target = String(customerName || "").trim();
  if (!target) return null;
  return otherBusinessCustomerOptions.value.find((customer) =>
    String(customer.name || "").trim() === target
    || String(customer.shortName || customer.short_name || "").trim() === target
  ) || null;
}

function otherBusinessCustomerSelectedFromCustomers(customer = otherBusinessForm.customer) {
  return Boolean(findOtherBusinessCustomerByName(customer));
}

function openOtherBusinessCustomerPicker() {
  otherBusinessCustomerPickerOpen.value = true;
}

function closeOtherBusinessCustomerPicker() {
  otherBusinessCustomerPickerOpen.value = false;
  const selectedCustomer = String(otherBusinessForm.customer || "").trim();
  if (selectedCustomer) {
    const customer = findOtherBusinessCustomerByName(selectedCustomer);
    otherBusinessCustomerSearch.value = customerShortDisplay(customer) || selectedCustomer;
  }
}

function handleOtherBusinessCustomerInput(event) {
  const value = String(event?.target?.value || "").trim();
  otherBusinessCustomerSearch.value = value;
  otherBusinessCustomerPickerOpen.value = true;
  const exactCustomer = findOtherBusinessCustomerByName(value);
  otherBusinessForm.customer = exactCustomer ? exactCustomer.name : "";
}

function selectOtherBusinessCustomer(customer) {
  const customerName = String(customer?.name || "").trim();
  otherBusinessForm.customer = customerName;
  otherBusinessCustomerSearch.value = customerShortDisplay(customer) || customerName;
  otherBusinessCustomerPickerOpen.value = false;
}

function clearOtherBusinessCustomer() {
  otherBusinessForm.customer = "";
  otherBusinessCustomerSearch.value = "";
  otherBusinessCustomerPickerOpen.value = true;
}

function confirmFirstOtherBusinessCustomerOption() {
  const [firstCustomer] = otherBusinessFilteredCustomerOptions.value;
  if (firstCustomer) selectOtherBusinessCustomer(firstCustomer);
}

function otherBusinessSearchValues(row = {}) {
  return [
    row.title,
    row.customer,
    row.remark,
    row.date,
    row.income,
    row.cost,
    row.totalIncome,
    row.totalCost,
    row.profit,
    ...normalizeOtherBusinessCustomFields(row.customFields).flatMap((field) => [field.name, field.income, field.cost, field.profit])
  ];
}

function otherBusinessNameValues(row = {}) {
  return [row.customer];
}

function otherBusinessMatchesFilters(row = {}) {
  const keyword = normalizedCustomsBusinessSearchText(otherBusinessSearchKeyword.value);
  if (keyword && !otherBusinessSearchValues(row).some((value) =>
    normalizedCustomsBusinessSearchText(value).includes(keyword)
  )) return false;
  if (otherBusinessCustomerFilter.value) {
    const customerValues = otherBusinessNameValues(row).map(normalizedOrderFilterText);
    if (!customerValues.includes(otherBusinessCustomerFilter.value)) return false;
  }
  return true;
}

const filteredOtherBusinessRows = computed(() =>
  otherBusinessRows.value.filter((row) => otherBusinessMatchesFilters(row))
);

const otherBusinessCustomColumns = computed(() => {
  const names = [];
  const seen = new Set();
  otherBusinessRows.value.forEach((row) => {
    normalizeOtherBusinessCustomFields(row.customFields).forEach((field) => {
      if (seen.has(field.name)) return;
      seen.add(field.name);
      names.push(field.name);
    });
  });
  return names;
});

function otherBusinessCustomColumnKey(name = "") {
  return `custom:${String(name || "").trim()}`;
}

function otherBusinessCustomColumnName(key = "") {
  return String(key || "").startsWith("custom:") ? String(key).slice(7) : "";
}

const otherBusinessBaseColumns = computed(() => {
  const customColumns = otherBusinessCustomColumns.value.map((name) => ({
    key: otherBusinessCustomColumnKey(name),
    label: name,
    width: 148,
    amount: true,
    custom: true
  }));
  return [
    ...OTHER_BUSINESS_PREFIX_COLUMNS,
    ...customColumns,
    ...OTHER_BUSINESS_SUFFIX_COLUMNS
  ].map((column, index) => ({ ...column, defaultIndex: index }));
});

const orderedOtherBusinessColumns = computed(() => {
  const columns = otherBusinessBaseColumns.value;
  const byKey = new Map(columns.map((column) => [column.key, column]));
  const savedKeys = Array.isArray(otherBusinessColumnOrder.value)
    ? otherBusinessColumnOrder.value.filter((key) => byKey.has(key) && key !== "actions")
    : [];
  const used = new Set(savedKeys);
  const ordered = savedKeys.map((key) => byKey.get(key));
  columns
    .filter((column) => column.key !== "actions" && !used.has(column.key))
    .forEach((column) => {
      const insertIndex = ordered.findIndex((item) => (item.defaultIndex ?? 999) > (column.defaultIndex ?? 999));
      if (insertIndex >= 0) ordered.splice(insertIndex, 0, column);
      else ordered.push(column);
    });
  const actionsColumn = byKey.get("actions");
  return actionsColumn ? [...ordered, actionsColumn] : ordered;
});

const otherBusinessTableMinWidth = computed(() =>
  `${orderedOtherBusinessColumns.value.reduce((sum, column) => sum + Number(column.width || 96), 0)}px`
);

function otherBusinessCustomFieldEntry(row = {}, columnName = "") {
  const target = String(columnName || "").trim();
  if (!target) return null;
  return normalizeOtherBusinessCustomFields(row.customFields)
    .find((field) => field.name === target) || null;
}

function otherBusinessCustomFieldDisplay(row = {}, columnName = "") {
  const field = otherBusinessCustomFieldEntry(row, columnName);
  if (!field) return "";
  return `收入 ${money(field.income)} / 成本 ${money(field.cost)} / 利润 ${money(otherBusinessCustomFieldProfit(field))}`;
}

function otherBusinessColumnStyle(column = {}) {
  const width = Number(column.width || 96);
  return { width: `${width}px`, minWidth: `${width}px` };
}

function otherBusinessCellText(row = {}, column = {}) {
  if (column.custom) return otherBusinessCustomFieldDisplay(row, otherBusinessCustomColumnName(column.key));
  const values = {
    date: row.date || "",
    title: row.title || "",
    customer: partnerDisplayLabel(row.customer || "", "客户") || row.customer || "",
    income: money(row.income),
    cost: money(row.cost),
    totalIncome: money(otherBusinessRowTotals(row).totalIncome),
    totalCost: money(otherBusinessRowTotals(row).totalCost),
    profit: money(otherBusinessRowTotals(row).profit),
    remark: row.remark || ""
  };
  return values[column.key] ?? "";
}

function saveOtherBusinessColumnOrder(columns = orderedOtherBusinessColumns.value) {
  const keys = columns
    .filter((column) => column.key !== "actions")
    .map((column) => column.key);
  otherBusinessColumnOrder.value = keys;
  saveStoredJson(OTHER_BUSINESS_COLUMN_ORDER_KEY, keys);
  saveAccountTablePreferencesSoon();
}

function moveOtherBusinessColumn(column = {}, offset = 0) {
  if (!column?.key || column.key === "actions") return;
  const columns = orderedOtherBusinessColumns.value.filter((item) => item.key !== "actions");
  const fromIndex = columns.findIndex((item) => item.key === column.key);
  const toIndex = fromIndex + offset;
  if (fromIndex < 0 || toIndex < 0 || toIndex >= columns.length) return;
  const [moved] = columns.splice(fromIndex, 1);
  columns.splice(toIndex, 0, moved);
  saveOtherBusinessColumnOrder(columns);
}

function startOtherBusinessColumnDrag(column, event) {
  if (!column?.key || column.key === "actions") return;
  draggedOtherBusinessColumnKey = column.key;
  event.dataTransfer.effectAllowed = "move";
  event.dataTransfer.setData("text/plain", column.key);
}

function dropOtherBusinessColumn(column) {
  if (!draggedOtherBusinessColumnKey || !column?.key || column.key === "actions") return;
  const columns = orderedOtherBusinessColumns.value.filter((item) => item.key !== "actions");
  const fromIndex = columns.findIndex((item) => item.key === draggedOtherBusinessColumnKey);
  const toIndex = columns.findIndex((item) => item.key === column.key);
  if (fromIndex >= 0 && toIndex >= 0 && fromIndex !== toIndex) {
    const [moved] = columns.splice(fromIndex, 1);
    const nextTargetIndex = columns.findIndex((item) => item.key === column.key);
    columns.splice(nextTargetIndex, 0, moved);
    saveOtherBusinessColumnOrder(columns);
  }
  draggedOtherBusinessColumnKey = "";
}

function endOtherBusinessColumnDrag() {
  draggedOtherBusinessColumnKey = "";
}

function resetOtherBusinessColumnOrder() {
  localStorage.removeItem(OTHER_BUSINESS_COLUMN_ORDER_KEY);
  otherBusinessColumnOrder.value = [];
  saveAccountTablePreferencesSoon();
  notify("已恢复其他业务默认列顺序");
}

const otherBusinessCustomerFilterOptions = computed(() =>
  orderFilterOptionValues(otherBusinessRows.value, otherBusinessNameValues)
);

const otherBusinessFiltersActive = computed(() =>
  Boolean(otherBusinessSearchKeyword.value.trim() || otherBusinessCustomerFilter.value)
);

function clearOtherBusinessFilters() {
  otherBusinessSearchKeyword.value = "";
  otherBusinessCustomerFilter.value = "";
}

watch(otherBusinessCustomerFilterOptions, (options) => {
  if (otherBusinessCustomerFilter.value && !options.includes(otherBusinessCustomerFilter.value)) {
    otherBusinessCustomerFilter.value = "";
  }
});

const otherBusinessSummary = computed(() => {
  const rows = filteredOtherBusinessRows.value;
  const income = rows.reduce((sum, row) => sum + otherBusinessRowTotals(row).totalIncome, 0);
  const cost = rows.reduce((sum, row) => sum + otherBusinessRowTotals(row).totalCost, 0);
  return {
    count: rows.length,
    income,
    cost,
    profit: income - cost
  };
});

function inputMonthKey(value) {
  const matched = String(value || "").match(/^(\d{4})-(\d{2})/);
  return matched ? `${matched[1]}-${matched[2]}` : "";
}

function currentPeriodMonthKey() {
  return todayInputValue().slice(0, 7);
}

const ORDER_DISPATCH_PERIOD_MODES = [
  { key: "day", label: "按天查看" },
  { key: "month", label: "按月查看" },
  { key: "year", label: "按年查看" },
  { key: "all", label: "全部" },
  { key: "range", label: "自定义范围" }
];
const STATEMENT_RECONCILIATION_PERIOD_MODES = [
  ...PERIOD_FILTER_MODES,
  { key: "range", label: "自定义范围" }
];
const CUSTOMS_STATEMENT_PERIOD_MODES = STATEMENT_RECONCILIATION_PERIOD_MODES;
const CUSTOMS_BUSINESS_QUICK_DATE_FILTERS = ORDER_QUICK_DATE_FILTERS;
const CUSTOMS_BUSINESS_PERIOD_FILTER_MODES = ORDER_DISPATCH_PERIOD_MODES;
const OTHER_BUSINESS_PERIOD_FILTER_MODES = [
  { key: "month", label: "按月查看" },
  { key: "year", label: "按年查看" },
  { key: "all", label: "全部" },
  { key: "range", label: "自定义范围" }
];
const statementMonthOptions = PERIOD_MONTH_OPTIONS;

function previousMonthKey(monthKey = currentPeriodMonthKey()) {
  const [year, month] = String(monthKey || currentPeriodMonthKey()).split("-").map(Number);
  const date = new Date(year, month - 2, 1);
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function normalizePeriodYear(year, fallbackYear = currentPeriodMonthKey().slice(0, 4)) {
  const text = String(year || "").trim().slice(0, 4);
  return /^\d{4}$/.test(text) ? text : fallbackYear;
}

function normalizePeriodMonth(month, fallbackMonth = currentPeriodMonthKey().slice(5, 7)) {
  const number = Number(month || fallbackMonth);
  return String(Math.min(12, Math.max(1, number || Number(fallbackMonth)))).padStart(2, "0");
}

function normalizePeriodRangeDate(value, fallback = todayInputValue()) {
  const text = String(value || "").trim().slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(text) && parseInputDate(text) ? text : fallback;
}

function normalizePeriodRange(startValue, endValue) {
  const start = normalizePeriodRangeDate(startValue);
  const end = normalizePeriodRangeDate(endValue, start);
  return start <= end ? { start, end } : { start: end, end: start };
}

function normalizePeriodFilter(value, fallbackMonthKey = currentPeriodMonthKey()) {
  const fallback = /^\d{4}-\d{2}$/.test(fallbackMonthKey) ? fallbackMonthKey : currentPeriodMonthKey();
  const [fallbackYear, fallbackMonth] = fallback.split("-");
  const text = String(value || "").trim();
  if (text === "all") return "all";
  const dayMatched = text.match(/^day:(\d{4}-\d{2}-\d{2})$/);
  if (dayMatched) return `day:${normalizePeriodRangeDate(dayMatched[1], `${fallback}-01`)}`;
  const rangeMatched = text.match(/^range:(\d{4}-\d{2}-\d{2}):(\d{4}-\d{2}-\d{2})$/);
  if (rangeMatched) {
    const { start, end } = normalizePeriodRange(rangeMatched[1], rangeMatched[2]);
    return `range:${start}:${end}`;
  }
  const yearMatched = text.match(/^year:(\d{4})$/);
  if (yearMatched) return `year:${normalizePeriodYear(yearMatched[1], fallbackYear)}`;
  const monthMatched = text.match(/^(\d{4})-(\d{2})$/);
  if (monthMatched) {
    return `${normalizePeriodYear(monthMatched[1], fallbackYear)}-${normalizePeriodMonth(monthMatched[2], fallbackMonth)}`;
  }
  return fallback;
}

function normalizeLegacyPeriodFilter(value) {
  const text = String(value || "").trim();
  if (text === "all") return "all";
  if (text === "year") return `year:${currentPeriodMonthKey().slice(0, 4)}`;
  if (text === "lastMonth") return previousMonthKey();
  if (/^day:\d{4}-\d{2}-\d{2}$/.test(text) || /^year:\d{4}$/.test(text) || /^\d{4}-\d{2}$/.test(text)) return normalizePeriodFilter(text);
  return currentPeriodMonthKey();
}

function normalizeDateFilterMode(value) {
  return value === DATE_FILTER_MODE_PERIOD ? DATE_FILTER_MODE_PERIOD : DATE_FILTER_MODE_QUICK;
}

function normalizeOrderDateFilterKey(value) {
  const text = String(value || "").trim();
  return ORDER_QUICK_DATE_FILTERS.some((item) => item.key === text) ? text : "today";
}

function normalizeDispatchDateFilterKey(value) {
  const text = String(value || "").trim();
  return DISPATCH_DATE_FILTERS.some((item) => item.key === text) ? text : "today";
}

function dispatchQuickDateValue(filterKey = dispatchPeriodFilter.value) {
  const matched = DISPATCH_DATE_FILTERS.find((item) => item.key === filterKey && Number.isFinite(item.offset));
  return matched ? offsetDateInputValue(matched.offset) : todayInputValue();
}

function dispatchDateFilterBounds(filterKey = dispatchPeriodFilter.value) {
  const today = parseInputDate(todayInputValue()) || new Date();
  const quickDate = DISPATCH_DATE_FILTERS.find((item) => item.key === filterKey && Number.isFinite(item.offset));
  if (quickDate) {
    const value = offsetDateInputValue(quickDate.offset);
    return { start: value, end: value };
  }
  if (filterKey === "week") {
    const start = new Date(today);
    start.setDate(today.getDate() - ((today.getDay() + 6) % 7));
    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    return { start: dateInputFromDate(start), end: dateInputFromDate(end) };
  }
  if (filterKey === "month") {
    const start = new Date(today.getFullYear(), today.getMonth(), 1);
    const end = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    return { start: dateInputFromDate(start), end: dateInputFromDate(end) };
  }
  if (filterKey === "lastMonth") {
    const start = new Date(today.getFullYear(), today.getMonth() - 1, 1);
    const end = new Date(today.getFullYear(), today.getMonth(), 0);
    return { start: dateInputFromDate(start), end: dateInputFromDate(end) };
  }
  if (filterKey === "custom") {
    const start = dispatchCustomDateStart.value || dispatchDate.value || todayInputValue();
    const end = dispatchCustomDateEnd.value || start;
    return { start, end };
  }
  const value = todayInputValue();
  return { start: value, end: value };
}

function dispatchDateFilterDateValue(filterKey = dispatchPeriodFilter.value) {
  if (filterKey === "custom") return dispatchCustomDateStart.value || dispatchDate.value || todayInputValue();
  if (["week", "month"].includes(filterKey)) return todayInputValue();
  return dispatchDateFilterBounds(filterKey).start || todayInputValue();
}

function dispatchDateFilterLabel(filterKey = dispatchPeriodFilter.value) {
  const filter = DISPATCH_DATE_FILTERS.find((item) => item.key === filterKey);
  const { start, end } = dispatchDateFilterBounds(filterKey);
  if (filterKey === "custom") {
    return start === end ? `自定义：${start || "-"}` : `自定义：${start || "-"} 至 ${end || "-"}`;
  }
  if (start && end && start !== end) return `${filter?.label || "排车"}：${start} 至 ${end}`;
  return `${filter?.label || "排车"}：${start || "-"}`;
}

function setDispatchDateFilter(filterKey) {
  const previousMode = dispatchDateFilterMode.value;
  const previousFilter = dispatchPeriodFilter.value;
  setDispatchDateFilterMode(DATE_FILTER_MODE_QUICK);
  dispatchPeriodFilter.value = normalizeDispatchDateFilterKey(filterKey);
  dispatchDate.value = dispatchDateFilterDateValue(dispatchPeriodFilter.value);
  localStorage.setItem("hanye_dispatch_period_filter", dispatchPeriodFilter.value);
  localStorage.setItem("hanye_dispatch_date", dispatchDate.value);
  if (previousMode !== DATE_FILTER_MODE_QUICK && previousFilter === dispatchPeriodFilter.value) {
    loadDispatchPlansForCurrentFilter();
  }
}

function setDispatchCustomDateStart(value) {
  dispatchCustomDateStart.value = String(value || "").trim() || todayInputValue();
  if (!dispatchCustomDateEnd.value) dispatchCustomDateEnd.value = dispatchCustomDateStart.value;
  setDispatchDateFilter("custom");
  localStorage.setItem("hanye_dispatch_custom_date_start", dispatchCustomDateStart.value);
  loadDispatchPlansForCurrentFilter();
}

function setDispatchCustomDateEnd(value) {
  dispatchCustomDateEnd.value = String(value || "").trim() || dispatchCustomDateStart.value || todayInputValue();
  setDispatchDateFilter("custom");
  localStorage.setItem("hanye_dispatch_custom_date_end", dispatchCustomDateEnd.value);
  loadDispatchPlansForCurrentFilter();
}

function periodFilterParts(filterKey = currentPeriodMonthKey()) {
  const currentMonthKey = currentPeriodMonthKey();
  const [currentYear, currentMonth] = currentMonthKey.split("-");
  const normalized = normalizePeriodFilter(filterKey, currentMonthKey);
  if (normalized === "all") return { mode: "all", year: currentYear, month: currentMonth };
  const dayMatched = normalized.match(/^day:(\d{4})-(\d{2})-(\d{2})$/);
  if (dayMatched) {
    return {
      mode: "day",
      year: dayMatched[1],
      month: dayMatched[2],
      day: `${dayMatched[1]}-${dayMatched[2]}-${dayMatched[3]}`
    };
  }
  const rangeMatched = normalized.match(/^range:(\d{4}-\d{2}-\d{2}):(\d{4}-\d{2}-\d{2})$/);
  if (rangeMatched) {
    const { start, end } = normalizePeriodRange(rangeMatched[1], rangeMatched[2]);
    const rangeMonth = inputMonthKey(start);
    return {
      mode: "range",
      year: rangeMonth.slice(0, 4) || currentYear,
      month: rangeMonth.slice(5, 7) || currentMonth,
      start,
      end
    };
  }
  const yearMatched = normalized.match(/^year:(\d{4})$/);
  if (yearMatched) return { mode: "year", year: yearMatched[1], month: currentMonth };
  const [year, month] = normalized.split("-");
  return { mode: "month", year, month };
}

function periodFilterValue(scope) {
  return normalizePeriodFilter(periodFilterRefs[scope]?.value);
}

function periodFilterMode(scope) {
  return periodFilterParts(periodFilterValue(scope)).mode;
}

function periodFilterYear(scope) {
  return periodFilterParts(periodFilterValue(scope)).year;
}

function periodFilterMonth(scope) {
  return periodFilterParts(periodFilterValue(scope)).month;
}

function periodFilterDay(scope) {
  return periodFilterParts(periodFilterValue(scope)).day || todayInputValue();
}

function periodFilterLabel(filterKey) {
  const { mode, year, month, day, start, end } = periodFilterParts(filterKey);
  if (mode === "all") return "全部";
  if (mode === "year") return `${year}年`;
  if (mode === "day") return `${year}年${Number(month)}月${Number(day.slice(8, 10))}日`;
  if (mode === "range") return start === end
    ? `自定义：${inputDateLabel(start)}`
    : `自定义：${inputDateLabel(start)} 至 ${inputDateLabel(end)}`;
  return `${year}年${Number(month)}月`;
}

function periodFilterLabelByScope(scope) {
  return periodFilterLabel(periodFilterValue(scope));
}

function periodFilterBounds(filterKey = currentPeriodMonthKey()) {
  const { mode, year, month, day, start, end } = periodFilterParts(filterKey);
  if (mode === "all") return { start: "", end: "" };
  if (mode === "year") return { start: `${year}-01-01`, end: `${year}-12-31` };
  if (mode === "day") return { start: day, end: day };
  if (mode === "range") return { start, end };
  const first = new Date(Number(year), Number(month) - 1, 1);
  const last = new Date(Number(year), Number(month), 0);
  return { start: dateInputFromDate(first), end: dateInputFromDate(last) };
}

function dateMatchesPeriodFilter(dateValue, filterKey) {
  const { mode, year, month, day, start, end } = periodFilterParts(filterKey);
  if (mode === "all") return true;
  if (mode === "day") return String(dateValue || "").slice(0, 10) === day;
  if (mode === "range") {
    const date = parseInputDate(dateValue);
    const startDate = parseInputDate(start);
    const endDate = parseInputDate(end);
    if (!date || !startDate || !endDate) return false;
    return date >= startDate && date <= endDate;
  }
  const monthKey = inputMonthKey(dateValue);
  return mode === "year" ? monthKey.startsWith(`${year}-`) : monthKey === `${year}-${month}`;
}

function periodFilterDateValue(filterKey) {
  const { mode, year, month, day, start } = periodFilterParts(filterKey);
  if (mode === "day") return day;
  if (mode === "month") {
    const monthKey = `${year}-${month}`;
    return monthKey === currentPeriodMonthKey() ? todayInputValue() : `${monthKey}-01`;
  }
  if (mode === "year") {
    return year === currentPeriodMonthKey().slice(0, 4) ? todayInputValue() : `${year}-01-01`;
  }
  if (mode === "range") return start || todayInputValue();
  return todayInputValue();
}

function periodSourceDates(scope) {
  if (scope === "orders") return orderRows.value.map((item) => orderDispatchLoadDate(item));
  if (scope === "finance") return [
    ...orderRows.value.map((item) => item.date),
    ...driverAdjustmentRows.value.map((item) => item.date)
  ];
  if (scope === "statement") return orderRows.value.map((item) => item.date);
  if (scope === "boss") return [
    ...orderRows.value.map((item) => item.date),
    ...driverAdjustmentRows.value.map((item) => item.date),
    ...vehicleExpenseRows.value.flatMap((item) => item.type === "annual"
      ? [vehicleExpenseAnnualStartDate(item), vehicleExpenseAnnualEndDate(item)]
      : [item.date]),
    ...bossCompanyProfitRows.map((item) => `${item.period}-01`),
    ...bossCompanyExpenseRows.value.map((item) => `${bossCompanyExpensePeriodMonth(item)}-01`),
    ...statementDownloadRows.value.flatMap((item) => {
      const { start, end } = statementRecordRange(item);
      return [start, end, item.downloadedAt, item.createdAt].filter(Boolean);
    }),
    ...customsBusinessAllRows.value.map((item) => item.date),
    ...otherBusinessAllRows.value.map((item) => item.date)
  ];
  if (scope === "customsBusiness" || scope === "customsStatement") return customsBusinessRows.value.map((item) => item.date);
  if (scope === "otherBusiness") return otherBusinessRows.value.map((item) => item.date);
  if (scope === "vehicleExpenses") return vehicleExpenseRows.value.flatMap((item) => item.type === "annual"
    ? [vehicleExpenseAnnualStartDate(item), vehicleExpenseAnnualEndDate(item)]
    : [item.date]);
  if (scope === "dispatch" || scope === "dispatchRange") return [
    ...dispatchPlanRows.value.map((item) => dispatchPlanDate(item)),
    ...orderRows.value.map((item) => item.date)
  ];
  return [];
}

function periodYearOptions(scope) {
  const currentYear = currentPeriodMonthKey().slice(0, 4);
  const selectedYear = periodFilterYear(scope);
  const years = new Set([currentYear, selectedYear]);
  const baseYear = Number(currentYear);
  if (Number.isFinite(baseYear)) {
    Array.from({ length: 7 }, (_, index) => String(baseYear - index)).forEach((year) => years.add(year));
  }
  periodSourceDates(scope).forEach((dateValue) => {
    const year = inputMonthKey(dateValue).slice(0, 4);
    if (year) years.add(year);
  });
  return Array.from(years).sort((left, right) => right.localeCompare(left));
}

function setPeriodFilterValue(scope, value) {
  const target = periodFilterRefs[scope];
  if (!target) return;
  target.value = normalizePeriodFilter(value);
  if (scope === "orders") {
    localStorage.setItem("hanye_order_period_filter", target.value);
  }
  if (scope === "finance") {
    localStorage.setItem("hanye_finance_period_filter", target.value);
  }
  if (scope === "vehicleExpenses") {
    localStorage.setItem("hanye_vehicle_expense_period_filter", target.value);
  }
  if (scope === "customsStatement") {
    localStorage.setItem("hanye_customs_statement_period_filter", target.value);
  }
  if (scope === "dispatchRange") {
    dispatchDate.value = periodFilterDateValue(target.value);
    localStorage.setItem("hanye_dispatch_range_period_filter", target.value);
    localStorage.setItem("hanye_dispatch_date", dispatchDate.value);
  }
}

function setPeriodFilterMode(scope, mode) {
  const { year, month } = periodFilterParts(periodFilterValue(scope));
  if (mode === "all") {
    setPeriodFilterValue(scope, "all");
  } else if (mode === "year") {
    setPeriodFilterValue(scope, `year:${year}`);
  } else if (mode === "day") {
    setPeriodFilterValue(scope, `day:${periodFilterDateValue(periodFilterValue(scope))}`);
  } else if (mode === "range") {
    const { start, end } = periodFilterBounds(periodFilterValue(scope));
    setPeriodFilterValue(scope, `range:${start || `${year}-${month}-01`}:${end || todayInputValue()}`);
  } else {
    setPeriodFilterValue(scope, `${year}-${month}`);
  }
}

function periodFilterRangeStart(scope) {
  const parts = periodFilterParts(periodFilterValue(scope));
  if (parts.mode === "range") return parts.start;
  return periodFilterBounds(periodFilterValue(scope)).start || todayInputValue();
}

function periodFilterRangeEnd(scope) {
  const parts = periodFilterParts(periodFilterValue(scope));
  if (parts.mode === "range") return parts.end;
  return periodFilterBounds(periodFilterValue(scope)).end || periodFilterRangeStart(scope);
}

function setPeriodFilterRangeStart(scope, value) {
  const start = normalizePeriodRangeDate(value, periodFilterRangeStart(scope));
  const end = periodFilterRangeEnd(scope) || start;
  setPeriodFilterValue(scope, `range:${start}:${end}`);
}

function setPeriodFilterRangeEnd(scope, value) {
  const end = normalizePeriodRangeDate(value, periodFilterRangeEnd(scope));
  const start = periodFilterRangeStart(scope) || end;
  setPeriodFilterValue(scope, `range:${start}:${end}`);
}

function setPeriodFilterYear(scope, year) {
  const { mode, month } = periodFilterParts(periodFilterValue(scope));
  const nextYear = normalizePeriodYear(year);
  setPeriodFilterValue(scope, mode === "year" ? `year:${nextYear}` : `${nextYear}-${month}`);
}

function setPeriodFilterMonth(scope, month) {
  const { year } = periodFilterParts(periodFilterValue(scope));
  setPeriodFilterValue(scope, `${year}-${normalizePeriodMonth(month)}`);
}

function setPeriodFilterDay(scope, day) {
  setPeriodFilterValue(scope, `day:${normalizePeriodRangeDate(day)}`);
}

function customsBusinessFilterValue() {
  return customsBusinessDateFilterMode.value === DATE_FILTER_MODE_PERIOD
    ? periodFilterValue("customsBusiness")
    : normalizeOrderDateFilterKey(customsBusinessQuickDateFilter.value);
}

function customsBusinessFilterLabel(filterValue = customsBusinessFilterValue()) {
  if (CUSTOMS_BUSINESS_QUICK_DATE_FILTERS.some((item) => item.key === filterValue)) {
    return dispatchDateFilterLabel(filterValue);
  }
  return periodFilterLabel(filterValue);
}

function customsBusinessFilterDateValue(filterValue = customsBusinessFilterValue()) {
  if (CUSTOMS_BUSINESS_QUICK_DATE_FILTERS.some((item) => item.key === filterValue)) {
    return dispatchDateFilterDateValue(filterValue);
  }
  return periodFilterDateValue(filterValue);
}

function customsBusinessFilterBounds(filterValue = customsBusinessFilterValue()) {
  if (CUSTOMS_BUSINESS_QUICK_DATE_FILTERS.some((item) => item.key === filterValue)) {
    return dispatchDateFilterBounds(filterValue);
  }
  return periodFilterBounds(filterValue);
}

function customsBusinessDateMatchesFilter(dateValue, filterValue = customsBusinessFilterValue()) {
  const text = String(dateValue || "").trim().slice(0, 10);
  if (!text) return false;
  if (CUSTOMS_BUSINESS_QUICK_DATE_FILTERS.some((item) => item.key === filterValue)) {
    const { start, end } = dispatchDateFilterBounds(filterValue);
    if (!start || !end) return false;
    return start === end
      ? text === start
      : text >= start && text < end;
  }
  return dateMatchesPeriodFilter(text, filterValue);
}

function customsBusinessListFilterValue(scope = customsBusinessActiveFilterScope()) {
  return scope === "customsStatement"
    ? periodFilterValue("customsStatement")
    : customsBusinessFilterValue();
}

