function orderAdvanceFeeDetailText(order, driver = null) {
  const fees = advanceFeesForOrder(order, driver);
  if (!fees.length) return "-";
  return fees
    .map((fee) => `${fee.name || "费用"} ${currencyCodeDisplay(fee.currency || "港币")} ${money(fee.amount)}`)
    .join("；");
}

function driverCostCenterFeeDetailText(order, feeName, driver) {
  const targetName = String(feeName || "").trim();
  if (!targetName || !driver) return "";
  const rule = driverCostCenterRuleForOrder(order, driver);
  const details = driverCostCenterOrderFeeRows(order)
    .filter((fee) => String(fee?.name || "").trim() === targetName)
    .map((fee) => driverCostCenterFeeCostForRule(rule, fee, driver))
    .filter((detail) =>
      detail.item
      && detail.item.category !== "代垫"
      && !isCompanyCoveredFeeItem(detail.item)
      && feeItemIncludesCostSource(detail.item, driverCostCenterSourceForDriver(driver))
    );
  if (!details.length) return "";
  return details
    .map((detail) => detail.matched
      ? `${money(detail.amount)} ${currencyCodeDisplay(detail.currency || "港币")}`
      : "成本中心未匹配")
    .join("；");
}

function driverWageFeeDetailText(order, feeName, driver) {
  const targetName = String(feeName || "").trim();
  const advanceText = advanceFeesForOrder(order, driver)
    .filter((fee) => String(fee?.name || "").trim() === targetName && Number(fee?.amount || 0) !== 0)
    .map((fee) => `${money(fee.amount)} ${currencyCodeDisplay(fee.currency || "港币")}`)
    .join("；");
  const costText = driverCostCenterFeeDetailText(order, targetName, driver);
  return [costText, advanceText].filter(Boolean).join("；") || "-";
}

function orderFeeDetailText(order) {
  const fees = Array.isArray(order?.fees) ? order.fees : [];
  if (!fees.length) return "-";
  return fees
    .filter((fee) => Number(fee?.amount || 0) !== 0)
    .map((fee) => {
      const parts = [
        fee.name || "费用",
        currencyCodeDisplay(fee.currency || "港币"),
        money(fee.amount)
      ];
      const remark = String(fee.remark || "").trim();
      const suffix = [remark].filter(Boolean).join("，");
      return suffix ? `${parts.join(" ")}（${suffix}）` : parts.join(" ");
    })
    .join("；") || "-";
}

function orderFeeCellText(order, feeName) {
  const name = String(feeName || "").trim();
  const fees = (Array.isArray(order?.fees) ? order.fees : [])
    .filter((fee) => String(fee?.name || "").trim() === name && Number(fee?.amount || 0) !== 0);
  if (!fees.length) return "-";
  return fees.map((fee) => {
    const amount = `${currencyCodeDisplay(fee.currency || "港币")} ${money(fee.amount)}`;
    const remark = String(fee.remark || "").trim();
    const suffix = [remark].filter(Boolean).join("，");
    return suffix ? `${amount}（${suffix}）` : amount;
  }).join("；");
}

function driverExtraFieldForFeeName(feeName = "") {
  const name = String(feeName || "");
  return Object.entries(DRIVER_EXTRA_FEE_KEYWORDS)
    .find(([, keywords]) => keywords.some((keyword) => name.includes(keyword)))?.[0] || "";
}

function financeWageFeeColumnLabel(feeName = "") {
  return String(feeName || "").trim();
}

function driverWageDetailForField(order, field, driver) {
  if (!field || !driver) return "";
  const rule = orderDriverWageRule(order, driver);
  if (!rule) return "司机工资未匹配规则";
  const rate = Number(rule[field] || 0);
  if (!rate) return "司机工资未设置规则";
  if (!driverExtraTripFeeApplies(order, field, driver)) return "";
  const amount = driverExtraTripFee(order, field, driver);
  if (DRIVER_QUANTITY_EXTRA_FIELDS.includes(field)) {
    const quantity = orderDriverExtraQuantity(order, field);
    return `${money(amount)} HKD（${money(quantity)}板×${money(rate)}/板）`;
  }
  return `${money(amount)} HKD`;
}

function driverWageDetailForFee(order, feeName, driver) {
  return driverWageDetailForField(order, driverExtraFieldForFeeName(feeName), driver);
}

function orderFeeCellWithDriverWageText(order, feeName, driver, options = {}) {
  if (options.includeAllAdvanceFees) {
    const allAdvanceText = (Array.isArray(order?.fees) ? order.fees : [])
      .filter((fee) => isAdvanceFee(fee))
      .filter((fee) => String(fee?.name || "").trim() === String(feeName || "").trim() && Number(fee?.amount || 0) !== 0)
      .map((fee) => `${money(fee.amount)} ${currencyCodeDisplay(fee.currency || "港币")}`)
      .join("；");
    const costText = driverCostCenterFeeDetailText(order, feeName, driver);
    return [costText, allAdvanceText].filter(Boolean).join("；") || "-";
  }
  return driverWageFeeDetailText(order, feeName, driver);
}

function financeWageDetailFeeColumns(row) {
  const columns = [];
  const upsertColumn = (label, feeName = "", driverField = "") => {
    const existing = columns.find((column) => column.label === label);
    if (existing) {
      if (feeName && !existing.feeNames.includes(feeName)) existing.feeNames.push(feeName);
      if (driverField && !existing.driverField) existing.driverField = driverField;
      return;
    }
    columns.push({ label, feeNames: feeName ? [feeName] : [], driverField });
  };
  (row?.orders || []).forEach((order) => {
    (Array.isArray(order?.fees) ? order.fees : []).forEach((fee) => {
      const name = String(fee?.name || "").trim();
      const label = financeWageFeeColumnLabel(name);
      if (!name) return;
      const isDriverAdvance = isAdvanceFee(fee)
        && advanceFeesForOrder(order, row?.driver).includes(fee);
      const item = feeItemForFee(fee);
      const isDriverCost = !isAdvanceFee(fee)
        && item
        && !isCompanyCoveredFeeItem(item)
        && feeItemIncludesCostSource(item, driverCostCenterSourceForDriver(row?.driver));
      if (isDriverAdvance || isDriverCost) {
        upsertColumn(label, name);
      }
    });
  });
  return columns;
}

function financeWageDetailColumns(row) {
  const baseColumns = [
    { key: "no", label: "订单号", min: 112 },
    { key: "date", label: "日期", min: 90 },
    { key: "customer", label: "客户", min: 160 },
    { key: "transportMode", label: "运输模式", min: 74 },
    { key: "route", label: "路线", min: 180 },
    { key: "tripFee", label: "成本中心合计", min: 96 },
    { key: "advanceAmount", label: "代垫合计HKD", min: 96 },
    { key: "advanceAmountRMB", label: "代垫合计RMB", min: 96 },
    { key: "routeAdjustHKD", label: "路线调整HKD", min: 96 },
    { key: "routeAdjustRMB", label: "路线调整RMB", min: 96 }
  ];
  const feeColumns = financeWageDetailFeeColumns(row).map((column) => ({
    key: `fee:${column.label}`,
    feeNames: column.feeNames,
    feeName: column.feeNames[0],
    driverField: column.driverField,
    label: column.label,
    min: 92,
    max: 260
  }));
  return [...baseColumns, ...feeColumns, { key: "status", label: "状态", min: 76 }];
}

function orderedFinanceWageDetailColumns(row) {
  const columns = financeWageDetailColumns(row);
  const order = financeWageDetailColumnOrder.value || [];
  const lockedKeys = new Set((financeWageDetailLockedColumns.value || []).filter((key) =>
    columns.some((column) => column.key === key)
  ));
  if (!order.length) return columns;
  const columnMap = new Map(columns.map((column) => [column.key, column]));
  const orderedKnownColumns = order.map((key) => columnMap.get(key)).filter(Boolean);
  const orderedKeySet = new Set(orderedKnownColumns.map((column) => column.key));
  const newColumns = columns.filter((column) => !orderedKeySet.has(column.key));
  let insertIndex = orderedKnownColumns.length;
  while (insertIndex > 0 && lockedKeys.has(orderedKnownColumns[insertIndex - 1].key)) {
    insertIndex -= 1;
  }
  return [
    ...orderedKnownColumns.slice(0, insertIndex),
    ...newColumns,
    ...orderedKnownColumns.slice(insertIndex)
  ];
}

function visibleFinanceWageDetailColumns(row) {
  return orderedFinanceWageDetailColumns(row)
    .filter((column) => financeWageDetailColumnVisibility[column.key] !== false);
}

function setFinanceWageDetailColumnVisible(column, visible) {
  financeWageDetailColumnVisibility[column.key] = visible;
  saveStoredJson(dataTableStorageKey("finance_wage_detail", "visibility"), { ...financeWageDetailColumnVisibility });
}

function isFinanceWageDetailColumnLocked(column) {
  return (financeWageDetailLockedColumns.value || []).includes(column?.key);
}

function toggleFinanceWageDetailColumnLock(column) {
  if (!column?.key || column.key === "no") return;
  const keys = financeWageDetailLockedColumns.value || [];
  const currentOrder = orderedFinanceWageDetailColumns(activeFinanceWageDetailRow.value).map((item) => item.key);
  financeWageDetailColumnOrder.value = currentOrder;
  saveStoredJson(dataTableStorageKey("finance_wage_detail", "order"), currentOrder);
  financeWageDetailLockedColumns.value = keys.includes(column.key)
    ? keys.filter((key) => key !== column.key)
    : [...keys, column.key];
  saveStoredJson(dataTableStorageKey("finance_wage_detail", "locked"), financeWageDetailLockedColumns.value);
}

function moveFinanceWageDetailColumn(column, offset) {
  const columns = orderedFinanceWageDetailColumns(activeFinanceWageDetailRow.value);
  const keys = columns.map((item) => item.key);
  const index = keys.indexOf(column.key);
  const target = index + offset;
  if (index < 0 || target < 0 || target >= keys.length) return;
  const [key] = keys.splice(index, 1);
  keys.splice(target, 0, key);
  financeWageDetailColumnOrder.value = keys;
  saveStoredJson(dataTableStorageKey("finance_wage_detail", "order"), keys);
  financeWageDetailLockedColumns.value = keys.filter((item) => isFinanceWageDetailColumnLocked({ key: item }));
  saveStoredJson(dataTableStorageKey("finance_wage_detail", "locked"), financeWageDetailLockedColumns.value);
}

function financeWageDetailStickyColumnStyle(row, column, index) {
  return index === 0 ? { left: "0px" } : {};
}

function financeWageDetailCellValue(order, column, row) {
  if (!order || !column) return "";
  if (column.key === "no") return order.no || "";
  if (column.key === "date") return order.date || "";
  if (column.key === "customer") return order.customer || "";
  if (column.key === "transportMode") return normalizeTransportMode(order.transportMode || "单司机") || "";
  if (column.key === "route") return relatedOrderRouteText(order);
  if (column.key === "tripFee") {
    const amount = driverCostCenterFeeBreakdown(order, row?.driver);
    return moneyPairSuffix(amount.hkd, amount.rmb);
  }
  if (column.key === "advanceAmount") {
    const amount = driverFinanceAdvanceBreakdown(order, row?.driver).hkd;
    return amount ? `${money(amount)} HKD` : "-";
  }
  if (column.key === "advanceAmountRMB") {
    const amount = driverFinanceAdvanceBreakdown(order, row?.driver).rmb;
    return amount ? `${money(amount)} RMB` : "-";
  }
  if (column.key === "routeAdjustHKD") {
    const amount = driverCustomerTripAdjustBreakdown(order, row?.driver).hkd;
    return amount ? `${money(amount)} HKD` : "-";
  }
  if (column.key === "routeAdjustRMB") {
    const amount = driverCustomerTripAdjustBreakdown(order, row?.driver).rmb;
    return amount ? `${money(amount)} RMB` : "-";
  }
  if (column.key === "status") return order.status || "";
  if (column.feeNames?.length) {
    const values = column.feeNames
      .map((feeName) => orderFeeCellWithDriverWageText(order, feeName, row?.driver))
      .filter((text) => text && text !== "-")
    return [...new Set(values)].join("；") || "-";
  }
  if (column.driverField) return driverWageDetailForField(order, column.driverField, row?.driver) || "-";
  if (column.feeName) return orderFeeCellWithDriverWageText(order, column.feeName, row?.driver);
  return "";
}

function financeWageDetailSortValue(order, column, row) {
  const value = financeWageDetailCellValue(order, column, row);
  if (!column) return value;
  if (column.key === "date") return order?.date || "";
  if (column.key === "no") return order?.no || "";
  if (
    ["tripFee", "advanceAmount", "advanceAmountRMB", "routeAdjustHKD", "routeAdjustRMB"].includes(column.key)
    || column.feeNames?.length
    || column.driverField
    || column.feeName
  ) {
    const hkd = amountTotalFromFinanceText(value, "HKD");
    const rmb = amountTotalFromFinanceText(value, "RMB");
    return hkd || rmb ? hkd + rmb : "";
  }
  return value;
}

function sortedFinanceWageDetailOrders(row) {
  const orders = row?.orders || [];
  const state = loadTableSortState("financeWageDetail");
  if (!state.key || !state.direction) return orders;
  const column = financeWageDetailColumns(row).find((item) => item.key === state.key);
  if (!column) return orders;
  const direction = state.direction === "desc" ? -1 : 1;
  return orders
    .map((order, index) => ({ order, index }))
    .sort((left, right) => {
      const compared = compareSortValues(
        financeWageDetailSortValue(left.order, column, row),
        financeWageDetailSortValue(right.order, column, row)
      );
      if (compared !== 0) return compared * direction;
      return left.index - right.index;
    })
    .map((item) => item.order);
}

function amountTotalFromFinanceText(text = "", currency = "HKD") {
  const pattern = new RegExp(`(?:${currency}\\s*([-+]?\\d[\\d,]*(?:\\.\\d+)?)|([-+]?\\d[\\d,]*(?:\\.\\d+)?)\\s*${currency})`, "g");
  let total = 0;
  let match;
  while ((match = pattern.exec(String(text || "")))) {
    total += Number(String(match[1] || match[2] || "0").replace(/,/g, "")) || 0;
  }
  return total;
}

function financeWageDetailFooterValue(column, row) {
  if (!column || !row) return "";
  if (column.key === "no") return "合计";
  const texts = (row.orders || []).map((order) => financeWageDetailCellValue(order, column, row));
  if (column.key === "advanceAmount") {
    const total = texts.reduce((sum, text) => sum + amountTotalFromFinanceText(text, "HKD"), 0);
    return `${money(total)} HKD`;
  }
  if (column.key === "advanceAmountRMB") {
    const total = texts.reduce((sum, text) => sum + amountTotalFromFinanceText(text, "RMB"), 0);
    return `${money(total)} RMB`;
  }
  if (column.key === "routeAdjustHKD") {
    const total = texts.reduce((sum, text) => sum + amountTotalFromFinanceText(text, "HKD"), 0);
    return `${money(total)} HKD`;
  }
  if (column.key === "routeAdjustRMB") {
    const total = texts.reduce((sum, text) => sum + amountTotalFromFinanceText(text, "RMB"), 0);
    return `${money(total)} RMB`;
  }
  if (column.key === "tripFee" || column.key === "extraFeeTotal" || column.feeNames?.length || column.driverField || column.feeName) {
    const hkd = texts.reduce((sum, text) => sum + amountTotalFromFinanceText(text, "HKD"), 0);
    const rmb = texts.reduce((sum, text) => sum + amountTotalFromFinanceText(text, "RMB"), 0);
    return moneyPairSuffix(hkd, rmb);
  }
  return "";
}

function financeWageDetailColumnWidth(row, column) {
  const values = [column.label, ...(row?.orders || []).map((order) => financeWageDetailCellValue(order, column, row))];
  return values.reduce((width, value) => Math.max(width, textWidthPx(value, column.min || 72, column.max || 320)), column.min || 72);
}

function loadFinanceWageDetailSavedWidths() {
  try {
    return JSON.parse(localStorage.getItem(dataTableStorageKey("finance_wage_detail", "widths")) || "{}") || {};
  } catch {
    return {};
  }
}

function syncFinanceWageDetailColumnWidths(row) {
  const saved = loadFinanceWageDetailSavedWidths();
  financeWageDetailColumns(row).forEach((column) => {
    const savedWidth = Number(saved[column.key]);
    financeWageDetailColumnWidths[column.key] = Number.isFinite(savedWidth) && savedWidth >= column.min
      ? savedWidth
      : financeWageDetailColumnWidth(row, column);
  });
}

function resetFinanceWageDetailColumnWidths(row = activeFinanceWageDetailRow.value) {
  localStorage.removeItem(dataTableStorageKey("finance_wage_detail", "widths"));
  if (row) syncFinanceWageDetailColumnWidths(row);
  notify("已恢复自适应列宽");
}

function resetFinanceWageDetailColumnOrder() {
  financeWageDetailColumnOrder.value = [];
  financeWageDetailLockedColumns.value = ["no"];
  localStorage.removeItem(dataTableStorageKey("finance_wage_detail", "order"));
  saveStoredJson(dataTableStorageKey("finance_wage_detail", "locked"), financeWageDetailLockedColumns.value);
  notify("已恢复默认列顺序");
}

function buildFinanceWageRows(sourceOrders, sourceAdjustments) {
  return sortRowsByTable(driverRows.value.map((driver) => {
    const orders = sourceOrders.filter((order) => orderMatchesDriverForWage(order, driver));
    const wageBreakdown = orders.reduce((sum, order) => {
      const amount = driverFinanceWageOrderBreakdown(order, driver);
      return {
        costCenterHKD: sum.costCenterHKD + amount.costCenterHKD,
        costCenterRMB: sum.costCenterRMB + amount.costCenterRMB,
        advanceHKD: sum.advanceHKD + amount.advanceHKD,
        advanceRMB: sum.advanceRMB + amount.advanceRMB,
        adjustmentsHKD: sum.adjustmentsHKD + amount.adjustmentsHKD,
        adjustmentsRMB: sum.adjustmentsRMB + amount.adjustmentsRMB,
        costCenterMatchedCount: sum.costCenterMatchedCount + amount.costCenterMatchedCount,
        costCenterMissingCount: sum.costCenterMissingCount + amount.costCenterMissingCount
      };
    }, {
      costCenterHKD: 0,
      costCenterRMB: 0,
      advanceHKD: 0,
      advanceRMB: 0,
      adjustmentsHKD: 0,
      adjustmentsRMB: 0,
      costCenterMatchedCount: 0,
      costCenterMissingCount: 0
    });
    const adjustmentBreakdown = sourceAdjustments
      .filter((item) => item.driverId === driver.id)
      .reduce((sum, item) => {
        const currency = currencyCodeDisplay(item.currency || "港币");
        return {
          hkd: sum.hkd + (currency === "RMB" ? 0 : Number(item.amount || 0)),
          rmb: sum.rmb + (currency === "RMB" ? Number(item.amount || 0) : 0)
        };
      }, { hkd: 0, rmb: 0 });
    return {
      driver,
      orders,
      orderCount: orders.length,
      payable: wageBreakdown.costCenterHKD,
      payableRMB: wageBreakdown.costCenterRMB,
      advanceFee: wageBreakdown.advanceHKD,
      advanceFeeRMB: wageBreakdown.advanceRMB,
      adjustments: adjustmentBreakdown.hkd,
      adjustmentsRMB: adjustmentBreakdown.rmb,
      routeAdjustments: wageBreakdown.adjustmentsHKD,
      routeAdjustmentsRMB: wageBreakdown.adjustmentsRMB,
      total: wageBreakdown.costCenterHKD + wageBreakdown.advanceHKD + wageBreakdown.adjustmentsHKD + adjustmentBreakdown.hkd,
      totalRMB: wageBreakdown.costCenterRMB + wageBreakdown.advanceRMB + wageBreakdown.adjustmentsRMB + adjustmentBreakdown.rmb,
      costCenterMatchedCount: wageBreakdown.costCenterMatchedCount,
      costCenterMissingCount: wageBreakdown.costCenterMissingCount
    };
  }).filter((row) => row.orderCount || row.payable || row.payableRMB || row.advanceFee || row.advanceFeeRMB || row.adjustments || row.adjustmentsRMB), "financeWages");
}

const financeWageRows = computed(() => buildFinanceWageRows(financeOrderRows.value, financeAdjustmentRows.value));
const statementWageRows = computed(() => buildFinanceWageRows(statementBillableOrderRows.value, statementAdjustmentRows.value));

watch(activeFinanceWageDetailRow, (row) => {
  if (row) syncFinanceWageDetailColumnWidths(row);
}, { flush: "post" });

function buildFinanceSummary(sourceOrders, sourceWageRows) {
  const receivable = sourceOrders.reduce((sum, order) => {
    const amount = orderCustomerReceivableBreakdown(order);
    return {
      hkd: sum.hkd + amount.hkd,
      rmb: sum.rmb + amount.rmb
    };
  }, { hkd: 0, rmb: 0 });
  const receivableHKD = receivable.hkd;
  const receivableRMB = receivable.rmb;
  const driverPayableHKD = sourceWageRows.reduce((sum, row) => sum + row.total, 0);
  const driverPayableRMB = sourceWageRows.reduce((sum, row) => sum + row.totalRMB, 0);
  const driverAdvanceHKD = sourceWageRows.reduce((sum, row) => sum + row.advanceFee, 0);
  const driverAdvanceRMB = sourceWageRows.reduce((sum, row) => sum + row.advanceFeeRMB, 0);
  const supplierAdvanceHKD = sourceOrders
    .filter(orderAdvanceFeeBelongsToSupplier)
    .reduce((sum, order) => sum + orderAdvanceFeeHKD(order), 0);
  const supplierAdvanceRMB = sourceOrders
    .filter(orderAdvanceFeeBelongsToSupplier)
    .reduce((sum, order) => sum + orderAdvanceFeeRMB(order), 0);
  const outsourcedHKD = sourceOrders.reduce((sum, order) => sum + supplierOrderPayableBreakdown(order).payableHKD, 0);
  const supplierPayableHKD = sourceOrders
    .filter(orderAdvanceFeeBelongsToSupplier)
    .reduce((sum, order) => sum + supplierOrderPayableBreakdown(order).payableHKD, 0);
  const supplierPayableRMB = sourceOrders
    .filter(orderAdvanceFeeBelongsToSupplier)
    .reduce((sum, order) => sum + supplierOrderPayableBreakdown(order).payableRMB, 0);
  return {
    orderCount: sourceOrders.length,
    receivableHKD,
    receivableRMB,
    driverPayableHKD,
    driverPayableRMB,
    driverAdvanceHKD,
    driverAdvanceRMB,
    supplierAdvanceHKD,
    supplierAdvanceRMB,
    outsourcedHKD,
    supplierPayableHKD,
    supplierPayableRMB,
    outsourcedOrderCount: sourceOrders.filter((order) => order.vehicleSource === "外派车辆").length
  };
}

const financeSummary = computed(() => buildFinanceSummary(financeOrderRows.value, financeWageRows.value));
const statementSummary = computed(() => buildFinanceSummary(statementBillableOrderRows.value, statementWageRows.value));

const bossOrderRows = computed(() =>
  orderRows.value.filter((order) =>
    isFinanceStatVisibleOrder(order) &&
    dateMatchesPeriodFilter(order.date, bossPeriodFilter.value)
  )
);

const bossCustomsBusinessRows = computed(() =>
  customsBusinessAllRows.value.filter((row) =>
    dateMatchesPeriodFilter(row.date, bossPeriodFilter.value)
  )
);

const bossOtherBusinessRows = computed(() =>
  otherBusinessAllRows.value.filter((row) =>
    dateMatchesPeriodFilter(row.date, bossPeriodFilter.value)
  )
);

const bossAdjustmentRows = computed(() =>
  driverAdjustmentRows.value.filter((item) => dateMatchesPeriodFilter(item.date, bossPeriodFilter.value))
);

const bossWageRows = computed(() => buildFinanceWageRows(bossOrderRows.value, bossAdjustmentRows.value));
const bossFinanceSummary = computed(() => buildFinanceSummary(bossOrderRows.value, bossWageRows.value));

function amountTextNumber(value) {
  const matched = String(value || "").replace(/,/g, "").match(/-?\d+(?:\.\d+)?/);
  return matched ? Number(matched[0]) : 0;
}

function bossCompanyExpenseAmount(row) {
  const value = Number(row?.amount);
  return Number.isFinite(value) ? value : amountTextNumber(row?.amount);
}

function createBossCompanyExpenseSalaryRow(row = {}) {
  return {
    id: String(row.id || `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`),
    employeeName: String(row.employeeName || row.employee_name || "").trim(),
    amount: row.amount === undefined || row.amount === null || row.amount === "" ? "" : Number(row.amount),
    note: String(row.note || "").trim()
  };
}

function bossCompanyExpenseEntryType(row = {}) {
  return row.entryType === "income" || row.entry_type === "income" ? "income" : "expense";
}

function bossCompanyExpensePeriodMonth(row = {}) {
  return inputMonthKey(row.periodMonth || row.period_month || row.date || "");
}

function bossCompanyExpenseEntryMonth() {
  return bossVehicleExchangeRatePeriodMonth(bossPeriodFilter.value) || currentPeriodMonthKey();
}

function sortBossCompanyExpenseRows(rows = []) {
  return [...rows].sort((left, right) =>
    bossCompanyExpensePeriodMonth(right).localeCompare(bossCompanyExpensePeriodMonth(left))
    || Number(right.id || 0) - Number(left.id || 0)
  );
}

const bossCompanyExpenseDisplayRows = computed(() =>
  sortBossCompanyExpenseRows(bossCompanyExpenseRows.value)
    .filter((row) => {
      const periodMonth = bossCompanyExpensePeriodMonth(row);
      return periodMonth && dateMatchesPeriodFilter(`${periodMonth}-01`, bossPeriodFilter.value);
    })
);

function bossCompanyExpenseDefaultCategory(source = "expense") {
  const normalizedType = typeof source === "object"
    ? bossCompanyExpenseEntryType(source)
    : bossCompanyExpenseEntryType({ entryType: source });
  return normalizedType === "income"
    ? COMPANY_INCOME_CATEGORY_OPTIONS[0]
    : COMPANY_EXPENSE_CATEGORY_OPTIONS[0];
}

function bossCompanyExpenseCategoryOptionsForType(entryType = "expense") {
  const normalizedType = bossCompanyExpenseEntryType({ entryType });
  const categories = new Set(normalizedType === "income" ? COMPANY_INCOME_CATEGORY_OPTIONS : COMPANY_EXPENSE_CATEGORY_OPTIONS);
  bossCompanyExpenseRows.value.forEach((row) => {
    if (bossCompanyExpenseEntryType(row) !== normalizedType) return;
    const category = String(row.category || "").trim();
    if (category && category !== COMPANY_EXPENSE_CUSTOM_CATEGORY_VALUE) categories.add(category);
  });
  return Array.from(categories);
}

function companyExpenseCategoryOptionsFor(row = {}) {
  const category = String(row.category || "").trim();
  const options = bossCompanyExpenseCategoryOptionsForType(bossCompanyExpenseEntryType(row));
  if (category && category !== COMPANY_EXPENSE_CUSTOM_CATEGORY_VALUE && !options.includes(category)) {
    options.push(category);
  }
  return options;
}

function syncBossCompanyExpenseCategoryForType(form) {
  if (!form) return;
  const options = bossCompanyExpenseCategoryOptionsForType(form.entryType);
  if (!options.includes(form.category) && form.category !== COMPANY_EXPENSE_CUSTOM_CATEGORY_VALUE) {
    form.category = options[0] || bossCompanyExpenseDefaultCategory(form.entryType);
    form.customCategory = "";
  }
}

watch(() => bossCompanyExpenseForm.entryType, () => {
  syncBossCompanyExpenseCategoryForType(bossCompanyExpenseForm);
  if (bossCompanyExpenseIsSalaryCategory(bossCompanyExpenseForm) && !bossCompanyExpenseSalaryRows.value.length) {
    bossCompanyExpenseSalaryRows.value = [createBossCompanyExpenseSalaryRow()];
  }
});

watch(() => bossCompanyExpenseEditForm.entryType, () => {
  syncBossCompanyExpenseCategoryForType(bossCompanyExpenseEditForm);
});

watch(() => bossCompanyExpenseForm.category, () => {
  if (bossCompanyExpenseIsSalaryCategory(bossCompanyExpenseForm) && !bossCompanyExpenseSalaryRows.value.length) {
    bossCompanyExpenseSalaryRows.value = [createBossCompanyExpenseSalaryRow()];
  }
});

function bossCompanyExpenseResolvedCategory(source = {}) {
  const category = String(source.category || "").trim();
  if (category !== COMPANY_EXPENSE_CUSTOM_CATEGORY_VALUE) return category;
  return String(source.customCategory || "").trim();
}

function bossCompanyExpenseIsSalaryCategory(source = {}) {
  return bossCompanyExpenseEntryType(source) === "expense" && bossCompanyExpenseResolvedCategory(source) === "员工工资";
}

function bossCompanyExpenseDisplayLabel(row = {}) {
  const category = String(row.category || "").trim() || "-";
  const employeeName = String(row.employeeName || row.employee_name || "").trim();
  return bossCompanyExpenseIsSalaryCategory(row) && employeeName ? `${category} / ${employeeName}` : category;
}

function bossCompanyExpenseSalaryTotal() {
  return bossCompanyExpenseSalaryRows.value.reduce((sum, row) => {
    const amount = Number(row.amount);
    return sum + (Number.isFinite(amount) ? amount : 0);
  }, 0);
}

function bossCompanyExpenseSalaryFilledRows() {
  return bossCompanyExpenseSalaryRows.value
    .map((row) => createBossCompanyExpenseSalaryRow(row))
    .filter((row) =>
      String(row.employeeName || "").trim()
      || String(row.amount ?? "").trim() !== ""
      || String(row.note || "").trim() !== ""
    );
}

function bossCompanyExpenseSalaryValidationMessage(rows = bossCompanyExpenseSalaryFilledRows()) {
  if (!rows.length) return "请先填写员工工资明细";
  for (const row of rows) {
    if (!String(row.employeeName || "").trim()) return "请填写员工姓名";
    if (!Number.isFinite(Number(row.amount)) || Number(row.amount) <= 0) return "请填写大于 0 的工资金额";
  }
  return "";
}

function addBossCompanyExpenseSalaryRow() {
  bossCompanyExpenseSalaryRows.value.push(createBossCompanyExpenseSalaryRow());
}

function removeBossCompanyExpenseSalaryRow(index) {
  if (bossCompanyExpenseSalaryRows.value.length <= 1) return;
  bossCompanyExpenseSalaryRows.value.splice(index, 1);
}

const bossCompanyExpenseSummary = computed(() => {
  const rows = bossCompanyExpenseDisplayRows.value;
  const incomeTotal = rows
    .filter((row) => bossCompanyExpenseEntryType(row) === "income")
    .reduce((sum, row) => sum + bossCompanyExpenseAmount(row), 0);
  const total = rows
    .filter((row) => bossCompanyExpenseEntryType(row) === "expense")
    .reduce((sum, row) => sum + bossCompanyExpenseAmount(row), 0);
  const activeMonth = bossCompanyExpenseEntryMonth();
  const monthTotal = bossCompanyExpenseRows.value
    .filter((row) => bossCompanyExpenseEntryType(row) === "expense" && bossCompanyExpensePeriodMonth(row) === activeMonth)
    .reduce((sum, row) => sum + bossCompanyExpenseAmount(row), 0);
  const monthIncomeTotal = bossCompanyExpenseRows.value
    .filter((row) => bossCompanyExpenseEntryType(row) === "income" && bossCompanyExpensePeriodMonth(row) === activeMonth)
    .reduce((sum, row) => sum + bossCompanyExpenseAmount(row), 0);
  const top = [...rows].sort((left, right) => bossCompanyExpenseAmount(right) - bossCompanyExpenseAmount(left))[0] || null;
  return {
    total,
    incomeTotal,
    monthTotal,
    monthIncomeTotal,
    itemCount: rows.length,
    topCategory: top ? bossCompanyExpenseDisplayLabel(top) : "-",
    topAmount: top ? bossCompanyExpenseAmount(top) : 0
  };
});

function resetBossCompanyExpenseForm() {
  Object.assign(bossCompanyExpenseForm, {
    entryType: "expense",
    periodMonth: bossCompanyExpenseEntryMonth(),
    category: bossCompanyExpenseDefaultCategory("expense"),
    customCategory: "",
    amount: "",
    note: ""
  });
  bossCompanyExpenseSalaryRows.value = [createBossCompanyExpenseSalaryRow()];
}

function bossCompanyExpensePayload(source = {}) {
  return {
    entryType: bossCompanyExpenseEntryType(source),
    periodMonth: inputMonthKey(source.periodMonth || source.period_month || source.date || bossCompanyExpenseEntryMonth()),
    category: bossCompanyExpenseResolvedCategory(source),
    employeeName: String(source.employeeName || source.employee_name || "").trim(),
    amount: Number(source.amount || 0),
    note: String(source.note || "").trim()
  };
}

function upsertBossCompanyExpenseRow(item) {
  bossCompanyExpenseRows.value = sortBossCompanyExpenseRows(
    bossCompanyExpenseRows.value.some((row) => String(row.id) === String(item.id))
      ? bossCompanyExpenseRows.value.map((row) => String(row.id) === String(item.id) ? item : row)
      : [item, ...bossCompanyExpenseRows.value]
  );
}

function isEditingBossCompanyExpense(row = {}) {
  return String(row.id || "") === String(editingBossCompanyExpenseId.value || "");
}

function startBossCompanyExpenseEdit(row = {}) {
  editingBossCompanyExpenseId.value = String(row.id || "");
  Object.assign(bossCompanyExpenseEditForm, {
    entryType: bossCompanyExpenseEntryType(row),
    periodMonth: bossCompanyExpensePeriodMonth(row),
    category: String(row.category || "").trim() || bossCompanyExpenseDefaultCategory(row),
    customCategory: "",
    employeeName: String(row.employeeName || row.employee_name || "").trim(),
    amount: row.amount ?? "",
    note: row.note || ""
  });
}

function cancelBossCompanyExpenseEdit(row = {}) {
  if (!row?.id || isEditingBossCompanyExpense(row)) {
    editingBossCompanyExpenseId.value = "";
  }
}

async function addBossCompanyExpense() {
  const payload = bossCompanyExpensePayload(bossCompanyExpenseForm);
  if (!payload.periodMonth) {
    notify("请选择月份");
    return;
  }
  if (!payload.category) {
    notify("请填写项目名称");
    return;
  }
  try {
    bossCompanyExpenseSaving.value = true;
    if (bossCompanyExpenseIsSalaryCategory(bossCompanyExpenseForm)) {
      const salaryRows = bossCompanyExpenseSalaryFilledRows();
      const validationMessage = bossCompanyExpenseSalaryValidationMessage(salaryRows);
      if (validationMessage) {
        notify(validationMessage);
        return;
      }
      const items = salaryRows.map((row) => ({
        ...payload,
        employeeName: row.employeeName,
        amount: Number(row.amount || 0),
        note: row.note
      }));
      const createdRows = await financeApi.createCompanyExpenseBatch({ items });
      createdRows.forEach(upsertBossCompanyExpenseRow);
      resetBossCompanyExpenseForm();
      notify(`已新增 ${createdRows.length} 条员工工资明细`);
      return;
    }
    if (!Number.isFinite(payload.amount) || payload.amount <= 0) {
      notify("请填写大于 0 的金额");
      return;
    }
    const item = await financeApi.createCompanyExpense(payload);
    upsertBossCompanyExpenseRow(item);
    resetBossCompanyExpenseForm();
    notify(payload.entryType === "income" ? "其他收入已新增" : "公司支出已新增");
  } catch (error) {
    notify(error.message || "公司级收支保存失败");
  } finally {
    bossCompanyExpenseSaving.value = false;
  }
}

async function saveBossCompanyExpense(row) {
  if (!row?.id) return;
  const payload = bossCompanyExpensePayload(isEditingBossCompanyExpense(row) ? bossCompanyExpenseEditForm : row);
  if (!payload.periodMonth || !payload.category || !Number.isFinite(payload.amount) || payload.amount <= 0) {
    notify("请填写完整的月份、项目和大于 0 的金额");
    return;
  }
  if (bossCompanyExpenseIsSalaryCategory(payload) && !String(payload.employeeName || "").trim()) {
    notify("请填写员工姓名");
    return;
  }
  try {
    bossCompanyExpenseSaving.value = true;
    const item = await financeApi.updateCompanyExpense(row.id, payload);
    upsertBossCompanyExpenseRow(item);
    cancelBossCompanyExpenseEdit(row);
    notify(payload.entryType === "income" ? "其他收入已保存" : "公司支出已保存");
  } catch (error) {
    notify(error.message || "公司级收支保存失败");
  } finally {
    bossCompanyExpenseSaving.value = false;
  }
}

async function deleteBossCompanyExpense(row) {
  if (!row?.id) return;
  const typeLabel = bossCompanyExpenseEntryType(row) === "income" ? "收入" : "支出";
  if (!window.confirm(`确定删除 ${bossCompanyExpensePeriodMonth(row)} / ${bossCompanyExpenseDisplayLabel(row)} 这笔${typeLabel}？`)) return;
  try {
    bossCompanyExpenseSaving.value = true;
    await financeApi.deleteCompanyExpense(row.id);
    bossCompanyExpenseRows.value = bossCompanyExpenseRows.value.filter((item) => String(item.id) !== String(row.id));
    cancelBossCompanyExpenseEdit(row);
    notify(`${typeLabel}已删除`);
  } catch (error) {
    notify(error.message || "公司级收支删除失败");
  } finally {
    bossCompanyExpenseSaving.value = false;
  }
}

function hkdToRmbRate() {
  const rate = Number(statementExchangeRate.value || 0.92);
  return Number.isFinite(rate) && rate > 0 ? rate : 0.92;
}

function rmbEquivalent(hkd = 0, rmb = 0) {
  return Number(rmb || 0) + Number(hkd || 0) * hkdToRmbRate();
}

function bossVehicleExchangeRatePeriodMonth(filterKey = bossPeriodFilter.value) {
  const { year, month } = periodFilterParts(filterKey);
  return `${year}-${month}`;
}

function monthlyExchangeRatePeriodMonth(scope = "boss") {
  if (scope === "statement") return bossVehicleExchangeRatePeriodMonth(activeStatementMonthFilter.value);
  return bossVehicleExchangeRatePeriodMonth(periodFilterValue(scope));
}

function normalizeMonthlyExchangeRatePeriodMonth(value = "") {
  const text = String(value || "").trim();
  return /^\d{4}-\d{2}$/.test(text) ? text : currentPeriodMonthKey();
}

function normalizeBossVehicleExchangeRate(value = BOSS_VEHICLE_DEFAULT_EXCHANGE_RATE) {
  const rate = Number(value);
  return Number.isFinite(rate) && rate > 0 ? rate : Number(BOSS_VEHICLE_DEFAULT_EXCHANGE_RATE);
}

function bossVehicleExchangeRateRow(periodMonth = bossVehicleExchangeRatePeriodMonth()) {
  return bossVehicleExchangeRateRows.value.find((row) => row.periodMonth === periodMonth) || null;
}

function upsertBossVehicleExchangeRateRow(item = {}, options = {}) {
  const periodMonth = String(item.periodMonth || item.period_month || "").trim();
  if (!periodMonth) return;
  const next = {
    ...item,
    periodMonth,
    rate: normalizeBossVehicleExchangeRate(item.rate)
  };
  bossVehicleExchangeRateRows.value = bossVehicleExchangeRateRows.value.some((row) => row.periodMonth === periodMonth)
    ? bossVehicleExchangeRateRows.value.map((row) => row.periodMonth === periodMonth ? { ...row, ...next } : row)
    : [next, ...bossVehicleExchangeRateRows.value];
  if (options.syncInput || !Object.prototype.hasOwnProperty.call(monthlyExchangeRateDrafts, periodMonth)) {
    monthlyExchangeRateDrafts[periodMonth] = String(next.rate);
  }
  if (options.syncInput && periodMonth === bossVehicleExchangeRatePeriodMonth()) {
    bossVehicleExchangeRateInputMonth.value = periodMonth;
    bossVehicleExchangeRate.value = String(next.rate);
  }
}

function syncBossVehicleExchangeRateFromRows() {
  const periodMonth = bossVehicleExchangeRatePeriodMonth();
  const row = bossVehicleExchangeRateRow(periodMonth);
  bossVehicleExchangeRateInputMonth.value = periodMonth;
  bossVehicleExchangeRate.value = String(row?.rate || BOSS_VEHICLE_DEFAULT_EXCHANGE_RATE);
}

function bossVehicleExchangeRateValue(periodMonth = bossVehicleExchangeRatePeriodMonth()) {
  const monthKey = normalizeMonthlyExchangeRatePeriodMonth(periodMonth);
  const draftRate = Number(monthlyExchangeRateDrafts[monthKey]);
  if (Object.prototype.hasOwnProperty.call(monthlyExchangeRateDrafts, monthKey) && Number.isFinite(draftRate) && draftRate > 0) {
    return draftRate;
  }
  const inputRate = Number(bossVehicleExchangeRate.value);
  if (bossVehicleExchangeRateInputMonth.value === monthKey && Number.isFinite(inputRate) && inputRate > 0) {
    return inputRate;
  }
  const rowRate = Number(bossVehicleExchangeRateRow(monthKey)?.rate);
  return Number.isFinite(rowRate) && rowRate > 0 ? rowRate : Number(BOSS_VEHICLE_DEFAULT_EXCHANGE_RATE);
}

function monthlyExchangeRateInputValue(periodMonth = bossVehicleExchangeRatePeriodMonth()) {
  const monthKey = normalizeMonthlyExchangeRatePeriodMonth(periodMonth);
  if (Object.prototype.hasOwnProperty.call(monthlyExchangeRateDrafts, monthKey)) {
    return monthlyExchangeRateDrafts[monthKey];
  }
  return String(bossVehicleExchangeRateRow(monthKey)?.rate || BOSS_VEHICLE_DEFAULT_EXCHANGE_RATE);
}

function clearBossVehicleExchangeRateSaveTimer(periodMonth = "") {
  const monthKey = normalizeMonthlyExchangeRatePeriodMonth(periodMonth);
  if (!bossVehicleExchangeRateSaveTimers[monthKey]) return;
  window.clearTimeout(bossVehicleExchangeRateSaveTimers[monthKey]);
  delete bossVehicleExchangeRateSaveTimers[monthKey];
}

function scheduleBossVehicleExchangeRateSave(periodMonth, rate) {
  const monthKey = normalizeMonthlyExchangeRatePeriodMonth(periodMonth);
  clearBossVehicleExchangeRateSaveTimer(monthKey);
  bossVehicleExchangeRateSaveTimers[monthKey] = window.setTimeout(() => {
    delete bossVehicleExchangeRateSaveTimers[monthKey];
    saveBossVehicleExchangeRate(monthKey, rate, { notifySuccess: false, notifyError: true });
  }, 500);
}

async function saveBossVehicleExchangeRate(periodMonth = bossVehicleExchangeRatePeriodMonth(), rateValue = bossVehicleExchangeRate.value, options = {}) {
  const rate = Number(rateValue);
  const monthKey = normalizeMonthlyExchangeRatePeriodMonth(periodMonth);
  if (!monthKey || !Number.isFinite(rate) || rate <= 0 || !loggedIn.value || !canAccessMonthlyExchangeRates()) return null;
  const requestId = bossVehicleExchangeRateSaveRequestId + 1;
  bossVehicleExchangeRateSaveRequestId = requestId;
  bossVehicleExchangeRateSaving.value = true;
  try {
    const item = await financeApi.saveVehicleProfitExchangeRate({ periodMonth: monthKey, rate });
    upsertBossVehicleExchangeRateRow(item, { syncInput: true });
    if (options.notifySuccess) notify("当月汇率已保存");
    return item;
  } catch (error) {
    if (options.notifyError !== false) notify(`当月汇率保存失败：${error.message}`);
    return null;
  } finally {
    if (requestId === bossVehicleExchangeRateSaveRequestId) {
      bossVehicleExchangeRateSaving.value = false;
    }
  }
}

function flushMonthlyExchangeRateSave(periodMonth = bossVehicleExchangeRatePeriodMonth()) {
  const monthKey = normalizeMonthlyExchangeRatePeriodMonth(periodMonth);
  clearBossVehicleExchangeRateSaveTimer(monthKey);
  saveBossVehicleExchangeRate(
    monthKey,
    monthlyExchangeRateInputValue(monthKey),
    { notifySuccess: false, notifyError: true }
  );
}

function flushBossVehicleExchangeRateSave() {
  flushMonthlyExchangeRateSave(bossVehicleExchangeRateInputMonth.value || bossVehicleExchangeRatePeriodMonth());
}

function setMonthlyExchangeRate(periodMonth = bossVehicleExchangeRatePeriodMonth(), value = "") {
  const monthKey = normalizeMonthlyExchangeRatePeriodMonth(periodMonth);
  const text = String(value ?? "").trim();
  const rate = Number(text);
  monthlyExchangeRateDrafts[monthKey] = text;
  if (monthKey === bossVehicleExchangeRatePeriodMonth()) {
    bossVehicleExchangeRateInputMonth.value = monthKey;
    bossVehicleExchangeRate.value = text;
  }
  if (!Number.isFinite(rate) || rate <= 0) {
    clearBossVehicleExchangeRateSaveTimer(monthKey);
    return;
  }
  upsertBossVehicleExchangeRateRow({ periodMonth: monthKey, rate });
  scheduleBossVehicleExchangeRateSave(monthKey, rate);
}

function setBossVehicleExchangeRate(value = "") {
  setMonthlyExchangeRate(bossVehicleExchangeRatePeriodMonth(), value);
}

function bossVehicleRmbEquivalent(hkd = 0, rmb = 0, periodMonth = bossVehicleExchangeRatePeriodMonth()) {
  return Number(rmb || 0) + Number(hkd || 0) * bossVehicleExchangeRateValue(periodMonth);
}

function bossCompanyRmbEquivalent(hkd = 0, rmb = 0, periodMonth = bossVehicleExchangeRatePeriodMonth()) {
  return bossVehicleRmbEquivalent(hkd, rmb, periodMonth);
}

function bossVehicleHkdEquivalent(hkd = 0, rmb = 0, periodMonth = bossVehicleExchangeRatePeriodMonth()) {
  const rate = bossVehicleExchangeRateValue(periodMonth);
  return Number(hkd || 0) + (rate > 0 ? Number(rmb || 0) / rate : 0);
}

function moneyHkdDisplay(value = 0) {
  return `HKD ${money(value)}`;
}

function moneyRmbDisplay(value = 0) {
  return `RMB ${money(value)}`;
}

function bossVehicleProfitRateText(profitHKD = 0, totalCostHKD = 0) {
  const revenueHKD = Number(profitHKD || 0) + Number(totalCostHKD || 0);
  if (!revenueHKD) return "-";
  return `${((Number(profitHKD || 0) / revenueHKD) * 100).toFixed(1)}%`;
}

function bossCompanyProfitMarginText(profitRMB = 0, revenueRMB = 0) {
  const revenue = Number(revenueRMB || 0);
  if (!revenue) return "-";
  return `${((Number(profitRMB || 0) / revenue) * 100).toFixed(1)}%`;
}

function marginText(profitHKD = 0, profitRMB = 0, revenueHKD = 0, revenueRMB = 0) {
  const revenue = rmbEquivalent(revenueHKD, revenueRMB);
  if (!revenue) return "-";
  return `${((rmbEquivalent(profitHKD, profitRMB) / revenue) * 100).toFixed(1)}%`;
}

function moneyPairDisplay(hkd = 0, rmb = 0) {
  return Number(hkd || 0) || Number(rmb || 0) ? moneyPair(hkd, rmb) : "HKD 0 / RMB 0";
}

function orderReceivableBreakdown(sourceOrders) {
  return sourceOrders.reduce((sum, order) => {
    const amount = orderCustomerReceivableBreakdown(order);
    return {
      hkd: sum.hkd + amount.hkd,
      rmb: sum.rmb + amount.rmb
    };
  }, { hkd: 0, rmb: 0 });
}

function customsBusinessRevenueBreakdown(sourceRows = []) {
  return sourceRows.reduce((sum, row) => ({
    hkd: sum.hkd,
    rmb: sum.rmb + Number(row.total || 0)
  }), { hkd: 0, rmb: 0 });
}

function otherBusinessRevenueBreakdown(sourceRows = []) {
  return sourceRows.reduce((sum, row) => {
    const totals = otherBusinessRowTotals(row);
    return {
      income: sum.income + totals.totalIncome,
      cost: sum.cost + totals.totalCost,
      profit: sum.profit + totals.profit
    };
  }, { income: 0, cost: 0, profit: 0 });
}

function orderDriverRows(order) {
  return driverRows.value.filter((driver) => orderMatchesDriverForWage(order, driver));
}

function orderDriverPayBreakdown(order) {
  return orderDriverRows(order).reduce((sum, driver) => {
    const amount = driverPayableTripFeeBreakdown(order, driver);
    return {
      hkd: sum.hkd + Number(amount.hkd || 0),
      rmb: sum.rmb + Number(amount.rmb || 0)
    };
  }, { hkd: 0, rmb: 0 });
}

function periodMonthSpanForRows(filterKey, sourceRows) {
  const { mode } = periodFilterParts(filterKey);
  if (mode === "month") return 1;
  if (mode === "year") return 12;
  const months = new Set(sourceRows.map((row) => inputMonthKey(row.date)).filter(Boolean));
  return Math.max(1, months.size);
}

function vehicleFixedCostRMB(vehicle, sourceOrders, filterKey) {
  const monthlyCost = Number(vehicle?.monthlyCost || 0);
  if (!monthlyCost || !sourceOrders.length) return 0;
  return monthlyCost * periodMonthSpanForRows(filterKey, sourceOrders);
}

function vehicleExpenseAmountBreakdown(expense = {}, filterKey = currentPeriodMonthKey()) {
  if (!expense?.plate) return { hkd: 0, rmb: 0 };
  const amount = Number(expense.amount || 0);
  if (!amount) return { hkd: 0, rmb: 0 };
  if (expense.type === "annual") {
    const startDate = vehicleExpenseAnnualStartDate(expense);
    const endDate = vehicleExpenseAnnualEndDate(expense);
    const { mode } = periodFilterParts(filterKey);
    if (mode === "all") {
      return expense.currency === "港币" ? { hkd: amount, rmb: 0 } : { hkd: 0, rmb: amount };
    }
    if (!startDate || !endDate) {
      const { year } = periodFilterParts(filterKey);
      const expenseYear = String(expense.year || String(expense.date || "").slice(0, 4));
      if (expenseYear !== year) return { hkd: 0, rmb: 0 };
      const fallbackAmount = mode === "month" ? amount / 12 : amount;
      return expense.currency === "港币" ? { hkd: fallbackAmount, rmb: 0 } : { hkd: 0, rmb: fallbackAmount };
    }
    const { start, end } = periodFilterBounds(filterKey);
    const overlapDays = inputDateRangeOverlapDays(startDate, endDate, start, end);
    if (!overlapDays) return { hkd: 0, rmb: 0 };
    const totalDays = inputDateRangeDays(startDate, endDate);
    if (!totalDays) return { hkd: 0, rmb: 0 };
    const periodAmount = amount * (overlapDays / totalDays);
    return expense.currency === "港币" ? { hkd: periodAmount, rmb: 0 } : { hkd: 0, rmb: periodAmount };
  }
  if (!dateMatchesPeriodFilter(expense.date, filterKey)) return { hkd: 0, rmb: 0 };
  return expense.currency === "港币" ? { hkd: amount, rmb: 0 } : { hkd: 0, rmb: amount };
}

function vehicleExpenseAppliesToPeriod(expense = {}, filterKey = currentPeriodMonthKey()) {
  const amount = vehicleExpenseAmountBreakdown(expense, filterKey);
  return Boolean(amount.hkd || amount.rmb);
}

function vehicleExpenseBreakdownForPlate(plate, filterKey = currentPeriodMonthKey()) {
  return vehicleExpenseRows.value
    .filter((expense) => String(expense.plate || "").trim() === String(plate || "").trim())
    .reduce((sum, expense) => {
      const amount = vehicleExpenseAmountBreakdown(expense, filterKey);
      return {
        hkd: sum.hkd + amount.hkd,
        rmb: sum.rmb + amount.rmb
      };
    }, { hkd: 0, rmb: 0 });
}

function vehicleExpenseBreakdownByTypeForPlate(plate, filterKey = currentPeriodMonthKey()) {
  const breakdowns = VEHICLE_EXPENSE_CONFIGS.reduce((result, config) => {
    result[config.type] = { hkd: 0, rmb: 0 };
    return result;
  }, {});
  breakdowns.insurance = { hkd: 0, rmb: 0 };
  breakdowns.review = { hkd: 0, rmb: 0 };
  breakdowns.plateHead = { hkd: 0, rmb: 0 };
  vehicleExpenseRows.value
    .filter((expense) => String(expense.plate || "").trim() === String(plate || "").trim())
    .forEach((expense) => {
      const amount = vehicleExpenseAmountBreakdown(expense, filterKey);
      const typeBucket = breakdowns[expense.type] || breakdowns.other;
      typeBucket.hkd += amount.hkd;
      typeBucket.rmb += amount.rmb;
      if (expense.type === "annual") {
        const annualName = String(expense.name || "").trim();
        const annualBucket = annualName === "年审费"
          ? breakdowns.review
          : annualName === "牌头费"
            ? breakdowns.plateHead
            : breakdowns.insurance;
        annualBucket.hkd += amount.hkd;
        annualBucket.rmb += amount.rmb;
      }
    });
  return breakdowns;
}

function bossVehicleExpenseTotalFromBreakdown(breakdown = {}) {
  return ["fuel", "repair", "insurance", "review", "plateHead", "other"]
    .map((key) => breakdown[key] || { hkd: 0, rmb: 0 })
    .reduce((sum, item) => ({
      hkd: sum.hkd + Number(item.hkd || 0),
      rmb: sum.rmb + Number(item.rmb || 0)
    }), { hkd: 0, rmb: 0 });
}

const BOSS_VEHICLE_FREIGHT_INCOME_FEE_NAMES = new Set(["中港运费", "基础运费"]);

function bossVehicleFeeName(fee = {}) {
  return String(feeItemForFee(fee)?.name || fee.name || "").trim();
}

function isBossVehicleFreightIncomeFee(fee = {}) {
  return BOSS_VEHICLE_FREIGHT_INCOME_FEE_NAMES.has(bossVehicleFeeName(fee));
}

function bossVehicleSingleDriverMode(order = {}) {
  return (normalizeTransportMode(order.transportMode || "单司机") || "单司机") === "单司机";
}

function isBossCompanyVehiclePlate(plate = "") {
  const targetPlate = String(plate || "").trim();
  return Boolean(targetPlate && vehiclePlateSet.value.has(targetPlate));
}

function bossVehicleRouteLevel1(value = "") {
  const [level1 = ""] = String(value || "")
    .split(/[\/／｜|>]+/)
    .map((item) => normalizeFreightLabel(item))
    .filter(Boolean);
  return level1;
}

function bossVehicleOrderDriverName(order = {}) {
  if (!bossVehicleSingleDriverMode(order)) return "";
  const directName = String(order.driver || order.hkDriver || order.mainlandDriver || "").trim();
  if (directName) return directName;
  const plate = String(order.plate || "").trim();
  const vehicle = vehicleRowsByPlate.value.get(plate) || null;
  const boundDriver = driverRowsByBoundPlate.value.get(plate) || null;
  return String(vehicle?.driver || boundDriver?.name || "").trim();
}

function bossVehicleOrderDriver(order = {}) {
  const driverName = bossVehicleOrderDriverName(order);
  if (!driverName && !order.plate) return null;
  const plate = String(order.plate || "").trim();
  return (driverName ? driverRowsByName.value.get(driverName) : null)
    || (plate ? driverRowsByBoundPlate.value.get(plate) : null)
    || null;
}

function bossVehicleDriverCostRuleMatchesOrder(rule = {}, order = {}, driver = null) {
  const driverName = bossVehicleOrderDriverName(order);
  const resolvedDriver = driver || (driverName ? driverRowsByName.value.get(driverName) : null) || null;
  return Boolean(resolvedDriver && driverCostCenterRuleMatchesOrder(rule, order, resolvedDriver));
}

function bossVehicleDriverCostRuleForOrder(order = {}) {
  if (!bossVehicleSingleDriverMode(order)) return null;
  const driver = bossVehicleOrderDriver(order);
  return driverCostCenterRuleForOrder(order, driver);
}

function amountBreakdownByCurrency(amount = 0, currency = "港币") {
  const value = Number(amount || 0);
  if (!value) return { hkd: 0, rmb: 0 };
  return currencyCodeDisplay(currency || "港币") === "RMB"
    ? { hkd: 0, rmb: value }
    : { hkd: value, rmb: 0 };
}

function bossVehicleOrderFeeRows(order = {}) {
  const allFees = Array.isArray(order?.fees) ? order.fees : [];
  const hasFeeRows = allFees.some((fee) =>
    bossVehicleFeeName(fee)
    && Number(fee.amount || 0) !== 0
  );
  const fees = allFees
    .filter((fee) => !isAdvanceFee(fee))
    .filter((fee) => bossVehicleFeeName(fee) && Number(fee.amount || 0) !== 0);
  if (hasFeeRows) return fees;
  const receivable = orderCustomerReceivableBreakdown(order);
  const fallbackFees = [];
  if (Number(receivable.hkd || 0)) {
    fallbackFees.push({ name: "基础运费", currency: "港币", amount: Number(receivable.hkd || 0) });
  }
  if (Number(receivable.rmb || 0)) {
    fallbackFees.push({ name: "基础运费", currency: "人民币", amount: Number(receivable.rmb || 0) });
  }
  return fallbackFees;
}

function bossVehicleDriverCostValueForFee(rule = {}, fee = {}) {
  if (!rule) return 0;
  const item = feeItemForFee(fee);
  if (!item || item.category === "代垫" || isCompanyCoveredFeeItem(item)) return 0;
  const values = parseCostCenterValues(rule.costValues);
  const matchedKey = driverCostCenterFeeValueKeys(fee, item)
    .find((key) => Object.prototype.hasOwnProperty.call(values, key));
  const costValue = normalizeCostCenterValue(
    matchedKey ? values[matchedKey] : 0,
    item.currency || fee.currency || "港币"
  );
  return Number((costValue.amount * feeCostQuantity(fee)).toFixed(2));
}

function bossVehicleDriverCostCurrencyForFee(fee = {}) {
  return feeItemForFee(fee)?.currency || fee.currency || "港币";
}

function bossVehicleOrderFeeBreakdown(order) {
  if (!bossVehicleSingleDriverMode(order)) {
    return { revenueHKD: 0, revenueRMB: 0, costHKD: 0, costRMB: 0, advanceHKD: 0, advanceRMB: 0, orderProfitHKD: 0, orderProfitRMB: 0, totalRevenueHKD: 0, totalRevenueRMB: 0 };
  }
  const driver = bossVehicleOrderDriver(order);
  const costRule = bossVehicleDriverCostRuleForOrder(order);
  const breakdown = bossVehicleOrderFeeRows(order)
    .reduce((sum, fee) => {
      const incomeHKD = feeAmountHKD(fee);
      const incomeRMB = feeAmountRMB(fee);
      const costDetail = isCompanyCoveredFee(fee)
        ? companyCoveredFeeCostSnapshot(fee, order)
        : driverCostCenterFeeCostForRule(costRule, fee, driver);
      const cost = amountBreakdownByCurrency(costDetail.amount, costDetail.currency || bossVehicleDriverCostCurrencyForFee(fee));
      const freightIncome = isBossVehicleFreightIncomeFee(fee)
        ? { hkd: incomeHKD, rmb: incomeRMB }
        : { hkd: 0, rmb: 0 };
      return {
        ...sum,
        revenueHKD: sum.revenueHKD + freightIncome.hkd,
        revenueRMB: sum.revenueRMB + freightIncome.rmb,
        costHKD: sum.costHKD + cost.hkd,
        costRMB: sum.costRMB + cost.rmb,
        totalRevenueHKD: sum.totalRevenueHKD + incomeHKD,
        totalRevenueRMB: sum.totalRevenueRMB + incomeRMB,
        orderProfitHKD: sum.orderProfitHKD + incomeHKD - cost.hkd,
        orderProfitRMB: sum.orderProfitRMB + incomeRMB - cost.rmb
      };
    }, { revenueHKD: 0, revenueRMB: 0, costHKD: 0, costRMB: 0, totalRevenueHKD: 0, totalRevenueRMB: 0, orderProfitHKD: 0, orderProfitRMB: 0 });
  const advance = driverFinanceAdvanceBreakdown(order, driver);
  return {
    ...breakdown,
    advanceHKD: advance.hkd,
    advanceRMB: advance.rmb,
    totalRevenueHKD: breakdown.totalRevenueHKD + advance.hkd,
    totalRevenueRMB: breakdown.totalRevenueRMB + advance.rmb
  };
}

function bossVehicleProfitOrdersForPlate(plate = "") {
  const targetPlate = String(plate || "").trim();
  if (!targetPlate) return [];
  return bossOrderRows.value
    .filter((order) =>
      normalizeVehicleSource(order.vehicleSource) === OWN_VEHICLE_SOURCE
      && String(order.plate || "").trim() === targetPlate
      && isBossCompanyVehiclePlate(order.plate)
      && bossVehicleSingleDriverMode(order)
    )
    .sort((left, right) => String(left.date || "").localeCompare(String(right.date || "")) || String(left.no || "").localeCompare(String(right.no || "")));
}

function bossVehicleProfitDetailFeeRows(order = {}) {
  const driver = bossVehicleOrderDriver(order);
  const costRule = bossVehicleDriverCostRuleForOrder(order);
  return bossVehicleOrderFeeRows(order).map((fee) => {
    const income = { hkd: feeAmountHKD(fee), rmb: feeAmountRMB(fee) };
    const costDetail = isCompanyCoveredFee(fee)
      ? companyCoveredFeeCostSnapshot(fee, order)
      : driverCostCenterFeeCostForRule(costRule, fee, driver);
    const cost = amountBreakdownByCurrency(costDetail.amount, costDetail.currency || bossVehicleDriverCostCurrencyForFee(fee));
    return {
      name: bossVehicleFeeName(fee) || "费用",
      income: moneyPairDisplay(income.hkd, income.rmb),
      cost: moneyPairDisplay(cost.hkd, cost.rmb),
      profit: moneyPairDisplay(income.hkd - cost.hkd, income.rmb - cost.rmb),
      costMatched: costDetail.matched,
      remark: String(fee.remark || "").trim()
    };
  });
}

function bossVehicleProfitDetailOrderRows(plate = "") {
  const periodMonth = bossVehicleExchangeRatePeriodMonth(bossPeriodFilter.value);
  return bossVehicleProfitOrdersForPlate(plate).map((order) => {
    const breakdown = bossVehicleOrderFeeBreakdown(order);
    return {
      order,
      no: order.no || "-",
      date: order.date || "-",
      customer: partnerDisplayLabel(order.customer || "", "客户") || order.customer || "-",
      driver: bossVehicleOrderDriverName(order) || "-",
      transportMode: normalizeTransportMode(order.transportMode || "") || "-",
      route: relatedOrderRouteText(order) || "-",
      freightRevenue: moneyPairDisplay(breakdown.revenueHKD, breakdown.revenueRMB),
      totalRevenue: moneyPairDisplay(breakdown.totalRevenueHKD, breakdown.totalRevenueRMB),
      cost: moneyPairDisplay(breakdown.costHKD, breakdown.costRMB),
      advance: moneyPairDisplay(breakdown.advanceHKD, breakdown.advanceRMB),
      profit: moneyPairDisplay(breakdown.orderProfitHKD, breakdown.orderProfitRMB),
      profitHKDEquivalent: moneyHkdDisplay(bossVehicleHkdEquivalent(breakdown.orderProfitHKD, breakdown.orderProfitRMB, periodMonth)),
      fees: bossVehicleProfitDetailFeeRows(order)
    };
  });
}

const activeBossVehicleProfitDetailRow = computed(() =>
  bossVehicleProfitDisplayRows.value.find((row) => row.plate === activeBossVehicleProfitDetailPlate.value) || null
);

const activeBossVehicleProfitDetailOrderRows = computed(() =>
  bossVehicleProfitDetailOrderRows(activeBossVehicleProfitDetailPlate.value)
);

function openBossVehicleProfitDetail(row = {}) {
  const plate = String(row?.plate || "").trim();
  if (!plate) return;
  activeBossVehicleProfitDetailPlate.value = plate;
}

function closeBossVehicleProfitDetail() {
  activeBossVehicleProfitDetailPlate.value = "";
}

const bossVehicleProfitDisplayRows = computed(() => {
  const groups = new Map();
  bossOrderRows.value
    .filter((order) =>
      normalizeVehicleSource(order.vehicleSource) === OWN_VEHICLE_SOURCE
      && isBossCompanyVehiclePlate(order.plate)
      && bossVehicleSingleDriverMode(order)
    )
    .forEach((order) => {
      const plate = String(order.plate || "").trim();
      const row = groups.get(plate) || {
        plate,
        driverNames: new Set(),
        orders: [],
        revenueHKD: 0,
        revenueRMB: 0,
        totalRevenueHKD: 0,
        totalRevenueRMB: 0,
        orderProfitHKD: 0,
        orderProfitRMB: 0
      };
      const feeBreakdown = bossVehicleOrderFeeBreakdown(order);
      row.orders.push(order);
      row.revenueHKD += feeBreakdown.revenueHKD;
      row.revenueRMB += feeBreakdown.revenueRMB;
      row.totalRevenueHKD += feeBreakdown.totalRevenueHKD;
      row.totalRevenueRMB += feeBreakdown.totalRevenueRMB;
      row.orderProfitHKD += feeBreakdown.orderProfitHKD;
      row.orderProfitRMB += feeBreakdown.orderProfitRMB;
      const driverName = bossVehicleOrderDriverName(order);
      if (driverName) row.driverNames.add(driverName);
      groups.set(plate, row);
    });
  vehicleExpenseRows.value
    .filter((expense) =>
      vehicleExpenseAppliesToPeriod(expense, bossPeriodFilter.value)
      && isBossCompanyVehiclePlate(expense.plate)
    )
    .forEach((expense) => {
      const plate = String(expense.plate || "").trim();
      if (!groups.has(plate)) {
        groups.set(plate, {
          plate,
          driverNames: new Set(),
          orders: [],
          revenueHKD: 0,
          revenueRMB: 0,
          totalRevenueHKD: 0,
          totalRevenueRMB: 0,
          orderProfitHKD: 0,
          orderProfitRMB: 0
        });
      }
    });
  return Array.from(groups.values())
    .map((row) => {
      const vehicle = vehicleRowsByPlate.value.get(String(row.plate || "").trim()) || null;
      const vehicleExpenseByType = vehicleExpenseBreakdownByTypeForPlate(row.plate, bossPeriodFilter.value);
      const vehicleExpense = bossVehicleExpenseTotalFromBreakdown(vehicleExpenseByType);
      const expenseHKD = vehicleExpense.hkd;
      const expenseRMB = vehicleExpense.rmb;
      const profitHKD = row.orderProfitHKD - expenseHKD;
      const profitRMB = row.orderProfitRMB - expenseRMB;
      const periodMonth = bossVehicleExchangeRatePeriodMonth(bossPeriodFilter.value);
      const profitHKDEquivalent = bossVehicleHkdEquivalent(profitHKD, profitRMB, periodMonth);
      const revenueHKDEquivalent = bossVehicleHkdEquivalent(row.totalRevenueHKD, row.totalRevenueRMB, periodMonth);
      const orderProfitHKDEquivalent = bossVehicleHkdEquivalent(row.orderProfitHKD, row.orderProfitRMB, periodMonth);
      const expenseHKDEquivalent = bossVehicleHkdEquivalent(expenseHKD, expenseRMB, periodMonth);
      const fuelExpenseHKDEquivalent = bossVehicleHkdEquivalent(vehicleExpenseByType.fuel.hkd, vehicleExpenseByType.fuel.rmb, periodMonth);
      const repairExpenseHKDEquivalent = bossVehicleHkdEquivalent(vehicleExpenseByType.repair.hkd, vehicleExpenseByType.repair.rmb, periodMonth);
      const insuranceExpenseHKDEquivalent = bossVehicleHkdEquivalent(vehicleExpenseByType.insurance.hkd, vehicleExpenseByType.insurance.rmb, periodMonth);
      const reviewExpenseHKDEquivalent = bossVehicleHkdEquivalent(vehicleExpenseByType.review.hkd, vehicleExpenseByType.review.rmb, periodMonth);
      const plateHeadExpenseHKDEquivalent = bossVehicleHkdEquivalent(vehicleExpenseByType.plateHead.hkd, vehicleExpenseByType.plateHead.rmb, periodMonth);
      const otherExpenseHKDEquivalent = bossVehicleHkdEquivalent(vehicleExpenseByType.other.hkd, vehicleExpenseByType.other.rmb, periodMonth);
      const driverCostHKDEquivalent = Math.max(0, revenueHKDEquivalent - orderProfitHKDEquivalent);
      const totalCostHKD = revenueHKDEquivalent - profitHKDEquivalent;
      const orderCount = row.orders.length;
      return {
        plate: row.plate,
        driver: Array.from(row.driverNames).join("、") || vehicle?.driver || "-",
        orderCount,
        revenue: moneyPairDisplay(row.revenueHKD, row.revenueRMB),
        orderProfit: moneyPairDisplay(row.orderProfitHKD, row.orderProfitRMB),
        fuelExpense: moneyPairDisplay(vehicleExpenseByType.fuel.hkd, vehicleExpenseByType.fuel.rmb),
        repairExpense: moneyPairDisplay(vehicleExpenseByType.repair.hkd, vehicleExpenseByType.repair.rmb),
        insuranceExpense: moneyPairDisplay(vehicleExpenseByType.insurance.hkd, vehicleExpenseByType.insurance.rmb),
        reviewExpense: moneyPairDisplay(vehicleExpenseByType.review.hkd, vehicleExpenseByType.review.rmb),
        plateHeadExpense: moneyPairDisplay(vehicleExpenseByType.plateHead.hkd, vehicleExpenseByType.plateHead.rmb),
        vehicleOtherExpense: moneyPairDisplay(vehicleExpenseByType.other.hkd, vehicleExpenseByType.other.rmb),
        expense: moneyPairDisplay(expenseHKD, expenseRMB),
        profit: moneyPairDisplay(profitHKD, profitRMB),
        profitHKDEquivalent: moneyHkdDisplay(profitHKDEquivalent),
        totalCostHKD,
        margin: bossVehicleProfitRateText(profitHKDEquivalent, totalCostHKD),
        revenueHKDEquivalent,
        orderProfitHKDEquivalent,
        expenseHKDEquivalent,
        fuelExpenseHKDEquivalent,
        repairExpenseHKDEquivalent,
        insuranceExpenseHKDEquivalent,
        reviewExpenseHKDEquivalent,
        plateHeadExpenseHKDEquivalent,
        otherExpenseHKDEquivalent,
        driverCostHKDEquivalent,
        profitMarginValue: revenueHKDEquivalent ? profitHKDEquivalent / revenueHKDEquivalent : 0,
        driverCostRate: revenueHKDEquivalent ? driverCostHKDEquivalent / revenueHKDEquivalent : 0,
        fuelPerOrderHKD: orderCount ? fuelExpenseHKDEquivalent / orderCount : fuelExpenseHKDEquivalent,
        repairPerOrderHKD: orderCount ? repairExpenseHKDEquivalent / orderCount : repairExpenseHKDEquivalent,
        revenuePerOrderHKD: orderCount ? revenueHKDEquivalent / orderCount : 0,
        expenseRate: revenueHKDEquivalent ? expenseHKDEquivalent / revenueHKDEquivalent : 0,
        otherExpenseRate: revenueHKDEquivalent ? otherExpenseHKDEquivalent / revenueHKDEquivalent : 0,
        annualExpenseHKDEquivalent: insuranceExpenseHKDEquivalent + reviewExpenseHKDEquivalent + plateHeadExpenseHKDEquivalent,
        profitEquivalent: profitHKDEquivalent
      };
    })
    .sort((left, right) => right.profitEquivalent - left.profitEquivalent || right.orderCount - left.orderCount);
});

function bossVehicleFuelMetricText(value, unit = "", digits = 1) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) return "-";
  const text = number.toLocaleString("zh-CN", {
    minimumFractionDigits: 0,
    maximumFractionDigits: digits
  });
  return unit ? `${text}${unit}` : text;
}

function bossVehicleFuelRecordOdometer(record = {}) {
  const value = Number(record.odometerKm ?? record.odometer_km ?? 0);
  return Number.isFinite(value) && value > 0 ? value : null;
}

function bossVehicleFuelRecordLiters(record = {}) {
  const value = Number(record.fuelLiters ?? record.fuel_liters ?? 0);
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function bossVehicleFuelConsumptionStatus(recordCount = 0, distanceKm = 0, abnormalSegments = 0) {
  if (recordCount < 2) return "需要至少 2 次加油记录";
  if (!distanceKm) return "公里数未递增";
  if (abnormalSegments > 0) return `已跳过 ${abnormalSegments} 段异常公里数`;
  return "正常";
}

const bossVehicleFuelConsumptionRows = computed(() => {
  const profitRowsByPlate = new Map(bossVehicleProfitDisplayRows.value.map((row) => [row.plate, row]));
  const groups = new Map();
  vehicleExpenseRows.value
    .filter((expense) =>
      expense.type === "fuel"
      && dateMatchesPeriodFilter(expense.date, bossPeriodFilter.value)
      && isBossCompanyVehiclePlate(expense.plate)
    )
    .forEach((expense) => {
      const plate = String(expense.plate || "").trim();
      if (!plate) return;
      const group = groups.get(plate) || {
        plate,
        records: [],
        fuelLitersTotal: 0,
        fuelAmountHKD: 0,
        fuelAmountRMB: 0
      };
      const amount = vehicleExpenseAmountBreakdown(expense, bossPeriodFilter.value);
      group.records.push(expense);
      group.fuelLitersTotal += bossVehicleFuelRecordLiters(expense);
      group.fuelAmountHKD += amount.hkd;
      group.fuelAmountRMB += amount.rmb;
      groups.set(plate, group);
    });

  return Array.from(groups.values())
    .map((group) => {
      const sortedRecords = group.records
        .slice()
        .sort((left, right) =>
          String(left.date || "").localeCompare(String(right.date || ""))
          || Number(left.id || 0) - Number(right.id || 0)
        );
      const odometerRecords = sortedRecords
        .map((record) => ({
          record,
          odometer: bossVehicleFuelRecordOdometer(record)
        }))
        .filter((item) => item.odometer !== null);
      let distanceKm = 0;
      let abnormalSegments = 0;
      for (let index = 1; index < odometerRecords.length; index += 1) {
        const previous = odometerRecords[index - 1].odometer;
        const current = odometerRecords[index].odometer;
        const distance = current - previous;
        if (distance > 0) {
          distanceKm += distance;
        } else {
          abnormalSegments += 1;
        }
      }
      const fuelPer100KmValue = distanceKm > 0 && group.fuelLitersTotal > 0
        ? (group.fuelLitersTotal / distanceKm) * 100
        : null;
      const periodMonth = bossVehicleExchangeRatePeriodMonth(bossPeriodFilter.value);
      const fuelAmountHKDEquivalent = bossVehicleHkdEquivalent(group.fuelAmountHKD, group.fuelAmountRMB, periodMonth);
      const profitRow = profitRowsByPlate.get(group.plate) || null;
      const vehicle = vehicleRowsByPlate.value.get(String(group.plate || "").trim()) || null;
      return {
        plate: group.plate,
        driver: profitRow?.driver || vehicle?.driver || "-",
        fuelCount: sortedRecords.length,
        fuelLitersTotal: group.fuelLitersTotal,
        fuelLitersDisplay: bossVehicleFuelMetricText(group.fuelLitersTotal, "L", 1),
        fuelDistanceKm: distanceKm,
        fuelDistanceDisplay: bossVehicleFuelMetricText(distanceKm, "km", 0),
        fuelPer100KmValue,
        fuelPer100KmDisplay: fuelPer100KmValue === null ? "-" : bossVehicleFuelMetricText(fuelPer100KmValue, "L/100km", 1),
        fuelAmount: moneyPairDisplay(group.fuelAmountHKD, group.fuelAmountRMB),
        fuelAmountHKDEquivalent,
        fuelAmountHKDDisplay: moneyHkdDisplay(fuelAmountHKDEquivalent),
        status: bossVehicleFuelConsumptionStatus(odometerRecords.length, distanceKm, abnormalSegments),
        statusLevel: abnormalSegments > 0 ? "warning" : (fuelPer100KmValue === null ? "muted" : "normal"),
        sourceRow: profitRow || {
          plate: group.plate,
          driver: vehicle?.driver || "-",
          orderCount: 0,
          revenue: "-",
          orderProfit: "-",
          expense: moneyPairDisplay(group.fuelAmountHKD, group.fuelAmountRMB),
          profit: "-",
          profitHKDEquivalent: "-",
          margin: "-"
        }
      };
    })
    .sort((left, right) => {
      const leftConsumption = left.fuelPer100KmValue ?? -1;
      const rightConsumption = right.fuelPer100KmValue ?? -1;
      return rightConsumption - leftConsumption
        || right.fuelLitersTotal - left.fuelLitersTotal
        || right.fuelDistanceKm - left.fuelDistanceKm;
    });
});

const bossTopVehicleProfitRow = computed(() => bossVehicleProfitDisplayRows.value[0] || {
  plate: "-",
  profit: "-",
  margin: "-"
});

const bossTopVehicleFuelConsumptionRow = computed(() =>
  bossVehicleFuelConsumptionRows.value.find((row) => row.fuelPer100KmValue !== null) || {
    plate: "-",
    fuelPer100KmDisplay: "-",
    fuelLitersDisplay: "-",
    fuelDistanceDisplay: "-"
  }
);

function bossVehiclePercentText(value = 0) {
  return `${(Number(value || 0) * 100).toFixed(1)}%`;
}

function bossVehicleAverageMetric(rows = [], key = "", positiveOnly = false) {
  const values = rows
    .map((row) => Number(row?.[key] || 0))
    .filter((value) => Number.isFinite(value) && (!positiveOnly || value > 0));
  if (!values.length) return 0;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function bossVehicleTopMetricRow(rows = [], key = "", predicate = () => true) {
  return rows
    .filter(predicate)
    .slice()
    .sort((left, right) => Number(right?.[key] || 0) - Number(left?.[key] || 0))[0] || null;
}

function bossVehicleLowMetricRow(rows = [], key = "", predicate = () => true) {
  return rows
    .filter(predicate)
    .slice()
    .sort((left, right) => Number(left?.[key] || 0) - Number(right?.[key] || 0))[0] || null;
}

function bossVehicleDiagnosisAverages(rows = []) {
  return {
    orderCount: bossVehicleAverageMetric(rows, "orderCount"),
    fuelPerOrderHKD: bossVehicleAverageMetric(rows, "fuelPerOrderHKD", true),
    repairPerOrderHKD: bossVehicleAverageMetric(rows, "repairPerOrderHKD", true),
    revenuePerOrderHKD: bossVehicleAverageMetric(rows, "revenuePerOrderHKD", true),
    driverCostRate: bossVehicleAverageMetric(rows, "driverCostRate", true),
    otherExpenseHKDEquivalent: bossVehicleAverageMetric(rows, "otherExpenseHKDEquivalent", true)
  };
}

function bossVehicleDiagnosisIssues(row = {}, averages = {}) {
  const issues = [];
  const add = (label, detail, weight = 1) => issues.push({ label, detail, weight });
  const revenue = Number(row.revenueHKDEquivalent || 0);
  if (Number(row.profitEquivalent || 0) < 0) {
    add("亏损", `净利润 ${moneyHkdDisplay(row.profitEquivalent)}`, 6);
  } else if (revenue > 0 && Number(row.profitMarginValue || 0) < 0.1) {
    add("利润率低", `利润率 ${row.margin}，低于 10%`, 4);
  }
  if (!row.orderCount && Number(row.expenseHKDEquivalent || 0) > 0) {
    add("本期无单", `无收入但有费用 ${moneyHkdDisplay(row.expenseHKDEquivalent)}`, 5);
  }
  if (averages.fuelPerOrderHKD > 0 && row.fuelPerOrderHKD > averages.fuelPerOrderHKD * 1.35) {
    add("油费高", `单均油费 ${moneyHkdDisplay(row.fuelPerOrderHKD)}，高于均值 ${moneyHkdDisplay(averages.fuelPerOrderHKD)}`, 3);
  }
  if (averages.repairPerOrderHKD > 0 && row.repairPerOrderHKD > averages.repairPerOrderHKD * 1.35) {
    add("维修费高", `单均维修 ${moneyHkdDisplay(row.repairPerOrderHKD)}，高于均值 ${moneyHkdDisplay(averages.repairPerOrderHKD)}`, 3);
  }
  if (revenue > 0 && row.driverCostRate > Math.max(0.55, averages.driverCostRate * 1.2)) {
    add("司机成本高", `司机成本占收入 ${bossVehiclePercentText(row.driverCostRate)}`, 3);
  }
  if (revenue > 0 && row.otherExpenseRate > 0.08) {
    add("异常费用多", `其他支出占收入 ${bossVehiclePercentText(row.otherExpenseRate)}`, 2);
  } else if (averages.otherExpenseHKDEquivalent > 0 && row.otherExpenseHKDEquivalent > averages.otherExpenseHKDEquivalent * 1.4) {
    add("异常费用多", `其他支出 ${moneyHkdDisplay(row.otherExpenseHKDEquivalent)}，高于均值 ${moneyHkdDisplay(averages.otherExpenseHKDEquivalent)}`, 2);
  }
  if (row.orderCount > 0 && averages.orderCount > 1 && row.orderCount < averages.orderCount * 0.55) {
    add("订单量低", `订单 ${row.orderCount} 单，低于均值 ${averages.orderCount.toFixed(1)} 单`, 2);
  }
  if (row.orderCount > 0 && averages.revenuePerOrderHKD > 0 && row.revenuePerOrderHKD < averages.revenuePerOrderHKD * 0.72) {
    add("疑似空跑/低价趟", `单均收入 ${moneyHkdDisplay(row.revenuePerOrderHKD)}，低于均值 ${moneyHkdDisplay(averages.revenuePerOrderHKD)}`, 2);
  }
  if (revenue > 0 && row.annualExpenseHKDEquivalent > 0 && row.annualExpenseHKDEquivalent / revenue > 0.12) {
    add("固定费用集中", `保险年审牌头占收入 ${bossVehiclePercentText(row.annualExpenseHKDEquivalent / revenue)}`, 1);
  }
  return issues.sort((left, right) => right.weight - left.weight);
}

function bossVehicleDiagnosisSuggestion(issues = []) {
  const labels = issues.map((issue) => issue.label);
  if (labels.includes("维修费高")) return "复核维修明细、事故责任和是否可走保险或保修。";
  if (labels.includes("油费高")) return "核对油耗、路线、加油记录，优先看是否绕路或怠速偏多。";
  if (labels.includes("司机成本高")) return "复核成本中心规则、司机结算口径和该车线路报价。";
  if (labels.includes("疑似空跑/低价趟")) return "重点复盘低收入趟次，检查空驶、低价线路和报价模板。";
  if (labels.includes("订单量低") || labels.includes("本期无单")) return "优先安排稳定线路，或评估本期闲置和固定成本。";
  if (labels.includes("异常费用多")) return "拆分其他支出来源，标注责任归属和可追偿金额。";
  return "继续跟踪该车收入、成本和费用变化。";
}

const bossVehicleProfitDiagnosisRows = computed(() => {
  const rows = bossVehicleProfitDisplayRows.value;
  const averages = bossVehicleDiagnosisAverages(rows);
  return rows
    .map((row) => {
      const issues = bossVehicleDiagnosisIssues(row, averages);
      return {
        plate: row.plate,
        driver: row.driver,
        orderCount: row.orderCount,
        profit: row.profitHKDEquivalent,
        profitRaw: row.profitEquivalent,
        margin: row.margin,
        issueTags: issues.slice(0, 4).map((issue) => issue.label),
        primaryIssue: issues[0]?.detail || "-",
        suggestion: bossVehicleDiagnosisSuggestion(issues),
        score: issues.reduce((sum, issue) => sum + issue.weight, 0),
        sourceRow: row
      };
    })
    .filter((row) => row.score > 0)
    .sort((left, right) => right.score - left.score || left.profitRaw - right.profitRaw)
    .slice(0, 8);
});

const bossVehicleProfitAnalysisCards = computed(() => {
  const rows = bossVehicleProfitDisplayRows.value;
  const topFuel = bossVehicleTopMetricRow(rows, "fuelExpenseHKDEquivalent", (row) => row.fuelExpenseHKDEquivalent > 0);
  const topRepair = bossVehicleTopMetricRow(rows, "repairExpenseHKDEquivalent", (row) => row.repairExpenseHKDEquivalent > 0);
  const topDriverCost = bossVehicleTopMetricRow(rows, "driverCostRate", (row) => row.revenueHKDEquivalent > 0);
  const topOther = bossVehicleTopMetricRow(rows, "otherExpenseHKDEquivalent", (row) => row.otherExpenseHKDEquivalent > 0);
  const lowRevenue = bossVehicleLowMetricRow(rows, "revenuePerOrderHKD", (row) => row.orderCount > 0 && row.revenuePerOrderHKD > 0);
  const lowProfitCount = rows.filter((row) => row.profitEquivalent < 0 || (row.revenueHKDEquivalent > 0 && row.profitMarginValue < 0.1)).length;
  return [
    { label: "需关注车辆", value: `${bossVehicleProfitDiagnosisRows.value.length} 台`, note: lowProfitCount ? `低利润/亏损 ${lowProfitCount} 台` : "暂无明显低利润车辆" },
    { label: "油费最高", value: topFuel?.plate || "-", note: topFuel ? `${moneyHkdDisplay(topFuel.fuelExpenseHKDEquivalent)} / 单均 ${moneyHkdDisplay(topFuel.fuelPerOrderHKD)}` : "暂无油费" },
    { label: "维修费最高", value: topRepair?.plate || "-", note: topRepair ? `${moneyHkdDisplay(topRepair.repairExpenseHKDEquivalent)} / 单均 ${moneyHkdDisplay(topRepair.repairPerOrderHKD)}` : "暂无维修费" },
    { label: "司机成本占比最高", value: topDriverCost?.plate || "-", note: topDriverCost ? `${bossVehiclePercentText(topDriverCost.driverCostRate)} / ${moneyHkdDisplay(topDriverCost.driverCostHKDEquivalent)}` : "暂无司机成本" },
    { label: "其他异常费最高", value: topOther?.plate || "-", note: topOther ? `${moneyHkdDisplay(topOther.otherExpenseHKDEquivalent)} / 占比 ${bossVehiclePercentText(topOther.otherExpenseRate)}` : "暂无其他支出" },
    { label: "单均收入最低", value: lowRevenue?.plate || "-", note: lowRevenue ? `${moneyHkdDisplay(lowRevenue.revenuePerOrderHKD)} / ${lowRevenue.orderCount} 单` : "暂无订单收入" }
  ];
});

function bossSupplierProfitOrderBreakdown(order = {}) {
  const revenue = orderCustomerReceivableBreakdown(order);
  const payable = supplierOrderPayableBreakdown(order);
  const companyCoveredCost = companyCoveredOrderCostBreakdown(order);
  const profitHKD = Number(revenue.hkd || 0) - Number(payable.payableHKD || 0);
  const profitRMB = Number(revenue.rmb || 0) - Number(payable.payableRMB || 0);
  const periodMonth = inputMonthKey(order.date) || bossVehicleExchangeRatePeriodMonth(bossPeriodFilter.value);
  const revenueRMBEquivalent = bossCompanyRmbEquivalent(revenue.hkd, revenue.rmb, periodMonth);
  const costRMBEquivalent = bossCompanyRmbEquivalent(payable.payableHKD, payable.payableRMB, periodMonth);
  const profitRMBEquivalent = revenueRMBEquivalent - costRMBEquivalent;
  return {
    revenueHKD: revenue.hkd,
    revenueRMB: revenue.rmb,
    costHKD: payable.payableHKD,
    costRMB: payable.payableRMB,
    profitHKD,
    profitRMB,
    companyCoveredCostHKD: companyCoveredCost.hkd,
    companyCoveredCostRMB: companyCoveredCost.rmb,
    revenueRMBEquivalent,
    costRMBEquivalent,
    profitRMBEquivalent,
    missingCostCount: Number(payable.missingCostCount || 0),
    matchedCostCount: Number(payable.matchedCostCount || 0),
    costStatus: supplierOrderCostStatus(payable),
    payable
  };
}

function bossSupplierProfitMarginText(profitRMB = 0, revenueRMB = 0) {
  const revenue = Number(revenueRMB || 0);
  if (!revenue) return "-";
  return `${((Number(profitRMB || 0) / revenue) * 100).toFixed(1)}%`;
}

function bossSupplierProfitOrdersForName(supplier = "", monthKey = "") {
  const target = String(supplier || "").trim();
  if (!target) return [];
  return bossOrderRows.value
    .filter((order) =>
      order.vehicleSource === "外派车辆"
      && String(order.supplier || "").trim() === target
      && (!monthKey || inputMonthKey(order.date) === monthKey)
    )
    .sort((left, right) => String(left.date || "").localeCompare(String(right.date || "")) || String(left.no || "").localeCompare(String(right.no || "")));
}

function bossSupplierProfitFeeRows(order = {}) {
  const payable = supplierOrderPayableBreakdown(order);
  const costFeesByKey = new Map((payable.feeRows || []).map((fee) => [
    `${fee.feeItemId || ""}::${fee.name || ""}::${fee.driverRole || ""}::${fee.driverName || ""}`,
    fee
  ]));
  const feeRows = (Array.isArray(order?.fees) ? order.fees : [])
    .filter((fee) => String(fee?.name || "").trim());
  const sourceRows = feeRows.length ? feeRows : bossVehicleOrderFeeRows(order);
  return sourceRows.map((fee) => {
    const item = feeItemForFee(fee);
    const key = `${fee.feeItemId || fee.fee_item_id || item?.id || ""}::${fee.name || ""}::${fee.driverRole || ""}::${fee.driverName || ""}`;
    const costFee = costFeesByKey.get(key) || (isCompanyCoveredFee(fee) ? companyCoveredFeeCostSnapshot(fee, order) : supplierOrderFeeCostSnapshot(fee, order));
    const income = { hkd: feeAmountHKD(fee), rmb: feeAmountRMB(fee) };
    const cost = amountBreakdownByCurrency(costFee.amount, costFee.currency || fee.currency || order.currency || "港币");
    const isCompanyCovered = isCompanyCoveredFee(fee);
    return {
      name: bossVehicleFeeName(fee) || "费用",
      income: moneyPairDisplay(income.hkd, income.rmb),
      cost: isCompanyCovered ? "公司自费" : moneyPairDisplay(cost.hkd, cost.rmb),
      profit: isCompanyCovered ? moneyPairDisplay(income.hkd, income.rmb) : moneyPairDisplay(income.hkd - cost.hkd, income.rmb - cost.rmb),
      costStatus: isCompanyCovered ? "公司自费" : (costFee.costMatched || costFee.matched ? "已匹配" : "未匹配"),
      remark: costFee.costLabel || costFee.label || fee.remark || ""
    };
  });
}

function bossSupplierProfitDetailOrderRows(supplier = "", monthKey = "") {
  return bossSupplierProfitOrdersForName(supplier, monthKey).map((order) => {
    const breakdown = bossSupplierProfitOrderBreakdown(order);
    return {
      order,
      no: order.no || "-",
      date: order.date || "-",
      customer: partnerDisplayLabel(order.customer || "", "客户") || order.customer || "-",
      businessType: order.businessType || "-",
      plate: order.plate || "-",
      route: relatedOrderRouteText(order) || "-",
      revenue: moneyPairDisplay(breakdown.revenueHKD, breakdown.revenueRMB),
      supplierCost: moneyPairDisplay(breakdown.costHKD, breakdown.costRMB),
      companyCost: moneyPairDisplay(breakdown.companyCoveredCostHKD, breakdown.companyCoveredCostRMB),
      profit: moneyPairDisplay(breakdown.profitHKD, breakdown.profitRMB),
      profitRMB: moneyRmbDisplay(breakdown.profitRMBEquivalent),
      margin: bossSupplierProfitMarginText(breakdown.profitRMBEquivalent, breakdown.revenueRMBEquivalent),
      costStatus: breakdown.costStatus,
      fees: bossSupplierProfitFeeRows(order)
    };
  });
}

function buildBossSupplierProfitRows(sourceOrders = []) {
  const groups = new Map();
  sourceOrders
    .filter((order) => order.vehicleSource === "外派车辆")
    .forEach((order) => {
      const supplier = String(order.supplier || "未填写供应商").trim();
      const row = groups.get(supplier) || {
        supplier,
        orderCount: 0,
        customers: new Set(),
        plates: new Set(),
        months: new Set(),
        revenueHKD: 0,
        revenueRMB: 0,
        costHKD: 0,
        costRMB: 0,
        profitHKD: 0,
        profitRMB: 0,
        companyCoveredCostHKD: 0,
        companyCoveredCostRMB: 0,
        revenueRMBEquivalent: 0,
        costRMBEquivalent: 0,
        profitRMBEquivalent: 0,
        missingCostCount: 0,
        matchedCostCount: 0
      };
      const breakdown = bossSupplierProfitOrderBreakdown(order);
      row.orderCount += 1;
      if (order.customer) row.customers.add(order.customer);
      if (order.plate) row.plates.add(order.plate);
      const monthKey = inputMonthKey(order.date);
      if (monthKey) row.months.add(monthKey);
      row.revenueHKD += breakdown.revenueHKD;
      row.revenueRMB += breakdown.revenueRMB;
      row.costHKD += breakdown.costHKD;
      row.costRMB += breakdown.costRMB;
      row.profitHKD += breakdown.profitHKD;
      row.profitRMB += breakdown.profitRMB;
      row.companyCoveredCostHKD += breakdown.companyCoveredCostHKD;
      row.companyCoveredCostRMB += breakdown.companyCoveredCostRMB;
      row.revenueRMBEquivalent += breakdown.revenueRMBEquivalent;
      row.costRMBEquivalent += breakdown.costRMBEquivalent;
      row.profitRMBEquivalent += breakdown.profitRMBEquivalent;
      row.missingCostCount += breakdown.missingCostCount;
      row.matchedCostCount += breakdown.matchedCostCount;
      groups.set(supplier, row);
    });
  return Array.from(groups.values())
    .map((row) => ({
      ...row,
      customerCount: row.customers.size,
      plateCount: row.plates.size,
      monthCount: row.months.size,
      revenue: moneyPairDisplay(row.revenueHKD, row.revenueRMB),
      revenueRMBDisplay: moneyRmbDisplay(row.revenueRMBEquivalent),
      supplierCost: moneyPairDisplay(row.costHKD, row.costRMB),
      supplierCostRMBDisplay: moneyRmbDisplay(row.costRMBEquivalent),
      companyCoveredCost: moneyPairDisplay(row.companyCoveredCostHKD, row.companyCoveredCostRMB),
      profit: moneyPairDisplay(row.profitHKD, row.profitRMB),
      profitRMBDisplay: moneyRmbDisplay(row.profitRMBEquivalent),
      monthCountLabel: row.monthCount ? `${row.monthCount} 月` : "-",
      averageProfitRMBDisplay: moneyRmbDisplay(row.orderCount ? row.profitRMBEquivalent / row.orderCount : 0),
      margin: bossSupplierProfitMarginText(row.profitRMBEquivalent, row.revenueRMBEquivalent),
      costStatus: row.missingCostCount ? `未匹配 ${row.missingCostCount} 项` : "已匹配",
      profitEquivalent: row.profitRMBEquivalent
    }))
    .sort((left, right) => right.profitEquivalent - left.profitEquivalent || right.orderCount - left.orderCount || left.supplier.localeCompare(right.supplier, "zh-Hans-CN"));
}

