function orderInDateRange(order, startValue, endValue) {
  const date = parseInputDate(order?.date);
  if (!date) return false;
  const start = parseInputDate(startValue);
  const end = parseInputDate(endValue);
  if (start && date < start) return false;
  if (end && date > end) return false;
  return true;
}

function buildFinanceCustomerRows(sourceOrders, limit = 0) {
  const groups = new Map();
  sourceOrders.forEach((order) => {
    const key = order.customer || "未填写客户";
    const row = groups.get(key) || { customer: key, customerId: order.customerId || "", count: 0, hkd: 0, rmb: 0 };
    const amount = orderCustomerReceivableBreakdown(order);
    if (!row.customerId && order.customerId) row.customerId = order.customerId;
    row.count += 1;
    row.hkd += amount.hkd;
    row.rmb += amount.rmb;
    groups.set(key, row);
  });
  const rows = Array.from(groups.values()).sort((a, b) => b.count - a.count || b.hkd - a.hkd);
  return limit ? rows.slice(0, limit) : rows;
}

const financeCustomerRanking = computed(() => buildFinanceCustomerRows(financeOrderRows.value, 12));
const statementCustomerRows = computed(() => buildFinanceCustomerRows(statementBillableOrderRows.value));

function buildStatementSupplierRows(sourceOrders) {
  const groups = new Map();
  sourceOrders
    .filter((order) => order.vehicleSource === "外派车辆" && order.supplier)
    .forEach((order) => {
      const key = order.supplier || "未填写供应商";
      const payable = supplierOrderPayableBreakdown(order);
      if (!payable.feeRows.length) return;
      const row = groups.get(key) || { supplier: key, count: 0, hkd: 0, rmb: 0, missingCostCount: 0, matchedCostCount: 0 };
      row.count += 1;
      row.hkd += Number(payable.payableHKD || 0);
      row.rmb += Number(payable.payableRMB || 0);
      row.matchedCostCount += Number(payable.matchedCostCount || 0);
      row.missingCostCount += Number(payable.missingCostCount || 0);
      groups.set(key, row);
    });
  return Array.from(groups.values()).sort((a, b) =>
    b.count - a.count || b.hkd - a.hkd || b.rmb - a.rmb || a.supplier.localeCompare(b.supplier, "zh-Hans-CN")
  );
}

