function applyStatementSupplierExportContext(row = {}) {
  statementExportType.value = "supplier";
  statementExportEntity.value = row.supplier || "";
  statementSettlementCurrency.value = "港币";
  statementExchangeRate.value = STATEMENT_DEFAULT_EXCHANGE_RATE;
  syncStatementExportRange(activeStatementMonthFilter.value);
  saveStatementExportSettings();
}

async function openStatementSupplierExportMenu(row = {}) {
  const key = statementSupplierRowKey(row);
  if (!key || !row.supplier) {
    notify("当前供应商信息不完整，无法导出对账单");
    return;
  }
  if (statementExportMenuOpen.value && statementExportMenuType.value === "supplier" && statementExportMenuKey.value === key) {
    closeStatementExportMenu();
    return;
  }
  applyStatementSupplierExportContext(row);
  await ensureTemplateRowsLoaded({ silent: true });
  statementExportMenuType.value = "supplier";
  statementExportMenuKey.value = key;
  statementExportMenuOpen.value = true;
}

function customsStatementRowKey(row = {}) {
  return row.company || "";
}

async function openCustomsStatementExportMenu(row = {}) {
  const key = customsStatementRowKey(row);
  if (!key || !row.company) {
    notify("当前客户信息不完整，无法导出报关对账单");
    return;
  }
  if (statementExportMenuOpen.value && statementExportMenuType.value === "customs" && statementExportMenuKey.value === key) {
    closeStatementExportMenu();
    return;
  }
  statementExportMenuType.value = "customs";
  statementExportMenuKey.value = key;
  statementExportMenuOpen.value = true;
}

const activeStatementExportRow = computed(() => {
  if (statementExportMenuType.value === "customs") {
    return customsStatementRows.value.find((row) => customsStatementRowKey(row) === statementExportMenuKey.value) || null;
  }
  if (statementExportMenuType.value === "supplier") {
    return statementSupplierRows.value.find((row) => statementSupplierRowKey(row) === statementExportMenuKey.value) || null;
  }
  return statementCustomerRows.value.find((row) => statementCustomerRowKey(row) === statementExportMenuKey.value) || null;
});

const activeStatementExportEntityName = computed(() => {
  const row = activeStatementExportRow.value || {};
  if (statementExportMenuType.value === "customs") return partnerDisplayLabel(row.company || "", "客户") || row.company || "";
  return statementExportMenuType.value === "supplier"
    ? row.supplier
    : (partnerDisplayLabel(row.customer || "", "客户") || row.customer || "");
});

const statementExportDialogMetaItems = computed(() => {
  const row = activeStatementExportRow.value || {};
  if (statementExportMenuType.value === "customs") {
    return [
      "报关对账单",
      `报关记录：${Number(row.count || 0)} 条`,
      `应收：RMB ${money(row.total || 0)}`
    ];
  }
  if (statementExportMenuType.value === "supplier") {
    return [
      "供应商对账单",
      `订单：${Number(row.count || 0)} 单`,
      `金额：${moneyPair(row.hkd || 0, row.rmb || 0)}`
    ];
  }
  return [
    "客户对账单",
    `结算：${statementCustomerSettlementCurrency(row)}`,
    `汇率：${statementCustomerExchangeRate(row)}`
  ];
});

function statementDownloadKey(type, entityName, start, end) {
  return [type, entityName || "全部", start || "", end || ""].join("|");
}

function statementDownloadPeriodPayload(type = "customer") {
  const periodKey = statementRecordType({ type }) === "customs"
    ? periodFilterValue("customsStatement")
    : activeStatementMonthFilter.value;
  return {
    periodKey,
    periodMode: periodFilterParts(periodKey).mode
  };
}

async function markStatementDownloaded(type, entityName, start, end, snapshot = {}) {
  const key = statementDownloadKey(type, entityName, start, end);
  const periodPayload = statementDownloadPeriodPayload(type);
  const payload = {
    key,
    type,
    entityName: entityName || "全部",
    start,
    end,
    periodKey: snapshot.periodKey || periodPayload.periodKey,
    periodMode: snapshot.periodMode || periodPayload.periodMode,
    status: "已导出",
    paymentStatus: "未收款",
    paymentDate: "",
    amountHKD: Number(snapshot.amountHKD || 0),
    amountRMB: Number(snapshot.amountRMB || 0),
    recordCount: Number(snapshot.recordCount || 0),
    snapshotReady: snapshot.snapshotReady !== undefined ? Boolean(snapshot.snapshotReady) : true,
    downloadedAt: new Date().toISOString()
  };
  try {
    const item = await financeApi.createStatementDownload(payload);
    const nextRows = statementDownloadRows.value.filter((row) => row.key !== item.key);
    statementDownloadRows.value = [item, ...nextRows].slice(0, 300);
    return true;
  } catch (error) {
    notify(`下载记录写入数据库失败：${error.message}`);
    return false;
  }
}

function statementCustomerPaymentPayload(row = {}, paymentStatus = "未收款", paymentDate = "", statusOverride = "") {
  const { start, end } = statementDateRangeBounds(activeStatementMonthFilter.value);
  const entityName = row.customer || "全部";
  const record = statementDownloadRecordForCustomerRow(row);
  const snapshot = statementDownloadSnapshotRecord(record);
  const snapshotPayload = statementDownloadSnapshotHasValue(snapshot)
    ? snapshot
    : (statementDownloadSnapshotForRecord(record) || snapshot);
  const periodPayload = statementDownloadPeriodPayload("customer");
  return {
    key: statementDownloadKey("customer", entityName, start || "", end || ""),
    type: "customer",
    entityName,
    start: start || "",
    end: end || "",
    periodKey: statementRecordPeriodKey(record) || periodPayload.periodKey,
    periodMode: statementRecordPeriodMode(record) || periodPayload.periodMode,
    status: statusOverride || record?.status || "未导出",
    paymentStatus,
    paymentDate: paymentStatus === "已收款" ? paymentDate : "",
    amountHKD: Number(snapshotPayload.amountHKD || 0),
    amountRMB: Number(snapshotPayload.amountRMB || 0),
    recordCount: Number(snapshotPayload.recordCount || 0),
    snapshotReady: Boolean(snapshotPayload.snapshotReady ?? true),
    downloadedAt: record?.downloadedAt || new Date().toISOString()
  };
}

async function saveCustomerStatementPayment(row = {}, paymentStatus = "未收款", paymentDate = "", options = {}) {
  try {
    const item = await financeApi.saveStatementPayment(statementCustomerPaymentPayload(row, paymentStatus, paymentDate, options.status));
    const nextRows = statementDownloadRows.value.filter((downloadRow) =>
      downloadRow.id !== item.id && downloadRow.key !== item.key && downloadRow.downloadKey !== item.downloadKey
    );
    statementDownloadRows.value = [item, ...nextRows].slice(0, 300);
    if (!options.silent) notify(paymentStatus === "已收款" ? "收款状态已标记为已收款" : "收款状态已标记为未收款");
    return item;
  } catch (error) {
    notify(`收款状态保存失败：${error.message}`);
    return null;
  }
}

function statementDownloadRecordForSupplierRow(row = {}) {
  return statementDownloadRecordForEntityForFilter("supplier", row.supplier || "全部");
}

function statementDownloadRecordForCustomsRowForFilter(row = {}, filterKey = periodFilterValue("customsStatement")) {
  const { start, end } = periodFilterBounds(filterKey);
  const key = statementDownloadKey("customs", row.company || "全部", start || "", end || "");
  return statementDownloadRows.value.find((item) => (item.key || item.downloadKey) === key) || null;
}

function statementDownloadRecordForCustomsRow(row = {}) {
  return statementDownloadRecordForCustomsRowForFilter(row);
}

function normalizeOrderChargedAt(value = "") {
  const text = String(value || "").trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : "";
}

function orderIsCharged(order = {}) {
  return Boolean(normalizeOrderChargedAt(order.chargedAt || order.charged_at));
}

function statementRecordStatus(record = {}) {
  return String(record.status || record.paymentStatus || "").trim() || "未导出";
}

function statementRecordPaymentStatus(record = {}) {
  return String(record.paymentStatus || record.payment_status || "").trim() || (statementRecordStatus(record) === "已收款" ? "已收款" : "未收款");
}

function statementRecordHasBeenExported(record = {}) {
  return statementStatusFlowIndex(statementRecordStatus(record)) >= statementStatusFlowIndex("已导出");
}

function statementRecordIsOpen(record = {}) {
  return statementRecordHasBeenExported(record)
    && statementRecordStatus(record) !== "已收款"
    && statementRecordPaymentStatus(record) !== "已收款";
}

function statementRecordType(record = {}) {
  return String(record.statementType || record.type || "").trim() || "customer";
}

function statementRecordRange(record = {}) {
  const start = String(record.start || record.startDate || record.start_date || "").trim().slice(0, 10);
  const end = String(record.end || record.endDate || record.end_date || "").trim().slice(0, 10);
  if (start && end && start > end) return { start: end, end: start };
  if (start && !end) return { start, end: start };
  if (!start && end) return { start: end, end };
  return { start, end };
}

function statementRecordPeriodKey(record = {}) {
  return String(record.periodKey || record.period_key || "").trim();
}

function statementPeriodModeFromKey(periodKey = "") {
  const key = String(periodKey || "").trim();
  if (/^\d{4}-\d{2}$/.test(key)) return "month";
  if (key === "all") return "all";
  if (key.startsWith("year:")) return "year";
  if (key.startsWith("range:")) return "range";
  if (key.startsWith("day:")) return "day";
  return "";
}

function statementRecordPeriodMode(record = {}) {
  const mode = String(record.periodMode || record.period_mode || "").trim();
  if (["month", "range", "year", "all", "day"].includes(mode)) return mode;
  return statementPeriodModeFromKey(statementRecordPeriodKey(record));
}

function statementRecordMonthlyKey(record = {}) {
  const { start, end } = statementRecordRange(record);
  if (!start || !end) return "";
  const monthKey = inputMonthKey(start);
  if (!/^\d{4}-\d{2}$/.test(monthKey) || inputMonthKey(end) !== monthKey) return "";
  const monthRange = periodFilterBounds(monthKey);
  return start === monthRange.start && end === monthRange.end ? monthKey : "";
}

function statementRecordIsMonthlySettlement(record = {}) {
  const monthlyKey = statementRecordMonthlyKey(record);
  if (!monthlyKey) return false;
  const mode = statementRecordPeriodMode(record);
  return mode === "month";
}

function statementRecordPeriodMonth(record = {}) {
  const { start, end } = statementRecordRange(record);
  return inputMonthKey(start || end || record.downloadedAt || record.createdAt || "");
}

function statementRecordPeriodLabel(record = {}) {
  const { start, end } = statementRecordRange(record);
  const monthKey = statementRecordPeriodMonth(record);
  if (monthKey && start && end && inputMonthKey(start) === inputMonthKey(end)) {
    return periodFilterLabel(monthKey);
  }
  if (start && end) {
    return start === end ? inputDateLabel(start) : `${inputDateLabel(start)} 至 ${inputDateLabel(end)}`;
  }
  return monthKey ? periodFilterLabel(monthKey) : "-";
}

function statementRecordMatchesPeriod(record = {}, filterKey = bossPeriodFilter.value) {
  const { start: filterStart, end: filterEnd } = periodFilterBounds(filterKey);
  if (!filterStart && !filterEnd) return true;
  const { start, end } = statementRecordRange(record);
  const recordStart = parseInputDate(start || end || record.downloadedAt || record.createdAt || "");
  const recordEnd = parseInputDate(end || start || record.downloadedAt || record.createdAt || "");
  const periodStart = parseInputDate(filterStart);
  const periodEnd = parseInputDate(filterEnd);
  if (!recordStart || !recordEnd || !periodStart || !periodEnd) return false;
  return recordStart <= periodEnd && recordEnd >= periodStart;
}

function statementSupplierStatementStatus(row = {}) {
  return statementDownloadRecordForSupplierRow(row)?.status || "未导出";
}

function customsStatementStatusForFilter(row = {}, filterKey = periodFilterValue("customsStatement")) {
  return statementDownloadRecordForCustomsRowForFilter(row, filterKey)?.status || "未导出";
}

function customsStatementStatus(row = {}) {
  return customsStatementStatusForFilter(row);
}

function statementDownloadStatusClass(status = "") {
  if (status === "已导出") return "exported";
  if (status === "已发送") return "sent";
  if (status === "已开票") return "invoiced";
  if (status === "已收款") return "paid";
  return "";
}

function statementStatusFlowIndex(status = "") {
  return STATEMENT_DOWNLOAD_STATUS_FLOW.indexOf(String(status || "").trim());
}

function nextStatementStatus(status = "") {
  const index = statementStatusFlowIndex(status);
  if (index < 1 || index >= STATEMENT_DOWNLOAD_STATUS_FLOW.length - 1) return "";
  return STATEMENT_DOWNLOAD_STATUS_FLOW[index + 1];
}

function previousStatementStatus(status = "") {
  const index = statementStatusFlowIndex(status);
  if (index <= 1) return "";
  return STATEMENT_DOWNLOAD_STATUS_FLOW[index - 1];
}

async function updateStatementStatusRecord(record, status = "") {
  if (!record?.id) {
    notify("请先导出这份对账单，再修改状态");
    return;
  }
  try {
    const item = await financeApi.updateStatementDownloadStatus(record.id, status);
    const nextRows = statementDownloadRows.value.filter((downloadRow) =>
      downloadRow.id !== item.id && downloadRow.key !== item.key && downloadRow.downloadKey !== item.downloadKey
    );
    statementDownloadRows.value = [item, ...nextRows].slice(0, 300);
    notify("对账单状态已更新");
  } catch (error) {
    notify(`对账单状态更新失败：${error.message}`);
  }
}

async function updateCustomerStatementStatus(row = {}, status = "") {
  const nextStatus = String(status || "").trim();
  const record = statementDownloadRecordForCustomerRow(row);
  if (!record?.id) {
    notify("请先导出这份对账单，再修改状态");
    return;
  }
  if (CUSTOMER_STATEMENT_STATUS_FLOW.indexOf(nextStatus) < 1) {
    notify("请选择有效对账状态");
    return;
  }
  if (nextStatus === "已收款") {
    const input = window.prompt("请输入收款日期（YYYY-MM-DD）", statementCustomerPaymentDate(row) || todayInputValue());
    if (input === null) return;
    const paymentDate = String(input || "").trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(paymentDate)) {
      notify("收款日期格式应为 YYYY-MM-DD");
      return;
    }
    const item = await saveCustomerStatementPayment(row, "已收款", paymentDate, { status: nextStatus, silent: true });
    if (item) {
      notify("对账单已标记为已收款");
    }
    return;
  }
  const item = await saveCustomerStatementPayment(row, "未收款", "", { status: nextStatus, silent: true });
  if (item) notify("对账单状态已更新");
}

function customerStatementStatusOptions(row = {}) {
  const current = statementCustomerWorkflowStatus(row);
  const index = CUSTOMER_STATEMENT_STATUS_FLOW.indexOf(current);
  const next = index >= 1 && index < CUSTOMER_STATEMENT_STATUS_FLOW.length - 1
    ? CUSTOMER_STATEMENT_STATUS_FLOW[index + 1]
    : "";
  return next ? [next] : [];
}

async function updateCustomerStatementStatusFromSelect(row = {}, status = "") {
  if (!status || status === statementCustomerWorkflowStatus(row)) return;
  await updateCustomerStatementStatus(row, status);
}

function customerStatementStatusReturn(row = {}) {
  const current = statementCustomerWorkflowStatus(row);
  const index = CUSTOMER_STATEMENT_STATUS_FLOW.indexOf(current);
  return index > 1 ? CUSTOMER_STATEMENT_STATUS_FLOW[index - 1] : "";
}

async function updateSupplierStatementStatus(row = {}, status = "") {
  await updateStatementStatusRecord(statementDownloadRecordForSupplierRow(row), status);
}

async function updateCustomsStatementStatus(row = {}, status = "") {
  await updateStatementStatusRecord(statementDownloadRecordForCustomsRow(row), status);
}

const statementEntityOptions = computed(() => {
  if (statementExportType.value === "driver") {
    return driverRows.value
      .filter((driver) => statementBillableOrderRows.value.some((order) => orderMatchesDriverForWage(order, driver)))
      .map((driver) => ({ id: driver.id, name: driver.name }))
      .filter((item) => item.name);
  }
  if (statementExportType.value === "supplier") {
    const names = new Set(statementBillableOrderRows.value
      .filter((order) =>
        order.vehicleSource === "外派车辆"
        && supplierOrderPayableBreakdown(order).feeRows.length
      )
      .map((order) => order.supplier)
      .filter(Boolean));
    return Array.from(names).map((name) => ({ id: name, name }));
  }
  return statementCustomerRows.value
    .map((row) => {
      const customer = customerRowsByName.value.get(String(row.customer || "").trim());
      return { id: customer?.id || row.customer, name: row.customer };
    })
    .filter((item) => item.name);
});

watch(statementEntityOptions, (options) => {
  if (!options.length) {
    statementExportEntity.value = "";
    return;
  }
  const exists = options.some((item) => item.name === statementExportEntity.value || item.id === statementExportEntity.value);
  if (!exists) statementExportEntity.value = options[0].name;
}, { immediate: true });

function ensureStatementEntity() {
  const options = statementEntityOptions.value;
  if (!options.length) return "";
  const exists = options.some((item) => item.name === statementExportEntity.value || item.id === statementExportEntity.value);
  if (!exists) statementExportEntity.value = options[0].name;
  return statementExportEntity.value || options[0].name;
}

function statementDateRange() {
  const fallback = statementDateRangeBounds(activeStatementMonthFilter.value);
  return {
    start: statementExportStart.value || fallback.start || "",
    end: statementExportEnd.value || fallback.end || ""
  };
}

function selectedStatementOrders() {
  const entity = ensureStatementEntity();
  const { start, end } = statementDateRange();
  const statementDriver = statementExportType.value === "driver"
    ? (driverRowsByName.value.get(String(entity || "").trim()) || driverRowsById.value.get(String(entity || "").trim()) || null)
    : null;
  const statementCustomer = statementExportType.value === "customer"
    ? (customerRowsByName.value.get(String(entity || "").trim()) || customerRowsById.value.get(String(entity || "").trim()) || null)
    : null;
  const orders = orderRows.value.filter((order) => {
    if (!isFinanceStatVisibleOrder(order)) return false;
    if (!orderInDateRange(order, start, end)) return false;
    if (statementExportType.value === "supplier") {
      return order.vehicleSource === "外派车辆" && order.supplier === entity;
    }
    if (statementExportType.value === "driver") {
      return Boolean(statementDriver && orderMatchesDriverForWage(order, statementDriver));
    }
    return order.customer === entity || Boolean(statementCustomer && statementCustomer.id === order.customerId);
  });
  return statementExportType.value === "customer"
    ? orders.map(customerStatementOrderSnapshot)
    : orders;
}

function statementConvertedTotal(orders, currency, rateValue) {
  const rate = Number(rateValue || 0);
  const totals = orders.reduce((sum, order) => {
    const amount = orderCustomerReceivableBreakdown(order);
    return {
      hkd: sum.hkd + amount.hkd,
      rmb: sum.rmb + amount.rmb
    };
  }, { hkd: 0, rmb: 0 });
  const hkd = totals.hkd;
  const rmb = totals.rmb;
  if (currency === "港币") {
    return { hkd, rmb, total: hkd + (rate ? rmb / rate : 0), label: "总计港币合计：" };
  }
  return { hkd, rmb, total: rmb + hkd * rate, label: "总计人民币合计：" };
}

function statementFeeText(order) {
  return (Array.isArray(order?.fees) ? order.fees : [])
    .filter((fee) => Number(fee.amount || 0) || fee.name)
    .map((fee) => orderFeeStatementText(fee))
    .filter(Boolean)
    .join("；");
}

function statementChargeNoteText(order = {}) {
  return customerStatementOrderDisplayChargeNote(order);
}

async function statementAttachmentText(order) {
  try {
    const files = await loadFiles("order", order.no);
    return files.map((file) => file.filename || file.name).filter(Boolean).join("；");
  } catch {
    return "";
  }
}

function saveStatementExportSettings() {
  localStorage.setItem("hanye_statement_export_type", statementExportType.value);
  localStorage.setItem("hanye_statement_export_start", statementExportStart.value);
  localStorage.setItem("hanye_statement_export_end", statementExportEnd.value);
  localStorage.setItem("hanye_statement_settlement_currency", statementSettlementCurrency.value);
  localStorage.setItem("hanye_statement_exchange_rate", statementExchangeRate.value);
}

const routeAdjustSelectedCustomer = computed(() =>
  findPartnerByTypedLabel(driverRouteAdjustForm.customerName, "客户") || null
);

const routeAdjustAddressOptions = computed(() => {
  const map = new Map();
  const addOption = (source, value, meta = "") => {
    const text = String(value || "").trim();
    if (!text) return;
    const key = addressOptionKey(text);
    if (!key || map.has(key)) return;
    map.set(key, { key, source, value: text, meta });
  };
  const customer = routeAdjustSelectedCustomer.value;
  if (customer) {
    addOption("客户档案", [customer.city, customer.address].filter(Boolean).join(" / "), customer.name);
    customerContactRows.value
      .filter((item) => item.customerId === customer.id)
      .forEach((item) => {
        const area = contactAreaText(item);
        const address = contactAddressText(item);
        addOption("客户地址", [area, address].filter(Boolean).join(" / "), item.name || item.mobile || item.phone || "");
      });
  } else {
    addressBookRows.value.forEach((item) => {
      addOption("地址本", [item.area, item.address].filter(Boolean).join(" / "), item.contact || item.phone || item.note || "");
    });
  }
  return [...map.values()].slice(0, 120);
});

function routeAdjustDriverPickerLabel() {
  const ids = driverRouteAdjustForm.driverIds.map((id) => Number(id)).filter(Boolean);
  if (!ids.length) return "全部司机";
  const selected = driverRows.value.filter((item) => ids.includes(Number(item.id)));
  if (selected.length <= 2) return selected.map((item) => item.name).join("、") || "选择司机";
  return `已选 ${selected.length} 位司机`;
}

async function addDriverRouteAdjustRule() {
  if (!driverRouteAdjustForm.customerName && !driverRouteAdjustForm.loading && !driverRouteAdjustForm.unloading && !driverRouteAdjustForm.driverIds.length) {
    notify("请至少填写客户、路线或指定司机");
    return;
  }
  const selectedRuleDrivers = driverRows.value.filter((item) =>
    driverRouteAdjustForm.driverIds.map((id) => Number(id)).includes(Number(item.id))
  );
  const currency = driverRouteAdjustForm.currency || "港币";
  const amountHKD = currency === "人民币" ? 0 : Number(driverRouteAdjustForm.amountHKD || -50);
  const amountRMB = currency === "人民币" ? Number(driverRouteAdjustForm.amountRMB || -50) : 0;
  const payload = {
    customerName: driverRouteAdjustForm.customerName,
    driverIds: selectedRuleDrivers.map((item) => item.id),
    driverNames: selectedRuleDrivers.map((item) => item.name),
    driverId: selectedRuleDrivers.length === 1 ? selectedRuleDrivers[0].id : "",
    driverName: selectedRuleDrivers.length === 1 ? selectedRuleDrivers[0].name : "",
    transportMode: normalizeTransportMode(driverRouteAdjustForm.transportMode || ""),
    loading: supplierCostRuleAreaValue(driverRouteAdjustForm.loading),
    unloading: supplierCostRuleAreaValue(driverRouteAdjustForm.unloading),
    amountHKD,
    amountRMB,
    note: driverRouteAdjustForm.note
  };
  try {
    loading.value = true;
    const item = await financeApi.createDriverRouteAdjustRule(payload);
    driverRouteAdjustRules.value = [item, ...driverRouteAdjustRules.value.filter((rule) => rule.id !== item.id)];
    Object.assign(driverRouteAdjustForm, { customerName: "", driverIds: [], transportMode: "", loading: "", unloading: "", currency: "港币", amountHKD: -50, amountRMB: 0, note: "" });
    routeAdjustDriverPickerOpen.value = false;
    notify("司机路线扣减规则已保存到数据库");
  } catch (error) {
    notify(error.message || "保存司机路线扣减规则失败");
  } finally {
    loading.value = false;
  }
}

async function removeDriverRouteAdjustRule(rule) {
  if (!rule?.id) return;
  try {
    await financeApi.deleteDriverRouteAdjustRule(rule.id);
    driverRouteAdjustRules.value = driverRouteAdjustRules.value.filter((item) => item.id !== rule.id);
    notify("司机路线扣减规则已删除");
  } catch (error) {
    notify(error.message || "删除司机路线扣减规则失败");
  }
}

function orderBelongsToPartner(order, partner) {
  if (!partner) return false;
  if (partner.type === "供应商") {
    return order.vehicleSource === "外派车辆" && order.supplier === partner.name;
  }
  return order.customerId === partner.id || order.customer === partner.name;
}

function orderDispatchPlanRow(order = {}) {
  const orderNo = String(order?.no || "").trim();
  return orderNo ? dispatchPlanRowsByOrderNo.value.get(orderNo) || null : null;
}

function orderDispatchLoadDate(order = {}) {
  const dispatchRow = orderDispatchPlanRow(order);
  return String((dispatchRow ? dispatchPlanDate(dispatchRow) : order.dispatchLoadDate) || order.date || "").trim().slice(0, 10);
}

function orderDispatchLoadTime(order = {}) {
  const dispatchRow = orderDispatchPlanRow(order);
  return String((dispatchRow?.loadTime || order.dispatchLoadTime || "")).trim();
}

function orderDispatchLoadDateTimeText(order = {}) {
  const date = orderDispatchLoadDate(order);
  if (!date) return "-";
  const time = orderDispatchLoadTime(order);
  return `${date} ${time || "-"}`;
}

function orderDispatchLoadSortValue(order = {}) {
  const date = orderDispatchLoadDate(order);
  if (!date) return "";
  const time = orderDispatchLoadTime(order);
  return `${date} ${time || "99:99"}`;
}

function isOrderVisibleInOrderManagement(order = {}) {
  if (order.status === "预排") return false;
  const dispatchRow = orderDispatchPlanRow(order);
  if (!dispatchRow) return true;
  return !["预排", "已派车"].includes(normalizeDispatchPlanStatus(dispatchRow.status, dispatchRow));
}

