function normalizedOrderFilterText(value = "") {
  return String(value || "").trim();
}

function normalizedOrderSearchText(value = "") {
  return normalizedOrderFilterText(value).toLowerCase();
}

function orderDriverFilterValues(order = {}) {
  return uniqueOrderCostNames([
    order.driver,
    order.hkDriver,
    order.mainlandDriver,
    ...String(order.driver || "").split("/")
  ]);
}

function orderPlateFilterValues(order = {}) {
  return [order.plate];
}

function orderBusinessTypeFilterValues(order = {}) {
  return [order.businessType];
}

function orderFilterOptionValues(rows = [], getter) {
  const values = rows.flatMap((row) => getter(row));
  return Array.from(new Set(values.map(normalizedOrderFilterText).filter(Boolean)))
    .sort((left, right) => left.localeCompare(right, "zh-Hans-CN", { numeric: true, sensitivity: "base" }));
}

function orderFilterValueMatch(values = [], filterValue = "") {
  const target = normalizedOrderFilterText(filterValue);
  if (!target) return true;
  return values.map(normalizedOrderFilterText).includes(target);
}

function orderRowSearchValues(order = {}) {
  return [
    order.no,
    order.dispatchNo,
    order.createdByName,
    order.createdByUsername,
    order.customer,
    order.businessType,
    order.plate,
    order.driver,
    order.hkDriver,
    order.mainlandDriver,
    order.port,
    order.direction,
    order.tonnage,
    order.quantity,
    order.weight,
    order.vehicleSource,
    order.supplier,
    order.transportMode,
    order.loading,
    order.unloading,
    relatedOrderRouteText(order),
    orderDispatchLoadDateTimeText(order),
    order.status,
    order.remark,
    order.tripNo,
    order.sixSheetNo
  ];
}

function matchesOrderSearchKeyword(order = {}) {
  const keyword = normalizedOrderSearchText(orderSearchKeyword.value);
  if (!keyword) return true;
  return orderRowSearchValues(order).some((value) =>
    normalizedOrderSearchText(value).includes(keyword)
  );
}

const orderFilterBaseRows = computed(() =>
  orderRows.value.filter((item) =>
    isOrderVisibleInOrderManagement(item)
    && isOrderDateFilterMatch(orderDispatchLoadDate(item))
  )
);

function orderMatchesSelectFilters(order = {}, excludedFilter = "") {
  if (excludedFilter !== "status" && orderStatusFilter.value && order.status !== orderStatusFilter.value) return false;
  if (excludedFilter !== "customer" && orderCustomerFilter.value && order.customer !== orderCustomerFilter.value) return false;
  if (excludedFilter !== "businessType" && orderBusinessFilter.value && order.businessType !== orderBusinessFilter.value) return false;
  if (excludedFilter !== "plate" && !orderFilterValueMatch(orderPlateFilterValues(order), orderPlateFilter.value)) return false;
  if (excludedFilter !== "driver" && !orderFilterValueMatch(orderDriverFilterValues(order), orderDriverFilter.value)) return false;
  return true;
}

function orderRowsForFilterOptions(excludedFilter = "") {
  return orderFilterBaseRows.value.filter((item) => orderMatchesSelectFilters(item, excludedFilter));
}

const orderCustomerFilterOptions = computed(() => {
  return orderFilterOptionValues(orderRowsForFilterOptions("customer"), (item) => [item.customer])
    .filter((customer) => customerNameMatchesCategory(customer, "运输客户"));
});

const orderPlateFilterOptions = computed(() =>
  orderFilterOptionValues(orderRowsForFilterOptions("plate"), orderPlateFilterValues)
);

const orderDriverFilterOptions = computed(() =>
  orderFilterOptionValues(orderRowsForFilterOptions("driver"), orderDriverFilterValues)
);

const orderBusinessFilterOptions = computed(() =>
  orderFilterOptionValues(orderRowsForFilterOptions("businessType"), orderBusinessTypeFilterValues)
);

function clearOrderFilters() {
  orderSearchKeyword.value = "";
  orderCustomerFilter.value = "";
  orderPlateFilter.value = "";
  orderDriverFilter.value = "";
  orderBusinessFilter.value = "";
  orderStatusFilter.value = "";
}

const orderFiltersActive = computed(() =>
  Boolean(
    orderSearchKeyword.value.trim()
      || orderCustomerFilter.value
      || orderPlateFilter.value
      || orderDriverFilter.value
      || orderBusinessFilter.value
      || orderStatusFilter.value
  )
);

[
  [orderCustomerFilterOptions, orderCustomerFilter],
  [orderPlateFilterOptions, orderPlateFilter],
  [orderDriverFilterOptions, orderDriverFilter],
  [orderBusinessFilterOptions, orderBusinessFilter]
].forEach(([optionsRef, valueRef]) => {
  watch(optionsRef, (options) => {
    if (valueRef.value && !options.includes(valueRef.value)) {
      valueRef.value = "";
    }
  });
});

function selectDispatchCustomer(customer) {
  dispatchForm.customerId = customer?.id || "";
  dispatchForm.customer = customer?.name || "";
  dispatchCustomerKeyword.value = customerShortDisplay(customer) || "";
  dispatchCustomerPickerOpen.value = false;
}

function handleDispatchCustomerInput() {
  const customer = findPartnerByTypedLabel(dispatchCustomerKeyword.value, "客户", "运输客户");
  dispatchForm.customer = customer?.name || dispatchCustomerKeyword.value;
  dispatchForm.customerId = customer?.id || "";
  dispatchCustomerPickerOpen.value = true;
}

function handleDispatchVehicleSourceChange() {
  if (normalizeVehicleSource(dispatchForm.vehicleSource) === OWN_VEHICLE_SOURCE) {
    dispatchForm.supplier = "";
  } else if (dispatchForm.vehicleSource === "外派车辆") {
    dispatchForm.plate = "";
    dispatchForm.hkDriver = "";
    dispatchForm.mainlandDriver = "";
    dispatchForm.transportMode = "";
  } else {
    dispatchForm.plate = "";
    dispatchForm.supplier = "";
    dispatchForm.driver = "";
    dispatchForm.hkDriver = "";
    dispatchForm.mainlandDriver = "";
    dispatchForm.transportMode = "";
  }
}

function dispatchExcelSimplifyText(value = "") {
  const map = {
    裝: "装",
    車: "车",
    櫃: "柜",
    貨: "货",
    運: "运",
    輸: "输",
    廠: "厂",
    時: "时",
    間: "间",
    約: "约",
    關: "关",
    報: "报",
    聯: "联",
    繫: "系",
    絡: "络",
    電: "电",
    話: "话",
    號: "号",
    數: "数",
    總: "总",
    積: "积",
    體: "体",
    稱: "称",
    達: "达",
    興: "兴",
    灃: "沣",
    倉: "仓",
    單: "单",
    寶: "宝",
    區: "区",
    龍: "龙",
    灣: "湾",
    載: "载",
    註: "注"
  };
  return String(value || "").replace(new RegExp(`[${Object.keys(map).join("")}]`, "g"), (char) => map[char] || char);
}

function compactDispatchOcrText(value = "") {
  return dispatchExcelSimplifyText(value)
    .replace(/\u00a0/g, " ")
    .replace(/([\u4e00-\u9fa5])\s+(?=[\u4e00-\u9fa5])/g, "$1")
    .replace(/([粤港澳])\s+(?=[A-Z0-9港澳])/gi, "$1")
    .replace(/([A-Z0-9])\s+(?=[港澳])/gi, "$1")
    .replace(/[ \t]+/g, " ")
    .replace(/\s*\n\s*/g, "\n")
    .trim();
}

function escapeDispatchRecognitionRegExp(value = "") {
  return String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function normalizeDispatchExcelLookupText(value = "") {
  return dispatchExcelSimplifyText(normalizeUserText(value, { singleLine: true, compactCjkSpacing: true }))
    .replace(/\s+/g, "")
    .replace(/[：:／/｜|,，.;；"'“”‘’()（）\[\]【】{}<>《》\-_*·。]/g, "")
    .toLowerCase();
}

function cleanDispatchExcelCellText(value = "") {
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return timestampInputValueFromDate(value).slice(0, 16);
  }
  return normalizeUserText(value, { singleLine: true, compactCjkSpacing: true })
    .replace(/\s+/g, " ")
    .trim();
}

function dispatchExcelRowText(row = []) {
  return row.map(cleanDispatchExcelCellText).filter(Boolean).join(" ");
}

function dispatchExcelAllText(rows = []) {
  return rows.map(dispatchExcelRowText).filter(Boolean).join("\n");
}

function dispatchExcelTextAfterLabel(cellText = "", label = "") {
  const text = cleanDispatchExcelCellText(cellText);
  if (!text) return "";
  const normalizedText = normalizeDispatchExcelLookupText(text);
  const normalizedLabel = normalizeDispatchExcelLookupText(label);
  if (!normalizedLabel || !normalizedText.includes(normalizedLabel)) return "";
  const colonIndex = text.search(/[：:]/);
  if (colonIndex >= 0) {
    const beforeColon = text.slice(0, colonIndex);
    if (normalizeDispatchExcelLookupText(beforeColon).includes(normalizedLabel)) {
      return text.slice(colonIndex + 1).trim();
    }
  }
  const plainLabel = String(label || "").replace(/[：:]\s*$/, "").trim();
  if (plainLabel) {
    const escaped = plainLabel.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const stripped = text.replace(new RegExp(`^\\s*${escaped}\\s*[：:]?\\s*`, "i"), "").trim();
    if (stripped && stripped !== text) return stripped;
  }
  return "";
}

function findDispatchExcelRowIndex(rows = [], labels = [], options = {}) {
  const normalizedLabels = labels.map(normalizeDispatchExcelLookupText).filter(Boolean);
  if (!normalizedLabels.length) return -1;
  const startRow = Math.max(0, Number(options.startRow || 0));
  const endRow = Math.min(rows.length, Number.isFinite(options.endRow) ? options.endRow : rows.length);
  for (let rowIndex = startRow; rowIndex < endRow; rowIndex += 1) {
    const rowText = normalizeDispatchExcelLookupText(dispatchExcelRowText(rows[rowIndex]));
    if (normalizedLabels.some((label) => rowText.includes(label))) return rowIndex;
  }
  return -1;
}

function dispatchExcelValueAfterLabel(rows = [], labels = [], options = {}) {
  const normalizedLabels = labels.map(normalizeDispatchExcelLookupText).filter(Boolean);
  if (!normalizedLabels.length) return "";
  const startRow = Math.max(0, Number(options.startRow || 0));
  const endRow = Math.min(rows.length, Number.isFinite(options.endRow) ? options.endRow : rows.length);
  for (let rowIndex = startRow; rowIndex < endRow; rowIndex += 1) {
    const row = rows[rowIndex] || [];
    for (let cellIndex = 0; cellIndex < row.length; cellIndex += 1) {
      const cellText = cleanDispatchExcelCellText(row[cellIndex]);
      const normalizedCell = normalizeDispatchExcelLookupText(cellText);
      const labelIndex = normalizedLabels.findIndex((label) => normalizedCell.includes(label));
      if (labelIndex < 0) continue;
      const inlineValue = dispatchExcelTextAfterLabel(cellText, labels[labelIndex]);
      if (inlineValue) return inlineValue;
      const remainder = row
        .slice(cellIndex + 1)
        .map(cleanDispatchExcelCellText)
        .filter(Boolean);
      if (remainder.length) return remainder.join(" ");
      const followingRows = Math.max(0, Number(options.followingRows || 0));
      for (let offset = 1; offset <= followingRows; offset += 1) {
        const nextRow = rows[rowIndex + offset];
        if (!nextRow) break;
        const nextText = dispatchExcelRowText(nextRow);
        if (!nextText) continue;
        if (isDispatchLikelyMetadataLine(nextText)) continue;
        return nextText;
      }
      break;
    }
  }
  return "";
}

function normalizeDispatchExcelDate(value = "") {
  const text = cleanDispatchExcelCellText(value);
  const matched = text.match(/(\d{4})[.\-/年](\d{1,2})[.\-/月](\d{1,2})/);
  if (!matched) return "";
  const date = new Date(Number(matched[1]), Number(matched[2]) - 1, Number(matched[3]));
  if (Number.isNaN(date.getTime())) return "";
  return dateInputFromDate(date);
}

function normalizeDispatchExcelTime(value = "") {
  const text = cleanDispatchExcelCellText(value);
  const matched = text.match(/(上午|下午|am|pm)?\s*(\d{1,2})[：:](\d{1,2})/i);
  if (!matched) return "";
  const meridiem = String(matched[1] || "").toLowerCase();
  let hour = Number(matched[2]);
  const minute = Number(matched[3]);
  if (!Number.isFinite(hour) || !Number.isFinite(minute)) return "";
  if ((meridiem === "下午" || meridiem === "pm") && hour < 12) hour += 12;
  if ((meridiem === "上午" || meridiem === "am") && hour === 12) hour = 0;
  return normalizeDispatchLoadTime(`${hour}:${String(minute).padStart(2, "0")}`);
}

function normalizeDispatchRecognitionPlate(value = "") {
  const compact = dispatchExcelSimplifyText(value).toUpperCase().replace(/[^A-Z0-9\u4e00-\u9fa5港澳]/g, "");
  if (!compact) return "";
  const labeled = compact.match(/车牌([粤港澳京津沪渝冀豫云辽黑湘皖鲁新苏浙赣鄂桂甘晋蒙陕吉闽贵青藏川宁琼][A-Z0-9]{0,6}(?:港|澳)?)/);
  const direct = compact.match(/([粤港澳京津沪渝冀豫云辽黑湘皖鲁新苏浙赣鄂桂甘晋蒙陕吉闽贵青藏川宁琼][A-Z0-9]{1,7}(?:港|澳)?)/);
  return labeled?.[1] || direct?.[1] || "";
}

function parseDispatchExcelTonnage(value = "") {
  const text = cleanDispatchExcelCellText(value).toUpperCase().replace(/\s+/g, "");
  if (!text) return "";
  const truckMatch = text.match(/(?:^|[^0-9])(?:\d+X)?(\d{1,2})T/);
  if (truckMatch) {
    const tonnage = `${Number(truckMatch[1])}T`;
    if (TONNAGE_OPTIONS.includes(tonnage)) return tonnage;
  }
  const containerMatch = text.match(/(20|40|45)\s*(?:尺|GP|HQ|柜|櫃)/);
  if (containerMatch) {
    const tonnage = `${containerMatch[1]}尺柜`;
    if (TONNAGE_OPTIONS.includes(tonnage)) return tonnage;
  }
  return TONNAGE_OPTIONS.find((item) => normalizeDispatchExcelLookupText(text).includes(normalizeDispatchExcelLookupText(item))) || "";
}

function parseDispatchRecognitionQuantity(value = "") {
  const text = compactDispatchOcrText(value).toUpperCase().replace(/\s+/g, "");
  const labelMatch = text.match(/(?:货物数量|貨物數量|箱(?:件\/板)?数|件\/板数|板数|件数)[:：]?([0-9]+(?:\.[0-9]+)?\s*(?:P|板|件|箱)?)/);
  const directMatch = text.match(/(?:^|[^A-Z0-9])([0-9]+(?:\.[0-9]+)?)(P|板|件|箱)(?:[^A-Z0-9]|$)/);
  if (labelMatch) return labelMatch[1].replace(/P$/i, "板");
  if (directMatch) return `${Number(directMatch[1])}${directMatch[2].toUpperCase() === "P" ? "板" : directMatch[2]}`;
  return "";
}

function parseDispatchRecognitionWeight(value = "") {
  const text = compactDispatchOcrText(value).toUpperCase().replace(/\s+/g, "");
  const matched = text.match(/重量[:：]?([0-9]+(?:\.[0-9]+)?\s*(?:KG|KGS|公斤|吨|T)?)/);
  if (!matched) return "";
  const unit = matched[1].replace(/KGS$/i, "kg").replace(/KG$/i, "kg");
  return unit;
}

function parseDispatchExcelPort(value = "") {
  const text = normalizeDispatchExcelLookupText(value);
  const options = [
    { value: "深圳湾海关", keywords: ["深圳湾", "深圳灣"] },
    { value: "莲塘海关", keywords: ["莲塘", "蓮塘"] },
    { value: "文锦渡海关", keywords: ["文锦渡", "文錦渡"] },
    { value: "大桥海关", keywords: ["大桥", "大橋", "港珠澳"] }
  ];
  return options.find((option) => option.keywords.some((keyword) => text.includes(normalizeDispatchExcelLookupText(keyword))))?.value || "";
}

function parseDispatchExcelDirection(rows = []) {
  const destination = dispatchExcelValueAfterLabel(rows, ["出口目的港", "目的港"]);
  const origin = dispatchExcelValueAfterLabel(rows, ["起运港", "起運港"]);
  if (isHongKongLocation(destination)) return "出口";
  if (isHongKongLocation(origin)) return "进口";
  const allText = normalizeDispatchExcelLookupText(dispatchExcelAllText(rows));
  if (allText.includes("进口")) return "进口";
  if (allText.includes("出口")) return "出口";
  return "";
}

function inferHongKongDistrict(address = "") {
  const text = dispatchExcelSimplifyText(address);
  const englishText = String(address || "").toUpperCase().replace(/\s+/g, " ");
  const englishDistricts = [
    { district: "元朗区", patterns: [/\bYUEN\s+LONG\b/] },
    { district: "葵青区", patterns: [/\bKWAI\s+CHUNG\b/, /\bTSING\s+YI\b/] },
    { district: "荃湾区", patterns: [/\bTSUEN\s+WAN\b/] },
    { district: "屯门区", patterns: [/\bTUEN\s+MUN\b/] },
    { district: "观塘区", patterns: [/\bKWUN\s+TONG\b/] },
    { district: "沙田区", patterns: [/\bSHA\s+TIN\b/] },
    { district: "大埔区", patterns: [/\bTAI\s+PO\b/] }
  ];
  const englishMatched = englishDistricts.find((item) => item.patterns.some((pattern) => pattern.test(englishText)));
  if (englishMatched) return englishMatched.district;
  const districts = ["中西区", "湾仔区", "东区", "南区", "油尖旺区", "深水埗区", "九龙城区", "黄大仙区", "观塘区", "葵青区", "荃湾区", "屯门区", "元朗区", "北区", "大埔区", "沙田区", "西贡区", "离岛区"];
  const matched = districts.find((district) => text.includes(district));
  if (!matched) return "";
  const originalMatched = address.match(new RegExp(matched.replace("区", "[区區]")));
  return originalMatched?.[0] || matched;
}

function cleanHongKongLocationDetail(address = "", district = "") {
  let detail = cleanDispatchExcelCellText(address)
    .replace(/^香港\s*/i, "")
    .replace(/^新界\s*/i, "")
    .replace(/^九[龍龙]\s*/i, "")
    .replace(/^香港島\s*/i, "");
  if (district) {
    detail = detail.replace(new RegExp(`^${district.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*`), "");
    detail = detail.replace(new RegExp(`^${dispatchExcelSimplifyText(district).replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*`), "");
  }
  return detail.trim();
}

function appendUniqueDispatchExcelParts(parts = []) {
  const result = [];
  parts.forEach((part) => {
    const text = cleanDispatchExcelCellText(part);
    if (!text) return;
    const normalized = normalizeDispatchExcelLookupText(text);
    if (!normalized) return;
    const duplicated = result.some((item) => {
      const current = normalizeDispatchExcelLookupText(item);
      return current.includes(normalized) || normalized.includes(current);
    });
    if (!duplicated) result.push(text);
  });
  return result;
}

const DISPATCH_IMAGE_ADDRESS_TAIL_WHITELIST = new Set([
  "hk",
  "nt",
  "co",
  "ltd",
  "st",
  "rd",
  "ft",
  "kg",
  "am",
  "pm",
  "no",
  "rm",
  "blk",
  "fl"
]);

function stripDispatchImageAddressTailArtifacts(value = "") {
  let text = cleanDispatchExcelCellText(value).replace(/\s+/g, " ");
  if (!text) return "";
  const normalizedText = normalizeDispatchExcelLookupText(text);
  const hasAddressContext = /[\u4e00-\u9fa5]/.test(text)
    || ["hongkong", "yuenlong", "kowloon", "logistics", "park", "road", "street", "ltd", "limited", "warehouse", "company", "co"].some((keyword) =>
      normalizedText.includes(keyword)
    );
  if (hasAddressContext) {
    while (true) {
      const spacedTail = text.match(/(?:^|[\s,，。\.；;：:、\-])([A-Za-z]{1,2})\.?$/);
      if (spacedTail) {
        const token = spacedTail[1].toLowerCase();
        if (!DISPATCH_IMAGE_ADDRESS_TAIL_WHITELIST.has(token)) {
          text = text.slice(0, spacedTail.index).trimEnd();
          continue;
        }
      }
      const attachedTail = text.match(/([A-Za-z]{1,2})$/);
      if (attachedTail) {
        const token = attachedTail[1];
        const normalizedToken = token.toLowerCase();
        if (!DISPATCH_IMAGE_ADDRESS_TAIL_WHITELIST.has(normalizedToken) && token !== token.toUpperCase()) {
          const prefix = text.slice(0, -attachedTail[1].length);
          if (prefix && /[\s,，。\.；;：:、\-]|[\u4e00-\u9fa5]/.test(prefix)) {
            text = prefix.trimEnd();
            continue;
          }
        }
      }
      break;
    }
  }
  return text
    .replace(/\s*([：:])\s*/g, "$1")
    .replace(/\s+/g, " ")
    .replace(/[，,;；、\s]+$/g, "")
    .trim();
}

function buildDispatchExcelLocation({ address = "", company = "", contact = "", defaultCity = "", defaultDistrict = "" } = {}) {
  const cleanAddress = cleanDispatchExcelCellText(address);
  if (!cleanAddress && !company && !contact) return "";
  return appendUniqueDispatchExcelParts([cleanAddress, company, contact]).join(" ");
}

function matchDispatchExcelCustomer(allText = "") {
  const normalizedAllText = normalizeDispatchExcelLookupText(allText);
  if (!normalizedAllText) return null;
  return customerRows.value
    .filter((item) => item.type === "客户")
    .map((item) => {
      const values = [item.name, item.shortName, item.short_name, item.id]
        .map(cleanDispatchExcelCellText)
        .filter((value, index, array) => value && array.indexOf(value) === index);
      const matchedValues = values.filter((value) => {
        const normalized = normalizeDispatchExcelLookupText(value);
        return normalized.length >= 2 && normalizedAllText.includes(normalized);
      });
      const score = matchedValues.reduce((total, value) => total + normalizeDispatchExcelLookupText(value).length, 0);
      return { item, score };
    })
    .filter((entry) => entry.score > 0)
    .sort((left, right) => right.score - left.score)[0]?.item || null;
}

function recognizeDispatchExcelRows(rows = []) {
  const allText = dispatchExcelAllText(rows);
  const loadingCompany = dispatchExcelValueAfterLabel(rows, ["装货公司名称", "裝貨公司名稱"]);
  const loadingAddressIndex = findDispatchExcelRowIndex(rows, ["装货公司地址", "裝貨公司地址"]);
  const unloadingStartIndex = findDispatchExcelRowIndex(rows, ["落货地址", "落貨地址"]);
  const loadingAddress = dispatchExcelValueAfterLabel(rows, ["装货公司地址", "裝貨公司地址"]);
  const loadingContact = dispatchExcelValueAfterLabel(rows, ["联系人", "聯繫人"], {
    startRow: loadingAddressIndex >= 0 ? loadingAddressIndex + 1 : 0,
    endRow: unloadingStartIndex >= 0 ? unloadingStartIndex : rows.length
  });
  const unloadingCompany = dispatchExcelValueAfterLabel(rows, ["公司名称", "公司名稱"], {
    startRow: unloadingStartIndex >= 0 ? unloadingStartIndex : 0,
    endRow: unloadingStartIndex >= 0 ? unloadingStartIndex + 2 : rows.length
  });
  const unloadingAddress = dispatchExcelValueAfterLabel(rows, ["地址"], {
    startRow: unloadingStartIndex >= 0 ? unloadingStartIndex + 1 : 0,
    endRow: unloadingStartIndex >= 0 ? unloadingStartIndex + 5 : rows.length
  });
  const unloadingContact = dispatchExcelValueAfterLabel(rows, ["联系人/电话", "联系人电话", "聯繫人/電話", "聯繫人電話"], {
    startRow: unloadingStartIndex >= 0 ? unloadingStartIndex : 0,
    endRow: unloadingStartIndex >= 0 ? unloadingStartIndex + 6 : rows.length
  });
  const loadingTimeValue = dispatchExcelValueAfterLabel(rows, ["装货时间", "裝貨時間", "装车时间", "裝車時間", "到厂时间", "到廠時間"], { followingRows: 2 });
  const bookingValue = dispatchExcelValueAfterLabel(rows, ["约车时间", "約車時間"], { followingRows: 1 });
  const vehicleTypeValue = dispatchExcelValueAfterLabel(rows, ["车/柜型", "車/櫃型", "车柜型", "車櫃型", "车型", "車型", "柜型", "櫃型"]);
  const portValue = dispatchExcelValueAfterLabel(rows, ["通关口岸", "通關口岸", "口岸"], { followingRows: 1 });
  const plateValue = dispatchExcelValueAfterLabel(rows, ["车牌", "車牌", "车牌号", "車牌號", "车号", "車號"], { followingRows: 1 });
  const noteValue = dispatchExcelValueAfterLabel(rows, ["备注", "備注", "備註", "注意事项", "注意事項"], { followingRows: 4 });
  return {
    customer: matchDispatchExcelCustomer(allText),
    date: normalizeDispatchExcelDate(loadingTimeValue) || normalizeDispatchExcelDate(bookingValue),
    loadTime: normalizeDispatchExcelTime(loadingTimeValue) || normalizeDispatchExcelTime(bookingValue),
    loading: buildDispatchExcelLocation({
      address: loadingAddress,
      company: loadingCompany,
      contact: loadingContact
    }),
    unloading: buildDispatchExcelLocation({
      address: unloadingAddress,
      company: unloadingCompany,
      contact: unloadingContact,
      defaultCity: "香港"
    }),
    direction: parseDispatchExcelDirection(rows),
    tonnage: parseDispatchExcelTonnage(vehicleTypeValue || allText),
    port: parseDispatchExcelPort(portValue || allText),
    plate: normalizeDispatchRecognitionPlate(plateValue || allText),
    quantity: parseDispatchRecognitionQuantity(allText),
    weight: parseDispatchRecognitionWeight(allText),
    needsWeighing: parseDispatchImageWeighing(allText),
    note: noteValue
  };
}

function dispatchRecognitionLineIncludes(line = "", labels = []) {
  const normalizedLine = normalizeDispatchExcelLookupText(line);
  return labels.some((label) => normalizedLine.includes(normalizeDispatchExcelLookupText(label)));
}

function dispatchRecognitionLineText(lines = [], labels = []) {
  return lines.find((line) => dispatchRecognitionLineIncludes(line, labels)) || "";
}

function isDispatchLikelyMetadataLine(line = "") {
  const normalized = normalizeDispatchExcelLookupText(line);
  if (!normalized) return true;
  return [
    "运单号",
    "托运单",
    "车牌",
    "订车日期",
    "装货时间",
    "车型",
    "柜型",
    "序号",
    "柜号",
    "口岸",
    "备注",
    "注意",
    "六联单号",
    "货物名称",
    "箱件板数",
    "重量",
    "注意事项"
  ].some((label) => normalized.includes(normalizeDispatchExcelLookupText(label)));
}

function normalizeDispatchImageAddressLine(line = "") {
  let text = cleanDispatchExcelCellText(line)
    .replace(/〈/g, "（")
    .replace(/〉/g, "）")
    .replace(/([（][^）)]*)\)/g, "$1）")
    .replace(/\bC0(?=[\s.,，。]|$)/g, "CO")
    .replace(/\bPARKR(?=[\s,，]|$)/gi, "PARK");
  if (isDispatchMostlyLatinLine(text)) {
    text = text
      .replace(/，/g, ",")
      .replace(/\s*,\s*/g, ", ")
      .replace(/\s*\.\s*/g, ".")
      .replace(/\bN\.T\./gi, "N. T.")
      .replace(/\bCO\.,\s*Ltd\.?/gi, "CO., Ltd.");
  }
  return text
    .replace(/\s*([：:])\s*/g, "$1")
    .replace(/\s+/g, " ")
    .trim();
}

function isDispatchImageInstructionLine(line = "") {
  const text = normalizeDispatchImageAddressLine(line);
  const normalized = normalizeDispatchExcelLookupText(text);
  if (!normalized) return true;
  if (/^\d+\s*[.、]/.test(text)) return true;
  return ["注意事项", "注意", "装卸货拍照", "装御货拍照", "请司机", "封条", "交仓文件"].some((label) =>
    normalized.includes(normalizeDispatchExcelLookupText(label))
  );
}

function isDispatchLikelyImageLocationContextLine(line = "") {
  const text = normalizeDispatchImageAddressLine(line).replace(/^[：:\-—"'“”‘’|｜\s]+/, "");
  if (!text || text.length < 3 || /^[\d\s./:：-]+$/.test(text) || /^[A-Z]$/i.test(text)) return false;
  const normalized = normalizeDispatchExcelLookupText(text);
  if (!normalized || isDispatchLikelyMetadataLine(text) || isDispatchImageInstructionLine(text)) return false;
  if (["装货地点", "装货地址", "提货地点", "提货地址", "送货地点", "送货地址", "卸货地点", "卸货地址", "落货地点", "落货地址"].some((label) => normalized.includes(normalizeDispatchExcelLookupText(label)))) {
    return false;
  }
  return /物流|仓|倉|公司|有限公司|货仓|貨倉|园区|園區|warehouse|logistics|park|road|street|ltd|limited|co/i.test(text) || isDispatchMostlyLatinLine(text);
}

function cleanDispatchImageAddressBlock(value = "") {
  const rejectLabels = [
    "装货地点",
    "装货地址",
    "提货地点",
    "提货地址",
    "送货地点",
    "送货地址",
    "卸货地点",
    "卸货地址",
    "落货地点",
    "落货地址",
    "六联单号",
    "货物名称",
    "注意",
    "注意事项",
    "装卸货拍照",
    "装御货拍照",
    "请司机",
    "封条",
    "交仓文件",
    "序号",
    "车型",
    "柜型",
    "柜号",
    "口岸",
    "备注"
  ].map(normalizeDispatchExcelLookupText);
  const cleaned = compactDispatchOcrText(value)
    .split(/\n+/)
    .map((line) => normalizeDispatchImageAddressLine(line).replace(/^[：:\-—"'“”‘’|｜\s]+/, ""))
    .map((line) => line.replace(/^(装货地点|装货地址|提货地点|提货地址|送货地点|送货地址|卸货地点|卸货地址|落货地点|落货地址)\s*[：:"'“”‘’|｜\s]*\s*/i, ""))
    .map((line) => line.replace(/^[：:\-—"'“”‘’|｜\s]+/, ""))
    .map((line) => stripDispatchImageAddressTailArtifacts(line))
    .filter((line) => {
      if (!line) return false;
      const normalized = normalizeDispatchExcelLookupText(line);
      if (!normalized) return false;
      if (rejectLabels.some((label) => normalized === label || normalized.includes(label))) return false;
      if (isDispatchImageInstructionLine(line)) return false;
      if (/^[A-Z]$/i.test(line)) return false;
      return !/^[\d\s./:：-]+$/.test(line);
    })
    .join(" ")
    .replace(/\s*([：:])\s*/g, "$1")
    .replace(/\s+/g, " ")
    .trim();
  return stripDispatchImageAddressTailArtifacts(cleaned);
}

function collectDispatchImageLeadingContextLines(lines = [], startIndex = 0) {
  const result = [];
  for (let index = startIndex - 1; index >= Math.max(0, startIndex - 3); index -= 1) {
    const line = lines[index];
    if (!isDispatchLikelyImageLocationContextLine(line)) break;
    result.unshift(line);
  }
  return result;
}

function extractDispatchImageSection(text = "", startLabels = [], endLabels = [], options = {}) {
  const source = compactDispatchOcrText(text);
  if (!source) return "";
  const normalizedStartLabels = startLabels.map(normalizeDispatchExcelLookupText).filter(Boolean);
  const normalizedEndLabels = endLabels.map(normalizeDispatchExcelLookupText).filter(Boolean);
  const lines = source.split(/\n+/).map(cleanDispatchExcelCellText).filter(Boolean);
  const collected = [];
  let collecting = false;
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const normalizedLine = normalizeDispatchExcelLookupText(line);
    if (!collecting) {
      const startLabel = normalizedStartLabels.find((label) => normalizedLine.includes(label));
      if (!startLabel) continue;
      collecting = true;
      if (options.includeLeadingContext) {
        collected.push(...collectDispatchImageLeadingContextLines(lines, index));
      }
      const originalLabel = startLabels.find((label) => normalizeDispatchExcelLookupText(label) === startLabel) || "";
      const stripped = originalLabel
        ? line.replace(new RegExp(`^[\\s\\S]*?${escapeDispatchRecognitionRegExp(originalLabel)}\\s*[：:"'“”‘’|｜\\s]*`, "i"), "")
        : line;
      if (stripped.trim()) collected.push(stripped);
      continue;
    }
    if (normalizedEndLabels.some((label) => normalizedLine.includes(label)) || isDispatchImageInstructionLine(line)) break;
    collected.push(line);
  }
  return cleanDispatchImageAddressBlock(collected.join("\n"));
}

function isDispatchMostlyLatinLine(line = "") {
  const latinCount = (line.match(/[A-Za-z]/g) || []).length;
  const chineseCount = (line.match(/[\u4e00-\u9fa5]/g) || []).length;
  return latinCount >= 8 && latinCount > chineseCount * 2;
}

function isDispatchLikelyHongKongEnglishLine(line = "") {
  const text = normalizeDispatchImageAddressLine(line);
  if (!isDispatchMostlyLatinLine(text)) return false;
  return /\b(?:HONG\s*KONG|N\.?\s*T\.?|YUEN|LONG|KOWLOON|LOGISTICS|PARK|ROAD|STREET|LTD|LIMITED|CO\.?|C0\.?)\b/i.test(text);
}

function trimDispatchMainlandLoadingText(block = "") {
  const text = cleanDispatchImageAddressBlock(block);
  if (!text) return "";
  const markerIndex = text.search(/\b(?:HONG\s*KONG|N\.?\s*T\.?|YUEN\s+LONG|KOWLOON|INTERNATIONAL|LOGISTICS|PARK|ROAD|STREET|LTD|LIMITED|CO\.?|C0\.?)\b/i);
  if (markerIndex > 0 && /[\u4e00-\u9fa5]/.test(text.slice(0, markerIndex))) {
    return text.slice(0, markerIndex).trim();
  }
  return text;
}

function extractDispatchImageUnloadingSection(text = "") {
  const source = compactDispatchOcrText(text);
  if (!source) return "";
  const unloadingLabels = ["送货地点", "送货地址", "卸货地点", "卸货地址", "落货地点", "落货地址"].map(normalizeDispatchExcelLookupText);
  const loadingLabels = ["装货地点", "装货地址", "提货地点", "提货地址"].map(normalizeDispatchExcelLookupText);
  const endLabels = ["六联单号", "货物名称", "箱", "重量", "注意事项", "注意", "备注"].map(normalizeDispatchExcelLookupText);
  const lines = source.split(/\n+/).map(cleanDispatchExcelCellText).filter(Boolean);
  const startIndex = lines.findIndex((line) => unloadingLabels.some((label) => normalizeDispatchExcelLookupText(line).includes(label)));
  if (startIndex < 0) return "";

  const loadingIndex = lines
    .slice(0, startIndex)
    .map((line, index) => ({ line, index }))
    .filter(({ line }) => loadingLabels.some((label) => normalizeDispatchExcelLookupText(line).includes(label)));
  const lastLoadingMatch = loadingIndex[loadingIndex.length - 1];
  const loadingStartIndex = lastLoadingMatch?.index ?? -1;
  const prefixLines = lines
    .slice(Math.max(0, loadingStartIndex + 1), startIndex)
    .filter(isDispatchLikelyHongKongEnglishLine);
  const collected = [...prefixLines];
  for (let index = startIndex; index < lines.length; index += 1) {
    const line = lines[index];
    const normalizedLine = normalizeDispatchExcelLookupText(line);
    if (index > startIndex && (endLabels.some((label) => normalizedLine.includes(label)) || isDispatchImageInstructionLine(line))) break;
    if (index === startIndex) {
      const matchedLabel = unloadingLabels.find((label) => normalizedLine.includes(label));
      const originalLabel = ["送货地点", "送货地址", "卸货地点", "卸货地址", "落货地点", "落货地址"]
        .find((label) => normalizeDispatchExcelLookupText(label) === matchedLabel) || "";
      const stripped = originalLabel
        ? line.replace(new RegExp(`^[\\s\\S]*?${escapeDispatchRecognitionRegExp(originalLabel)}\\s*[：:"'“”‘’|｜\\s]*`, "i"), "")
        : line;
      if (stripped.trim()) collected.push(stripped);
    } else {
      collected.push(line);
    }
  }
  return cleanDispatchImageAddressBlock(collected.join("\n"));
}

function buildDispatchImageLocation(block = "", options = {}) {
  const text = cleanDispatchImageAddressBlock(block);
  if (!text) return "";
  return buildDispatchExcelLocation({ address: text, defaultCity: options.defaultCity || "" });
}

function parseDispatchImageDirection(allText = "", loadingBlock = "", unloadingBlock = "") {
  const normalized = normalizeDispatchExcelLookupText(allText);
  if (normalized.includes("出口")) return "出口";
  if (normalized.includes("进口")) return "进口";
  if (isHongKongLocation(unloadingBlock) || normalizeDispatchExcelLookupText(unloadingBlock).includes("hongkong")) return "出口";
  if (isHongKongLocation(loadingBlock) || normalizeDispatchExcelLookupText(loadingBlock).includes("hongkong")) return "进口";
  return "";
}

function parseDispatchImageWeighing(allText = "") {
  const normalized = normalizeDispatchExcelLookupText(allText);
  if (!normalized.includes("过磅")) return undefined;
  if (normalized.includes("不用过磅") || normalized.includes("无需过磅") || normalized.includes("不需过磅") || normalized.includes("免过磅") || normalized.includes("不过磅")) {
    return false;
  }
  return true;
}

function recognizeDispatchImageText(rawText = "") {
  const text = compactDispatchOcrText(rawText);
  const lines = text.split(/\n+/).map(cleanDispatchExcelCellText).filter(Boolean);
  const allText = lines.join("\n");
  const loadingTimeText = dispatchRecognitionLineText(lines, ["装货时间", "裝貨時間", "到厂时间", "到廠時間"]) || allText;
  const loadingBlock = extractDispatchImageSection(
    allText,
    ["装货地点", "装货地址", "提货地点", "提货地址"],
    ["送货地点", "送货地址", "卸货地点", "卸货地址", "落货地点", "落货地址", "六联单号", "货物名称", "箱", "注意事项", "注意"],
    { includeLeadingContext: true }
  );
  const unloadingBlock = extractDispatchImageUnloadingSection(allText);
  const result = {
    customer: matchDispatchExcelCustomer(allText),
    date: normalizeDispatchExcelDate(loadingTimeText),
    loadTime: normalizeDispatchExcelTime(loadingTimeText),
    plate: normalizeDispatchRecognitionPlate(dispatchRecognitionLineText(lines, ["车牌", "車牌"]) || allText),
    port: parseDispatchExcelPort(allText),
    tonnage: parseDispatchExcelTonnage(allText),
    quantity: parseDispatchRecognitionQuantity(allText),
    weight: parseDispatchRecognitionWeight(allText),
    note: extractDispatchImageNoteText(allText),
    loading: buildDispatchImageLocation(trimDispatchMainlandLoadingText(loadingBlock)),
    unloading: buildDispatchImageLocation(unloadingBlock, { defaultCity: "香港" }),
    direction: parseDispatchImageDirection(allText, loadingBlock, unloadingBlock)
  };
  const needsWeighing = parseDispatchImageWeighing(allText);
  if (typeof needsWeighing === "boolean") result.needsWeighing = needsWeighing;
  return result;
}

function clearDispatchLocationDraftsForTarget(target) {
  Object.keys(dispatchLocationDrafts).forEach((key) => {
    if (key.startsWith(`${target}:`)) delete dispatchLocationDrafts[key];
  });
  Object.keys(dispatchLocationInputComposing).forEach((key) => {
    if (key.startsWith(`${target}:`)) delete dispatchLocationInputComposing[key];
  });
  dispatchLocationDistrictPicker.key = "";
  dispatchLocationDistrictPicker.keyword = "";
}

function clearAllDispatchLocationDrafts() {
  clearDispatchLocationDraftsForTarget("loading");
  clearDispatchLocationDraftsForTarget("unloading");
}

function setDispatchRecognitionStatus(message = "", tone = "busy") {
  window.clearTimeout(dispatchRecognitionStatusTimer);
  dispatchRecognitionStatus.value = message;
  dispatchRecognitionTone.value = tone;
}

function clearDispatchRecognitionStatus() {
  window.clearTimeout(dispatchRecognitionStatusTimer);
  dispatchRecognitionStatus.value = "";
  dispatchRecognitionTone.value = "busy";
}

function scheduleClearDispatchRecognitionStatus(delay = 4200) {
  window.clearTimeout(dispatchRecognitionStatusTimer);
  dispatchRecognitionStatusTimer = window.setTimeout(() => {
    dispatchRecognitionStatus.value = "";
    dispatchRecognitionTone.value = "busy";
  }, delay);
}

function dispatchRecognitionDetailOnlyLocation(value = "") {
  const detail = cleanDispatchExcelCellText(value);
  return detail ? { city: "", district: "", detail } : "";
}

function dispatchImageTextAfterLabel(line = "", label = "") {
  const text = cleanDispatchExcelCellText(line);
  const normalizedText = normalizeDispatchExcelLookupText(text);
  const normalizedLabel = normalizeDispatchExcelLookupText(label);
  if (!normalizedText || !normalizedLabel || !normalizedText.includes(normalizedLabel)) return "";
  const colonIndex = text.search(/[：:]/);
  if (colonIndex >= 0) {
    const beforeColon = text.slice(0, colonIndex);
    if (normalizeDispatchExcelLookupText(beforeColon).includes(normalizedLabel)) {
      return text.slice(colonIndex + 1).trim();
    }
  }
  const plainLabel = String(label || "").replace(/[：:]\s*$/, "").trim();
  if (plainLabel) {
    const escaped = plainLabel.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const stripped = text.replace(new RegExp(`^\\s*${escaped}\\s*[：:]?\\s*`, "i"), "").trim();
    if (stripped && stripped !== text) return stripped;
  }
  return "";
}

function stripDispatchImageWeightRemarkText(value = "") {
  return normalizeDispatchImageAddressLine(value)
    .replace(/(?:不?用|无须|无需|不需|免)?过磅/ig, "")
    .replace(/^[：:\-—"'“”‘’|｜\s]+/, "")
    .replace(/[，,；;、\s]+$/g, "")
    .trim();
}

function extractDispatchImageNoteText(text = "") {
  const source = compactDispatchOcrText(text);
  if (!source) return "";
  const lines = source.split(/\n+/).map(cleanDispatchExcelCellText).filter(Boolean);
  const collected = [];
  const remarkLine = lines.find((line) => {
    const normalized = normalizeDispatchExcelLookupText(line);
    return normalized.includes(normalizeDispatchExcelLookupText("备注")) && !normalized.includes(normalizeDispatchExcelLookupText("注意事项"));
  });
  if (remarkLine) {
    const remark = stripDispatchImageWeightRemarkText(dispatchImageTextAfterLabel(remarkLine, "备注"));
    if (remark) collected.push(remark);
  }
  const noteLabels = ["注意事项", "注意"];
  const noteIndex = lines.findIndex((line) =>
    noteLabels.some((label) => normalizeDispatchExcelLookupText(line).includes(normalizeDispatchExcelLookupText(label)))
  );
  if (noteIndex >= 0) {
    const matchedLabel = noteLabels.find((label) =>
      normalizeDispatchExcelLookupText(lines[noteIndex]).includes(normalizeDispatchExcelLookupText(label))
    ) || "注意事项";
    const inline = dispatchImageTextAfterLabel(lines[noteIndex], matchedLabel);
    if (inline) collected.push(inline);
    for (let index = noteIndex + 1; index < lines.length; index += 1) {
      const line = normalizeDispatchImageAddressLine(lines[index]);
      if (!line) continue;
      const normalized = normalizeDispatchExcelLookupText(line);
      if (isDispatchLikelyMetadataLine(line) && !/^\d+\s*[.、]/.test(line)) break;
      if (normalized.includes(normalizeDispatchExcelLookupText("装货地点"))
        || normalized.includes(normalizeDispatchExcelLookupText("装货地址"))
        || normalized.includes(normalizeDispatchExcelLookupText("提货地点"))
        || normalized.includes(normalizeDispatchExcelLookupText("提货地址"))
        || normalized.includes(normalizeDispatchExcelLookupText("送货地点"))
        || normalized.includes(normalizeDispatchExcelLookupText("送货地址"))
        || normalized.includes(normalizeDispatchExcelLookupText("卸货地点"))
        || normalized.includes(normalizeDispatchExcelLookupText("卸货地址"))
        || normalized.includes(normalizeDispatchExcelLookupText("落货地点"))
        || normalized.includes(normalizeDispatchExcelLookupText("落货地址"))) {
        break;
      }
      collected.push(line);
    }
  }
  return appendUniqueDispatchExcelParts(collected).join(" ");
}

function applyDispatchExcelRecognition(result = {}, options = {}) {
  const sourceLabel = options.sourceLabel || "Excel";
  const filled = new Set();
  if (result.customer) {
    selectDispatchCustomer(result.customer);
    filled.add("客户");
  }
  [
    ["date", "排车日期", result.date],
    ["port", "口岸", result.port],
    ["direction", "进出口", result.direction],
    ["tonnage", "吨位", result.tonnage],
    ["loadTime", "装车时间", result.loadTime],
    ["plate", "车牌", result.plate],
    ["quantity", "件数/板数", result.quantity],
    ["weight", "重量", result.weight]
  ].forEach(([field, label, value]) => {
    const text = cleanDispatchExcelCellText(value);
    if (!text) return;
    dispatchForm[field] = text;
    filled.add(label);
  });
  if (result.note) {
    dispatchForm.note = cleanDispatchExcelCellText(result.note);
    filled.add("备注");
  }
  if (typeof result.needsWeighing === "boolean") {
    dispatchForm.needsWeighing = result.needsWeighing;
    filled.add("是否过磅");
  }
  if (result.loading) {
    clearDispatchLocationDraftsForTarget("loading");
    setDispatchLocationEntries("loading", [dispatchRecognitionDetailOnlyLocation(result.loading)]);
    filled.add("装货地");
  }
  if (result.unloading) {
    clearDispatchLocationDraftsForTarget("unloading");
    setDispatchLocationEntries("unloading", [dispatchRecognitionDetailOnlyLocation(result.unloading)]);
    filled.add("卸货地");
  }
  syncDispatchLoadHourDraft();
  const filledLabels = [...filled];
  if (!filledLabels.length) {
    const message = `没有识别到可回填的排车信息，请确认${sourceLabel}内容是否清晰`;
    notify(message);
    setDispatchRecognitionStatus(message, "error");
    scheduleClearDispatchRecognitionStatus(6200);
    return [];
  }
  const suffix = result.customer ? "" : "；客户未自动匹配，请手动选择客户";
  const message = `已识别：${filledLabels.join("、")}${suffix}`;
  notify(message);
  setDispatchRecognitionStatus(message, "success");
  scheduleClearDispatchRecognitionStatus(5200);
  return filledLabels;
}

function readDispatchExcelFileAsArrayBuffer(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error || new Error("读取 Excel 文件失败"));
    reader.readAsArrayBuffer(file);
  });
}

function readDispatchPdfFileAsArrayBuffer(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error || new Error("读取 PDF 文件失败"));
    reader.readAsArrayBuffer(file);
  });
}

function readDispatchWordFileAsArrayBuffer(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error || new Error("读取 Word 文件失败"));
    reader.readAsArrayBuffer(file);
  });
}

function openDispatchExcelFilePicker() {
  if (dispatchRecognitionBusy.value) return;
  const input = dispatchExcelFileInput.value;
  if (!input) return;
  input.value = "";
  input.click();
}

async function handleDispatchExcelFileChange(event) {
  const file = event?.target?.files?.[0];
  if (event?.target) event.target.value = "";
  if (!file || dispatchRecognitionBusy.value) return;
  dispatchExcelRecognizing.value = true;
  setDispatchRecognitionStatus("正在读取 Excel 文件", "busy");
  try {
    const buffer = await readDispatchExcelFileAsArrayBuffer(file);
    setDispatchRecognitionStatus("正在解析 Excel 内容", "busy");
    const XLSX = await import("xlsx");
    const workbook = XLSX.read(buffer, {
      type: "array",
      cellDates: true,
      raw: false
    });
    const sheetName = workbook.SheetNames[0];
    if (!sheetName) throw new Error("Excel 文件没有可识别的工作表");
    const worksheet = workbook.Sheets[sheetName];
    const rows = XLSX.utils.sheet_to_json(worksheet, {
      header: 1,
      defval: "",
      raw: false,
      blankrows: false
    });
    applyDispatchExcelRecognition(recognizeDispatchExcelRows(rows), { sourceLabel: "Excel" });
  } catch (error) {
    const message = error.message || "Excel 自动识别失败";
    setDispatchRecognitionStatus(message, "error");
    scheduleClearDispatchRecognitionStatus(6200);
    notify(message);
  } finally {
    dispatchExcelRecognizing.value = false;
  }
}

function isDispatchWordFile(file) {
  const type = String(file?.type || "").toLowerCase();
  const name = String(file?.name || "").toLowerCase();
  return type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document" || /\.docx$/.test(name);
}

function openDispatchWordFilePicker() {
  if (dispatchRecognitionBusy.value) return;
  const input = dispatchWordFileInput.value;
  if (!input) return;
  input.value = "";
  input.click();
}

function normalizeDispatchWordText(rawText = "") {
  const source = String(rawText ?? "");
  return (typeof source.normalize === "function" ? source.normalize("NFC") : source)
    .replace(/\u00a0/g, " ")
    .replace(/[\u200b-\u200d\ufeff]/g, "")
    .replace(/\r\n?/g, "\n")
    .replace(/[ \t]+/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim() || "";
}

async function extractDispatchWordText(file) {
  const buffer = await readDispatchWordFileAsArrayBuffer(file);
  const module = await import("mammoth");
  const mammoth = module.default || module;
  if (!mammoth?.extractRawText) throw new Error("Word 识别组件加载失败");
  const result = await mammoth.extractRawText({ arrayBuffer: buffer });
  return normalizeDispatchWordText(result?.value || "");
}

function dispatchWordLineMatchesLabel(line = "", labels = []) {
  const normalizedLine = normalizeDispatchExcelLookupText(line);
  return labels.some((label) => normalizedLine.includes(normalizeDispatchExcelLookupText(label)));
}

function stripDispatchWordAddressLabel(line = "", labels = []) {
  let text = normalizeDispatchWordText(line).replace(/^[：:\-—"'“”‘’|｜\s]+/, "");
  labels.forEach((label) => {
    if (!text) return;
    const escaped = escapeDispatchRecognitionRegExp(label);
    text = text.replace(new RegExp(`^\\s*${escaped}\\s*[：:"'“”‘’|｜\\s]*`, "i"), "");
  });
  return text.replace(/^[：:\-—"'“”‘’|｜\s]+/, "").trim();
}

function cleanDispatchWordAddressBlock(value = "") {
  return normalizeDispatchWordText(value)
    .split(/\n+/)
    .map((line) => normalizeDispatchWordText(line))
    .filter(Boolean)
    .join(" ")
    .replace(/\s*([：:])\s*/g, "$1")
    .replace(/[ \t]+/g, " ")
    .trim();
}

function extractDispatchWordLabeledBlock(text = "", startLabels = [], endLabels = []) {
  const lines = normalizeDispatchWordText(text).split(/\n+/).map((line) => normalizeDispatchWordText(line)).filter(Boolean);
  const collected = [];
  let collecting = false;
  for (const line of lines) {
    if (!collecting) {
      if (!dispatchWordLineMatchesLabel(line, startLabels)) continue;
      collecting = true;
      const stripped = stripDispatchWordAddressLabel(line, startLabels);
      if (stripped) collected.push(stripped);
      continue;
    }
    if (dispatchWordLineMatchesLabel(line, endLabels)) break;
    collected.push(line);
  }
  return cleanDispatchWordAddressBlock(collected.join("\n"));
}

function recognizeDispatchWordText(rawText = "") {
  const text = normalizeDispatchWordText(rawText);
  const baseResult = recognizeDispatchImageText(text);
  const lines = text.split(/\n+/).map(cleanDispatchExcelCellText).filter(Boolean);
  const allText = lines.join("\n");
  const bookingLine = dispatchRecognitionLineText(lines, ["装货日期", "裝貨日期", "装货时间", "裝貨時間", "到厂时间", "到廠時間"]) || allText;
  const loadingBlock = extractDispatchWordLabeledBlock(
    text,
    ["装货地点", "装货地址", "提货地点", "提货地址"],
    ["送货地点", "送货地址", "卸货地点", "卸货地址", "落货地点", "落货地址", "六联单号", "货物名称", "箱", "注意事项", "注意", "备注"]
  );
  const unloadingBlock = extractDispatchWordLabeledBlock(
    text,
    ["送货地点", "送货地址", "卸货地点", "卸货地址", "落货地点", "落货地址"],
    ["六联单号", "货物名称", "箱", "重量", "注意事项", "注意", "备注"]
  );
  return {
    ...baseResult,
    date: baseResult.date || normalizeDispatchExcelDate(bookingLine),
    loadTime: baseResult.loadTime || normalizeDispatchExcelTime(bookingLine),
    tonnage: baseResult.tonnage || parseDispatchExcelTonnage(dispatchRecognitionLineText(lines, ["车型", "車型", "车/柜型", "車/櫃型", "柜型", "櫃型"]) || allText),
    port: baseResult.port || parseDispatchExcelPort(dispatchRecognitionLineText(lines, ["口岸", "通关口岸", "通關口岸", "行走"]) || allText),
    needsWeighing: typeof baseResult.needsWeighing === "boolean" ? baseResult.needsWeighing : parseDispatchImageWeighing(allText),
    loading: loadingBlock || baseResult.loading,
    unloading: unloadingBlock || baseResult.unloading,
    direction: baseResult.direction || parseDispatchImageDirection(allText, loadingBlock || baseResult.loading, unloadingBlock || baseResult.unloading)
  };
}

function dispatchPdfReceiptLineValue(lines = [], labels = [], options = {}) {
  const startIndex = lines.findIndex((line) => dispatchWordLineMatchesLabel(line, labels));
  if (startIndex < 0) return "";
  const labelLine = lines[startIndex] || "";
  const matchedLabel = labels.find((label) => dispatchWordLineMatchesLabel(labelLine, [label])) || labels[0] || "";
  let value = dispatchImageTextAfterLabel(labelLine, matchedLabel) || labelLine.replace(/^[^：:]*[：:]\s*/, "");
  if (!value && options.followingRows) {
    const end = Math.min(lines.length, startIndex + 1 + Number(options.followingRows || 0));
    value = lines.slice(startIndex + 1, end).find((line) => !isDispatchLikelyMetadataLine(line)) || "";
  }
  return cleanDispatchPdfReceiptValue(value);
}

function normalizeDispatchPdfReceiptText(value = "") {
  return normalizeUserText(value, { singleLine: true, compactCjkSpacing: true })
    .replace(new RegExp(`([${USER_TEXT_CJK}])\\s+(?=[A-Za-z])`, "gu"), "$1")
    .replace(new RegExp(`([A-Za-z])\\s+(?=[${USER_TEXT_CJK}])`, "gu"), "$1")
    .replace(/（/g, "(")
    .replace(/）/g, ")")
    .replace(/\s*\(\s*/g, "（")
    .replace(/\s*\)\s*/g, "）")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
}

function cleanDispatchPdfReceiptValue(value = "") {
  return normalizeDispatchPdfReceiptText(value)
    .replace(/^(到客公司|收货公司|收貨公司|地址|联系人|聯絡人|电话|電話|CUSTOMER|RECEIVER\s*CO\.?|ADDRESS|CONTACT|TEL\s*NO)\s*[：:]?\s*/i, "")
    .replace(/\s*\d{1,4}\s*\*\s*司机填写.*$/i, "")
    .replace(/\s*\*\s*司机填写.*$/i, "")
    .replace(/\s*司机专用.*$/i, "")
    .replace(/\s*(到客时间|到客時間|ARRIVAL\s*TIME).*$/i, "")
    .replace(/\s*(离厂时间|離廠時間|LEAVING\s*TIME).*$/i, "")
    .replace(/\s*(约定时间|約定時間|APPOINTED\s*TIME).*$/i, "")
    .trim();
}

function findDispatchPdfSectionLineIndex(lines = [], labels = [], startIndex = 0) {
  const begin = Math.max(0, Number(startIndex || 0));
  return lines.findIndex((line, index) => index >= begin && dispatchWordLineMatchesLabel(line, labels));
}

function findDispatchPdfLineInSection(lines = [], labels = [], startIndex = 0, endIndex = lines.length) {
  const begin = Math.max(0, Number(startIndex || 0));
  const end = Math.min(lines.length, Number.isFinite(endIndex) ? endIndex : lines.length);
  for (let index = begin; index < end; index += 1) {
    if (dispatchWordLineMatchesLabel(lines[index], labels)) return { index, line: lines[index] };
  }
  return { index: -1, line: "" };
}

function isUsefulDispatchPdfAddressValue(value = "") {
  const text = cleanDispatchPdfReceiptValue(value);
  if (!text) return false;
  const normalized = normalizeDispatchExcelLookupText(text);
  if (["arrivaltime", "leavingtime", "appointedtime"].includes(normalized)) return false;
  return /[\u3400-\u9fff]|[A-Za-z]{2,}|\d/.test(text);
}

function findDispatchPdfAddressLineInSection(lines = [], startIndex = 0, endIndex = lines.length) {
  const begin = Math.max(0, Number(startIndex || 0));
  const end = Math.min(lines.length, Number.isFinite(endIndex) ? endIndex : lines.length);
  for (let index = begin; index < end; index += 1) {
    const line = lines[index] || "";
    if (!dispatchWordLineMatchesLabel(line, ["地址", "ADDRESS"])) continue;
    if (isUsefulDispatchPdfAddressValue(line)) return { index, line };
  }
  return { index: -1, line: "" };
}

function dispatchPdfReceiptContactValue(line = "") {
  const text = normalizeDispatchPdfReceiptText(line);
  if (!text) return "";
  const contactMatch = text.match(/(?:联系人|聯絡人|CONTACT)\s*[：:]\s*([\s\S]*?)(?=\s*(?:电话|電話|TEL\s*NO)\s*[：:]|$)/i);
  const contact = contactMatch?.[1] || dispatchImageTextAfterLabel(text, "联系人") || dispatchImageTextAfterLabel(text, "聯絡人") || dispatchImageTextAfterLabel(text, "CONTACT") || text.replace(/^[^：:]*[：:]\s*/, "");
  return cleanDispatchPdfReceiptValue(contact).replace(/\s*(电话|電話|TEL\s*NO)\s*[：:].*$/i, "").trim();
}

function dispatchPdfReceiptPhoneValue(line = "") {
  const text = normalizeDispatchPdfReceiptText(line);
  const phoneMatch = text.match(/(?:电话|電話|TEL\s*NO)\s*[：:]\s*([\s\S]+)$/i);
  const phone = phoneMatch?.[1] || dispatchImageTextAfterLabel(text, "电话") || dispatchImageTextAfterLabel(text, "電話") || dispatchImageTextAfterLabel(text, "TEL NO");
  return cleanDispatchPdfReceiptValue(phone)
    .replace(/(?<=\d),(?=\d)/g, "")
    .replace(/\s*\/\s*/g, " /")
    .trim();
}

function findDispatchPdfContactLineInSection(lines = [], startIndex = 0, endIndex = lines.length) {
  const begin = Math.max(0, Number(startIndex || 0));
  const end = Math.min(lines.length, Number.isFinite(endIndex) ? endIndex : lines.length);
  for (let index = begin; index < end; index += 1) {
    const line = lines[index] || "";
    if (!dispatchWordLineMatchesLabel(line, ["联系人", "聯絡人", "CONTACT"])) continue;
    if (dispatchPdfReceiptContactValue(line) || dispatchPdfReceiptPhoneValue(line)) return { index, line };
  }
  return { index: -1, line: "" };
}

function recognizeDispatchPdfText(rawText = "") {
  const text = normalizeDispatchWordText(rawText);
  const baseResult = recognizeDispatchWordText(text);
  const lines = text.split(/\n+/).map(cleanDispatchExcelCellText).filter(Boolean);
  const allText = lines.join("\n");
  const loadingSectionIndex = findDispatchPdfSectionLineIndex(lines, ["到客公司"]);
  const unloadingSectionIndex = findDispatchPdfSectionLineIndex(lines, ["收货公司", "收貨公司", "RECEIVER CO"], loadingSectionIndex >= 0 ? loadingSectionIndex + 1 : 0);
  const loadingSectionEnd = unloadingSectionIndex >= 0 ? unloadingSectionIndex : lines.length;
  const loadingAddressEntry = loadingSectionIndex >= 0
    ? findDispatchPdfAddressLineInSection(lines, loadingSectionIndex + 1, loadingSectionEnd)
    : { index: -1, line: "" };
  const loadingAddress = loadingAddressEntry.index >= 0 ? cleanDispatchPdfReceiptValue(loadingAddressEntry.line) : "";
  const loadingContactEntry = loadingAddressEntry.index >= 0
    ? findDispatchPdfContactLineInSection(lines, loadingAddressEntry.index + 1, loadingSectionEnd)
    : { index: -1, line: "" };
  const loadingContactLine = loadingContactEntry.line || "";
  const unloadingAddressEntry = unloadingSectionIndex >= 0
    ? findDispatchPdfAddressLineInSection(lines, unloadingSectionIndex + 1, lines.length)
    : { index: -1, line: "" };
  const unloadingAddress = unloadingAddressEntry.index >= 0 ? cleanDispatchPdfReceiptValue(unloadingAddressEntry.line) : "";
  const unloadingContactEntry = unloadingAddressEntry.index >= 0
    ? findDispatchPdfContactLineInSection(lines, unloadingAddressEntry.index + 1, lines.length)
    : { index: -1, line: "" };
  const unloadingContactLine = unloadingContactEntry.line || "";
  const loading = appendUniqueDispatchExcelParts([
    loadingAddress,
    dispatchPdfReceiptContactValue(loadingContactLine),
    dispatchPdfReceiptPhoneValue(loadingContactLine)
  ]).join("，");
  const unloading = appendUniqueDispatchExcelParts([
    unloadingAddress,
    dispatchPdfReceiptContactValue(unloadingContactLine),
    dispatchPdfReceiptPhoneValue(unloadingContactLine)
  ]).join("，");
  return {
    ...baseResult,
    customer: baseResult.customer || matchDispatchExcelCustomer(allText),
    loading: loading || baseResult.loading,
    unloading: unloading || baseResult.unloading,
    direction: baseResult.direction || parseDispatchImageDirection(allText, loading || baseResult.loading, unloading || baseResult.unloading)
  };
}

async function handleDispatchWordFileChange(event) {
  const file = event?.target?.files?.[0];
  if (event?.target) event.target.value = "";
  if (!file || dispatchRecognitionBusy.value) return;
  if (!isDispatchWordFile(file)) {
    notify("请选择 .docx Word 文件进行自动识别");
    return;
  }
  dispatchWordRecognizing.value = true;
  setDispatchRecognitionStatus("正在读取 Word 文件", "busy");
  try {
    const text = await extractDispatchWordText(file);
    if (!String(text || "").trim()) throw new Error("Word 文件里没有识别到文字");
    setDispatchRecognitionStatus("正在匹配排车单字段", "busy");
    applyDispatchExcelRecognition(recognizeDispatchWordText(text), { sourceLabel: "Word" });
  } catch (error) {
    const message = error.message || "Word 自动识别失败";
    setDispatchRecognitionStatus(message, "error");
    scheduleClearDispatchRecognitionStatus(6800);
    notify(message);
  } finally {
    dispatchWordRecognizing.value = false;
  }
}

function isDispatchImageFile(file) {
  const type = String(file?.type || "").toLowerCase();
  const name = String(file?.name || "").toLowerCase();
  return type.startsWith("image/") || /\.(png|jpe?g|webp|bmp|gif|tiff?)$/.test(name);
}

function openDispatchImageFilePicker() {
  if (dispatchRecognitionBusy.value) return;
  const input = dispatchImageFileInput.value;
  if (!input) return;
  input.value = "";
  input.click();
}

function isDispatchPdfFile(file) {
  const type = String(file?.type || "").toLowerCase();
  const name = String(file?.name || "").toLowerCase();
  return type === "application/pdf" || /\.pdf$/.test(name);
}

function openDispatchPdfFilePicker() {
  if (dispatchRecognitionBusy.value) return;
  const input = dispatchPdfFileInput.value;
  if (!input) return;
  input.value = "";
  input.click();
}

async function extractDispatchPdfText(file) {
  const buffer = await readDispatchPdfFileAsArrayBuffer(file);
  const [pdfModule, workerModule] = await Promise.all([
    import("pdfjs-dist/legacy/build/pdf.mjs"),
    import("pdfjs-dist/legacy/build/pdf.worker.mjs?url")
  ]);
  const pdfjs = pdfModule.default || pdfModule;
  const workerSrc = workerModule.default || workerModule;
  pdfjs.GlobalWorkerOptions.workerSrc = `${workerSrc}${String(workerSrc).includes("?") ? "&" : "?"}v=pdf-worker-js`;
  const loadingTask = pdfjs.getDocument({
    data: new Uint8Array(buffer),
    useWorkerFetch: false,
    isEvalSupported: false
  });
  const pdf = await loadingTask.promise;
  const pages = [];
  try {
    for (let pageNo = 1; pageNo <= pdf.numPages; pageNo += 1) {
      const page = await pdf.getPage(pageNo);
    const content = await page.getTextContent();
      const rowMap = new Map();
      (content.items || []).forEach((item) => {
        const str = cleanDispatchExcelCellText(item?.str || "");
        if (!str) return;
        const [, , , , x = 0, y = 0] = item.transform || [];
        const rowKey = Math.round(Number(y || 0) / 3) * 3;
        if (!rowMap.has(rowKey)) rowMap.set(rowKey, []);
        rowMap.get(rowKey).push({ x: Number(x || 0), str });
      });
      const text = [...rowMap.entries()]
        .sort((left, right) => right[0] - left[0])
        .map(([, items]) => items
          .sort((left, right) => left.x - right.x)
          .map((item) => item.str)
          .join(" "))
        .filter(Boolean)
        .join("\n");
      if (text.trim()) pages.push(text);
      page.cleanup?.();
    }
  } finally {
    await pdf.destroy?.();
  }
  return pages.join("\n");
}

async function handleDispatchPdfFileChange(event) {
  const file = event?.target?.files?.[0];
  if (event?.target) event.target.value = "";
  if (!file || dispatchRecognitionBusy.value) return;
  if (!isDispatchPdfFile(file)) {
    notify("请选择 PDF 文件进行自动识别");
    return;
  }
  dispatchPdfRecognizing.value = true;
  setDispatchRecognitionStatus("正在读取 PDF 文件", "busy");
  try {
    const text = await extractDispatchPdfText(file);
    if (!String(text || "").trim()) throw new Error("PDF 里没有识别到可用文字，请换一个文本版 PDF");
    setDispatchRecognitionStatus("正在匹配排车单字段", "busy");
    applyDispatchExcelRecognition(recognizeDispatchPdfText(text), { sourceLabel: "PDF" });
  } catch (error) {
    const message = error.message || "PDF 自动识别失败";
    setDispatchRecognitionStatus(message, "error");
    scheduleClearDispatchRecognitionStatus(6800);
    notify(message);
  } finally {
    dispatchPdfRecognizing.value = false;
  }
}

function dispatchOcrStatusLabel(status = "") {
  const text = String(status || "").toLowerCase();
  if (text.includes("loading tesseract core")) return "正在加载 OCR 核心";
  if (text.includes("loading language")) return "正在加载中英文识别模型";
  if (text.includes("initializing")) return "正在初始化 OCR";
  if (text.includes("recognizing")) return "正在识别图片文字";
  return status || "正在识别图片";
}

async function recognizeDispatchImageFile(file) {
  setDispatchRecognitionStatus("正在加载 OCR 识别模型", "busy");
  const module = await import("tesseract.js");
  const Tesseract = module.default || module;
  if (!Tesseract?.createWorker) throw new Error("OCR 识别组件加载失败");
  const worker = await Tesseract.createWorker("chi_sim+eng", 1, {
    logger(message = {}) {
      const label = dispatchOcrStatusLabel(message.status);
      const progress = Number(message.progress || 0);
      const percent = progress > 0 && progress <= 1 ? ` ${Math.round(progress * 100)}%` : "";
      setDispatchRecognitionStatus(`${label}${percent}`, "busy");
    }
  });
  try {
    await worker.setParameters?.({
      preserve_interword_spaces: "1"
    });
    const result = await worker.recognize(file);
    return result?.data?.text || "";
  } finally {
    await worker.terminate();
  }
}

async function handleDispatchImageFileChange(event) {
  const file = event?.target?.files?.[0];
  if (event?.target) event.target.value = "";
  if (!file || dispatchRecognitionBusy.value) return;
  if (!isDispatchImageFile(file)) {
    notify("请选择图片文件进行自动识别");
    return;
  }
  dispatchImageRecognizing.value = true;
  try {
    const text = await recognizeDispatchImageFile(file);
    if (!text.trim()) throw new Error("图片里没有识别到文字，请换一张更清晰的图片");
    setDispatchRecognitionStatus("正在匹配排车单字段", "busy");
    applyDispatchExcelRecognition(recognizeDispatchImageText(text), { sourceLabel: "图片" });
  } catch (error) {
    const message = error.message || "图片自动识别失败";
    setDispatchRecognitionStatus(message, "error");
    scheduleClearDispatchRecognitionStatus(6800);
    notify(message);
  } finally {
    dispatchImageRecognizing.value = false;
  }
}

