function createBlankFeeRow() {
  return {
    _clientKey: createOrderFeeClientKey(),
    feeItemId: "",
    category: "正常",
    name: "",
    quantity: 1,
    unitPrice: 0,
    _manualUnitPrice: false,
    currency: "",
    amount: 0,
    _manualAmount: false,
    cost: 0,
    costCurrency: "",
    _manualCost: false,
    advanceAddress: "",
    _manualAssignee: false,
    driverRole: "",
    driverName: "",
    remark: ""
  };
}

function createOrderFeeClientKey() {
  const randomPart = typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  return `fee-${randomPart}`;
}

function normalizeOrderFeeClientKey(value = "") {
  return String(value || "").trim();
}

function orderFeeRowKey(fee = {}, index = 0) {
  return normalizeOrderFeeClientKey(fee._clientKey || fee.clientKey || fee.client_key) || `fee-row-${index}`;
}

function ensureOrderFeeClientKey(fee = {}) {
  const key = normalizeOrderFeeClientKey(fee._clientKey || fee.clientKey || fee.client_key);
  if (key) {
    fee._clientKey = key;
    return key;
  }
  const nextKey = createOrderFeeClientKey();
  fee._clientKey = nextKey;
  return nextKey;
}

function normalizeFeeAmount(fee) {
  const manualAmount = booleanFlag(fee?.amountManual ?? fee?.amount_manual ?? fee?.manualAmount ?? fee?._manualAmount, false);
  const candidates = manualAmount ? [fee?.amount] : [
    fee?.amount,
    fee?.defaultAmount,
    fee?.amountValue,
    fee?.amount_hkd,
    fee?.amount_rmb,
    fee?.hkdAmount,
    fee?.rmbAmount
  ];
  const value = candidates.find((item) => item !== undefined && item !== null && String(item).trim() !== "");
  if (value === undefined) return "";
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : "";
}

function isFreightFeeRow(fee) {
  return !fee.name || fee.name.includes("运费") || fee.autoFreight;
}

function isCrossBorderFreightFee(fee = {}) {
  return String(feeItemForFee(fee)?.name || fee.name || "").trim() === "中港运费";
}

function markFeeUnitPriceManual(fee) {
  if (!fee) return;
  fee._manualUnitPrice = true;
}

function markFeeAmountManual(fee, value) {
  if (!fee) return;
  if (value !== undefined) {
    const number = Number(value);
    fee.amount = Number.isFinite(number) && number >= 0 ? number : 0;
  }
  fee._manualAmount = true;
  if (isFreightFeeRow(fee)) fee._manualFreightAmount = true;
  refreshOrderFeeCost(fee);
}

function markFeeCurrencyManual(fee) {
  if (!fee) return;
  fee._manualCurrency = true;
  refreshOrderFeeCost(fee);
}

function syncFeeAmountFromQuantityOrUnitPrice(fee) {
  if (!fee) return;
  fee._manualAmount = false;
  if (isFreightFeeRow(fee)) fee._manualFreightAmount = false;
  syncFeeAmountFromUnitPrice(fee);
}

function rawFeeUnitPrice(fee = {}) {
  const value = fee.unitPrice ?? fee.unit_price ?? fee.price;
  if (value === undefined || value === null || String(value).trim() === "") return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

function matchedFeeUnitPrice(fee = {}) {
  const name = String(fee.name || "").trim();
  if (name && isFreightFeeRow(fee)) {
    const freightTemplate = findFreightFeeTemplate();
    if (freightTemplate) {
      const amount = Number(freightTemplate.defaultAmount || 0);
      return Number.isFinite(amount) && amount >= 0 ? amount : 0;
    }
  }
  const item = feeItemForFee(fee);
  const amount = Number(item?.defaultAmount || 0);
  return Number.isFinite(amount) && amount >= 0 ? amount : 0;
}

function normalizeFeeUnitPrice(fee = {}, options = {}) {
  const raw = rawFeeUnitPrice(fee);
  const manualUnitPrice = booleanFlag(fee.unitPriceManual ?? fee.unit_price_manual ?? fee.manualUnitPrice ?? fee._manualUnitPrice, false);
  if (raw !== null && (raw > 0 || manualUnitPrice)) return raw;
  if (options.matchTemplate === false) return raw ?? 0;
  return matchedFeeUnitPrice(fee);
}

function normalizeFeeQuantity(fee = {}) {
  const quantity = quantityNumber(fee.quantity);
  return quantity > 0 ? quantity : 1;
}

function normalizeFeeCost(fee = {}) {
  const value = fee.cost ?? fee.costValue ?? fee.cost_value ?? fee.costAmount ?? fee.cost_amount;
  if (value === undefined || value === null || String(value).trim() === "") return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : 0;
}

function orderFeeCostCurrencyDisplay(fee = {}) {
  if (fee._costMultiCurrency) return "多币种";
  return currencyCodeDisplay(fee.costCurrency || fee._costCurrency || fee.currency || orderForm.currency || "港币") || "HKD";
}

function orderFeeCostBreakdownDisplay(fee = {}) {
  return fee._costBreakdownText || fee._costSourceText || "未匹配到成本";
}

function orderFeeCostTitle(fee = {}) {
  if (fee._manualCost) return "手动成本";
  return [
    fee._costSourceText || "未匹配到成本",
    fee._costMultiCurrency && fee._costBreakdownText ? fee._costBreakdownText : ""
  ].filter(Boolean).join(" / ");
}

function booleanFlag(value, fallback = false) {
  if (value === undefined || value === null || value === "") return fallback;
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return value !== 0;
  const text = String(value).trim().toLowerCase();
  if (["1", "true", "yes", "on", "过磅"].includes(text)) return true;
  if (["0", "false", "no", "off", "不用过磅"].includes(text)) return false;
  return fallback;
}

function feeCostQuantity(fee = {}) {
  return normalizeFeeQuantity(fee);
}

function setOrderFeeCost(fee, value = 0) {
  const number = Number(value);
  fee.cost = Number.isFinite(number) && number >= 0 ? number : 0;
  const currency = normalizeCostCenterCurrency(fee.costCurrency || fee._costCurrency || fee.currency || orderForm.currency || "港币");
  fee.costCurrency = currency;
  fee._costCurrency = currency;
  fee._costSourceCurrency = currency;
  fee._costMultiCurrency = false;
  fee._costBreakdownText = "";
  fee._manualCost = true;
}

function setOrderFeeCostCurrency(fee, value = "港币") {
  if (!fee) return;
  const currency = normalizeCostCenterCurrency(value, fee.costCurrency || fee._costCurrency || fee.currency || orderForm.currency || "港币");
  fee.costCurrency = currency;
  fee._costCurrency = currency;
  fee._costSourceCurrency = currency;
  fee._manualCost = true;
}

function calculateFeeAmountFromUnitPrice(fee = {}) {
  const quantity = normalizeFeeQuantity(fee);
  const rawUnitPrice = rawFeeUnitPrice(fee);
  const unitPrice = rawUnitPrice === null ? normalizeFeeUnitPrice(fee) : rawUnitPrice;
  return Number((quantity * Math.max(0, Number(unitPrice) || 0)).toFixed(2));
}

function syncFeeAmountFromUnitPrice(fee) {
  fee.quantity = normalizeFeeQuantity(fee);
  if (rawFeeUnitPrice(fee) === null && !fee._manualUnitPrice) {
    fee.unitPrice = matchedFeeUnitPrice(fee);
  }
  if (!fee._manualAmount) {
    fee.amount = calculateFeeAmountFromUnitPrice(fee);
    if (isFreightFeeRow(fee)) fee._manualFreightAmount = false;
  }
  refreshOrderFeeCost(fee);
}

function normalizeOrderFeeRow(fee = {}) {
  const row = { ...fee };
  ensureOrderFeeClientKey(row);
  syncCompanySelfPayFeeRemark(row);
  row.category = feeCategoryLabel(row);
  row.quantity = normalizeFeeQuantity(row);
  row.unitPrice = normalizeFeeUnitPrice(row);
  row.amount = row._manualAmount
    ? normalizeFeeAmount(row)
    : calculateFeeAmountFromUnitPrice(row);
  row.costCurrency = normalizeCostCenterCurrency(row.costCurrency || row._costCurrency || row.currency || orderForm.currency || "港币");
  row._costCurrency = row.costCurrency;
  row.advanceAddress = feeCategoryLabel(row) === "代垫"
    ? String(row.advanceAddress || row.advance_address || "").trim()
    : "";
  row.driverRole = normalizeOrderFeeAssigneeText(row.driverRole || row.driver_role || "");
  row.driverName = normalizeOrderFeeAssigneeText(row.driverName || row.driver_name || "");
  row._manualAssignee = normalizeOrderFeeManualAssigneeFlag(row);
  syncCrossBorderFreightDriverRole(row);
  return row;
}

function normalizeOrderFeeRows() {
  orderFees.value = orderFees.value.map((fee) => normalizeOrderFeeRow(fee));
}

function normalizeLocationText(value) {
  return String(value || "")
    .replace(/[市区县镇街道\s/｜|,，-]/g, "")
    .toLowerCase();
}

function locationNameMatches(left = "", right = "") {
  const normalizedLeft = normalizeLocationText(left);
  const normalizedRight = normalizeLocationText(right);
  if (!normalizedLeft || !normalizedRight) return false;
  return normalizedLeft === normalizedRight;
}

function normalizeFreightLabel(value) {
  return String(value || "")
    .trim()
    .replace(/[／｜|]+/g, "/")
    .replace(/\s*\/\s*/g, "/")
    .replace(/\s+/g, " ")
    .replace(/^[-/]+|[-/]+$/g, "");
}

function freightRateCustomerId(item = {}) {
  return String(item.customerId ?? item.customer_id ?? "").trim();
}

function freightRateCustomerName(item = {}) {
  return String(item.customerName ?? item.customer_name ?? "").trim();
}

function isPublicFreightRate(item = {}) {
  return !freightRateCustomerId(item) && !freightRateCustomerName(item);
}

function freightRateBelongsToCustomer(item = {}, customer = {}) {
  const rateCustomerId = freightRateCustomerId(item);
  const rateCustomerName = freightRateCustomerName(item);
  const customerId = String(customer.id || "").trim();
  const customerName = String(customer.name || "").trim();
  if (!rateCustomerId && !rateCustomerName) return false;
  if (customerId && rateCustomerId) return rateCustomerId === customerId;
  if (customerName && rateCustomerName) return rateCustomerName === customerName;
  return false;
}

function normalizeFreightRateEntry(item) {
  const level1 = normalizeFreightLabel(item.level1 || item.city || "");
  const level2 = normalizeFreightLabel(item.level2 || "");
  return {
    ...item,
    customerId: freightRateCustomerId(item),
    customerName: freightRateCustomerName(item),
    direction: freightRateDirectionValue(item),
    level1,
    level2,
    level3: "",
    city: normalizeFreightLabel(item.city || level2 || level1)
  };
}

function priceEffectiveDate(item = {}, fallback = "1970-01-01") {
  return normalizePriceEffectiveDate(
    item.effectiveDate ?? item.effective_date ?? item.modifiedDate ?? item.modified_date,
    fallback
  );
}

function priceEffectiveDateDisplay(item = {}) {
  const date = priceEffectiveDate(item);
  return date === "1970-01-01" ? "历史默认" : date;
}

function orderPricingDate(order = orderForm) {
  return normalizePriceEffectiveDate(order?.date || todayInputValue(), todayInputValue());
}

function priceRuleAppliesToOrderDate(item = {}, order = orderForm) {
  return priceEffectiveDate(item) <= orderPricingDate(order);
}

function priceUpdatedTime(item = {}) {
  const parsed = new Date(item.updatedAt || item.updated_at || "").getTime();
  return Number.isFinite(parsed) ? parsed : 0;
}

function comparePriceRuleVersionDesc(left = {}, right = {}) {
  return priceEffectiveDate(right).localeCompare(priceEffectiveDate(left))
    || priceUpdatedTime(right) - priceUpdatedTime(left)
    || Number(right.id || 0) - Number(left.id || 0);
}

function latestPriceVersionRows(rows = [], keyForRow, targetDate = "") {
  const groups = new Map();
  rows.forEach((row) => {
    if (targetDate && priceEffectiveDate(row) > targetDate) return;
    const key = keyForRow(row);
    if (!key) return;
    const current = groups.get(key);
    if (!current || comparePriceRuleVersionDesc(row, current) < 0) {
      groups.set(key, row);
    }
  });
  return [...groups.values()];
}

function locationMatchesCity(locationText, city) {
  const location = normalizeLocationText(locationText);
  const target = normalizeLocationText(city);
  if (!location || !target) return false;
  return location.includes(target) || target.includes(location);
}

function freightRateDirectionValue(item = {}) {
  return String(item.direction || SHARED_DIRECTION).trim() || SHARED_DIRECTION;
}

function freightRateDirectionPriority(item = {}, direction = "") {
  const rateDirection = freightRateDirectionValue(item);
  if (direction && rateDirection === direction) return 2;
  if (rateDirection === SHARED_DIRECTION) return 1;
  return 0;
}

function splitLocationTokens(value) {
  return String(value || "")
    .split(/[\/／|｜,，>＞\-\s]+/)
    .map((item) => normalizeLocationText(item))
    .filter(Boolean);
}

function locationPartMatches(part, location, tokens) {
  if (!part || !location) return false;
  return (
    location.includes(part) ||
    part.includes(location) ||
    tokens.some((token) => token && (token.includes(part) || part.includes(token)))
  );
}

function splitFreightLocationEntries(value = "") {
  return String(value || "")
    .replace(/\r/g, "\n")
    .split(/[；;]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function freightLocationCandidateFromText(value = "") {
  const normalized = normalizeFreightLabel(value);
  const levels = normalized.split("/").map((item) => normalizeFreightLabel(item)).filter(Boolean);
  return {
    value,
    levels,
    structured: levels.length > 1,
    normalizedText: normalizeLocationText(value),
    tokens: splitLocationTokens(value)
  };
}

function freightLocationCandidatesFromText(value = "") {
  return splitFreightLocationEntries(value)
    .map((item) => freightLocationCandidateFromText(item))
    .filter((item) => item.normalizedText || item.levels.length);
}

function orderFreightPricedLocationText() {
  return orderForm.direction === "进口" ? orderForm.unloading : orderForm.loading;
}

function orderFreightCurrency() {
  return orderForm.currency || "港币";
}

function ensureOrderFreightCurrency() {
  if (orderHasTransportFields.value && !orderForm.currency) orderForm.currency = "港币";
}

function freightLocationLevelMatches(rateLevel = "", targetLevel = "", candidate = {}) {
  const rate = normalizeLocationText(rateLevel);
  const target = normalizeLocationText(targetLevel);
  if (!rate) return true;
  if (candidate.structured) return Boolean(target && target === rate);
  return Boolean(
    (target && target === rate) ||
    locationPartMatches(rate, candidate.normalizedText, candidate.tokens || [])
  );
}

function freightRateLocationScore(item, locationCandidate) {
  const normalizedItem = normalizeFreightRateEntry(item);
  const [targetLevel1 = "", targetLevel2 = ""] = locationCandidate.levels || [];
  if (!freightLocationLevelMatches(normalizedItem.level1, targetLevel1, locationCandidate)) return 0;
  let score = 100;
  if (normalizedItem.level2) {
    if (!freightLocationLevelMatches(normalizedItem.level2, targetLevel2, locationCandidate)) return 0;
    score = 200;
  }
  return score;
}

function currentOrderFreightCustomer() {
  return {
    id: String(orderForm.customerId || "").trim(),
    name: String(orderForm.customer || "").trim()
  };
}

function rankFreightRateRows(rows, pricedLocation, priceField, quotePriority = 0) {
  const locationCandidates = freightLocationCandidatesFromText(pricedLocation);
  return rows
    .filter((item) => item.tonnage === orderForm.tonnage && priceRuleAppliesToOrderDate(item, orderForm))
    .flatMap((item) => {
      const directionPriority = freightRateDirectionPriority(item, orderForm.direction);
      if (!directionPriority) return [];
      return locationCandidates.map((locationCandidate) => ({
        item,
        quotePriority,
        directionPriority,
        score: freightRateLocationScore(item, locationCandidate),
        amount: Number(item?.[priceField] || 0)
      }));
    })
    .filter((entry) => entry.score > 0);
}

function rankedRouteFreightRates() {
  const pricedLocation = orderFreightPricedLocationText();
  if (!orderForm.customer && !orderForm.customerId) return [];
  if (!orderForm.direction || !orderForm.tonnage || !pricedLocation) {
    return [];
  }
  const priceField = orderFreightCurrency() === "人民币" ? "rmbAmount" : "hkdAmount";
  const customer = currentOrderFreightCustomer();
  const customerRowsForQuote = freightRateRows.value.filter((item) => freightRateBelongsToCustomer(item, customer));
  return rankFreightRateRows(customerRowsForQuote, pricedLocation, priceField, 1)
    .sort((a, b) =>
      b.directionPriority - a.directionPriority
      || b.score - a.score
      || priceEffectiveDate(b.item).localeCompare(priceEffectiveDate(a.item))
      || Number(a.item?.sortOrder || 0) - Number(b.item?.sortOrder || 0)
      || Number(a.item?.id || 0) - Number(b.item?.id || 0)
    );
}

function matchRouteFreightRate() {
  return rankedRouteFreightRates()[0]?.item || null;
}

function findRouteFreightTemplate() {
  const matched = matchRouteFreightRate();
  const priceField = orderFreightCurrency() === "人民币" ? "rmbAmount" : "hkdAmount";
  const amount = Number(matched?.[priceField] || 0);
  const ready = Boolean(orderForm.customer || orderForm.customerId)
    && Boolean(orderForm.direction && orderForm.tonnage && orderFreightPricedLocationText());
  if (!ready) return null;
  return {
    category: "正常",
    name: "中港运费",
    currency: orderFreightCurrency(),
    defaultAmount: amount
  };
}

const routeFreightPreview = computed(() => {
  const pricedLocation = orderFreightPricedLocationText();
  const missing = [
    ["客户", orderForm.customer || orderForm.customerId],
    ["进出口", orderForm.direction],
    ["吨位", orderForm.tonnage],
    [orderForm.direction === "进口" ? "卸货地" : "装货地", pricedLocation]
  ].filter(([, value]) => !value).map(([label]) => label);
  if (missing.length) {
    return { state: "pending", text: `运费模板：待填写 ${missing.join("、")}` };
  }

  const matched = matchRouteFreightRate();
  if (!matched) {
    return { state: "empty", text: `客户运费模板：未匹配到 ${orderForm.direction}/${pricedLocation}/${orderForm.tonnage}，金额 0` };
  }

  const priceField = orderFreightCurrency() === "人民币" ? "rmbAmount" : "hkdAmount";
  const amount = Number(matched[priceField] || 0);
  const routePath = [matched.level1, matched.level2, matched.level3].filter(Boolean).join(" / ") || matched.city || pricedLocation;
  if (amount <= 0) {
    return { state: "empty", text: `客户运费模板：${routePath} / ${orderForm.tonnage} 有模板，${currencyCodeDisplay(orderFreightCurrency())} 金额 0` };
  }
  return { state: "matched", text: `客户运费模板：${routePath} / ${orderForm.tonnage} / ${currencyCodeDisplay(orderFreightCurrency())} ${amount}（修改日期 ${priceEffectiveDateDisplay(matched)}）` };
});

function findFreightFeeTemplate() {
  const routeTemplate = findRouteFreightTemplate();
  if (routeTemplate) return routeTemplate;
  return null;
}

function findAutoFreightFeeIndex() {
  const index = orderFees.value.findIndex((fee) => fee.autoFreight || isFreightFeeRow(fee));
  return index >= 0 ? index : 0;
}

function syncAutoFreightFee() {
  if (!orderFees.value.length) {
    orderFees.value = [createBlankFeeRow()];
  }
  ensureOrderFreightCurrency();

  const template = findFreightFeeTemplate();
  if (!template) {
    const existingAutoFee = orderFees.value.find((fee) => fee.autoFreight);
    if (!existingAutoFee) return;

    const keepManualUnitPrice = Boolean(existingAutoFee._manualUnitPrice);
    const keepManualAmount = Boolean(existingAutoFee._manualAmount || existingAutoFee._manualFreightAmount);
    const keepManualCurrency = Boolean(existingAutoFee._manualCurrency);
    if (!keepManualUnitPrice) existingAutoFee.unitPrice = 0;
    if (!keepManualAmount) {
      existingAutoFee.amount = keepManualUnitPrice
        ? calculateFeeAmountFromUnitPrice(existingAutoFee)
        : 0;
      existingAutoFee._autoFreightAmount = existingAutoFee.amount;
    }
    if (!keepManualCurrency) existingAutoFee.currency = orderForm.currency || existingAutoFee.currency;
    syncCrossBorderFreightDriverRole(existingAutoFee);
    refreshOrderFeeCost(existingAutoFee);
    return;
  }

  const targetIndex = findAutoFreightFeeIndex();
  let targetFee = orderFees.value[targetIndex];
  if (!targetFee || !isFreightFeeRow(targetFee)) {
    targetFee = createBlankFeeRow();
    orderFees.value.splice(0, 0, targetFee);
  }
  if (!targetFee || !isFreightFeeRow(targetFee)) return;

  const templateName = template?.name || "中港运费";
  const templateAmount = Math.max(0, Number(template?.defaultAmount || 0));
  const keepManualUnitPrice = Boolean(targetFee._manualUnitPrice);
  const keepManualAmount = Boolean(targetFee._manualAmount || targetFee._manualFreightAmount);
  const keepManualCurrency = Boolean(targetFee._manualCurrency);
  const nextUnitPrice = keepManualUnitPrice ? targetFee.unitPrice : templateAmount;
  const nextAmount = keepManualAmount
    ? normalizeFeeAmount(targetFee)
    : calculateFeeAmountFromUnitPrice({ ...targetFee, unitPrice: nextUnitPrice });
  const nextCurrency = keepManualCurrency
    ? (targetFee.currency || template?.currency || orderForm.currency)
    : (template?.currency || orderForm.currency);
  Object.assign(targetFee, {
    feeItemId: feeItemRowsByName.value.get(templateName)?.id || "",
    category: template?.category || "正常",
    name: templateName,
    quantity: normalizeFeeQuantity(targetFee),
    unitPrice: nextUnitPrice,
    currency: nextCurrency,
    amount: nextAmount,
    remark: targetFee.remark || "",
    autoFreight: true,
    _autoFreightAmount: nextAmount,
    _manualAmount: keepManualAmount,
    _manualFreightAmount: keepManualAmount,
    _manualCurrency: keepManualCurrency
  });
  syncCrossBorderFreightDriverRole(targetFee);
  refreshOrderFeeCost(targetFee);
}

async function ensureReferenceDataLoaded() {
  if (customerRows.value.length && feeItemRows.value.length && freightRateRows.value.length) return;
  await loadDatabaseData({ preserveSelection: true });
}

function scheduleAutoFreightSync() {
  if (!orderModalOpen.value) return;
  nextTick(() => {
    syncAutoFreightFee();
    syncOrderFeeCosts();
  });
  window.setTimeout(() => {
    if (orderModalOpen.value) {
      syncAutoFreightFee();
      syncOrderFeeCosts();
    }
  }, 80);
}

function splitWorkspaceStyle(scope) {
  const value = scope === "vehicle" ? vehicleSplitPercent.value : customerSplitPercent.value;
  return { "--top-pane-height": `${value}%` };
}

function startSplitResize(scope, event) {
  const container = event.currentTarget?.closest?.(".split-workspace");
  if (!container) return;
  const rect = container.getBoundingClientRect();
  const storageKey = scope === "vehicle" ? "hanye_vehicle_split_percent" : "hanye_customer_split_percent";
  const assign = (percent) => {
    const nextValue = Math.min(78, Math.max(24, percent));
    if (scope === "vehicle") vehicleSplitPercent.value = nextValue;
    else customerSplitPercent.value = nextValue;
    localStorage.setItem(storageKey, String(Math.round(nextValue)));
  };
  const clientYFromEvent = (moveEvent) => moveEvent.touches?.[0]?.clientY ?? moveEvent.clientY;
  const onMove = (moveEvent) => {
    moveEvent.preventDefault?.();
    assign(((clientYFromEvent(moveEvent) - rect.top) / rect.height) * 100);
  };
  const stop = () => {
    window.removeEventListener("mousemove", onMove);
    window.removeEventListener("mouseup", stop);
    window.removeEventListener("touchmove", onMove);
    window.removeEventListener("touchend", stop);
  };
  window.addEventListener("mousemove", onMove);
  window.addEventListener("mouseup", stop);
  window.addEventListener("touchmove", onMove, { passive: false });
  window.addEventListener("touchend", stop);
}

const selectedFeeItem = computed(() =>
  feeItemRowsById.value.get(String(selectedFeeItemId.value || "").trim()) || null
);

function feeItemSortValue(item, index = 0) {
  const sortOrder = Number(item?.sortOrder ?? item?.sort_order);
  return Number.isFinite(sortOrder) && sortOrder > 0 ? sortOrder : 100000 + index;
}

function feeItemSortGroup(item = {}) {
  if (isCompanyCoveredFeeItem(item)) return 3;
  if (String(item.category || "").trim() === "代垫") return 2;
  return 1;
}

function sortFeeItems(items) {
  return [...(items || [])].sort((a, b) =>
    feeItemSortGroup(a) - feeItemSortGroup(b)
    || feeItemSortValue(a) - feeItemSortValue(b)
    || String(a.name || "").localeCompare(String(b.name || ""), "zh-Hans-CN")
    || Number(a.id || 0) - Number(b.id || 0)
  );
}

function normalizeFeeItemCostSources(value = ["供应商"]) {
  let parsedValue = value;
  if (typeof parsedValue === "string" && parsedValue.trim().startsWith("[")) {
    try {
      parsedValue = JSON.parse(parsedValue);
    } catch {
      parsedValue = value;
    }
  }
  const rawValues = Array.isArray(parsedValue)
    ? parsedValue
    : String(parsedValue || "供应商")
      .replace(/，/g, ",")
      .replace(/、/g, ",")
      .split(",");
  const sources = rawValues
    .map((source) => {
      const text = String(source || "").trim();
      if (text === "司机") return "香港司机";
      if (text === "其他平台") return "大陆骑师";
      return text;
    })
    .filter((source, index, list) => FEE_ITEM_COST_SOURCE_OPTIONS.includes(source) && list.indexOf(source) === index);
  return sources.length ? sources : ["供应商"];
}

function feeItemCategoryLabel(value = "正常") {
  return String(value || "").trim() === "代垫" ? "代垫" : "正常";
}

function feeItemCategoryClass(value = "正常") {
  return feeItemCategoryLabel(value) === "代垫" ? "advance" : "normal";
}

function feeItemCostSourceTokens(item = {}) {
  return normalizeFeeItemCostSources(item.costSources || item.costSource || item.cost_source);
}

function feeItemCostSourceClass(source = "") {
  const text = String(source || "").trim();
  if (text === COMPANY_SELF_PAY_CATEGORY) return "self-pay";
  if (text === OTHER_EXPENSE_COST_SOURCE) return "other-expense";
  return "";
}

function feeItemHasCompanySelfPayCostSource(item = {}) {
  return feeItemCostSourceTokens(item).includes(COMPANY_SELF_PAY_CATEGORY);
}

function feeItemHasOtherExpenseCostSource(item = {}) {
  return feeItemCostSourceTokens(item).includes(OTHER_EXPENSE_COST_SOURCE);
}

function feeItemCostSourceSelectClass(item = {}) {
  return {
    "has-self-pay": feeItemHasCompanySelfPayCostSource(item),
    "has-other-expense": feeItemHasOtherExpenseCostSource(item)
  };
}

function ensureFeeItemCostSources(target) {
  target.costSources = normalizeFeeItemCostSources(target.costSources);
}

function handleFeeItemCategoryChange(target = {}) {
  target.category = feeItemCategoryLabel(target.category);
  ensureFeeItemCostSources(target);
}

function feeItemCostSourceText(item = {}) {
  return normalizeFeeItemCostSources(item.costSources || item.costSource || item.cost_source).join("、");
}

const sortedFeeItemRows = computed(() => sortFeeItems(feeItemRows.value));
const orderFeeNameOptions = computed(() => {
  const keyword = String(orderFeeNameSearchKeyword.value || "").trim().toLowerCase();
  if (!keyword) return sortedFeeItemRows.value;
  return sortedFeeItemRows.value.filter((item) => [
    item.name,
    feeItemCategoryLabel(item.category),
    feeItemCostSourceText(item),
    currencyCodeDisplay(item.currency)
  ].some((value) => String(value || "").toLowerCase().includes(keyword)));
});
const feeItemSearchActive = computed(() => Boolean(feeItemSearchKeyword.value.trim()));
const visibleFeeItemRows = computed(() => {
  const keyword = feeItemSearchKeyword.value.trim().toLowerCase();
  if (!keyword) return sortedFeeItemRows.value;
  return sortedFeeItemRows.value.filter((item) =>
    String(item.name || "").toLowerCase().includes(keyword)
  );
});
const advanceFeeItemRows = computed(() =>
  sortedFeeItemRows.value.filter((item) => item.category === "代垫")
);

function feeItemIncludesCostSource(item = {}, source = "") {
  const normalizedSource = normalizeFeeItemCostSources([source])[0] || source;
  return normalizeFeeItemCostSources(item.costSources || item.costSource || item.cost_source).includes(normalizedSource);
}

function costCenterFeeItemsForSource(source = activeCostCenterSource.value) {
  const normalizedSource = normalizeCostCenterSourceLabel(source);
  return sortedFeeItemRows.value.filter((item) =>
    String(item.category || "").trim() !== "代垫"
    && (isCompanyCoveredFeeItem(item)
      ? feeItemCompanyCoveredCostSources(item).includes(normalizedSource)
      : feeItemIncludesCostSource(item, normalizedSource))
  );
}

const activeCostCenterFeeItems = computed(() => costCenterFeeItemsForSource(activeCostCenterSource.value));
const costCenterRuleFeeItems = computed(() => costCenterFeeItemsForSource(costCenterRuleForm.source));

function costCenterFeeItemLabel(item = {}) {
  return item.name || "收费项目";
}

function driverCostStorageFieldForFeeItem(item = {}) {
  const name = String(item.name || "").trim();
  if (!name) return "";
  if (item.category !== "代垫" && /基础|运费|趟费/.test(name)) {
    return item.currency === "人民币" ? "baseRMB" : "baseHKD";
  }
  if (item.category !== "代垫") return driverExtraFieldForFeeName(name);
  return "";
}

function driverCostRateValue(rule = {}, item = {}) {
  const field = driverCostStorageFieldForFeeItem(item);
  if (field) return Number(rule?.[field] || 0);
  return advanceFeeRateValue(rule?.advanceFeeRates, item);
}

function setDriverCostRate(target = {}, item = {}, value = 0) {
  const field = driverCostStorageFieldForFeeItem(item);
  if (field) {
    target[field] = Number(value || 0);
    return;
  }
  target.advanceFeeRates ||= {};
  setAdvanceFeeRate(target.advanceFeeRates, item, value);
}

function parseCostCenterValues(value = {}) {
  if (typeof value === "string") {
    try {
      return JSON.parse(value || "{}") || {};
    } catch {
      return {};
    }
  }
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}

function normalizeCostCenterCurrency(value = "", fallback = "港币") {
  return currencyCodeDisplay(value || fallback) === "RMB" ? "人民币" : "港币";
}

function normalizeCostCenterValue(value = 0, fallbackCurrency = "港币") {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const amount = Number(value.amount ?? value.value ?? value.cost ?? 0);
    return {
      amount: Number.isFinite(amount) && amount >= 0 ? amount : 0,
      currency: normalizeCostCenterCurrency(value.currency, fallbackCurrency)
    };
  }
  const amount = Number(value || 0);
  return {
    amount: Number.isFinite(amount) && amount >= 0 ? amount : 0,
    currency: normalizeCostCenterCurrency("", fallbackCurrency)
  };
}

function normalizeCostCenterValues(value = {}, fallbackCurrency = "港币") {
  return Object.fromEntries(
    Object.entries(parseCostCenterValues(value))
      .map(([key, amount]) => [String(key), normalizeCostCenterValue(amount, fallbackCurrency)])
      .filter(([key]) => key)
  );
}

function normalizeCostCenterTonnage(value = "") {
  return String(value || "").trim();
}

function costCenterValueForItem(values = {}, item = {}) {
  const rawValues = parseCostCenterValues(values);
  return normalizeCostCenterValue(
    rawValues[costCenterFeeValueKey(item)],
    item.currency || "港币"
  );
}

function costCenterFeeValueKey(item = {}) {
  return String(item.id || item.name || "");
}

function costCenterTonnageSortIndex(value = "") {
  const tonnage = normalizeCostCenterTonnage(value);
  if (!tonnage) return TONNAGE_OPTIONS.length + 1;
  const index = TONNAGE_OPTIONS.indexOf(tonnage);
  return index >= 0 ? index : TONNAGE_OPTIONS.length + 2;
}

const costCenterRouteGroups = computed(() =>
  freightRateGroups.value.filter((group) => group.level1)
);

const costCenterRouteLevel1Options = computed(() =>
  uniqueSorted(costCenterRouteGroups.value.map((group) => group.level1))
);

function splitCostCenterRouteValue(value = "") {
  const [level1 = ""] = String(value || "")
    .split(/[\/／]/)
    .map((item) => normalizeFreightLabel(item))
    .filter(Boolean);
  return { level1, level2: "" };
}

function costCenterRouteValue(kind = "origin") {
  const level1 = kind === "destination"
    ? costCenterRuleForm.destinationLevel1
    : costCenterRuleForm.originLevel1;
  return formatFreightLocationOption([level1]);
}

function syncCostCenterRouteValue(kind = "origin") {
  const value = costCenterRouteValue(kind);
  if (kind === "destination") {
    costCenterRuleForm.destination = value;
  } else {
    costCenterRuleForm.origin = value;
  }
}

function handleCostCenterRouteLevel1Change(kind = "origin") {
  if (kind === "destination") {
    costCenterRuleForm.destinationLevel2 = "";
  } else {
    costCenterRuleForm.originLevel2 = "";
  }
  syncCostCenterRouteValue(kind);
}

function closeCostCenterRoutePicker() {
  costCenterRoutePicker.open = false;
  costCenterRoutePicker.kind = "";
}

function isCostCenterRoutePickerOpen(kind = "origin") {
  return costCenterRoutePicker.open && costCenterRoutePicker.kind === kind;
}

function toggleCostCenterRoutePicker(kind = "origin") {
  if (isCostCenterRoutePickerOpen(kind)) {
    closeCostCenterRoutePicker();
    return;
  }
  costCenterRoutePicker.open = true;
  costCenterRoutePicker.kind = kind;
}

function costCenterRouteLevel1Value(kind = "origin") {
  return kind === "destination" ? costCenterRuleForm.destinationLevel1 : costCenterRuleForm.originLevel1;
}

function setCostCenterRouteSelection(kind = "origin", level1 = "") {
  if (kind === "destination") {
    costCenterRuleForm.destinationLevel1 = level1;
    costCenterRuleForm.destinationLevel2 = "";
  } else {
    costCenterRuleForm.originLevel1 = level1;
    costCenterRuleForm.originLevel2 = "";
  }
  syncCostCenterRouteValue(kind);
}

function selectCostCenterRouteLevel1(kind = "origin", level1 = "") {
  setCostCenterRouteSelection(kind, level1);
  closeCostCenterRoutePicker();
}

function hasCostCenterRuleRoute(row = {}) {
  return Boolean(String(row.origin || "").trim() || String(row.destination || "").trim());
}

function costCenterRuleVersionKey(row = {}) {
  return [
    normalizeCostCenterSourceLabel(row.source),
    String(row.entityName || row.entity_name || "").trim(),
    normalizeFreightLabel(row.origin || ""),
    normalizeFreightLabel(row.destination || ""),
    normalizeCostCenterTonnage(row.tonnage || "")
  ].join("||");
}

function costCenterRuleSupplierName(row = {}) {
  return String(row.entityName || row.entity_name || "").trim();
}

function costCenterRuleMatchesActiveSupplier(row = {}) {
  if (activeCostCenterSource.value !== "供应商") return true;
  const supplierName = String(activeCostCenterSupplierName.value || "").trim();
  return supplierName ? costCenterRuleSupplierName(row) === supplierName : true;
}

const activeCostCenterRuleRows = computed(() =>
  latestPriceVersionRows(
    costCenterRateRows.value
      .filter((item) =>
        normalizeCostCenterSourceLabel(item.source) === activeCostCenterSource.value
        && hasCostCenterRuleRoute(item)
        && costCenterRuleMatchesActiveSupplier(item)
      ),
    costCenterRuleVersionKey
  )
    .sort((a, b) =>
      String(a.origin || "").localeCompare(String(b.origin || ""), "zh-Hans-CN")
      || String(a.destination || "").localeCompare(String(b.destination || ""), "zh-Hans-CN")
      || costCenterTonnageSortIndex(a.tonnage) - costCenterTonnageSortIndex(b.tonnage)
      || comparePriceRuleVersionDesc(a, b)
      || Number(a.id || 0) - Number(b.id || 0)
    )
);

const costCenterRuleNeedsTonnage = computed(() => normalizeCostCenterSourceLabel(costCenterRuleForm.source) === "供应商");
const costCenterRuleTableHasTonnage = computed(() => activeCostCenterSource.value === "供应商");
const costCenterRuleTableColspan = computed(() =>
