}, { immediate: true });

const costCenterDriverOptions = computed(() =>
  driverRows.value
    .filter((item) => item.name)
    .sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), "zh-Hans-CN"))
);

const costCenterHongKongDriverOptions = computed(() =>
  costCenterDriverOptions.value.filter((item) => (item.type || "香港司机") === "香港司机")
);

const costCenterMainlandRiderOptions = computed(() =>
  costCenterDriverOptions.value.filter((item) => item.type === "大陆骑师")
);

function normalizeCostCenterSourceLabel(source = "") {
  const text = String(source || "").trim();
  if (text === "司机") return "香港司机";
  if (text === "其他平台") return "大陆骑师";
  return text;
}

function costCenterEntityLabelForSource(source = activeCostCenterSource.value) {
  const normalizedSource = normalizeCostCenterSourceLabel(source);
  if (normalizedSource === "供应商") return "供应商";
  if (normalizedSource === "香港司机") return "香港司机";
  if (normalizedSource === "大陆骑师") return "大陆骑师";
  if (normalizedSource === "公司自费") return "费用名称";
  if (normalizedSource === OTHER_EXPENSE_COST_SOURCE) return "支出名称";
  return "成本对象";
}

const activeCostCenterEntityLabel = computed(() => costCenterEntityLabelForSource(activeCostCenterSource.value));
const costCenterRuleEntityLabel = computed(() => costCenterEntityLabelForSource(costCenterRuleForm.source));

function costCenterEntityOptionsForSource(source = costCenterRuleForm.source) {
  const normalizedSource = normalizeCostCenterSourceLabel(source);
  if (normalizedSource === "供应商") return costCenterSupplierCardOptions.value;
  if (normalizedSource === "香港司机") return costCenterHongKongDriverOptions.value;
  if (normalizedSource === "大陆骑师") return costCenterMainlandRiderOptions.value;
  return [];
}

function costCenterSourceRequiresEntitySelection(source = costCenterRuleForm.source) {
  return ["供应商", "香港司机", "大陆骑师"].includes(normalizeCostCenterSourceLabel(source));
}

function costCenterEntityOptionId(item = {}) {
  return String(item.id ?? item.no ?? item.name ?? "").trim();
}

function costCenterEntityOptionName(item = {}) {
  return String(item.name || item.displayName || "").trim();
}

function findCostCenterEntityRefId(source = "", entityName = "") {
  const name = String(entityName || "").trim();
  if (!name) return "";
  const option = costCenterEntityOptionsForSource(source)
    .find((item) => costCenterEntityOptionName(item) === name);
  return option ? costCenterEntityOptionId(option) : "";
}

function syncCostCenterRuleEntityName() {
  const source = normalizeCostCenterSourceLabel(costCenterRuleForm.source);
  if (!costCenterSourceRequiresEntitySelection(source)) return;
  const option = costCenterEntityOptionsForSource(source)
    .find((item) => costCenterEntityOptionId(item) === String(costCenterRuleForm.entityRefId || ""));
  costCenterRuleForm.entityName = option ? costCenterEntityOptionName(option) : "";
}

function costCenterRuleEntityDisplay(row = {}) {
  const name = String(row.entityName || "").trim();
  const routeName = [row.origin, row.destination].filter(Boolean).join(" - ");
  if (!name || name === row.source || name === routeName) return "-";
  return name;
}

function costCenterRuleTonnageDisplay(row = {}) {
  return normalizeCostCenterTonnage(row.tonnage) || "全部";
}

function setActiveCostCenterSource(source) {
  const normalizedSource = normalizeCostCenterSourceLabel(source);
  if (!FEE_ITEM_COST_SOURCE_OPTIONS.includes(normalizedSource)) return;
  activeCostCenterSource.value = normalizedSource;
  if (normalizedSource === "供应商") ensureActiveCostCenterSupplier();
}

function costCenterRuleEntityName(rule = costCenterRuleForm) {
  return String(rule.entityName || "").trim()
    || [rule.origin, rule.destination].map((item) => String(item || "").trim()).filter(Boolean).join(" - ")
    || rule.source
    || activeCostCenterSource.value;
}

function createCostCenterRuleValues(source = activeCostCenterSource.value, savedValues = {}) {
  const rawValues = parseCostCenterValues(savedValues);
  const values = {};
  Object.entries(rawValues).forEach(([key, value]) => {
    values[String(key)] = normalizeCostCenterValue(value);
  });
  costCenterFeeItemsForSource(source).forEach((item) => {
    const key = costCenterFeeValueKey(item);
    values[key] = normalizeCostCenterValue(rawValues[key], item.currency || "港币");
  });
  return values;
}

function resetCostCenterRuleForm(item = null) {
  const source = normalizeCostCenterSourceLabel(item?.source || activeCostCenterSource.value);
  const costValues = createCostCenterRuleValues(source, normalizeCostCenterValues(item?.costValues));
  const originParts = splitCostCenterRouteValue(item?.origin || "");
  const destinationParts = splitCostCenterRouteValue(item?.destination || "");
  const defaultEntityName = item?.entityName || (source === "供应商" ? activeCostCenterSupplierName.value : "");
  Object.assign(costCenterRuleForm, {
    id: item?.id || null,
    source,
    entityId: item?.entityId || "",
    entityRefId: findCostCenterEntityRefId(source, defaultEntityName),
    entityName: defaultEntityName,
    origin: item?.origin || "",
    originLevel1: originParts.level1,
    originLevel2: originParts.level2,
    destination: item?.destination || "",
    destinationLevel1: destinationParts.level1,
    destinationLevel2: destinationParts.level2,
    tonnage: normalizeCostCenterTonnage(item?.tonnage || ""),
    costValues,
    effectiveDate: todayInputValue(),
    note: item?.note || ""
  });
}

function openCostCenterRuleModal(item = null) {
  if (!item && normalizeCostCenterSourceLabel(activeCostCenterSource.value) === "供应商") {
    ensureActiveCostCenterSupplier();
  }
  resetCostCenterRuleForm(item);
  closeCostCenterRoutePicker();
  costCenterRuleModalOpen.value = true;
}

function closeCostCenterRuleModal() {
  if (costCenterRuleSaving.value) return;
  closeCostCenterRoutePicker();
  costCenterRuleModalOpen.value = false;
}

function costCenterRuleValue(item = {}) {
  return Number(costCenterValueForItem(costCenterRuleForm.costValues, item).amount || 0);
}

function setCostCenterRuleValue(item = {}, value = 0) {
  const current = costCenterValueForItem(costCenterRuleForm.costValues, item);
  const amount = Number(value);
  costCenterRuleForm.costValues[costCenterFeeValueKey(item)] = {
    amount: Number.isFinite(amount) && amount >= 0 ? amount : 0,
    currency: current.currency
  };
}

function costCenterRuleCurrency(item = {}) {
  return costCenterValueForItem(costCenterRuleForm.costValues, item).currency;
}

function setCostCenterRuleCurrency(item = {}, value = "") {
  const current = costCenterValueForItem(costCenterRuleForm.costValues, item);
  costCenterRuleForm.costValues[costCenterFeeValueKey(item)] = {
    amount: current.amount,
    currency: normalizeCostCenterCurrency(value, item.currency || "港币")
  };
}

function costCenterRuleRowValue(row = {}, item = {}) {
  return Number(costCenterValueForItem(row.costValues, item).amount || 0);
}

function costCenterRuleRowValueDisplay(row = {}, item = {}) {
  const value = costCenterValueForItem(row.costValues, item);
  return `${currencyCodeDisplay(value.currency)} ${money(value.amount)}`;
}

function costCenterRouteMatchScore(ruleRoute = "", orderRoute = "") {
  const ruleValue = supplierCostRuleAreaValue(ruleRoute);
  if (!ruleValue) return 0;
  if (!supplierCostRuleAreaMatches(ruleRoute, orderRoute)) return -1;
  return ruleValue.split("/").filter(Boolean).length * 100 + ruleValue.length;
}

function uniqueOrderCostNames(values = []) {
  return Array.from(new Set(values.map((value) => String(value || "").trim()).filter(Boolean)));
}

function orderCostDriverNamesForFee(order = orderForm, fee = {}) {
  if (fee.driverName) return uniqueOrderCostNames([fee.driverName]);
  const item = feeItemForFee(fee) || {};
  const role = String(fee.driverRole || item.defaultDriverRole || "").trim();
  const mode = normalizeTransportMode(order.transportMode || "单司机") || "单司机";
  const driver = String(order.driver || "").trim();
  const hkDriver = String(order.hkDriver || driver || "").trim();
  const mainlandDriver = String(order.mainlandDriver || "").trim();
  if (role === "手动指定") return [];
  if (role === "香港司机") return uniqueOrderCostNames([hkDriver, driver]);
  if (role === "大陆骑师") return mode === "双司机" ? uniqueOrderCostNames([mainlandDriver]) : [];
  if (role === "跟随订单司机") {
    return mode === "双司机"
      ? uniqueOrderCostNames([driver, hkDriver, mainlandDriver, ...driver.split("/")])
      : uniqueOrderCostNames([driver, hkDriver, ...driver.split("/")]);
  }
  if (mode === "双司机") return uniqueOrderCostNames([hkDriver, mainlandDriver]);
  if (isDomesticTransferMode(mode)) return uniqueOrderCostNames([hkDriver, driver]);
  return uniqueOrderCostNames([driver, hkDriver, ...driver.split("/")]);
}

function orderCostEntityNamesForSource(source = "", order = orderForm, fee = {}) {
  const item = feeItemForFee(fee) || {};
  const normalizedSource = normalizeCostCenterSourceLabel(source);
  if (normalizedSource === "供应商") return uniqueOrderCostNames([order.supplier]);
  if (normalizedSource === "香港司机") return uniqueOrderCostNames([order.hkDriver || order.driver, order.driver]);
  if (normalizedSource === "大陆骑师") {
    if (normalizeVehicleSource(order?.vehicleSource) !== OWN_VEHICLE_SOURCE || !orderIsDoubleDriverMode(order)) return [];
    return uniqueOrderCostNames([order.mainlandDriver]);
  }
  if (normalizedSource === "公司自费") return uniqueOrderCostNames([fee.name, item.name, "公司自费"]);
  if (normalizedSource === OTHER_EXPENSE_COST_SOURCE) return uniqueOrderCostNames([fee.name, item.name, OTHER_EXPENSE_COST_SOURCE]);
  return [];
}

function costCenterRuleEntityMatches(rule = {}, entityNames = []) {
  const ruleName = String(rule.entityName || "").trim();
  return Boolean(ruleName && entityNames.includes(ruleName));
}

function costCenterCandidateLabel(candidate = {}) {
  const costText = candidate.quantity > 1
    ? `${currencyCodeDisplay(candidate.sourceCurrency)} ${money(candidate.unitCost)} x ${money(candidate.quantity)}`
    : `${currencyCodeDisplay(candidate.sourceCurrency)} ${money(candidate.unitCost)}`;
  return [
    candidate.source,
    candidate.rule?.entityName,
    [candidate.rule?.origin, candidate.rule?.destination].filter(Boolean).join(" - "),
    candidate.rule?.tonnage ? candidate.rule.tonnage : (candidate.source === "供应商" ? "全部吨位" : ""),
    candidate.rule ? `修改日期 ${priceEffectiveDateDisplay(candidate.rule)}` : "",
    costText
  ].filter(Boolean).join(" / ");
}

function costCenterCandidatesForFeeSource(fee = {}, order = orderForm, item = {}, source = "", sourceIndex = 0) {
  const normalizedSource = normalizeCostCenterSourceLabel(source);
  const entityNames = orderCostEntityNamesForSource(normalizedSource, order, fee);
  if (!entityNames.length) return [];
  const orderTonnage = normalizeCostCenterTonnage(order.tonnage);
  return costCenterRateRows.value
    .filter((rule) => normalizeCostCenterSourceLabel(rule.source) === normalizedSource)
    .filter((rule) => priceRuleAppliesToOrderDate(rule, order))
    .flatMap((rule) => {
      if (!costCenterRuleEntityMatches(rule, entityNames)) return [];
      const originScore = costCenterRouteMatchScore(rule.origin, order.loading);
      const destinationScore = costCenterRouteMatchScore(rule.destination, order.unloading);
      if (originScore < 0 || destinationScore < 0) return [];
      const ruleTonnage = normalizeCostCenterTonnage(rule.tonnage);
      const tonnageScore = normalizedSource === "供应商"
        ? (ruleTonnage ? (ruleTonnage === orderTonnage ? 2 : -1) : 1)
        : 0;
      if (tonnageScore < 0) return [];
      const costValue = costCenterValueForItem(rule.costValues, item);
      const unitCost = Number(costValue.amount || 0);
      const quantity = feeCostQuantity(fee);
      const sourceAmount = Number((unitCost * quantity).toFixed(2));
      return [{
        rule,
        source: normalizedSource,
        sourceIndex,
        routeScore: originScore + destinationScore,
        tonnageScore,
        unitCost,
        quantity,
        sourceCurrency: costValue.currency,
        sourceAmount,
        currency: costValue.currency,
        amount: sourceAmount
      }];
    });
}

function sortCostCenterCandidates(candidates = []) {
  return [...candidates].sort((left, right) =>
    left.sourceIndex - right.sourceIndex
    || right.tonnageScore - left.tonnageScore
    || right.routeScore - left.routeScore
    || Number(right.unitCost > 0) - Number(left.unitCost > 0)
    || priceEffectiveDate(right.rule).localeCompare(priceEffectiveDate(left.rule))
    || Number(left.rule?.id || 0) - Number(right.rule?.id || 0)
  );
}

function matchedOrderFeeCostForSource(fee = {}, order = orderForm, item = {}, source = "", sourceIndex = 0) {
  const normalizedSource = normalizeCostCenterSourceLabel(source);
  const matched = sortCostCenterCandidates(
    costCenterCandidatesForFeeSource(fee, order, item, normalizedSource, sourceIndex)
  )[0];
  const fallbackCurrency = normalizeCostCenterCurrency(fee.currency || order.currency || item?.currency || "港币");
  if (!matched) {
    return {
      amount: 0,
      matched: false,
      label: `${normalizedSource || "成本"}未匹配到成本`,
      currency: fallbackCurrency,
      sourceCurrency: fallbackCurrency,
      sourceAmount: 0,
      source: normalizedSource
    };
  }
  return {
    amount: Number(matched.amount || 0),
    matched: true,
    label: costCenterCandidateLabel(matched),
    currency: matched.currency,
    sourceCurrency: matched.sourceCurrency,
    sourceAmount: matched.sourceAmount,
    source: normalizedSource,
    rule: matched.rule,
    unitCost: matched.unitCost,
    quantity: matched.quantity
  };
}

function costAmountDisplay(amount = 0, currency = "港币") {
  return `${currencyCodeDisplay(currency)} ${money(amount)}`;
}

function combineCostPartsByCurrency(parts = []) {
  const totals = new Map();
  parts
    .filter((part) => part.matched)
    .forEach((part) => {
      const currency = normalizeCostCenterCurrency(part.sourceCurrency || part.currency || "港币");
      totals.set(currency, Number((Number(totals.get(currency) || 0) + Number(part.sourceAmount ?? part.amount ?? 0)).toFixed(2)));
    });
  return Array.from(totals.entries()).map(([currency, amount]) => ({ currency, amount }));
}

function matchedCrossBorderFreightDriverCost(fee = {}, order = orderForm, item = {}) {
  if (!isCrossBorderFreightFee(fee) || order.vehicleSource === "外派车辆") return null;
  const roles = crossBorderFreightDriverRoles(order, fee);
  if (!roles.length) return null;
  const parts = roles.map((role, index) => ({
    role,
    driverName: orderDriverNameByRole(order, role),
    ...matchedOrderFeeCostForSource(fee, order, item, role, index)
  }));
  const totals = combineCostPartsByCurrency(parts);
  const missingParts = parts.filter((part) => !part.matched);
  const matchedParts = parts.filter((part) => part.matched);
  const breakdownText = totals.length
    ? totals.map((part) => costAmountDisplay(part.amount, part.currency)).join(" + ")
    : "";
  const roleLabels = parts.map((part) => {
    if (!part.matched) return `${part.role}${part.driverName ? ` ${part.driverName}` : ""}未匹配`;
    return `${part.role}${part.driverName ? ` ${part.driverName}` : ""} ${costAmountDisplay(part.sourceAmount ?? part.amount, part.sourceCurrency || part.currency)}`;
  });
  const isMultiCurrency = totals.length > 1;
  const sameCurrencyTotal = totals.length === 1 ? totals[0] : null;
  const fallbackCurrency = normalizeCostCenterCurrency(fee.currency || order.currency || item?.currency || "港币");
  return {
    amount: sameCurrencyTotal ? sameCurrencyTotal.amount : 0,
    matched: matchedParts.length > 0 && missingParts.length === 0,
    label: roleLabels.join("；") || "未匹配到成本",
    currency: sameCurrencyTotal?.currency || fallbackCurrency,
    sourceCurrency: sameCurrencyTotal?.currency || fallbackCurrency,
    sourceAmount: sameCurrencyTotal ? sameCurrencyTotal.amount : 0,
    multiCurrency: isMultiCurrency,
    breakdownText,
    skipSavedCostFallback: true
  };
}

function matchedOrderFeeCost(fee = {}, order = orderForm) {
  const item = feeItemForFee(fee);
  const fallbackCurrency = normalizeCostCenterCurrency(fee.currency || order.currency || item?.currency || "港币");
  if (feeCategoryLabel(fee) === "代垫") {
    const amount = Number(fee.amount || 0);
    const cost = Number.isFinite(amount) && amount >= 0 ? Number(amount.toFixed(2)) : 0;
    const currency = normalizeCostCenterCurrency(fee.currency || fee.costCurrency || fee._costCurrency || order.currency || "港币");
    return {
      amount: cost,
      matched: true,
      label: "代垫成本跟随金额",
      currency,
      sourceCurrency: currency,
      sourceAmount: cost,
      skipSavedCostFallback: true
    };
  }
  if (!item) {
    return {
      amount: 0,
      matched: false,
      label: "未选择收费项目",
      currency: fallbackCurrency,
      sourceCurrency: fallbackCurrency,
      sourceAmount: 0
    };
  }
  const crossBorderCost = matchedCrossBorderFreightDriverCost(fee, order, item);
  if (crossBorderCost) return crossBorderCost;
  const companyCoveredSources = feeItemCompanyCoveredCostSources(item);
  const sources = companyCoveredSources.length
    ? companyCoveredSources
    : normalizeFeeItemCostSources(item.costSources || item.costSource || item.cost_source);
  const candidates = sources.flatMap((source, sourceIndex) =>
    costCenterCandidatesForFeeSource(fee, order, item, source, sourceIndex)
  );
  const matched = sortCostCenterCandidates(candidates)[0];
  if (!matched) {
    return {
      amount: 0,
      matched: false,
      label: "未匹配到成本",
      currency: fallbackCurrency,
      sourceCurrency: fallbackCurrency,
      sourceAmount: 0
    };
  }
  return {
    amount: Number(matched.amount || 0),
    matched: true,
    label: costCenterCandidateLabel(matched),
    currency: matched.currency,
    sourceCurrency: matched.sourceCurrency,
    sourceAmount: matched.sourceAmount
  };
}

function assignOrderFeeCostSnapshot(fee, matched) {
  const cost = Number(matched.amount || 0);
  const matchedFlag = Boolean(matched.matched);
  const sourceText = String(matched.label || "");
  if (Number(fee.cost || 0) !== cost) fee.cost = cost;
  if (fee._costMatched !== matchedFlag) fee._costMatched = matchedFlag;
  if (fee._costSourceText !== sourceText) fee._costSourceText = sourceText;
  const currency = normalizeCostCenterCurrency(matched.currency || fee.costCurrency || fee._costCurrency || fee.currency || orderForm.currency || "港币");
  fee.costCurrency = currency;
  fee._costCurrency = currency;
  fee._costSourceCurrency = matched.sourceCurrency || currency;
  fee._costMultiCurrency = Boolean(matched.multiCurrency);
  fee._costBreakdownText = matched.breakdownText || "";
}

function refreshOrderFeeCost(fee, options = {}) {
  if (!fee) return;
  if (options.force) fee._manualCost = false;
  if (!String(fee.name || "").trim()) {
    assignOrderFeeCostSnapshot(fee, { amount: 0, matched: false, label: "" });
    return;
  }
  if (fee._manualCost && !options.force) return;
  const matched = matchedOrderFeeCost(fee);
  if (!matched.matched && !matched.skipSavedCostFallback && fee._savedCost !== undefined && fee._savedCost !== null) {
    assignOrderFeeCostSnapshot(fee, {
      amount: Number(fee._savedCost || 0),
      matched: false,
      label: "已保存成本",
      currency: fee.costCurrency || fee._costCurrency || fee.currency || orderForm.currency || "港币",
      sourceCurrency: fee.costCurrency || fee._costCurrency || fee.currency || orderForm.currency || "港币"
    });
    return;
  }
  assignOrderFeeCostSnapshot(fee, matched);
}

function syncOrderFeeCosts(options = {}) {
  orderFees.value.forEach((fee) => refreshOrderFeeCost(fee, options));
}

function orderFeeCostDependencySignature() {
  const orderSignature = [
    orderModalOpen.value,
    orderForm.date,
    orderForm.transportMode,
    orderForm.tonnage,
    orderForm.driver,
    orderForm.hkDriver,
    orderForm.mainlandDriver,
    orderForm.loading,
    orderForm.unloading,
    orderForm.vehicleSource,
    orderForm.supplier
  ];
  const feeSignature = orderFees.value.map((fee) => [
    fee.feeItemId,
    fee.name,
    fee.quantity,
    fee.currency,
    fee.costCurrency,
    fee.driverRole,
    fee.driverName
  ]);
  const ruleSignature = costCenterRateRows.value.map((rule) => [
    rule.id,
    rule.source,
    rule.entityId,
    rule.entityName,
    rule.origin,
    rule.destination,
    rule.tonnage,
    rule.currency,
    rule.effectiveDate,
    rule.updatedAt,
    Object.entries(normalizeCostCenterValues(rule.costValues))
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, value]) => `${key}:${value.amount}:${value.currency}`)
      .join(",")
  ]);
  const itemSignature = feeItemRows.value.map((item) => [
    item.id,
    item.name,
    item.category,
    item.currency,
    item.defaultDriverRole,
    normalizeFeeItemCostSources(item.costSources || item.costSource || item.cost_source).join(",")
  ]);
  return JSON.stringify([
    orderSignature,
    feeSignature,
    ruleSignature,
    itemSignature
  ]);
}

function scheduleOrderFeeCostSync(options = {}) {
  if (!orderModalOpen.value) return;
  window.clearTimeout(orderFeeCostSyncTimer);
  nextTick(() => syncOrderFeeCosts(options));
  orderFeeCostSyncTimer = window.setTimeout(() => {
    if (orderModalOpen.value) syncOrderFeeCosts(options);
  }, 80);
}

function createCostCenterRuleEntityId() {
  return `cost-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function saveCostCenterRule() {
  if (costCenterSourceRequiresEntitySelection(costCenterRuleForm.source)) {
    syncCostCenterRuleEntityName();
  }
  syncCostCenterRouteValue("origin");
  syncCostCenterRouteValue("destination");
  const origin = String(costCenterRuleForm.origin || "").trim();
  const destination = String(costCenterRuleForm.destination || "").trim();
  const entityName = String(costCenterRuleForm.entityName || "").trim();
  if (costCenterSourceRequiresEntitySelection(costCenterRuleForm.source) && !costCenterRuleForm.entityRefId) {
    notify(`请选择${costCenterRuleEntityLabel.value}`);
    return;
  }
  if (!entityName) {
    notify(`请先填写${costCenterRuleEntityLabel.value}`);
    return;
  }
  if (costCenterRouteLevel1Options.value.length === 0) {
    notify("请先在运费模板报价中维护一级目录");
    return;
  }
  if (!costCenterRuleForm.originLevel1 || !costCenterRuleForm.destinationLevel1) {
    notify("请选择装货地和卸货地的一级目录");
    return;
  }
  if (
    !costCenterRouteLevel1Options.value.includes(costCenterRuleForm.originLevel1)
    || !costCenterRouteLevel1Options.value.includes(costCenterRuleForm.destinationLevel1)
  ) {
    notify("装货地和卸货地需从运费模板报价目录中选择");
    return;
  }
  if (!origin || !destination) {
    notify("请选择装货地和卸货地");
    return;
  }
  if (costCenterRuleNeedsTonnage.value && !normalizeCostCenterTonnage(costCenterRuleForm.tonnage)) {
    notify("请选择吨位");
    return;
  }
  const payload = {
    id: costCenterRuleForm.id || undefined,
    source: normalizeCostCenterSourceLabel(costCenterRuleForm.source || activeCostCenterSource.value),
    entityId: costCenterRuleForm.entityId || createCostCenterRuleEntityId(),
    entityName,
    origin,
    destination,
    tonnage: costCenterRuleNeedsTonnage.value ? normalizeCostCenterTonnage(costCenterRuleForm.tonnage) : "",
    costValues: normalizeCostCenterValues(costCenterRuleForm.costValues),
    effectiveDate: normalizePriceEffectiveDate(costCenterRuleForm.effectiveDate),
    note: costCenterRuleForm.note
  };
  try {
    costCenterRuleSaving.value = true;
    const item = await financeApi.saveCostCenterRate(payload);
    costCenterRateRows.value = costCenterRateRows.value.some((row) => row.id === item.id)
      ? costCenterRateRows.value.map((row) => row.id === item.id ? item : row)
      : [...costCenterRateRows.value, item];
    if (normalizeCostCenterSourceLabel(item.source) === "供应商") {
      setActiveCostCenterSupplier(item.entityName);
    }
    costCenterRuleModalOpen.value = false;
    notify(costCenterRuleForm.id ? "成本规则已更新" : "成本规则已增加");
  } catch (error) {
    notify(error.message);
  } finally {
    costCenterRuleSaving.value = false;
  }
}

async function deleteCostCenterRule(item) {
  if (!item?.id) return;
  if (!window.confirm(`确定删除 ${item.source}/${item.origin || "-"}-${item.destination || "-"} 的成本规则？`)) return;
  try {
    await financeApi.deleteCostCenterRate(item.id);
    costCenterRateRows.value = costCenterRateRows.value.filter((row) => row.id !== item.id);
    notify("成本规则已删除");
  } catch (error) {
    notify(error.message);
  }
}

function advanceFeeRateKey(item = {}) {
  return String(item.id || item.name || "");
}

function advanceFeeRateLabel(item = {}) {
  const currency = currencyCodeDisplay(item.currency || "港币") || "HKD";
  return `${item.name || "代垫项目"} ${currency}`;
}

function advanceFeeRateValue(rates = {}, item = {}) {
  return Number(rates?.[advanceFeeRateKey(item)] || 0);
}

function setAdvanceFeeRate(rates = {}, item = {}, value = 0) {
  rates[advanceFeeRateKey(item)] = Number(value || 0);
}

const selectedFreightRate = computed(() =>
  activeFreightRateRows.value.find((item) => item.id === selectedFreightRateId.value) || activeFreightRateRows.value[0]
);

function freightRateGroupKey(item) {
  const normalized = normalizeFreightRateEntry(item);
  return [
    normalized.customerId || "",
    normalized.direction || "",
    normalized.level1 || normalized.city || "",
    normalized.level2 || ""
  ].join("||");
}

function groupFreightRateRows(rows = []) {
  const groups = new Map();
  rows.forEach((item) => {
    const normalized = normalizeFreightRateEntry(item);
    const { level1, level2 } = normalized;
    const key = freightRateGroupKey(normalized);
    if (!groups.has(key)) {
      groups.set(key, {
        key,
        customerId: normalized.customerId || "",
        customerName: normalized.customerName || "",
        direction: normalized.direction || "",
        level1,
        level2,
        level3: "",
        city: level2 || level1 || normalized.city || "",
        rates: {}
      });
    }
    const group = groups.get(key);
    const current = group.rates[normalized.tonnage];
    if (!current || comparePriceRuleVersionDesc(normalized, current) < 0) {
      group.rates[normalized.tonnage] = normalized;
    }
  });
  return [...groups.values()].sort((a, b) =>
    `${a.customerId}${a.direction}${a.level1}${a.level2}`.localeCompare(`${b.customerId}${b.direction}${b.level1}${b.level2}`, "zh-Hans-CN")
  );
}

const publicFreightRateRows = computed(() => freightRateRows.value.filter(isPublicFreightRate));

const freightCustomerRows = computed(() =>
  customerRows.value
    .filter((item) => item.type === "客户")
    .sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), "zh-Hans-CN"))
);

const selectedFreightCustomer = computed(() =>
  freightCustomerRows.value.find((item) => item.id === selectedFreightCustomerId.value) || null
);

function currentFreightQuoteScope() {
  if (activeFreightQuoteType.value !== CUSTOMER_FREIGHT_QUOTE_TYPE) {
    return { customerId: "", customerName: "" };
  }
  const customer = selectedFreightCustomer.value;
  return {
    customerId: String(customer?.id || selectedFreightCustomerId.value || "").trim(),
    customerName: String(customer?.name || "").trim()
  };
}

function freightRateCountForCustomer(customer) {
  return freightRateRows.value.filter((item) => freightRateBelongsToCustomer(item, customer)).length;
}

const customerFreightRateRows = computed(() =>
  freightRateRows.value.filter((item) => freightRateCustomerId(item) || freightRateCustomerName(item))
);

const activeFreightRateRows = computed(() => {
  if (activeFreightQuoteType.value !== CUSTOMER_FREIGHT_QUOTE_TYPE) return publicFreightRateRows.value;
  const customer = selectedFreightCustomer.value;
  if (!customer) return [];
  return freightRateRows.value.filter((item) => freightRateBelongsToCustomer(item, customer));
});

const freightRateGroups = computed(() => groupFreightRateRows(publicFreightRateRows.value));
const activeFreightRateGroups = computed(() => groupFreightRateRows(activeFreightRateRows.value));
const freightGroupsByKey = computed(() => new Map(activeFreightRateGroups.value.map((group) => [group.key, group])));

const freightDirectoryMeta = computed(() =>
  FREIGHT_DIRECTORY_LEVELS.find((item) => item.value === freightDirectoryLevel.value) || FREIGHT_DIRECTORY_LEVELS[0]
);
const freightFixedEndpointText = computed(() =>
  activeFreightQuoteType.value === CUSTOMER_FREIGHT_QUOTE_TYPE
    ? `${selectedFreightCustomer.value?.name || "客户"}专属报价，未录入时为空`
    : "进出口共用报价，目录维护香港以外的常用片区"
);

const freightDirectionGroups = computed(() =>
  activeFreightRateGroups.value
);

const freightLevel1Options = computed(() => {
  const values = new Set();
  freightDirectionGroups.value.forEach((group) => {
    if (group.level1) values.add(group.level1);
  });
  return [...values].sort((a, b) => a.localeCompare(b, "zh-Hans-CN"));
});

const freightLevel2Options = computed(() => {
  const values = new Set();
  freightDirectionGroups.value.forEach((group) => {
    if (group.level1 === freightParentLevel1.value && group.level2) values.add(group.level2);
  });
  return [...values].sort((a, b) => a.localeCompare(b, "zh-Hans-CN"));
});

function uniqueSorted(values) {
  return [...new Set(values.map(normalizeFreightLabel).filter(Boolean))].sort((a, b) => a.localeCompare(b, "zh-Hans-CN"));
}

function buildFreightDirectoryGroup(level1, level2 = "", level3 = "") {
  const scope = currentFreightQuoteScope();
  const normalizedLevel1 = normalizeFreightLabel(level1);
  const normalizedLevel2 = normalizeFreightLabel(level2);
  const key = freightRateGroupKey({
    customerId: scope.customerId,
    customerName: scope.customerName,
    direction: SHARED_DIRECTION,
    level1: normalizedLevel1,
    level2: normalizedLevel2
  });
  const existing = freightGroupsByKey.value.get(key);
  return existing || {
    key,
    customerId: scope.customerId,
    customerName: scope.customerName,
    direction: SHARED_DIRECTION,
    level1: normalizedLevel1,
    level2: normalizedLevel2,
    level3: "",
    city: normalizedLevel2 || normalizedLevel1,
    rates: {},
    synthetic: true
  };
}

const visibleFreightRateGroups = computed(() => {
  const groups = freightDirectionGroups.value;
  if (freightDirectoryLevel.value === "level1") {
    return uniqueSorted(groups.map((group) => group.level1)).map((level1) => buildFreightDirectoryGroup(level1));
  }
  if (freightDirectoryLevel.value === "level2") {
    if (!freightParentLevel1.value) return [];
    return uniqueSorted(
      groups
        .filter((group) => group.level1 === freightParentLevel1.value)
        .map((group) => group.level2)
    ).map((level2) => buildFreightDirectoryGroup(freightParentLevel1.value, level2));
  }
  return [];
});

const visibleFreightRateDisplayGroups = computed(() => {
  return visibleFreightRateGroups.value.map((group) => {
    return {
      ...group,
      primaryLabel: freightGroupPrimaryLabel(group),
      secondaryLabel: freightGroupSecondaryLabel(group)
    };
  });
});

const visibleFreightStats = computed(() => ({
  groups: visibleFreightRateDisplayGroups.value.length,
  prices: visibleFreightRateDisplayGroups.value.reduce((sum, group) => sum + Object.keys(group.rates || {}).length, 0),
  label: freightDirectoryMeta.value.primary
}));

const freightQuoteTemplateRows = computed(() => [
  {
    key: CUSTOMER_FREIGHT_QUOTE_TYPE,
    title: "客户运费报价模板",
    description: "按客户维护独立报价，初始为空",
    countLabel: `${freightCustomerRows.value.length} 个客户`,
    priceLabel: `${customerFreightRateRows.value.length} 条客户报价`,
    icon: "users"
  },
  {
    key: PUBLIC_FREIGHT_QUOTE_TYPE,
    title: "公共运费报价模板",
    description: "系统默认报价，沿用当前公共数据",
    countLabel: `${freightRateGroups.value.length} 个目录`,
    priceLabel: `${publicFreightRateRows.value.length} 条公共报价`,
    icon: "file"
  }
]);

const activeFreightQuoteTitle = computed(() =>
  activeFreightQuoteType.value === CUSTOMER_FREIGHT_QUOTE_TYPE
    ? `${selectedFreightCustomer.value?.name || "客户"} · 客户运费报价模板`
    : "公共运费报价模板"
);

function freightGroupPrimaryLabel(group) {
  if (freightDirectoryLevel.value === "level1") return group.level1 || "-";
  if (freightDirectoryLevel.value === "level2") return group.level2 || "-";
  return group.level2 || group.level1 || "-";
}

function freightGroupSecondaryLabel(group) {
  if (freightDirectoryLevel.value === "level1") {
    const childCount = uniqueSorted(
      freightDirectionGroups.value
        .filter((item) => item.level1 === group.level1)
        .map((item) => item.level2)
    ).length;
    const priceCount = freightDirectionGroups.value
      .filter((item) => item.level1 === group.level1)
      .reduce((sum, item) => sum + Object.keys(item.rates || {}).length, 0);
    return `${childCount ? `${childCount} 个二级目录` : "暂无二级目录"} · ${priceCount} 条价格`;
  }
  if (freightDirectoryLevel.value === "level2") {
    const priceCount = freightDirectionGroups.value
      .filter((item) => item.level1 === group.level1 && item.level2 === group.level2)
      .reduce((sum, item) => sum + Object.keys(item.rates || {}).length, 0);
    return `${group.level1 || "-"} · ${priceCount} 条价格`;
  }
  return [group.level1, group.level2].filter(Boolean).join(" / ") || "-";
}

function freightGroupModifiedDate(group = {}) {
  const latest = Object.values(group.rates || {})
    .sort(comparePriceRuleVersionDesc)[0];
  return latest ? priceEffectiveDateDisplay(latest) : "-";
}

function freightGroupChildCount(group) {
  if (freightDirectoryLevel.value === "level1") {
    return uniqueSorted(
      freightDirectionGroups.value
        .filter((item) => item.level1 === group.level1)
        .map((item) => item.level2)
    ).length;
  }
  return 0;
}

function canEnterFreightGroup(group) {
  return freightDirectoryLevel.value === "level1" && freightGroupChildCount(group) > 0;
}

function resetFreightDirectoryState() {
  freightDirectionFilter.value = SHARED_DIRECTION;
  freightDirectoryLevel.value = "level1";
  freightParentLevel1.value = "";
  freightParentLevel2.value = "";
  cancelFreightDirectoryCreate();
  cancelFreightGroupRowEdit();
  clearFreightGroupSelection();
  selectedFreightRateId.value = null;
}

function openFreightQuoteRoot() {
  freightPanelTab.value = FREIGHT_QUOTE_TAB;
  freightQuoteView.value = FREIGHT_QUOTE_ROOT_VIEW;
  activeFreightQuoteType.value = PUBLIC_FREIGHT_QUOTE_TYPE;
  selectedFreightCustomerId.value = "";
  resetFreightDirectoryState();
}

function openPublicFreightQuoteTemplate() {
  freightPanelTab.value = FREIGHT_QUOTE_TAB;
  freightQuoteView.value = FREIGHT_QUOTE_MATRIX_VIEW;
  activeFreightQuoteType.value = PUBLIC_FREIGHT_QUOTE_TYPE;
  selectedFreightCustomerId.value = "";
  resetFreightDirectoryState();
  editFreightRate(publicFreightRateRows.value[0] || null, { silent: true });
}

function openCustomerFreightQuoteList() {
  freightPanelTab.value = FREIGHT_QUOTE_TAB;
  freightQuoteView.value = FREIGHT_QUOTE_CUSTOMERS_VIEW;
  activeFreightQuoteType.value = CUSTOMER_FREIGHT_QUOTE_TYPE;
  selectedFreightCustomerId.value = "";
  resetFreightDirectoryState();
}

function openCustomerFreightQuoteTemplate(customer) {
  if (!customer?.id) return;
  freightPanelTab.value = FREIGHT_QUOTE_TAB;
  freightQuoteView.value = FREIGHT_QUOTE_MATRIX_VIEW;
  activeFreightQuoteType.value = CUSTOMER_FREIGHT_QUOTE_TYPE;
  selectedFreightCustomerId.value = customer.id;
  resetFreightDirectoryState();
  editFreightRate(activeFreightRateRows.value[0] || null, { silent: true });
}

function openFreightQuoteTemplate(row) {
  if (row?.key === CUSTOMER_FREIGHT_QUOTE_TYPE) {
    openCustomerFreightQuoteList();
  } else {
    openPublicFreightQuoteTemplate();
  }
}

function setFreightDirectoryLevel(level) {
  const nextLevel = ["level1", "level2"].includes(level) ? level : "level1";
  if (nextLevel === "level2" && !freightParentLevel1.value) {
    freightParentLevel1.value = freightRateForm.level1 || freightLevel1Options.value[0] || "";
  }
  freightDirectoryLevel.value = nextLevel;
  cancelFreightDirectoryCreate();
  clearFreightGroupSelection();
}

function switchFreightDirection(direction) {
  openFreightQuoteRoot();
  Object.assign(freightRateForm, {
    customerId: "",
    customerName: "",
    direction: SHARED_DIRECTION,
    level1: "",
    level2: "",
    city: ""
  });
}

function enterFreightGroup(group) {
  if (!canEnterFreightGroup(group)) {
    editFreightGroup(group, freightRateForm.tonnage || "3T");
    return;
  }
  if (freightDirectoryLevel.value === "level1") {
    freightParentLevel1.value = group.level1 || "";
    freightDirectoryLevel.value = "level2";
    Object.assign(freightRateForm, {
      direction: SHARED_DIRECTION,
      level1: group.level1 || "",
      level2: "",
      city: ""
    });
  }
  clearFreightGroupSelection();
}

function addressOptionKey(value) {
  return normalizeLocationText(value) || String(value || "").trim();
}

function formatFreightLocationOption(levels) {
  return levels.filter(Boolean).join(" / ");
}

const freightAddressOptions = computed(() => {
  const map = new Map();
  freightRateGroups.value.forEach((group) => {
    const levels = [group.level1, group.level2].filter(Boolean);
    levels.forEach((_, index) => {
      const pathLevels = levels.slice(0, index + 1);
      const value = formatFreightLocationOption(pathLevels);
      if (!value) return;
      const key = `freight:${group.direction}:${addressOptionKey(value)}`;
      if (!map.has(key)) {
        map.set(key, {
          key,
          source: "运费模板",
          direction: group.direction || "-",
          level1: pathLevels[0] || "-",
          level2: pathLevels[1] || "-",
          level3: "-",
          rank: pathLevels.length,
          pathLabel: value,
          value
        });
      }
    });
  });
  return [...map.values()];
});

const historicalAddressOptions = computed(() => {
  const map = new Map();
  const hidden = new Set(hiddenAddressHistoryRows.value.map((item) => item.key));
  orderRows.value.forEach((order) => {
    [
      { value: order.loading, kind: "装货地" },
      { value: order.unloading, kind: "卸货地" }
    ].forEach(({ value, kind }) => {
      splitDispatchLocationEntriesText(value).forEach((entry) => {
        const text = String(entry || "").trim();
        if (!text) return;
        const addressKey = addressOptionKey(text);
        if (hidden.has(addressKey)) return;
        const key = `history:${addressKey}`;
        if (!map.has(key)) {
          map.set(key, {
            key,
            source: "历史地址",
            direction: kind,
            level1: "-",
            level2: "-",
            level3: "-",
            rank: 0,
            pathLabel: text,
            value: text
          });
        }
      });
    });
  });
  return [...map.values()].slice(0, 100);
});

const savedAddressBookOptions = computed(() =>
  addressBookRows.value.map((item) => ({
    key: `book:${item.id}`,
    id: item.id,
    source: "地址本",
    direction: "-",
    level1: "-",
    level2: "-",
    level3: "-",
    rank: 0,
    area: item.area || "",
    contact: item.contact || "",
    phone: item.phone || "",
    note: item.note || "",
    pathLabel: item.address,
    value: [item.area, item.address].filter(Boolean).join(" / "),
    address: item.address || ""
  }))
);

function currentAddressBookCustomerId() {
  if (locationPicker.owner === "dispatch") {
    const matchedCustomer = (dispatchForm.customerId ? customerRowsById.value.get(String(dispatchForm.customerId || "").trim()) : null)
      || findPartnerByTypedLabel(dispatchForm.customer, "客户");
    return dispatchForm.customerId || matchedCustomer?.id || "";
  }
  return orderForm.customerId || selectedCustomer.value?.id || "";
}

const dispatchCustomerSelected = computed(() => {
  const customerName = String(dispatchForm.customer || "").trim();
  if (!customerName && !dispatchForm.customerId) return false;
  const byId = dispatchForm.customerId ? customerRowsById.value.get(String(dispatchForm.customerId || "").trim()) : null;
  return byId?.type === "客户" || Boolean(findPartnerByTypedLabel(customerName, "客户"));
});

const customerContactAddressOptions = computed(() => {
  const customerId = currentAddressBookCustomerId();
  if (!customerId) return [];
  return customerContactRows.value
    .filter((item) => item.customerId === customerId)
    .map((item) => {
      const area = contactAreaText(item);
      const address = contactAddressText(item);
      return {
        key: `contact:${item.id}`,
        id: item.id,
        source: "联系人",
        direction: "-",
        level1: "-",
        level2: "-",
        level3: "-",
        rank: 0,
        area,
        contact: item.name || "",
        phone: item.mobile || item.phone || "",
        note: item.remark || "",
        pathLabel: address,
        value: [area, address].filter(Boolean).join(" / "),
        address
      };
    })
    .filter((item) => item.area || item.address || item.contact || item.phone);
});

const addressBookCityOptions = computed(() =>
  uniqueSorted(templateLocationGroups.value.map((group) => group.level1))
);

const addressBookAreaLevel1Options = addressBookCityOptions;

const addressBookAreaLevel2Options = computed(() => {
  const city = String(addressBookForm.city || "").trim();
  if (!city) return [];
