);

const locationCityOptions = computed(() =>
  uniqueSorted([
    ...Object.values(chinaProvinceCities).flat(),
    ...templateLocationGroups.value.map((group) => group.level1),
    ...customerContactRows.value.map((item) => splitLocationParts(contactAreaText(item)).city),
    ...addressBookRows.value.map((item) => splitLocationParts(item.area).city),
    ...orderRows.value.flatMap((order) => [
      ...splitDispatchLocationEntriesText(order.loading).map((entry) => splitLocationParts(entry).city),
      ...splitDispatchLocationEntriesText(order.unloading).map((entry) => splitLocationParts(entry).city)
    ])
  ].filter(Boolean))
);

function dispatchLocationCityRestrictedToHongKong(target = "") {
  const direction = String(dispatchForm.direction || "").trim();
  return (direction === "出口" && target === "unloading")
    || (direction === "进口" && target === "loading");
}

function dispatchLocationCityOptionsForTarget(target = "") {
  return dispatchLocationCityRestrictedToHongKong(target) ? ["香港"] : addressBookCityOptions.value;
}

function dispatchLocationCityOptionsListId(target = "") {
