function realtimeAffectedModules(event = {}) {
  return new Set(Array.isArray(event.affectedModules) ? event.affectedModules.map(String) : []);
}

function shouldRefreshRemindersForRealtime(event = {}) {
  const modules = realtimeAffectedModules(event);
  return modules.has("reminders") || ["driver", "vehicle", "vehicle_expense"].includes(String(event.entityType || ""));
}

function isDispatchPlanEditorOpen() {
  return dispatchModalOpen.value || dispatchDuplicateModalOpen.value;
}

async function flushRealtimeRefresh() {
  const pending = { ...realtimePendingRefresh };
  realtimePendingRefresh.database = false;
  realtimePendingRefresh.dispatch = false;
  realtimePendingRefresh.reminders = false;

  try {
    if (pending.database) {
      await loadDatabaseData({ preserveSelection: true, silent: true });
    }
    if (pending.reminders && loggedIn.value) {
      await loadExpiryReminders({ silent: true, showPopup: activeModule.value === "home" });
    }
    if (pending.dispatch && loggedIn.value && canAccessModule("dispatchBoard")) {
      if (isDispatchPlanEditorOpen()) {
        realtimePendingRefresh.dispatch = true;
        return;
      }
      await loadDispatchPlansForCurrentFilter();
    }
  } catch (error) {
    console.warn("Realtime refresh failed", error);
  }
}

function scheduleRealtimeRefresh(event = {}) {
  if (!loggedIn.value) return;
  const modules = realtimeAffectedModules(event);
  realtimePendingRefresh.database = true;
  realtimePendingRefresh.dispatch = realtimePendingRefresh.dispatch || modules.has("dispatchBoard");
  realtimePendingRefresh.reminders = realtimePendingRefresh.reminders || shouldRefreshRemindersForRealtime(event);
  window.clearTimeout(realtimeRefreshTimer);
  realtimeRefreshTimer = window.setTimeout(() => {
    realtimeRefreshTimer = null;
    flushRealtimeRefresh();
  }, 500);
}

function closeRealtimeConnection() {
  window.clearTimeout(realtimeRefreshTimer);
  realtimeRefreshTimer = null;
  realtimePendingRefresh.database = false;
  realtimePendingRefresh.dispatch = false;
  realtimePendingRefresh.reminders = false;
  if (realtimeClient) {
    realtimeClient.disconnect();
    realtimeClient = null;
  }
}

function ensureRealtimeConnection() {
  if (!loggedIn.value || !authToken.value) {
    closeRealtimeConnection();
    return;
  }
  if (!realtimeClient) {
    realtimeClient = createRealtimeClient({
      getToken: () => authToken.value,
      onChange: scheduleRealtimeRefresh,
      onStatus: (_status) => {}
    });
  }
  realtimeClient.connect();
}

function tableSortKey(tableId) {
  return `hanye_table_sort_${tableId}`;
}

function loadTableSortState(tableId) {
  if (tableSortState[tableId]) return tableSortState[tableId];
  try {
    const saved = JSON.parse(localStorage.getItem(tableSortKey(tableId)) || "{}");
    tableSortState[tableId] = {
      key: String(saved.key || ""),
      direction: saved.direction === "desc" ? "desc" : (saved.direction === "asc" ? "asc" : "")
    };
  } catch {
    tableSortState[tableId] = { key: "", direction: "" };
  }
  return tableSortState[tableId];
}

function tableSortDirection(tableId, key) {
  const state = loadTableSortState(tableId);
  return state.key === key ? state.direction : "";
}

function toggleTableSort(tableId, column = {}) {
  if (!column?.key || ["select", "actions", "sequence"].includes(column.key)) return;
  const state = loadTableSortState(tableId);
  if (state.key !== column.key) {
    state.key = column.key;
    state.direction = "asc";
  } else if (state.direction === "asc") {
    state.direction = "desc";
  } else {
    state.key = "";
    state.direction = "";
  }
  localStorage.setItem(tableSortKey(tableId), JSON.stringify(state));
}

function resetTableSort(tableId) {
  if (!tableId) return;
  const state = loadTableSortState(tableId);
  state.key = "";
  state.direction = "";
  localStorage.removeItem(tableSortKey(tableId));
  notify("已恢复默认排序");
}

function tableSortLabel(tableId, column = {}) {
  const direction = tableSortDirection(tableId, column.key);
  if (direction === "asc") return "升序";
  if (direction === "desc") return "降序";
  return "";
}

function tableSortValue(row = {}, key = "") {
  if (!key) return "";
  if (key === "date" && (row.no || row.order?.no)) return orderDispatchLoadSortValue(row.order || row);
  if (key === "driver" && row.driver) return row.driver.name || "";
  if (key === "type" && row.driver) return row.driver.type || "";
  if (key === "status" && row.driver) return row.driver.status || "";
  if (key === "expiry") return vehicleExpenseAnnualEndDate(row);
  if (key === "orderCount") return row.orderCount ?? "";
  if (key === "tripFee") return (row.payable ?? 0) + (row.payableRMB ?? 0);
  if (key === "advanceFee") return (row.advanceFee ?? 0) + (row.advanceFeeRMB ?? 0);
  if (key === "adjustments") return (row.adjustments ?? 0) + (row.adjustmentsRMB ?? 0);
  if (key === "total") return (row.total ?? 0) + (row.totalRMB ?? 0);
  if (key === "recentOrderDate") return partnerRecentOrderDate(row);
  const direct = row?.[key];
  if (direct !== undefined && direct !== null && direct !== "") return direct;
  if (row.order && row.order[key] !== undefined) return row.order[key];
  if (row.driver && row.driver[key] !== undefined) return row.driver[key];
  if (key === "route") return `${row.loading || row.order?.loading || ""} ${row.unloading || row.order?.unloading || ""}`;
  if (key === "baseFee") return row.baseFee ?? row.payable ?? "";
  if (key === "tripFee") return row.payable ?? "";
  return "";
}

function normalizeSortValue(value) {
  if (value === null || value === undefined) return { type: "empty", value: "" };
  const text = String(value).trim();
  if (!text) return { type: "empty", value: "" };
  const dateTimeMatch = text.match(/^(\d{4}-\d{2}-\d{2})(?:\s+(\d{1,2}):(\d{2}))?/);
  if (dateTimeMatch) {
    const date = parseInputDate(dateTimeMatch[1]);
    if (date) {
      const hour = Number(dateTimeMatch[2] || 0);
      const minute = Number(dateTimeMatch[3] || 0);
      const timeOffset = Number.isFinite(hour) && Number.isFinite(minute)
        ? (hour * 60 + minute) * 60000
        : 0;
      return { type: "date", value: date.getTime() + timeOffset };
    }
  }
  const date = parseInputDate(text);
  if (date && /^\d{4}-\d{2}-\d{2}/.test(text)) return { type: "date", value: date.getTime() };
  const numeric = Number(text.replace(/,/g, "").match(/-?\d+(?:\.\d+)?/)?.[0]);
  if (Number.isFinite(numeric) && /-?\d/.test(text)) return { type: "number", value: numeric };
  return { type: "text", value: text };
}

function compareSortValues(left, right) {
  const a = normalizeSortValue(left);
  const b = normalizeSortValue(right);
  if (a.type === "empty" && b.type !== "empty") return 1;
  if (b.type === "empty" && a.type !== "empty") return -1;
  if (a.type === "number" && b.type === "number") return a.value - b.value;
  if (a.type === "date" && b.type === "date") return a.value - b.value;
  return String(a.value).localeCompare(String(b.value), "zh-Hans-CN", { numeric: true });
}

function orderDefaultGroupKey(order = {}) {
  const plate = String(order.plate || "").trim();
  if (plate) return plate;
  return String(order.supplier || "").trim();
}

function compareOrderRowsForDefaultSort(left = {}, right = {}) {
  const leftGroup = orderDefaultGroupKey(left);
  const rightGroup = orderDefaultGroupKey(right);
  if (!leftGroup && rightGroup) return 1;
  if (!rightGroup && leftGroup) return -1;
  const groupCompare = leftGroup.localeCompare(rightGroup, "zh-Hans-CN", { numeric: true, sensitivity: "base" });
  if (groupCompare !== 0) return groupCompare;

  const dateCompare = compareSortValues(
    orderDispatchLoadSortValue(left.order || left) || left.date || left.order?.date || "",
    orderDispatchLoadSortValue(right.order || right) || right.date || right.order?.date || ""
  );
  if (dateCompare !== 0) return dateCompare;

  const noCompare = String(left.no || "").localeCompare(String(right.no || ""), "zh-Hans-CN", { numeric: true, sensitivity: "base" });
  if (noCompare !== 0) return noCompare;
  return (left.__sortIndex ?? 0) - (right.__sortIndex ?? 0);
}

function sortRowsByTable(rows = [], tableId, fallbackIndexKey = "__sortIndex") {
  const state = loadTableSortState(tableId);
  if (!state.key || !state.direction) {
    if (!["orders", "customerOrders", "relatedVehicleOrders", "relatedDriverOrders"].includes(tableId)) return rows;
    return rows
      .map((row, index) => ({ row, index }))
      .sort((left, right) => {
        const compared = compareOrderRowsForDefaultSort(left.row, right.row);
        if (compared !== 0) return compared;
        return (left.row?.[fallbackIndexKey] ?? left.index) - (right.row?.[fallbackIndexKey] ?? right.index);
      })
      .map((item) => item.row);
  }
  const direction = state.direction === "desc" ? -1 : 1;
  return rows
    .map((row, index) => ({ row, index }))
    .sort((left, right) => {
      const compared = compareSortValues(tableSortValue(left.row, state.key), tableSortValue(right.row, state.key));
      if (compared !== 0) return compared * direction;
      return (left.row?.[fallbackIndexKey] ?? left.index) - (right.row?.[fallbackIndexKey] ?? right.index);
    })
    .map((item) => item.row);
}

