function closeRouteTreeDropdown() {
  routeTreeDropdown.open = false;
}

function toggleRouteTreeDropdown(target) {
  if (routeTreeDropdown.open && routeTreeDropdown.target === target) {
    closeRouteTreeDropdown();
    return;
  }
  const current = readRouteTreePath(orderForm[target]);
  routeTreeDropdown.target = target;
  routeTreeDropdown.level1 = current.level1;
  routeTreeDropdown.level2 = current.level2;
  routeTreeDropdown.level3 = current.level3;
  const validLevel1Options = uniqueSorted(orderLocationGroupsForTarget(target).map((group) => group.level1));
  if (routeTreeDropdown.level1 && !validLevel1Options.includes(routeTreeDropdown.level1)) {
    routeTreeDropdown.level1 = "";
    routeTreeDropdown.level2 = "";
    routeTreeDropdown.level3 = "";
  }
  routeTreeDropdown.open = true;
}

function selectRouteTreeLevel(level, value) {
  if (level === 1) {
    const selected = routeTreeDropdown.level1 === value;
    routeTreeDropdown.level1 = selected ? "" : value;
    routeTreeDropdown.level2 = "";
    routeTreeDropdown.level3 = "";
  } else if (level === 2) {
    const selected = routeTreeDropdown.level2 === value;
    routeTreeDropdown.level2 = selected ? "" : value;
    routeTreeDropdown.level3 = "";
  } else {
    routeTreeDropdown.level3 = routeTreeDropdown.level3 === value ? "" : value;
  }
}

function confirmRouteTreeSelection() {
  const value = routeTreeValue.value;
  if (!value) {
    orderForm[routeTreeDropdown.target] = "";
    orderForm[dispatchLocationEntriesKey(routeTreeDropdown.target)] = [];
  } else {
    setOrderLocationEntries(routeTreeDropdown.target, [{
      city: routeTreeDropdown.level1,
      district: routeTreeDropdown.level2,
      detail: ""
    }]);
  }
  closeRouteTreeDropdown();
  scheduleAutoFreightSync();
}

function currentLocationForm() {
  return locationPicker.owner === "dispatch" ? dispatchForm : orderForm;
}

function clearDispatchLocationDraftsForPickerTarget() {
  if (locationPicker.owner === "dispatch" && locationPicker.target) {
    clearDispatchLocationDraftsForTarget(locationPicker.target);
  }
}

function addressBookOptionValue(option = {}) {
  return String(option.value || option.address || option.pathLabel || "").trim();
}

function locationCityCandidates() {
  const provinceCities = Object.values(chinaProvinceCities).flat();
  const values = new Set([
    ...provinceCities,
    ...templateLocationGroups.value.map((group) => group.level1),
    "香港",
    "澳门"
  ]);
  provinceCities.forEach((city) => {
    const text = String(city || "").trim();
    if (text.endsWith("市") && text.length > 1) values.add(text.slice(0, -1));
  });
  return [...values].filter(Boolean).sort((left, right) => right.length - left.length);
}

function splitLocationParts(value = "") {
  const text = String(value || "")
    .replace(/\r/g, "\n")
    .replace(/[／｜|]/g, "/")
    .split(/[；;]+/)
    .map((part) => part.trim())
    .filter(Boolean)[0] || "";
  const parts = text
    .split("/")
    .map((part) => part.trim())
    .filter(Boolean);
  if (parts.length <= 1 && text) {
    const sourceText = parts.length === 1 ? parts[0] : text;
    const cities = locationCityCandidates();
    const city = cities.find((item) => sourceText === item || sourceText.startsWith(item)) || "";
    const afterCity = city ? sourceText.slice(sourceText.indexOf(city) + city.length).trim() : sourceText;
    const district = afterCity.match(/^([\u4e00-\u9fa5A-Za-z0-9]+?(?:区|县|镇|乡|街道))/u)?.[1] || "";
    const detail = district ? afterCity.slice(district.length).trim() : afterCity;
    return {
      city,
      district,
      detail: city || district ? detail : sourceText
    };
  }
  return {
    city: parts[0] || "",
    district: parts[1] || "",
    detail: parts.slice(2).join(" / ")
  };
}

function composeLocationParts(city = "", district = "", detail = "") {
  return [city, district, detail]
    .map((part) => String(part || "").trim())
    .filter(Boolean)
    .join(" / ");
}

function isLikelyDispatchLocationCity(value = "") {
  const text = String(value || "").trim();
  if (!text) return false;
  const normalized = normalizeLocationText(text);
  return locationCityCandidates().some((city) => normalizeLocationText(city) === normalized) ||
    /(?:市|盟|地区|自治州|特别行政区)$/.test(text) ||
    text === "香港" ||
    text === "澳门";
}

function isLikelyDispatchLocationDistrict(value = "") {
  const text = String(value || "").trim();
  return Boolean(text && /(?:区|區|县|縣|镇|鎮|乡|鄉|街道|开发区|工業區|工业区|新区)$/.test(text));
}

function isStructuredDispatchLocationParts(parts = []) {
  const [city = "", district = "", ...detailParts] = parts;
  const hasDetail = detailParts.some((part) => String(part || "").trim());
  if (!city && !district && hasDetail) return true;
  if (!city && isLikelyDispatchLocationDistrict(district)) return true;
  if (isLikelyDispatchLocationCity(city)) return true;
  return false;
}

function splitDispatchLocationParts(value = "") {
  const rawText = String(value || "").replace(/\r/g, "\n").replace(/[／｜|]/g, "/");
  const text = rawText.replace(/^\n+|\n+$/g, "");
  if (!text.trim()) return { city: "", district: "", detail: "" };
  if (["香港", "澳门"].includes(text.trim())) {
    return {
      city: text.trim(),
      district: "",
      detail: ""
    };
  }
  if (text.includes("/")) {
    const parts = text.split("/").map((part) => part.trim());
    if (!isStructuredDispatchLocationParts(parts)) {
      return {
        city: "",
        district: "",
        detail: text
      };
    }
    if (!parts[0] && !parts[1] && parts.slice(2).some(Boolean)) {
      return {
        city: "",
        district: "",
        detail: parts.slice(2).join(" / ")
      };
    }
    if (!parts[0] && parts.filter(Boolean).length === 1) {
      return splitLocationParts(parts.filter(Boolean)[0]);
    }
    const parsed = {
      city: parts[0] || "",
      district: parts[1] || "",
      detail: parts.slice(2).join(" / ")
    };
    if (parsed.district) {
      const districtParts = splitLocationParts(parsed.district);
      if (!districtParts.city && districtParts.district && districtParts.district !== parsed.district) {
        parsed.district = districtParts.district;
        parsed.detail = [districtParts.detail, parsed.detail].filter(Boolean).join(" / ");
      }
    }
    if (!parsed.city && parsed.detail) {
      return splitLocationParts(parsed.detail);
    }
    if (parsed.city && !parsed.district && parsed.detail) {
      const detailParts = splitLocationParts(parsed.detail);
      if (detailParts.city && normalizeLocationText(detailParts.city) === normalizeLocationText(parsed.city) && !detailParts.district && !detailParts.detail) {
        parsed.detail = "";
      }
    }
    return parsed;
  }
  if (text.includes("\n")) {
    return {
      city: "",
      district: "",
      detail: text
    };
  }
  return {
    city: "",
    district: "",
    detail: text
  };
}

function composeDispatchLocationParts(city = "", district = "", detail = "") {
  const cityText = String(city || "").trim();
  const districtText = String(district || "").trim();
  const detailText = String(detail ?? "").replace(/\r\n?/g, "\n");
  if (!cityText && !districtText) return detailText;
  if (cityText && !districtText && !detailText) return cityText;
  if (cityText && districtText && !detailText) return [cityText, districtText].join(" / ");
  if (cityText && !districtText && detailText) return [cityText, "", detailText].join(" / ");
  return [cityText, districtText, detailText].join(" / ");
}

function normalizeDispatchLocationText(value = "", options = {}) {
  return normalizeUserText(value, {
    singleLine: options.singleLine,
    compactCjkSpacing: true
  });
}

function normalizeDispatchLocationDetailText(value = "") {
  return String(value ?? "").replace(/\r\n?/g, "\n");
}

function normalizeDispatchLocationPartValue(value = "", part = "") {
  const text = part === "detail"
    ? normalizeDispatchLocationDetailText(value)
    : normalizeDispatchLocationText(value, { singleLine: true });
  return text;
}

function normalizeDispatchLocationCityValue(target = "", value = "") {
  return normalizeDispatchLocationPartValue(value, "city");
}

function isDispatchLocationCityLikeValue(target = "", value = "") {
  const text = normalizeDispatchLocationText(value, { singleLine: true });
  if (!text) return false;
  if (dispatchLocationCityRestrictedToHongKong(target)) return normalizeLocationText(splitLocationParts(text).city).startsWith("香港");
  const normalized = normalizeLocationText(text);
  return isLikelyDispatchLocationCity(text)
    || locationCityCandidates().some((city) => normalizeLocationText(city) === normalized);
}

function normalizeDispatchLocationPartsForTarget(target = "", value = "") {
  const parsed = splitDispatchLocationParts(value);
  let city = normalizeDispatchLocationCityValue(target, parsed.city);
  let district = normalizeDispatchLocationText(parsed.district, { singleLine: true });
  let detail = normalizeDispatchLocationDetailText(parsed.detail);

  return { city, district, detail };
}

function emptyDispatchLocationEntry() {
  return { city: "", district: "", detail: "" };
}

function dispatchLocationEntriesKey(target = "") {
  return target === "unloading" ? "unloadingLocations" : "loadingLocations";
}

function dispatchLocationEntryHasValue(entry = {}) {
  return Boolean(String(entry.city || entry.district || entry.detail || "").trim());
}

function normalizeDispatchLocationEntryForTarget(target = "", entry = {}) {
  if (entry && typeof entry === "object" && !Array.isArray(entry)) {
    const hasStructuredParts = Object.prototype.hasOwnProperty.call(entry, "city")
      || Object.prototype.hasOwnProperty.call(entry, "district")
      || Object.prototype.hasOwnProperty.call(entry, "detail");
    if (hasStructuredParts) {
      return {
        city: normalizeDispatchLocationCityValue(target, entry.city),
        district: normalizeDispatchLocationText(entry.district, { singleLine: true }),
        detail: normalizeDispatchLocationDetailText(entry.detail)
      };
    }
    if (Object.prototype.hasOwnProperty.call(entry, "value")) {
      return normalizeDispatchLocationPartsForTarget(target, entry.value);
    }
  }
  return normalizeDispatchLocationPartsForTarget(target, entry);
}

function parseDispatchLocationEntriesJson(value) {
  if (Array.isArray(value)) return value;
  if (value && typeof value === "object") return [value];
  const text = String(value ?? "").trim();
  if (!text || !text.startsWith("[")) return [];
  try {
    const parsed = JSON.parse(text);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function normalizeStructuredDispatchLocationEntries(target = "", entries = [], fallbackText = "", options = {}) {
  const sourceEntries = parseDispatchLocationEntriesJson(entries);
  let normalized = sourceEntries
    .map((entry) => normalizeDispatchLocationEntryForTarget(target, entry))
    .filter(options.preserveDraftEntries ? () => true : dispatchLocationEntryHasValue);
  const legacyText = fallbackText || (typeof entries === "string" ? entries : "");
  if (!normalized.length && legacyText) {
    normalized = options.fallbackAsDetail
      ? [{ city: "", district: "", detail: normalizeDispatchLocationDetailText(legacyText) }]
      : (options.parseLegacy === false ? [] : splitDispatchLocationEntriesText(legacyText)
        .map((entry) => normalizeDispatchLocationPartsForTarget(target, entry))
        .filter(dispatchLocationEntryHasValue));
  }
  if (!normalized.length && options.includeBlank !== false) return [emptyDispatchLocationEntry()];
  return normalized;
}

function cloneDispatchLocationEntries(entries = []) {
  return (Array.isArray(entries) ? entries : [])
    .map((entry) => ({
      city: normalizeDispatchLocationCityValue("", entry.city),
      district: normalizeDispatchLocationText(entry.district, { singleLine: true }),
      detail: normalizeDispatchLocationDetailText(entry.detail)
    }))
    .filter(dispatchLocationEntryHasValue);
}

function composeDispatchLocationEntriesText(entries = []) {
  return (Array.isArray(entries) ? entries : [])
    .map((entry) => composeDispatchLocationParts(entry.city, entry.district, entry.detail))
    .filter((entry) => String(entry || "").trim())
    .join("；");
}

function recordDispatchLocationEntries(record = {}, target = "", fallbackRecord = {}) {
  const key = dispatchLocationEntriesKey(target);
  const entries = normalizeStructuredDispatchLocationEntries(
    target,
    record[key] && record[key].length ? record[key] : fallbackRecord[key],
    record[target] || fallbackRecord[target] || "",
    { includeBlank: false }
  );
  return entries;
}

function setDispatchFormLocationEntriesFromRecord(target = "", record = {}, fallbackRecord = {}) {
  const entries = recordDispatchLocationEntries(record, target, fallbackRecord);
  setDispatchLocationEntries(target, entries.length ? entries : [emptyDispatchLocationEntry()]);
}

function dispatchLocationPayload(target = "") {
  const entries = dispatchLocationEntries(target)
    .map((entry, index) => dispatchLocationPartsForEdit(target, index))
    .filter(dispatchLocationEntryHasValue);
  const normalized = entries.length ? entries : [];
  return {
    [target]: composeDispatchLocationEntriesText(normalized),
    [dispatchLocationEntriesKey(target)]: cloneDispatchLocationEntries(normalized)
  };
}

function splitAddressBookLocationValue(value = "") {
  return String(value || "")
    .replace(/\r/g, "\n")
    .split(/[；;]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function splitDispatchLocationEntriesText(value = "") {
  const raw = String(value || "").replace(/\r/g, "\n");
  if (!raw.trim()) return [""];
  const trailingBlankCount = (raw.match(/[；;]+$/)?.[0].length) || 0;
  const text = trailingBlankCount > 0 ? raw.slice(0, raw.length - trailingBlankCount) : raw;
  const entries = text
    .split(/[；;]+/)
    .map((item) => item.trim())
    .filter(Boolean);
  if (!entries.length) return [""];
  return trailingBlankCount > 0
    ? [...entries, ...Array.from({ length: trailingBlankCount }, () => "")]
    : entries;
}

function dispatchLocationEntries(target) {
  const key = dispatchLocationEntriesKey(target);
  const entries = normalizeStructuredDispatchLocationEntries(target, dispatchForm[key], dispatchForm[target], {
    preserveDraftEntries: true
  });
  return entries.length ? entries : [emptyDispatchLocationEntry()];
}

function dispatchLocationEntryCount(target) {
  return dispatchLocationEntries(target).filter(dispatchLocationEntryHasValue).length;
}

function setDispatchLocationEntries(target, entries) {
  const key = dispatchLocationEntriesKey(target);
  const normalized = normalizeStructuredDispatchLocationEntries(target, entries, "", {
    includeBlank: true,
    preserveDraftEntries: true
  });
  dispatchForm[key] = normalized;
  dispatchForm[target] = composeDispatchLocationEntriesText(normalized);
}

function setOrderLocationEntries(target, entries = []) {
  const key = dispatchLocationEntriesKey(target);
  const normalized = normalizeStructuredDispatchLocationEntries(target, entries, "", { includeBlank: false });
  orderForm[key] = cloneDispatchLocationEntries(normalized);
  orderForm[target] = composeDispatchLocationEntriesText(normalized);
}

function setCurrentLocationEntries(target, entries = []) {
  if (locationPicker.owner === "dispatch") {
    setDispatchLocationEntries(target, entries);
    return;
  }
  setOrderLocationEntries(target, entries);
}

function locationEntryFromAreaAndDetail(target = "", area = "", detail = "") {
  const parts = splitLocationParts(area || "");
  return normalizeDispatchLocationEntryForTarget(target, {
    city: parts.city,
    district: parts.district,
    detail: normalizeDispatchLocationDetailText(detail)
  });
}

function locationEntryFromOption(target = "", option = {}, detailOverride = "") {
  const detailText = normalizeDispatchLocationDetailText(
    detailOverride
    || option.address
    || option.detail
    || ""
  );
  if (option.area) return locationEntryFromAreaAndDetail(target, option.area, detailText);
  if (option.level1 || option.level2) {
    return normalizeDispatchLocationEntryForTarget(target, {
      city: option.level1 || "",
      district: option.level2 || "",
      detail: detailText
    });
  }
  const parsed = normalizeDispatchLocationPartsForTarget(target, option.value || "");
  if (detailText) parsed.detail = detailText;
  return parsed;
}

function dispatchLocationPersistedParts(target, index) {
  return normalizeDispatchLocationEntryForTarget(target, dispatchLocationEntries(target)[index] || emptyDispatchLocationEntry());
}

function dispatchLocationDraftHasPart(draft, part) {
  return Boolean(draft && Object.prototype.hasOwnProperty.call(draft, part));
}

function dispatchLocationPartsForEdit(target, index) {
  const persisted = dispatchLocationPersistedParts(target, index);
  const draft = dispatchLocationDrafts[dispatchLocationDraftKey(target, index)];
  return {
    city: dispatchLocationDraftHasPart(draft, "city") ? normalizeDispatchLocationCityValue(target, draft.city) : persisted.city,
    district: dispatchLocationDraftHasPart(draft, "district") ? normalizeDispatchLocationText(draft.district, { singleLine: true }) : persisted.district,
    detail: dispatchLocationDraftHasPart(draft, "detail") ? normalizeDispatchLocationDetailText(draft.detail) : persisted.detail
  };
}

function persistDispatchLocationEntryParts(target, index, parts = {}) {
  const entries = dispatchLocationEntries(target);
  entries[index] = {
    city: normalizeDispatchLocationCityValue(target, parts.city),
    district: normalizeDispatchLocationText(parts.district, { singleLine: true }),
    detail: normalizeDispatchLocationDetailText(parts.detail)
  };
  setDispatchLocationEntries(target, entries);
}

function updateDispatchLocationEntry(target, index, value) {
  const entries = dispatchLocationEntries(target);
  entries[index] = normalizeDispatchLocationEntryForTarget(target, value);
  setDispatchLocationEntries(target, entries);
}

function updateDispatchLocationEntryPart(target, index, part, value) {
  const current = dispatchLocationPartsForEdit(target, index);
  current[part] = normalizeDispatchLocationPartValue(value, part);
  persistDispatchLocationEntryParts(target, index, current);
}

function dispatchLocationInputKey(target, index, part) {
  return `${target}:${index}:${part}`;
}

function dispatchLocationDraftKey(target, index) {
  return `${target}:${index}`;
}

function ensureDispatchLocationDraft(target, index) {
  const key = dispatchLocationDraftKey(target, index);
  if (!dispatchLocationDrafts[key]) {
    dispatchLocationDrafts[key] = {};
  }
  return dispatchLocationDrafts[key];
}

function dispatchLocationDraftValue(target, index, part) {
  const key = dispatchLocationDraftKey(target, index);
  const draft = dispatchLocationDrafts[key];
  if (draft && Object.prototype.hasOwnProperty.call(draft, part)) {
    return String(draft[part] ?? "");
  }
  return dispatchLocationPersistedParts(target, index)[part] || "";
}

function dispatchLocationPartValue(target, index, part) {
  return dispatchLocationDraftValue(target, index, part).trim();
}

function dispatchLocationCityValue(target, index) {
  return dispatchLocationPartValue(target, index, "city");
}

function dispatchLocationDistrictValue(target, index) {
  return dispatchLocationPartValue(target, index, "district");
}

function dispatchLocationHasCity(target, index) {
  return Boolean(dispatchLocationCityValue(target, index));
}

function setDispatchLocationDraftPart(target, index, part, value) {
  const draft = ensureDispatchLocationDraft(target, index);
  draft[part] = String(value || "");
}

function setDispatchLocationInputComposing(target, index, part, composing) {
  dispatchLocationInputComposing[dispatchLocationInputKey(target, index, part)] = Boolean(composing);
}

function isDispatchLocationInputComposing(target, index, part) {
  return Boolean(dispatchLocationInputComposing[dispatchLocationInputKey(target, index, part)]);
}

function handleDispatchLocationTextInput(target, index, part, event) {
  if (event?.isComposing || isDispatchLocationInputComposing(target, index, part)) return;
  const value = part === "detail"
    ? normalizeDispatchLocationDetailText(event?.target?.value || "")
    : normalizeDispatchLocationText(event?.target?.value || "", { singleLine: true });
  if (event?.target && event.target.value !== value) event.target.value = value;
  setDispatchLocationDraftPart(target, index, part, value);
  if (part === "district") {
    dispatchLocationDistrictPicker.key = dispatchLocationDistrictKey(target, index);
    dispatchLocationDistrictPicker.keyword = String(value || "").trim();
  }
}

function handleDispatchLocationTextCompositionStart(target, index, part) {
  setDispatchLocationInputComposing(target, index, part, true);
}

function handleDispatchLocationTextCompositionEnd(target, index, part, event) {
  setDispatchLocationInputComposing(target, index, part, false);
  const value = part === "detail"
    ? normalizeDispatchLocationDetailText(event?.target?.value || "")
    : normalizeDispatchLocationText(event?.target?.value || "", { singleLine: true });
  if (event?.target && event.target.value !== value) event.target.value = value;
  setDispatchLocationDraftPart(target, index, part, value);
  if (part === "district") {
    dispatchLocationDistrictPicker.key = dispatchLocationDistrictKey(target, index);
    dispatchLocationDistrictPicker.keyword = String(value || "").trim();
  }
}

function commitDispatchLocationDraftPart(target, index, part) {
  const value = dispatchLocationDraftValue(target, index, part);
  if (part === "city") {
    updateDispatchLocationCity(target, index, value);
  } else {
    updateDispatchLocationEntryPart(target, index, part, value);
  }
}

function updateDispatchLocationCity(target, index, value) {
  if (isDispatchLocationInputComposing(target, index, "city")) return;
  const persisted = dispatchLocationPersistedParts(target, index);
  const current = dispatchLocationPartsForEdit(target, index);
  const previousCity = normalizeLocationText(persisted.city || current.city || "");
  const nextCity = dispatchLocationCityRestrictedToHongKong(target)
    ? "香港"
    : normalizeDispatchLocationCityValue(target, value);
  if (persisted.city !== nextCity) {
    current.district = "";
    setDispatchLocationDraftPart(target, index, "district", "");
    if (previousCity && !previousCity.startsWith("香港")) {
      current.detail = "";
      setDispatchLocationDraftPart(target, index, "detail", "");
    }
    if (dispatchLocationDistrictSearchKey(target, index)) {
      dispatchLocationDistrictPicker.keyword = "";
      dispatchLocationDistrictPicker.key = "";
    }
  }
  current.city = nextCity;
  setDispatchLocationDraftPart(target, index, "city", nextCity);
  persistDispatchLocationEntryParts(target, index, current);
}

function dispatchLocationDistrictKey(target, index) {
  return `${target}:${index}`;
}

function dispatchLocationDistrictSearchKey(target, index) {
  return dispatchLocationDistrictPicker.key === dispatchLocationDistrictKey(target, index);
}

function dispatchLocationDistrictOptions(target, index) {
  return locationDistrictOptions(dispatchLocationCityValue(target, index));
}

function dispatchFilteredDistrictOptions(target, index) {
  const keyword = normalizeLocationText(dispatchLocationDistrictPicker.keyword);
  const options = dispatchLocationDistrictOptions(target, index);
  if (!keyword) return options;
  return options.filter((district) => normalizeLocationText(district).includes(keyword));
}

function openDispatchLocationDistrictPicker(target, index) {
  if (!dispatchLocationHasCity(target, index)) return;
  dispatchLocationDistrictPicker.key = dispatchLocationDistrictKey(target, index);
  dispatchLocationDistrictPicker.keyword = dispatchLocationDistrictValue(target, index);
}

function closeDispatchLocationDistrictPicker(target, index) {
  if (!dispatchLocationDistrictSearchKey(target, index)) return;
  const current = dispatchLocationPartsForEdit(target, index);
  const value = String(dispatchLocationDistrictPicker.keyword || dispatchLocationDraftValue(target, index, "district") || current.district || "").trim();
  current.district = value;
  setDispatchLocationDraftPart(target, index, "district", value);
  persistDispatchLocationEntryParts(target, index, current);
  dispatchLocationDistrictPicker.key = "";
  dispatchLocationDistrictPicker.keyword = value;
}

function selectDispatchLocationDistrict(target, index, value = "") {
  const district = String(value || "").trim();
  const current = dispatchLocationPartsForEdit(target, index);
  current.district = district;
  setDispatchLocationDraftPart(target, index, "district", district);
  persistDispatchLocationEntryParts(target, index, current);
  dispatchLocationDistrictPicker.key = "";
  dispatchLocationDistrictPicker.keyword = district;
}

function clearDispatchLocationDistrict(target, index) {
  const current = dispatchLocationPartsForEdit(target, index);
  current.district = "";
  setDispatchLocationDraftPart(target, index, "district", "");
  persistDispatchLocationEntryParts(target, index, current);
  dispatchLocationDistrictPicker.key = dispatchLocationDistrictKey(target, index);
  dispatchLocationDistrictPicker.keyword = "";
}

function confirmFirstDispatchLocationDistrictOption(target, index) {
  const [firstDistrict] = dispatchFilteredDistrictOptions(target, index);
  selectDispatchLocationDistrict(target, index, firstDistrict || dispatchLocationDistrictPicker.keyword);
}

function invalidDispatchLocationMessage(target) {
  const label = target === "unloading" ? "卸货地" : "装货地";
  const entries = dispatchLocationEntries(target).filter(dispatchLocationEntryHasValue);
  if (!entries.length) return `请填写${label}`;
  const invalidIndex = entries.findIndex((entry) => {
    const parts = normalizeDispatchLocationEntryForTarget(target, entry);
    return !parts.city && !parts.detail;
  });
  return invalidIndex >= 0 ? `${label}第 ${invalidIndex + 1} 条需要填写市或详细地址` : "";
}

function addDispatchLocationEntry(target) {
  const entries = dispatchLocationEntries(target);
  setDispatchLocationEntries(target, [...entries, emptyDispatchLocationEntry()]);
  dispatchLocationDistrictPicker.key = "";
  dispatchLocationDistrictPicker.keyword = "";
}

function normalizeDispatchLocationFormValuesForSave() {
  ["loading", "unloading"].forEach((target) => {
    const entries = dispatchLocationEntries(target)
      .map((item, index) => dispatchLocationPartsForEdit(target, index))
      .filter(dispatchLocationEntryHasValue);
    setDispatchLocationEntries(target, entries.length ? entries : [emptyDispatchLocationEntry()]);
  });
}

function normalizeDispatchFormTextValuesForSave() {
  [
    "customer",
    "port",
    "direction",
    "tonnage",
    "quantity",
    "weight",
    "loadTime",
    "vehicleSource",
    "supplier",
    "transportMode",
    "driver",
    "hkDriver",
    "mainlandDriver",
    "note"
  ].forEach((key) => {
    dispatchForm[key] = normalizeUserText(dispatchForm[key], { singleLine: true, compactCjkSpacing: true });
  });
  dispatchForm.plate = normalizePlateText(dispatchForm.plate);
  ["loading", "unloading"].forEach((key) => {
    dispatchForm[key] = normalizeDispatchLocationDetailText(dispatchForm[key]);
  });
}

function normalizedOrderPayloadTextValue(value, options = {}) {
  return normalizeUserText(value, {
    singleLine: options.singleLine !== false,
    compactCjkSpacing: true
  });
}

function buildNormalizedOrderPayload() {
  const payload = { ...orderForm };
  [
    "customer",
    "businessType",
    "port",
    "direction",
    "tonnage",
    "currency",
    "quantity",
    "weight",
    "vehicleSource",
    "supplier",
    "driver",
    "hkDriver",
    "mainlandDriver",
    "transportMode",
    "loadingContact",
    "loadingPhone",
    "unloadingContact",
    "unloadingPhone",
    "status",
    "tripNo",
    "sixSheetNo",
    "customsNo",
    "customsUnit",
    "customsItemCount",
    "customsPageCount"
  ].forEach((key) => {
    payload[key] = normalizedOrderPayloadTextValue(payload[key]);
  });
  payload.currency = payload.currency || "港币";
  payload.transportMode = normalizeTransportMode(
    payload.transportMode || (normalizeVehicleSource(payload.vehicleSource) === OWN_VEHICLE_SOURCE ? "单司机" : "")
  );
		  payload.plate = normalizePlateText(payload.plate);
		  const loadingText = normalizeDispatchLocationDetailText(payload.loading).trim();
		  const unloadingText = normalizeDispatchLocationDetailText(payload.unloading).trim();
		  const loadingLocations = normalizeStructuredDispatchLocationEntries("loading", payload.loadingLocations, loadingText, { includeBlank: false, parseLegacy: false, fallbackAsDetail: true });
		  const unloadingLocations = normalizeStructuredDispatchLocationEntries("unloading", payload.unloadingLocations, unloadingText, { includeBlank: false, parseLegacy: false, fallbackAsDetail: true });
		  payload.loadingLocations = cloneDispatchLocationEntries(loadingLocations);
		  payload.unloadingLocations = cloneDispatchLocationEntries(unloadingLocations);
		  payload.loading = composeDispatchLocationEntriesText(loadingLocations) || loadingText;
		  payload.unloading = composeDispatchLocationEntriesText(unloadingLocations) || unloadingText;
	  payload.remark = normalizedOrderPayloadTextValue(mergeCustomsRemark(orderForm.remark), { singleLine: false });
  return payload;
}

function removeDispatchLocationEntry(target, index) {
  const entries = dispatchLocationEntries(target);
  if (entries.length <= 1 || index <= 0) {
    return;
  }
  entries.splice(index, 1);
  setDispatchLocationEntries(target, entries);
  dispatchLocationDistrictPicker.key = "";
  dispatchLocationDistrictPicker.keyword = "";
}

function selectedAddressBookOptionsForApply() {
  const optionsById = new Map(customerContactAddressOptions.value.map((item) => [item.id, item]));
  return selectedAddressBookIds.value
    .map((id) => optionsById.get(id))
    .filter(Boolean);
}

function syncAddressBookSelectionFromLocationValue(value = "") {
  const values = splitAddressBookLocationValue(value);
  if (!values.length) {
    selectedAddressBookIds.value = [];
    return;
  }
  const optionIdsByValue = new Map();
  customerContactAddressOptions.value.forEach((option) => {
    [
      addressBookOptionValue(option),
      option.address,
      option.pathLabel,
      [option.area, option.address].filter(Boolean).join(" / ")
    ].forEach((candidate) => {
      const key = normalizeLocationText(candidate);
      if (key && !optionIdsByValue.has(key)) optionIdsByValue.set(key, option.id);
    });
  });
  const selectedIds = [];
  values.forEach((value) => {
    const id = optionIdsByValue.get(normalizeLocationText(value));
    if (id && !selectedIds.includes(id)) selectedIds.push(id);
  });
  selectedAddressBookIds.value = selectedIds;
}

function openLocationPicker(target, mode = "template", owner = "order") {
  locationPicker.owner = owner;
  locationPicker.target = target;
  locationPicker.mode = mode;
  const form = currentLocationForm();
  locationPicker.keyword = mode === "addressBook" ? "" : (form[target] || "");
  locationPicker.detail = "";
  if (mode === "addressBook") {
    resetAddressBookForm();
    addressBookFormOpen.value = false;
    syncAddressBookSelectionFromLocationValue(form[target]);
  }
  const [level1 = "", level2 = "", level3 = ""] = String(form[target] || "")
    .split("/")
    .map((part) => part.trim());
  locationPicker.level1 = mode === "template" ? level1 : "";
  locationPicker.level2 = mode === "template" ? level2 : "";
  locationPicker.level3 = mode === "template" ? level3 : "";
  locationPicker.open = true;
}

function openDispatchLocationPicker(target) {
  if (!dispatchCustomerSelected.value) {
    notify("请先选择客户，再使用联系人地址");
    return;
  }
  openLocationPicker(target, "addressBook", "dispatch");
}

function closeLocationPicker() {
  locationPicker.open = false;
  addressBookAreaTree.open = false;
}

function resetAddressBookForm() {
  editingAddressBookId.value = "";
  Object.assign(addressBookForm, {
    area: "",
    city: "",
    district: "",
    contact: "",
    phone: "",
    address: "",
    note: ""
  });
}

function startNewAddressBookEntry() {
  resetAddressBookForm();
  syncAddressBookAreaTreeFromValue("");
  addressBookDistrictSearch.value = "";
  addressBookDistrictPickerOpen.value = false;
  addressBookFormOpen.value = true;
}

function buildAddressBookContactRemark(row) {
  return row.note ? String(row.note).trim() : "";
}

async function syncAddressBookEntryToCustomerContact(row, contactId = "", customerId = currentAddressBookCustomerId()) {
  const activeCustomerId = String(customerId || "").trim();
  const name = String(row.contact || "").trim();
  if (!activeCustomerId || !name) return false;

  const phone = String(row.phone || "").trim();
  const remark = buildAddressBookContactRemark(row);
  const existing = customerContactRows.value.find((item) => {
    if (contactId && item.id === contactId) return true;
    if (item.customerId !== activeCustomerId) return false;
    if (phone) {
      return item.name === name && (item.phone === phone || item.mobile === phone);
    }
    return item.name === name;
  });
  const payload = {
    customerId: activeCustomerId,
    name,
    gender: existing?.gender || "",
    title: existing?.title || "",
    mobile: existing?.mobile || "",
    phone: existing?.mobile === phone ? (existing?.phone || "") : (phone || existing?.phone || ""),
    area: row.area || existing?.area || "",
    address: row.address || existing?.address || "",
    fax: existing?.fax || "",
    email: existing?.email || "",
    wechat: existing?.wechat || "",
    qq: existing?.qq || "",
    remark: remark || existing?.remark || ""
  };
  const saved = existing
    ? await customersApi.updateCustomerContact(existing.id, payload)
    : await customersApi.createCustomerContact(payload);
  customerContactRows.value = existing
    ? customerContactRows.value.map((item) => item.id === saved.id ? saved : item)
    : [saved, ...customerContactRows.value];
  return true;
}

async function saveAddressBookEntry() {
  addressBookForm.area = composeLocationParts(addressBookForm.city, addressBookForm.district);
  if (!String(addressBookForm.city || "").trim() || !String(addressBookForm.district || "").trim()) {
    notify("请填写市和区");
    return;
  }
  const address = String(addressBookForm.address || "").trim();
  if (!address) {
    notify("请填写详细地址");
    return;
  }
  const customerId = currentAddressBookCustomerId();
  if (!customerId) {
    notify("请先选择当前客户");
    return;
  }
  const row = {
    area: String(addressBookForm.area || "").trim(),
    contact: String(addressBookForm.contact || "").trim(),
    phone: String(addressBookForm.phone || "").trim(),
    address,
    note: String(addressBookForm.note || "").trim()
  };
  try {
    const contactSynced = await syncAddressBookEntryToCustomerContact(row, editingAddressBookId.value, customerId);
    if (!contactSynced) {
      notify("请先填写联系人");
      return;
    }
    resetAddressBookForm();
    addressBookFormOpen.value = false;
    notify("地址已保存到客户联系人");
  } catch (error) {
    notify(error.message);
  }
}

function editAddressBookEntry(option) {
  if (!option?.id) return;
  const row = customerContactRows.value.find((item) => item.id === option.id);
  if (!row) return;
  editingAddressBookId.value = row.id;
  addressBookFormOpen.value = true;
  const areaParts = splitLocationParts(contactAreaText(row) || "");
  Object.assign(addressBookForm, {
    area: contactAreaText(row) || "",
    city: areaParts.city,
    district: areaParts.district,
    contact: row.name || "",
    phone: row.mobile || row.phone || "",
    address: contactAddressText(row) || "",
    note: row.remark || ""
  });
  addressBookDistrictSearch.value = String(areaParts.district || "").trim();
  addressBookDistrictPickerOpen.value = false;
}

async function deleteAddressBookEntry(id) {
  if (!id) return;
  try {
    await customersApi.deleteCustomerContact(id);
    customerContactRows.value = customerContactRows.value.filter((item) => item.id !== id);
    selectedAddressBookIds.value = selectedAddressBookIds.value.filter((item) => item !== id);
    if (editingAddressBookId.value === id) {
      resetAddressBookForm();
      addressBookFormOpen.value = false;
    }
    notify("联系人地址已删除");
  } catch (error) {
    notify(error.message);
  }
}

function toggleAddressBookSelection(id, checked) {
  if (!id) return;
  selectedAddressBookIds.value = checked
    ? [...new Set([...selectedAddressBookIds.value, id])]
    : selectedAddressBookIds.value.filter((item) => item !== id);
}

function toggleAllAddressBookSelection(checked) {
  selectedAddressBookIds.value = checked ? [...visibleSavedAddressBookIds.value] : [];
}

function applySelectedAddressBookEntries() {
  const selectedOptions = selectedAddressBookOptionsForApply();
  if (!selectedOptions.length) {
    notify("请先勾选地址");
    return;
  }
  const seen = new Set();
  const values = selectedOptions
    .map((option) => addressBookOptionValue(option))
    .filter((value) => {
      const key = normalizeLocationText(value);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  if (!values.length) {
    notify("请选择有效地址");
    return;
  }
			  clearDispatchLocationDraftsForPickerTarget();
		  if (locationPicker.owner === "dispatch") {
		    setDispatchLocationEntries(
		      locationPicker.target,
		      selectedOptions.map((option) => locationEntryFromOption(locationPicker.target, option))
		    );
		  } else {
		    setOrderLocationEntries(
		      locationPicker.target,
		      selectedOptions.map((option) => locationEntryFromOption(locationPicker.target, option))
		    );
		  }
  const firstOption = selectedOptions[0] || {};
  if (locationPicker.owner === "order" && locationPicker.target === "unloading") {
    orderForm.unloadingContact = firstOption.contact || "";
    orderForm.unloadingPhone = firstOption.phone || "";
  } else if (locationPicker.owner === "order") {
    orderForm.loadingContact = firstOption.contact || "";
    orderForm.loadingPhone = firstOption.phone || "";
  }
  closeLocationPicker();
  if (locationPicker.owner === "order") {
    scheduleAutoFreightSync();
  }
}

async function deleteSelectedAddressBookEntries() {
  const selected = new Set(selectedAddressBookIds.value);
  if (selected.size === 0) {
    notify("请先勾选地址");
    return;
  }
  try {
    await Promise.all([...selected].map((id) =>
      customersApi.deleteCustomerContact(id)
    ));
    customerContactRows.value = customerContactRows.value.filter((item) => !selected.has(item.id));
    selectedAddressBookIds.value = [];
    if (selected.has(editingAddressBookId.value)) {
      resetAddressBookForm();
      addressBookFormOpen.value = false;
    }
    notify(`已删除 ${selected.size} 条联系人地址`);
  } catch (error) {
    notify(error.message);
  }
}

async function hideHistoricalAddress(option) {
  const address = String(option?.value || "").trim();
  const key = addressOptionKey(address);
  if (!address || !key) return;
  try {
    const hidden = await customersApi.hideAddressHistory({ key, address });
    hiddenAddressHistoryRows.value = [hidden, ...hiddenAddressHistoryRows.value.filter((item) => item.key !== hidden.key)];
    notify("历史地址已删除");
  } catch (error) {
    notify(error.message);
  }
}

async function applyAddressBookEntry(option) {
  applyLocationOption(option);
  if (option?.source !== "联系人") return;
  try {
    const contactSynced = await syncAddressBookEntryToCustomerContact({
      area: option.area || "",
      contact: option.contact || "",
      phone: option.phone || "",
      address: option.address || option.value || "",
      note: option.note || ""
    });
    if (contactSynced) notify("地址已写入，联系人已同步");
  } catch (error) {
    notify(`地址已写入，联系人同步失败：${error.message}`);
  }
}

function handleLocationInput(target) {
  const form = currentLocationForm();
  if (locationPicker.open && locationPicker.target === target) {
    locationPicker.keyword = form[target] || "";
  }
  if (locationPicker.owner === "order") {
    scheduleAutoFreightSync();
  }
}

function applyLocationOption(option) {
  const detail = String(locationPicker.detail || "").trim();
  clearDispatchLocationDraftsForPickerTarget();
  setCurrentLocationEntries(locationPicker.target, [locationEntryFromOption(locationPicker.target, option, detail)]);
  if (locationPicker.owner === "order" && locationPicker.target === "unloading") {
    orderForm.unloadingContact = option.contact || "";
    orderForm.unloadingPhone = option.phone || "";
  } else if (locationPicker.owner === "order") {
    orderForm.loadingContact = option.contact || "";
    orderForm.loadingPhone = option.phone || "";
  }
  closeLocationPicker();
  if (locationPicker.owner === "order") {
    scheduleAutoFreightSync();
  }
}

function handleTemplateLocationLevelChange(level) {
  if (level === 1) {
    locationPicker.level2 = "";
    locationPicker.level3 = "";
  } else if (level === 2) {
    locationPicker.level3 = "";
  }
  locationPicker.keyword = templateLocationValue.value;
}

function applyTemplateLocationSelection() {
  const value = templateLocationValue.value;
  if (!value) {
    notify("请选择一级目录");
    return;
  }
  const detail = String(locationPicker.detail || "").trim();
  clearDispatchLocationDraftsForPickerTarget();
  setCurrentLocationEntries(locationPicker.target, [{
    city: locationPicker.level1,
    district: locationPicker.level2,
    detail
  }]);
  closeLocationPicker();
  if (locationPicker.owner === "order") {
    scheduleAutoFreightSync();
  }
}

function applyCustomLocation() {
  if (locationPicker.mode === "template" && templateLocationValue.value) {
    applyTemplateLocationSelection();
    return;
  }
  const value = String(locationPicker.keyword || locationPicker.detail || "").trim();
  if (!value) {
    notify("请输入地址或选择片区");
    return;
  }
  clearDispatchLocationDraftsForPickerTarget();
  setCurrentLocationEntries(locationPicker.target, [{ city: "", district: "", detail: value }]);
  closeLocationPicker();
  if (locationPicker.owner === "order") {
    scheduleAutoFreightSync();
  }
}

function money(value) {
  return Number(value || 0).toLocaleString();
}

function moneyPair(hkd = 0, rmb = 0) {
  const parts = [];
  if (Number(hkd || 0) !== 0) parts.push(`HKD ${money(hkd)}`);
  if (Number(rmb || 0) !== 0) parts.push(`RMB ${money(rmb)}`);
  return parts.join(" / ") || "-";
}

function moneyPairSuffix(hkd = 0, rmb = 0) {
  const parts = [];
  if (Number(hkd || 0) !== 0) parts.push(`${money(hkd)} HKD`);
  if (Number(rmb || 0) !== 0) parts.push(`${money(rmb)} RMB`);
  return parts.join(" / ") || "-";
}

function quantityNumber(value) {
  const match = String(value ?? "").replace(/,/g, "").match(/-?\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : 0;
}

async function apiFetchListFrom(request, label, options = {}) {
  try {
    const data = await request();
    return Array.isArray(data) ? data : [];
  } catch (error) {
    console.warn(`${label} 加载失败`, error);
    if (!options.silent) {
      notify(`${label} 加载失败：${error.message}`);
    }
    return [];
  }
}

