      needsWeighing: booleanFlag(order.needsWeighing, false),
      direction: order.direction || "",
      tonnage: order.tonnage || "",
      currency: order.currency || "",
      quantity: String(order.quantity || ""),
      weight: order.weight || "",
      vehicleSource: orderVehicleSource,
      supplier: order.supplier || "",
      plate: order.plate || "",
      driver: order.driver || "",
      hkDriver: order.hkDriver || "",
      mainlandDriver: order.mainlandDriver || "",
	      transportMode: normalizeTransportMode(order.transportMode || (orderVehicleSource === OWN_VEHICLE_SOURCE ? "单司机" : "")),
	      loading: order.loading || "",
	      loadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(order, "loading")),
	      loadingContact: order.loadingContact || "",
	      loadingPhone: order.loadingPhone || "",
	      unloading: order.unloading || "",
	      unloadingLocations: cloneDispatchLocationEntries(recordDispatchLocationEntries(order, "unloading")),
      unloadingContact: order.unloadingContact || "",
      unloadingPhone: order.unloadingPhone || "",
      date: order.date || "",
      receivableHKD: Number(order.receivableHKD || 0),
      receivableRMB: Number(order.receivableRMB || 0),
      status: order.status || "",
      remark: order.remark || "",
      tripNoEnabled: Boolean(order.tripNoEnabled),
      tripNo: order.tripNo || "",
      sixSheetEnabled: Boolean(order.sixSheetEnabled),
      sixSheetNo: order.sixSheetNo || "",
      customsNo: "",
      customsUnit: "",
      customsItemCount: "",
      customsPageCount: ""
    });
    ensureOrderFreightCurrency();
    if (orderUsesRelayDrivers.value && !orderForm.hkDriver && orderForm.driver.includes(" / ")) {
      const [hkDriver = "", mainlandDriver = ""] = orderForm.driver.split(" / ");
      orderForm.hkDriver = hkDriver.trim();
      orderForm.mainlandDriver = mainlandDriver.trim();
      orderForm.driver = "";
    }
    loadCustomsFieldsFromRemark(order.remark || "");
    applyOrderRequiredFieldDefaults({ force: true });
    orderFees.value = (order.fees?.length ? order.fees : [
      {
        feeItemId: "",
        category: "正常",
        name: "中港运费",
        quantity: 1,
        unitPrice: 0,
        currency: order.currency || (order.receivableRMB ? "人民币" : "港币"),
        amount: 0,
        _manualUnitPrice: false,
        _manualAmount: false,
        costCurrency: order.currency || "港币",
        remark: ""
      }
    ]).map((fee) => {
      const savedCost = normalizeFeeCost(fee);
      const hasUnitPriceManualFlag = fee.unitPriceManual !== undefined || fee.unit_price_manual !== undefined || fee.manualUnitPrice !== undefined || fee._manualUnitPrice !== undefined;
      const hasAmountManualFlag = fee.amountManual !== undefined || fee.amount_manual !== undefined || fee.manualAmount !== undefined || fee._manualAmount !== undefined;
      const hasCurrencyManualFlag = fee.currencyManual !== undefined || fee.currency_manual !== undefined || fee.manualCurrency !== undefined || fee._manualCurrency !== undefined;
      const manualUnitPrice = hasUnitPriceManualFlag
        ? booleanFlag(fee.unitPriceManual ?? fee.unit_price_manual ?? fee.manualUnitPrice ?? fee._manualUnitPrice, false)
        : false;
      const legacyManualAmount = !hasAmountManualFlag
        && isFreightFeeRow(fee)
        && fee.amount !== undefined
        && fee.amount !== null
        && String(fee.amount).trim() !== ""
        && !fee.autoFreight;
      const manualAmount = hasAmountManualFlag
        ? booleanFlag(fee.amountManual ?? fee.amount_manual ?? fee.manualAmount ?? fee._manualAmount, false)
        : legacyManualAmount;
      const manualCurrency = hasCurrencyManualFlag
        ? booleanFlag(fee.currencyManual ?? fee.currency_manual ?? fee.manualCurrency ?? fee._manualCurrency, false)
        : (isFreightFeeRow(fee) && Boolean(fee.currency) && Boolean(order.currency) && currencyCodeDisplay(fee.currency) !== currencyCodeDisplay(order.currency));
      const hasCostManualFlag = fee.costManual !== undefined || fee.cost_manual !== undefined || fee.manualCost !== undefined || fee._manualCost !== undefined;
      const row = normalizeOrderFeeRow({
        id: fee.id || "",
        _clientKey: fee.clientKey || fee.client_key || fee._clientKey || "",
        feeItemId: fee.feeItemId || fee.fee_item_id || "",
        category: fee.category || "正常",
        name: fee.name || "",
        quantity: fee.quantity,
        unitPrice: fee.unitPrice ?? fee.unit_price,
        _manualUnitPrice: manualUnitPrice,
        currency: fee.currency || "",
        amount: fee.amount,
        _manualAmount: manualAmount,
        cost: savedCost ?? 0,
        _savedCost: savedCost,
        costCurrency: fee.costCurrency || fee.cost_currency || fee._costCurrency || fee.currency || orderForm.currency || "港币",
        advanceAddress: fee.advanceAddress || fee.advance_address || "",
        remark: fee.remark || "",
        driverRole: fee.driverRole || fee.driver_role || "",
        driverName: fee.driverName || fee.driver_name || "",
        autoFreight: Boolean(fee.autoFreight)
      });
      return {
        ...row,
        _manualFreightAmount: isFreightFeeRow(row) && Boolean(row._manualAmount),
        _manualAssignee: String(row.driverRole || "").trim() === "手动指定" || Boolean(row.driverName),
        _manualCurrency: manualCurrency,
        _manualCost: hasCostManualFlag ? booleanFlag(fee.costManual ?? fee.cost_manual ?? fee.manualCost ?? fee._manualCost, false) : false
      };
    });
    loadOrderFiles(order.no);
  } else {
    resetOrderForm();
    if (customer?.id) {
      orderForm.customerId = customer.id;
      orderForm.customer = customer.name || "";
    }
    applyOrderRequiredFieldDefaults({ force: true });
    const bindableRows = bindableDispatchRowsForCustomer(orderForm.customer);
    if (bindableRows.length) {
      const targetRow = bindableRows[0];
      const shouldBind = window.confirm(`发现该客户有未绑定排车单 ${targetRow.dispatchNo}，是否绑定并自动带入排车信息？`);
      if (shouldBind) applyDispatchRowToOrderForm(targetRow);
    }
  }
  orderCustomerKeyword.value = partnerDisplayLabel(orderForm.customer, "客户") || orderForm.customer || "";
  orderCustomerPickerOpen.value = false;
  orderSupplierKeyword.value = supplierDisplayLabel(orderForm.supplier) || orderForm.supplier || "";
  orderSupplierPickerOpen.value = false;
  orderModalOpen.value = true;
  scheduleAutoFreightSync();
  scheduleOrderFeeCostSync();
}

function closeOrderModal() {
  stopModalDrag();
  orderModalOpen.value = false;
  orderAuditMode.value = false;
  orderViewMode.value = false;
  closeOrderFeeNamePicker();
  orderSupplierPickerOpen.value = false;
}

async function submitOrderModal() {
  if (orderViewMode.value) {
    notify("查看模式不可修改订单");
    return;
  }
  if (orderAuditMode.value) {
    await confirmOrderAudit();
    return;
  }
  await saveOrder();
}

async function saveOrder(options = {}) {
  const closeAfterSave = options.closeAfterSave !== false;
  const notifySuccess = options.notifySuccess !== false;
  try {
    if (orderAttachmentUploading.value) {
      notify("附件正在上传，请稍候再保存订单");
      return null;
    }
    if (hasMissingAdvanceFeeAmount()) {
      notify("代垫类型收费项目请先填写金额");
      return null;
    }
    if (orderModalStatusValue() === "已签收" && orderSignRequiredMissingLabels.value.length) {
      notify(orderSignRequiredMessage.value);
      return null;
    }
    if (!(await confirmSaveOrderWithMissingAdvanceReceipts())) return null;
    loading.value = true;
    if (orderIsCustomsOnly.value) {
      clearOrderTransportFields();
    } else {
      handleOrderVehicleSourceChange();
    }
    normalizeOrderDriversForSave();
    syncAutoFreightFee();
    normalizeOrderFeeRows();
    syncOrderFeeCosts();
    const payload = {
      ...buildNormalizedOrderPayload(),
      fees: orderFees.value
        .map((fee) => {
          const normalized = normalizeOrderFeeRow(fee);
          return {
            ...normalized,
            clientKey: normalizeOrderFeeClientKey(normalized._clientKey),
            name: normalizeUserText(normalized.name, { singleLine: true, compactCjkSpacing: true }),
            category: normalizeUserText(normalized.category, { singleLine: true, compactCjkSpacing: true }),
            currency: normalizeUserText(normalized.currency, { singleLine: true, compactCjkSpacing: true }),
            remark: normalizeUserText(normalized.remark, { singleLine: true, compactCjkSpacing: true }),
            driverRole: normalizeUserText(normalized.driverRole, { singleLine: true, compactCjkSpacing: true }),
            driverName: normalizeUserText(normalized.driverName, { singleLine: true, compactCjkSpacing: true }),
            advanceAddress: normalizeUserText(normalized.advanceAddress, { singleLine: true, compactCjkSpacing: true }),
            cost: normalizeFeeCost(fee) ?? 0,
            costCurrency: normalizeCostCenterCurrency(fee.costCurrency || fee._costCurrency || fee.currency || orderForm.currency || "港币"),
            unitPriceManual: Boolean(fee._manualUnitPrice),
            amountManual: Boolean(fee._manualAmount),
            costManual: Boolean(fee._manualCost)
          };
        })
        .filter((fee) => String(fee.name || "").trim())
    };
    const item = editingOrderNo.value
      ? await ordersApi.updateOrder(editingOrderNo.value, payload)
      : await ordersApi.createOrder(payload);
    orderRows.value = editingOrderNo.value
      ? orderRows.value.map((row) => row.no === item.no ? item : row)
      : [item, ...orderRows.value];
    if (item.customerId) {
      selectedCustomerId.value = item.customerId;
      activatePartnerContextById(item.customerId);
    } else {
      activatePartnerContext();
    }
    activeCustomerDetailTab.value = "订单管理";
    if (pendingDispatchBindId.value) {
      const target = dispatchPlanRows.value.find((row) => row.id === pendingDispatchBindId.value);
      if (target) {
        target.orderNo = item.no;
        target.dispatchNo = item.dispatchNo || target.dispatchNo;
        target.customer = item.customer || target.customer;
        target.port = item.port || target.port;
        target.direction = item.direction || target.direction;
        target.tonnage = item.tonnage || target.tonnage;
        target.quantity = item.quantity || target.quantity;
	        target.weight = item.weight || target.weight;
	        target.loading = item.loading || target.loading;
	        target.loadingLocations = cloneDispatchLocationEntries(recordDispatchLocationEntries(item, "loading", target));
	        target.unloading = item.unloading || target.unloading;
	        target.unloadingLocations = cloneDispatchLocationEntries(recordDispatchLocationEntries(item, "unloading", target));
        target.vehicleSource = item.vehicleSource || target.vehicleSource;
        target.supplier = item.supplier || target.supplier;
        target.plate = item.plate || target.plate;
        saveDispatchPlan({ silent: true });
      }
      pendingDispatchBindId.value = "";
    }
    editingOrderNo.value = item.no;
    if (closeAfterSave) closeOrderModal();
    if (notifySuccess) notify(`已保存订单：${item.no}`);
    return item;
  } catch (error) {
    notify(error.message);
    return null;
  } finally {
    loading.value = false;
  }
}

function syncLocalDispatchRowsForOrderStatus(order = {}, dispatchStatus = "") {
  const orderNo = String(order.no || "").trim();
  const dispatchNo = String(order.dispatchNo || "").trim();
  if (!orderNo && !dispatchNo) return;
  dispatchPlanRows.value = dispatchPlanRows.value.map((row) => {
    const matchesOrder = orderNo && String(row.orderNo || row.order?.no || "").trim() === orderNo;
    const matchesDispatch = dispatchNo && String(row.dispatchNo || row.order?.dispatchNo || "").trim() === dispatchNo;
    if (!matchesOrder && !matchesDispatch) return row;
    const previousStatus = dispatchStatusValueForRow(row);
    return {
      ...row,
      status: dispatchStatus,
      previousStatus: previousStatus && previousStatus !== dispatchStatus ? previousStatus : row.previousStatus || ""
    };
  });
}

function orderModalStatusValue() {
  return String(orderForm.status || "").trim();
}

const orderModalCurrentOrder = computed(() =>
  editingOrderNo.value
    ? orderRows.value.find((item) => item.no === editingOrderNo.value) || null
    : null
);

const showOrderModalAuditAction = computed(() =>
  Boolean(editingOrderNo.value)
  && !orderAuditMode.value
  && !orderViewMode.value
  && orderModalStatusValue() === "已签收"
  && canAuditOrder(orderModalCurrentOrder.value)
);

const orderModalAuditActionTitle = computed(() =>
  orderAuditButtonTitle(orderModalCurrentOrder.value || { status: orderModalStatusValue() })
);

function orderStatusActionDisabled(targetStatus = "") {
  const status = orderModalStatusValue();
  if (status === "已签收") return true;
  if (targetStatus === "异常滞留" && ["异常滞留", "费用待确认"].includes(status)) return true;
  if (targetStatus === "已签收" && orderSignRequiredMissingLabels.value.length) return true;
  if (targetStatus === "已签收" && !orderFreightAmountReadyForSign()) return true;
  return false;
}

function orderFreightAmountReadyForSign() {
  const freightFee = orderFees.value.find((fee) => isCrossBorderFreightFee(fee) || String(fee?.name || "").trim() === "中港运费");
  return Number(freightFee?.amount || 0) > 0;
}

async function auditOrderFromOrderModal() {
  if (!showOrderModalAuditAction.value) {
    notify(orderModalAuditActionTitle.value || "只有已签收订单才能审核");
    return;
  }
  await confirmOrderAudit();
}

async function completeOrderFromOrderModal(targetStatus = "") {
  if (orderViewMode.value || orderAuditMode.value) return;
  if (orderStatusActionDisabled(targetStatus)) {
    if (targetStatus === "已签收" && orderSignRequiredMessage.value) notify(orderSignRequiredMessage.value);
    return;
  }
  const orderStatus = targetStatus === "异常滞留" ? "费用待确认" : targetStatus;
  const dispatchStatus = targetStatus === "异常滞留" ? "异常滞留" : targetStatus;
  if (!["已签收", "费用待确认"].includes(orderStatus)) return;
  const saved = await saveOrder({ closeAfterSave: false, notifySuccess: false });
  if (!saved?.no) return;
  try {
    loading.value = true;
    const updated = await ordersApi.updateOrderStatus(saved.no, orderStatus);
    replaceOrder(updated);
    syncLocalDispatchRowsForOrderStatus(updated, dispatchStatus);
    if (canAccessModule("dispatchBoard")) {
      await loadDispatchPlansForCurrentFilter();
    }
    closeOrderModal();
    notify(`订单 ${updated.no} 已标记为${targetStatus}`);
  } catch (error) {
    notify(error.message || `更新${targetStatus}状态失败`);
  } finally {
    loading.value = false;
  }
}

async function loadOrderFiles(orderNo = editingOrderNo.value) {
  orderAttachmentRows.value = orderNo ? await loadFiles("order", orderNo) : [];
}

function orderUploadStatusOptions() {
  return {
    onStart() {
      orderAttachmentUploading.value = true;
    },
    onStatus: setOrderAttachmentUploadStatus,
    onFinish() {
      orderAttachmentUploading.value = false;
      if (orderAttachmentUploadStatus.value) {
        scheduleClearOrderAttachmentUploadStatus(orderAttachmentUploadTone.value === "error" ? 7000 : 4200);
      }
    }
  };
}

async function uploadOrderFiles(files, category = "订单附件") {
  if (orderAttachmentUploading.value) {
    notify("附件正在上传，请稍候");
    return false;
  }
  const result = await uploadStoredFilesFor("order", editingOrderNo.value, category, files, orderAttachmentRows, {
    ...orderUploadStatusOptions(),
    missingEntityMessage: "请先保存订单，再上传附件",
    onProgress(file, index, total) {
      setOrderAttachmentUploadStatus(`正在上传 ${index + 1}/${total}：${file.name}`, "busy");
    },
    onComplete({ success, failed }) {
      const tone = failed ? "error" : "success";
      const message = failed
        ? `已上传 ${success} 个附件，${failed} 个失败`
        : `已上传 ${success} 个附件`;
      setOrderAttachmentUploadStatus(message, tone);
      scheduleClearOrderAttachmentUploadStatus(failed ? 7000 : 4200);
    }
  });
  return result.failed === 0;
}

function openOrderFileUploadPanel() {
  if (orderAttachmentUploading.value) {
    notify("附件正在上传，请稍候");
    return;
  }
  if (!editingOrderNo.value) {
    notify("请先保存订单，再上传附件");
    return;
  }
  openUploadPanel({
    title: "上传订单附件",
    description: "可拖拽单据 Excel、PDF 或图片，也可以从微信复制图片后直接粘贴。",
    accept: FILE_UPLOAD_ACCEPT,
    multiple: true,
    handler(files) {
      return uploadOrderFiles(files, "订单附件");
    }
  });
}

function uploadOrderFile(event) {
  if (event?.target?.files) {
    const files = Array.from(event.target.files || []);
    event.target.value = "";
    return uploadOrderFiles(files, "订单附件");
  }
  openOrderFileUploadPanel();
}

function feeAttachmentCategory(fee, index) {
  const key = ensureOrderFeeClientKey(fee);
  if (key) return `收费项目行-${key}`;
  const name = String(fee?.name || "").trim();
  return `收费项目-${name || `第${index + 1}行`}`;
}

function legacyFeeAttachmentCategory(fee, index) {
  const name = String(fee?.name || "").trim();
  return `收费项目-${name || `第${index + 1}行`}`;
}

function isFirstFeeRowWithName(fee, index) {
  const name = String(fee?.name || "").trim();
  if (!name) return false;
  return orderFees.value.findIndex((item) => String(item?.name || "").trim() === name) === index;
}

function feeAttachmentRows(fee, index) {
  const category = feeAttachmentCategory(fee, index);
  const legacyCategory = legacyFeeAttachmentCategory(fee, index);
  return orderAttachmentRows.value.filter((file) => {
    if (file.category === category) return true;
    return file.category === legacyCategory && isFirstFeeRowWithName(fee, index);
  });
}

function orderFeeHasContent(fee = {}) {
  return Boolean(
    String(fee.name || "").trim()
    || String(fee.quantity || "").trim()
    || normalizeFeeAmount(fee)
    || normalizeFeeUnitPrice(fee)
    || String(fee.remark || "").trim()
  );
}

function missingAdvanceFeeAmountLabels() {
  return orderFees.value
    .map((fee, index) => ({ fee, index }))
    .filter(({ fee }) => feeCategoryLabel(fee) === "代垫" && orderFeeHasContent(fee))
    .filter(({ fee }) => Number(fee.amount || 0) <= 0)
    .map(({ fee, index }) => String(fee.name || "").trim() || `第 ${index + 1} 行代垫费用`);
}

function hasMissingAdvanceFeeAmount() {
  return missingAdvanceFeeAmountLabels().length > 0;
}

function isReceiptAttachmentFile(file = {}) {
  const mime = String(file.mime || file.type || "").toLowerCase();
  const filename = String(file.filename || file.name || "").toLowerCase();
  return mime.startsWith("image/")
    || mime === "application/pdf"
    || /\.(png|jpe?g|webp|gif|bmp|tiff?|avif|heic|heif|pdf)$/i.test(filename);
}

function feeHasReceiptAttachment(fee, index) {
  return feeAttachmentRows(fee, index).some(isReceiptAttachmentFile);
}

function missingAdvanceReceiptLabels() {
  return orderFees.value
    .map((fee, index) => ({ fee, index }))
    .filter(({ fee }) => orderFeeHasContent(fee) && feeCategoryLabel(fee) === "代垫")
    .filter(({ fee, index }) => !feeHasReceiptAttachment(fee, index))
    .map(({ fee, index }) => String(fee.name || "").trim() || `第 ${index + 1} 行代垫费用`);
}

function missingAdvanceReceiptMessage(labels = []) {
  const names = labels.slice(0, 5).join("、");
  const suffix = labels.length > 5 ? `等 ${labels.length} 项` : "";
  return [
    `检测到代垫费用「${names}${suffix}」还没有上传对应票据图片或 PDF。`,
    "票据缺失可能影响后续对账和审核，建议先补齐票据。",
    "",
    "是否仍然保存订单？"
  ].join("\n");
}

async function confirmSaveOrderWithMissingAdvanceReceipts() {
  if (editingOrderNo.value) {
    await loadOrderFiles(editingOrderNo.value);
  }
  const missingLabels = missingAdvanceReceiptLabels();
  if (!missingLabels.length) return true;
  return window.confirm(missingAdvanceReceiptMessage(missingLabels));
}

function openOrderFeeUploadPanel(fee, index) {
  if (orderAttachmentUploading.value) {
    notify("附件正在上传，请稍候");
    return;
  }
  if (!editingOrderNo.value) {
    notify("请先保存订单，再上传收费项目附件");
    return;
  }
  if (!String(fee?.name || "").trim()) {
    notify("请先选择收费项目，再上传附件");
    return;
  }
  const category = feeAttachmentCategory(fee, index);
  openUploadPanel({
    title: `上传${fee.name}票据`,
    description: "支持拖拽、选择文件和粘贴微信复制的图片，上传后会归档到当前收费项目。",
    accept: FILE_UPLOAD_ACCEPT,
    multiple: true,
    handler(files) {
      return uploadOrderFiles(files, category);
    }
  });
}

function uploadOrderFeeFile(fee, index, event) {
  if (event?.target?.files) {
    const files = Array.from(event.target.files || []);
    event.target.value = "";
    if (!files.length) return false;
    return uploadOrderFiles(files, feeAttachmentCategory(fee, index));
  }
  openOrderFeeUploadPanel(fee, index);
}

async function loadCustomerFiles() {
  customerFileRows.value = selectedCustomer.value
    ? await filesApi.listFiles("customer", selectedCustomer.value.id, { includeOrderFiles: true })
    : [];
}

async function uploadCustomerFiles(files) {
  const result = await uploadStoredFilesFor("customer", selectedCustomer.value?.id, "客户附件", files, customerFileRows, {
    missingEntityMessage: "请先保存客户，再上传附件"
  });
  await loadCustomerFiles().catch((error) => notify(error.message));
  return result.failed === 0;
}

function openCustomerFileUploadPanel() {
  if (!selectedCustomer.value?.id) {
    notify("请先保存客户，再上传附件");
    return;
  }
  openUploadPanel({
    title: "上传客户附件",
    description: "客户合同、资质、往来附件会保存到 OSS 附件库。",
    accept: FILE_UPLOAD_ACCEPT,
    multiple: true,
    handler: uploadCustomerFiles
  });
}

function uploadCustomerFile(event) {
  if (event?.target?.files) {
    const files = Array.from(event.target.files || []);
    event.target.value = "";
    return uploadCustomerFiles(files);
  }
  openCustomerFileUploadPanel();
}

async function loadVehicleFiles() {
  vehicleFileRows.value = selectedVehicle.value ? await loadFiles("vehicle", selectedVehicle.value.plate) : [];
}

async function uploadVehicleFiles(files, category = "车辆证件", plate = selectedVehicle.value?.plate) {
  const result = await uploadStoredFilesFor("vehicle", plate, category, files, vehicleFileRows, {
    missingEntityMessage: category.includes("保险") ? "请先保存车辆，再上传保险单据" : "请先保存车辆，再上传证件"
  });
  return result.failed === 0;
}

function openVehicleFileUploadPanel() {
  if (!selectedVehicle.value?.plate) {
    notify("请先保存车辆，再上传证件");
    return;
  }
  openUploadPanel({
    title: "上传车辆证件",
    description: "保险单、年审资料等文件会保存到 OSS 附件库。",
    accept: FILE_UPLOAD_ACCEPT,
    multiple: true,
    handler(files) {
      return uploadVehicleFiles(files, "车辆证件", selectedVehicle.value?.plate);
    }
  });
}

function uploadVehicleFile(event) {
  if (event?.target?.files) {
    const files = Array.from(event.target.files || []);
    event.target.value = "";
    return uploadVehicleFiles(files);
  }
  openVehicleFileUploadPanel();
}

function openVehicleInsuranceUploadPanel(category) {
  const targetPlate = editingVehiclePlate.value || "";
  if (!targetPlate) {
    notify("请先保存车辆，再上传保险单据");
    return;
  }
  if (vehicleForm.plate && vehicleForm.plate !== editingVehiclePlate.value) {
    notify("车牌已修改，请先保存车辆后再上传保险单据");
    return;
  }
  openUploadPanel({
    title: `上传${category}`,
    description: "支持拖拽保险单图片或 PDF，也可以从微信复制图片后粘贴。",
    accept: FILE_UPLOAD_ACCEPT,
    multiple: true,
    handler(files) {
      return uploadVehicleFiles(files, category, targetPlate);
    }
  });
}

function uploadVehicleInsuranceFile(category, event) {
  if (event?.target?.files) {
    const files = Array.from(event.target.files || []);
    event.target.value = "";
    return uploadVehicleFiles(files, category, editingVehiclePlate.value || "");
  }
  openVehicleInsuranceUploadPanel(category);
}

function vehicleInsuranceFiles(category) {
  return vehicleFileRows.value.filter((file) => file.category === category);
}

async function loadDriverFiles() {
  driverFileRows.value = selectedDriver.value ? await loadFiles("driver", selectedDriver.value.id) : [];
}

async function uploadDriverFiles(files) {
  const result = await uploadStoredFilesFor("driver", selectedDriver.value?.id, "司机证件", files, driverFileRows, {
    missingEntityMessage: "请先保存司机，再上传证件"
  });
  return result.failed === 0;
}

function openDriverFileUploadPanel() {
  if (!selectedDriver.value?.id) {
    notify("请先保存司机，再上传证件");
    return;
  }
  openUploadPanel({
    title: "上传司机证件",
    description: "驾驶证、身份证、港澳证等文件会保存到 OSS 附件库。",
    accept: FILE_UPLOAD_ACCEPT,
    multiple: true,
    handler: uploadDriverFiles
  });
}

function uploadDriverFile(event) {
  if (event?.target?.files) {
    const files = Array.from(event.target.files || []);
    event.target.value = "";
    return uploadDriverFiles(files);
  }
  openDriverFileUploadPanel();
}

function addFeeRow() {
  const row = createBlankFeeRow();
  row.currency = orderForm.currency || "";
  row.costCurrency = orderForm.currency || "港币";
  orderFees.value.push(row);
}

function ensureTrailingBlankFeeRow() {
  const last = orderFees.value[orderFees.value.length - 1];
  if (!last || last.feeItemId || last.name || last.amount || last.remark) {
    addFeeRow();
  }
}

function removeFeeRow(index) {
  if (orderFees.value.length === 1) return;
  orderFees.value.splice(index, 1);
}

function moveFeeRow(index, offset) {
  const targetIndex = index + offset;
  if (index < 0 || index >= orderFees.value.length) return;
  if (targetIndex < 0 || targetIndex >= orderFees.value.length) return;
  const [movedRow] = orderFees.value.splice(index, 1);
  orderFees.value.splice(targetIndex, 0, movedRow);
  if (orderFeeNamePickerOpenIndex.value === index) {
    orderFeeNamePickerOpenIndex.value = targetIndex;
  } else if (orderFeeNamePickerOpenIndex.value === targetIndex) {
    orderFeeNamePickerOpenIndex.value = index;
  }
  if (feeItemManagerTargetIndex.value === index) {
    feeItemManagerTargetIndex.value = targetIndex;
  } else if (feeItemManagerTargetIndex.value === targetIndex) {
    feeItemManagerTargetIndex.value = index;
  }
}

function replaceOrder(updatedOrder) {
  orderRows.value = orderRows.value.map((item) => item.no === updatedOrder.no ? updatedOrder : item);
}

function canManageOrderAudit() {
  return currentAccountCanManageOrderAudit.value;
}

function orderAuditPermissionMessage() {
  return "只有财务或管理员可以审核或取消审核订单";
}

function orderStatusValue(order = {}) {
  return String(order?.status || "").trim();
}

function canAuditOrder(order = {}) {
  return canManageOrderAudit() && orderStatusValue(order) === "已签收";
}

function canCancelAuditOrder(order = {}) {
  return canManageOrderAudit() && orderStatusValue(order) === "已审核";
}

function canEditOrder(order = {}) {
  const status = orderStatusValue(order);
  return !status || status !== "已审核";
}

const orderReadOnlyMode = computed(() => orderAuditMode.value || orderViewMode.value);

watch(
  () => [orderModalOpen.value, orderForm.customerId, orderForm.customer, orderForm.businessType, customerRows.value.length],
  () => {
    if (!orderModalOpen.value || orderReadOnlyMode.value) return;
    applyOrderRequiredFieldDefaults();
  }
);

function orderEditButtonTitle(order = {}) {
  return canEditOrder(order) ? "编辑订单" : "查看订单";
}

function orderEditButtonLabel(order = {}) {
  return canEditOrder(order) ? "编辑" : "查看";
}

function orderEditButtonIcon(order = {}) {
  return canEditOrder(order) ? "edit" : "eye";
}

function orderAuditButtonTitle(order = {}) {
  if (!canManageOrderAudit()) return orderAuditPermissionMessage();
  if (canAuditOrder(order)) return "待审核";
  if (orderStatusValue(order) === "已审核") return "订单已审核";
  return "订单状态为已签收后才能审核";
}

function orderCancelAuditButtonTitle(order = {}) {
  if (!canManageOrderAudit()) return orderAuditPermissionMessage();
  return orderStatusValue(order) === "已审核" ? "取消审核" : "只有已审核订单才能取消审核";
}

async function auditOrder(order) {
  if (!canManageOrderAudit()) {
    notify(orderAuditPermissionMessage());
    return;
  }
  if (order.status === "已审核") {
    notify("该订单已审核");
    return;
  }
  if (!canAuditOrder(order)) {
    notify("只有已签收订单才能审核");
    return;
  }
  await openOrderModal(null, order, { audit: true });
}

async function confirmOrderAudit() {
  if (!canManageOrderAudit()) {
    notify(orderAuditPermissionMessage());
    return;
  }
  const orderNo = editingOrderNo.value;
  const order = orderRows.value.find((item) => item.no === orderNo) || null;
  if (!orderNo || !order) {
    notify("当前审核订单不存在");
    return;
  }
  if (!canAuditOrder(order)) {
    notify(order.status === "已审核" ? "该订单已审核" : "只有已签收订单才能审核");
    return;
  }
  try {
    loading.value = true;
    const updated = await ordersApi.updateOrderStatus(orderNo, "已审核");
    replaceOrder(updated);
    closeOrderModal();
    notify(`订单 ${orderNo} 已审核`);
  } catch (error) {
    notify(error.message);
  } finally {
    loading.value = false;
  }
}

async function cancelAuditOrder(order) {
  if (!canManageOrderAudit()) {
    notify(orderAuditPermissionMessage());
    return;
  }
  if (order.status !== "已审核") {
    notify("只有已审核订单才需要取消审核");
    return;
  }
  if (!window.confirm(`确定取消审核订单 ${order.no}？`)) return;
  try {
    const updated = await ordersApi.updateOrderStatus(order.no, "已签收");
    replaceOrder(updated);
    notify(`订单 ${order.no} 已取消审核`);
  } catch (error) {
    notify(error.message);
  }
}

async function auditPendingOrders() {
  if (!canManageOrderAudit()) {
    notify(orderAuditPermissionMessage());
    return;
  }
  const scope = selectedOrderNos.value.length
    ? filteredOrders.value.filter((item) => selectedOrderNoSet.value.has(String(item.no)))
    : filteredOrders.value;
  const auditableOrders = scope.filter(canAuditOrder);
  const pendingNos = auditableOrders.map((item) => item.no);
  if (pendingNos.length === 0) {
    notify("当前没有已签收订单可审核");
    return;
  }
  try {
    const updatedOrders = await ordersApi.auditOrders({ orderNos: pendingNos });
    const updatedMap = new Map(updatedOrders.map((item) => [item.no, item]));
    orderRows.value = orderRows.value.map((item) => updatedMap.get(item.no) || item);
    selectedOrderNos.value = [];
    notify(`已批量审核 ${updatedOrders.length} 条订单`);
  } catch (error) {
    notify(error.message);
  }
}

async function cancelSelectedAudits() {
  if (!canManageOrderAudit()) {
    notify(orderAuditPermissionMessage());
    return;
  }
  const targets = filteredOrders.value.filter((item) => selectedOrderNoSet.value.has(String(item.no)));
  if (targets.length === 0) {
    notify("请先勾选要取消审核的订单");
    return;
  }
  const auditedOrders = targets.filter((item) => item.status === "已审核");
  if (auditedOrders.length === 0) {
    notify("已勾选订单没有已审核状态");
    return;
  }
  if (!window.confirm(`确定取消审核 ${auditedOrders.length} 条订单？`)) return;
  try {
    const updatedOrders = await Promise.all(auditedOrders.map((order) =>
      ordersApi.updateOrderStatus(order.no, "已签收")
    ));
    const updatedMap = new Map(updatedOrders.map((item) => [item.no, item]));
    orderRows.value = orderRows.value.map((item) => updatedMap.get(item.no) || item);
    selectedOrderNos.value = [];
    notify(`已取消审核 ${updatedOrders.length} 条订单`);
  } catch (error) {
    notify(error.message);
  }
}

async function deleteSelectedOrders() {
  const targets = filteredOrders.value.filter((item) => selectedOrderNoSet.value.has(String(item.no)));
  if (targets.length === 0) {
    notify("请先勾选要删除的订单");
    return;
  }
  const locked = targets.filter((item) => !canDeleteOrder(item));
  if (locked.length) {
    notify(currentAccountCanDeleteAdminOnlyOrder.value ? "已审核订单不可删除，请取消勾选后再操作" : "已审核、待确认或通关中订单不可删除，请取消勾选后再操作");
    return;
  }
  if (!window.confirm(`确定删除 ${targets.length} 条订单？删除后会进入回收站。`)) return;
  try {
    for (const order of targets) {
      await ordersApi.deleteOrder(order.no);
    }
    const deletedNos = new Set(targets.map((item) => item.no));
    orderRows.value = orderRows.value.filter((item) => !deletedNos.has(item.no));
    removeDispatchRowsByOrderRefs(targets);
    selectedOrderNos.value = [];
    notify(`已删除 ${targets.length} 条订单`);
  } catch (error) {
    notify(error.message);
  }
}

async function deleteOrder(order) {
  if (!canDeleteOrder(order)) {
    if (ADMIN_ONLY_DELETE_ORDER_STATUSES.includes(order.status)) {
      notify(`${order.status}订单不可删除，请使用管理员账号操作`);
      return;
    }
    notify("已审核订单不可删除");
    return;
  }
  const orderLabel = [order.no, order.customer].filter(Boolean).join(" / ");
  if (!window.confirm(`确定删除订单 ${orderLabel || order.no || ""}？删除后会进入回收站。`)) return;
  try {
    await ordersApi.deleteOrder(order.no);
    orderRows.value = orderRows.value.filter((item) => item.no !== order.no);
    removeDispatchRowsByOrderRefs([order]);
    notify(`订单 ${order.no} 已移入回收站`);
  } catch (error) {
    notify(error.message);
  }
}

function toggleCustomerOrderSelection(orderNo, checked) {
  if (checked) {
    selectedOrderNos.value = Array.from(new Set([...selectedOrderNos.value, orderNo]));
  } else {
    selectedOrderNos.value = selectedOrderNos.value.filter((no) => no !== orderNo);
  }
}

function toggleAllCustomerOrders(checked) {
  const customerNos = selectedCustomerOrderNos.value;
  const customerNoSet = new Set(customerNos.map((no) => String(no)));
  selectedOrderNos.value = selectedOrderNos.value.filter((no) => !customerNoSet.has(String(no)));
  if (checked) {
    selectedOrderNos.value = [...selectedOrderNos.value, ...customerNos];
  }
}

