const FINANCE_WAGE_AUDIT_FEE_COLUMN_LABELS = ["香港停车费", "香港登记费", "加点费", "大陆停车费", "装货等候费"];
const FINANCE_WAGE_AUDIT_HEADERS = [
  "序号",
  "订单号",
  "日期",
  "客户",
  "运输模式",
  "车辆来源",
  "车牌",
  "计价城市",
  "路线",
  "基础趟费HKD",
  "基础趟费RMB",
  "其他合计HKD",
  "代垫费HKD",
  "代垫费RMB",
  "代垫明细",
  ...FINANCE_WAGE_AUDIT_FEE_COLUMN_LABELS,
  "客户调整HKD",
  "预支/报销HKD",
  "预支/报销RMB",
  "应付合计HKD",
  "应付合计RMB",
  "状态"
];
const FINANCE_WAGE_AUDIT_BASE_FEE_KEYWORDS = ["基础运费", "基础趟费", "中港运费", "运费", "趟费"];

function financeWageAuditBaseCostBreakdown(costCenter = {}) {
  return (costCenter.details || []).reduce((sum, detail) => {
    const name = String(detail.name || detail.item?.name || detail.fee?.name || "").trim();
    if (!FINANCE_WAGE_AUDIT_BASE_FEE_KEYWORDS.some((keyword) => name.includes(keyword))) return sum;
    const amount = Number(detail.amount || 0);
    if (currencyCodeDisplay(detail.currency || detail.item?.currency || "港币") === "RMB") {
      sum.rmb += amount;
    } else {
      sum.hkd += amount;
    }
    return sum;
  }, { hkd: 0, rmb: 0 });
}

function financeWageAuditOtherCostHKD(costCenter = {}, base = financeWageAuditBaseCostBreakdown(costCenter)) {
  return Number((Number(costCenter.hkd || 0) - Number(base.hkd || 0)).toFixed(2));
}

function financeWageAuditFeeCellValue(order, feeName, driver) {
  const targetName = String(feeName || "").trim();
  if (!targetName) return "-";
  const advanceText = advanceFeesForOrder(order, driver)
    .filter((fee) => String(fee?.name || "").trim() === targetName && Number(fee?.amount || 0) !== 0)
    .map((fee) => `${money(fee.amount)} ${currencyCodeDisplay(fee.currency || "港币")}`)
    .join("；");
  const costText = driverCostCenterFeeDetailText(order, targetName, driver);
  return [costText, advanceText].filter(Boolean).join("；") || "-";
}

function financeDriverOrderDetailRows(row) {
  const driver = row?.driver;
  if (!driver) return [];
  return (row.orders || []).map((order, index) => {
    const wage = driverFinanceWageOrderBreakdown(order, driver);
    const costCenter = driverCostCenterFeeBreakdown(order, driver);
    const baseCost = financeWageAuditBaseCostBreakdown(costCenter);
    const advance = driverFinanceAdvanceBreakdown(order, driver);
    const adjust = driverCustomerTripAdjustBreakdown(order, driver);
    return [
      index + 1,
      order.no || "",
      order.date || "",
      order.customer || "",
      normalizeTransportMode(order.transportMode || "单司机") || "",
      order.vehicleSource || "",
      order.plate || "",
      orderDriverWageCity(order, driver) || "",
      relatedOrderRouteText(order),
      money(baseCost.hkd),
      money(baseCost.rmb || costCenter.rmb),
      money(financeWageAuditOtherCostHKD(costCenter, baseCost)),
      money(advance.hkd),
      money(advance.rmb),
      orderAdvanceFeeDetailText(order, driver),
      ...FINANCE_WAGE_AUDIT_FEE_COLUMN_LABELS.map((label) => financeWageAuditFeeCellValue(order, label, driver)),
      money(adjust.hkd),
      "",
      "",
      money(wage.hkd),
      money(wage.rmb),
      order.status || ""
    ];
  });
}

async function exportFinanceWageRow(row) {
  const detailRows = financeDriverOrderDetailRows(row);
  if (!detailRows.length) {
    notify("该司机当前期间暂无可导出的订单明细");
    return;
  }
  const costCenterTotal = row.orders.reduce((sum, order) => {
    const amount = driverCostCenterFeeBreakdown(order, row.driver);
    return { hkd: sum.hkd + amount.hkd, rmb: sum.rmb + amount.rmb };
  }, { hkd: 0, rmb: 0 });
  const baseTotal = row.orders.reduce((sum, order) => {
    const amount = financeWageAuditBaseCostBreakdown(driverCostCenterFeeBreakdown(order, row.driver));
    return { hkd: sum.hkd + amount.hkd, rmb: sum.rmb + amount.rmb };
  }, { hkd: 0, rmb: 0 });
  const otherTotalHKD = Number((costCenterTotal.hkd - baseTotal.hkd).toFixed(2));
  const advanceTotal = row.orders.reduce((sum, order) => {
    const amount = driverFinanceAdvanceBreakdown(order, row.driver);
    return { hkd: sum.hkd + amount.hkd, rmb: sum.rmb + amount.rmb };
  }, { hkd: 0, rmb: 0 });
  const customerAdjustTotal = row.orders.reduce((sum, order) => {
    const amount = driverCustomerTripAdjustBreakdown(order, row.driver);
    return sum + amount.hkd;
  }, 0);
  const wageTotal = row.orders.reduce((sum, order) => {
    const amount = driverFinanceWageOrderBreakdown(order, row.driver);
    return { hkd: sum.hkd + amount.hkd, rmb: sum.rmb + amount.rmb };
  }, { hkd: 0, rmb: 0 });
  const totalRow = [
    "合计",
    "",
    "",
    `${detailRows.length} 单`,
    "",
    "",
    "",
    "",
    "",
    money(baseTotal.hkd),
    money(baseTotal.rmb || costCenterTotal.rmb),
    money(otherTotalHKD),
    money(advanceTotal.hkd),
    money(advanceTotal.rmb),
    "",
    ...FINANCE_WAGE_AUDIT_FEE_COLUMN_LABELS.map(() => ""),
    money(customerAdjustTotal),
    money(row.adjustments),
    money(row.adjustmentsRMB),
    money(wageTotal.hkd + Number(row.adjustments || 0)),
    money(wageTotal.rmb + Number(row.adjustmentsRMB || 0)),
    ""
  ];
  await exportXlsx(
    `工资核对-${row.driver.name}-${financeDateRangeLabel()}-${todayInputValue()}.xlsx`,
    FINANCE_WAGE_AUDIT_HEADERS,
    [...detailRows, totalRow],
    "工资核对"
  );
  notify(`已导出${row.driver.name}的订单核对明细`);
}

async function exportStatementCsv() {
  const entityName = ensureStatementEntity();
  const { start, end } = statementDateRange();
  const orders = selectedStatementOrders();
  if (!entityName) {
    notify("请先选择对账对象");
    return;
  }
  if (!orders.length) {
    notify("当前条件没有可导出的对账订单");
    return;
  }
  saveStatementExportSettings();
  try {
    loading.value = true;
    if (statementExportType.value === "supplier") {
      const rows = orders.map((order, index) => {
        const payable = supplierOrderPayableBreakdown(order);
        return [
          index + 1,
          order.dispatchNo || "",
          order.no || "",
          order.date || "",
          order.customer || "",
          order.port || "",
          order.direction || "",
          order.tonnage || "",
          order.quantity || "",
          order.weight || "",
          relatedOrderLocationText(order.loading),
          relatedOrderLocationText(order.unloading),
          order.plate || "",
          order.transportMode || "",
          payable.currency,
          payable.payableHKD,
          payable.payableRMB,
          supplierOrderCostStatus(payable),
          supplierOrderPayableDetailText(order),
          order.status || ""
        ];
      });
      const totalHKD = rows.reduce((sum, row) => sum + Number(row[15] || 0), 0);
      const totalRMB = rows.reduce((sum, row) => sum + Number(row[16] || 0), 0);
      const payableOrders = orders.filter((order) => !isChargedOrder(order));
      await exportXlsx(
        `${exportFilenamePart(entityName)}_供应商对账_${start || "全部"}_${end || "全部"}.xlsx`,
        ["序号", "排车单号", "订单号", "日期", "客户", "口岸", "进出口", "吨位", "件数/板数", "重量", "装货地", "卸货地", "车牌", "运输模式", "币种", "应付HKD", "应付RMB", "成本匹配", "成本明细", "状态"],
        [...rows, ["合计", "", "", "", "", "", "", "", "", "", "", "", "", "", "", money(totalHKD), money(totalRMB), "", "", ""]],
        "供应商对账"
      );
      await markStatementDownloaded("supplier", entityName, start, end, {
        amountHKD: totalHKD,
        amountRMB: totalRMB,
        recordCount: payableOrders.length,
        snapshotReady: true
      });
      notify("已按订单成本导出供应商对账单");
      return;
    }

    if (statementExportType.value === "driver") {
      const driver = driverRowsByName.value.get(String(entityName || "").trim())
        || driverRowsById.value.get(String(entityName || "").trim())
        || null;
      const rows = orders.map((order, index) => {
        const wage = driverFinanceWageOrderBreakdown(order, driver);
        const costCenter = driverCostCenterFeeBreakdown(order, driver);
        const advance = driverFinanceAdvanceBreakdown(order, driver);
        const adjust = driverCustomerTripAdjustBreakdown(order, driver);
        return [
          index + 1,
          order.no || "",
          order.date || "",
          order.customer || "",
          order.vehicleSource || "",
          order.plate || "",
          normalizeTransportMode(order.transportMode || "单司机") || "",
          orderDriverWageCity(order, driver) || "",
          relatedOrderRouteText(order),
          money(costCenter.hkd),
          money(costCenter.rmb),
          money(advance.hkd),
          money(advance.rmb),
          orderAdvanceFeeDetailText(order, driver),
          money(adjust.hkd),
          money(wage.hkd),
          money(wage.rmb),
          order.status || ""
        ];
      });
      await exportXlsx(
        `${exportFilenamePart(entityName)}_司机对账_${start || "全部"}_${end || "全部"}.xlsx`,
        ["序号", "订单号", "日期", "客户", "车辆来源", "车牌", "运输模式", "计价城市", "路线", "基础趟费HKD", "基础趟费RMB", "代垫费HKD", "代垫费RMB", "代垫明细", "路线/客户调整HKD", "应付HKD", "应付RMB", "状态"],
        rows,
        "司机对账"
      );
      await markStatementDownloaded("driver", entityName, start, end);
      notify("已导出司机对账单");
      return;
    }

    const attachmentTexts = await Promise.all(orders.map((order) => statementAttachmentText(order)));
    const rows = orders.map((order, index) => [
      index + 1,
      order.dispatchNo || "",
      order.no || "",
      order.date || "",
      order.customer || "",
      order.port || "",
      order.direction || "",
      order.tonnage || "",
      order.quantity || "",
      order.weight || "",
      relatedOrderLocationText(order.loading),
      relatedOrderLocationText(order.unloading),
      order.receivableHKD || "",
      order.receivableRMB || "",
      statementFeeText(order),
      attachmentTexts[index] || "",
      order.status || "",
      statementChargeNoteText(order)
    ]);
    const totalOrders = orders.filter(customerStatementOrderIncludedInTotals);
    const total = statementConvertedTotal(totalOrders, statementSettlementCurrency.value, statementExchangeRate.value);
    const snapshotAmount = totalOrders.reduce((sum, order) => {
      const receivable = orderCustomerReceivableBreakdown(order);
      return {
        hkd: sum.hkd + Number(receivable.hkd || 0),
        rmb: sum.rmb + Number(receivable.rmb || 0)
      };
    }, { hkd: 0, rmb: 0 });
    await exportXlsx(
      `${exportFilenamePart(entityName)}_客户对账_${start || "全部"}_${end || "全部"}.xlsx`,
      ["序号", "排车单号", "订单号", "日期", "客户", "口岸", "进出口", "吨位", "件数/板数", "重量", "装货地", "卸货地", "应收HKD", "应收RMB", "杂费明细", "附件", "状态", "收费备注"],
      [
        ...rows,
        ["合计", "", "", "", "", "", "", "", "", "", "", money(total.hkd), money(total.rmb), `${total.label}${statementSettlementCurrency.value} ${money(total.total)}；汇率 ${statementExchangeRate.value}`, "", "", ""]
      ],
      "客户对账"
    );
    await markStatementDownloaded("customer", entityName, start, end, {
      amountHKD: snapshotAmount.hkd,
      amountRMB: snapshotAmount.rmb,
      recordCount: totalOrders.length,
      snapshotReady: true
    });
    notify("已导出客户对账单并记录下载");
  } catch (error) {
    notify(error.message || "对账单导出失败");
  } finally {
    loading.value = false;
  }
}

function statementExportExchangePayload() {
  if (statementExportType.value !== "customer") return null;
  const rate = Number(statementExchangeRate.value || 0);
  if (!Number.isFinite(rate) || rate <= 0) return null;
  return {
    mode: statementSettlementCurrency.value === "港币" ? "rmb-to-hkd" : "hkd-to-rmb",
    rate
  };
}

function statementExportTypeLabel() {
  if (statementExportType.value === "supplier") return "供应商对账单";
  if (statementExportType.value === "driver") return "司机对账单";
  return "客户对账单";
}

function statementExportFilename(entityName = "对账对象", start = "", end = "", extension = "xlsx") {
  const typeLabel = statementExportTypeLabel().replace("对账单", "对账");
  return `${exportFilenamePart(entityName)}_${typeLabel}_${start || "全部"}_${end || "全部"}.${extension}`;
}

