    notify("请先选择对账对象");
    return;
  }
  if (!orders.length) {
    notify("当前条件没有可导出的对账订单");
    return;
  }
  saveStatementExportSettings();
  if (templateRow?.id) selectedTemplateId.value = templateRow.id;
  if (isKenfaTemplateRow(templateRow) && (statementExportType.value !== "customer" || format !== "excel")) {
    notify("肯发专用模板仅支持客户对账单 Excel 导出");
    return;
  }
  const title = `${statementExportTypeLabel()}-${entityName}`;
  const exchange = statementExportExchangePayload();
  if (statementExportType.value === "supplier") {
    const exportOrders = supplierStatementTemplateOrders(orders);
    const snapshot = {
      amountHKD: Number(exportRow.hkd || 0),
      amountRMB: Number(exportRow.rmb || 0),
      recordCount: Number(exportRow.count || 0),
      snapshotReady: true
    };
    const ok = format === "pdf"
      ? await exportOrderSnapshotsAsPdf(exportOrders, title, templateRow, exchange, statementExportFilename(entityName, start, end, "pdf"))
      : await exportOrderSnapshotsAsExcel(exportOrders, title, templateRow, exchange, statementExportFilename(entityName, start, end, "xlsx"), { includeReceiptSheet: false });
    if (ok) await markStatementDownloaded(statementExportType.value, entityName, start, end, snapshot);
    return;
  }
  if (statementExportType.value === "customer") {
    const snapshot = {
      amountHKD: Number(exportRow.hkd || 0),
      amountRMB: Number(exportRow.rmb || 0),
      recordCount: Number(exportRow.count || 0),
      snapshotReady: true
    };
    const ok = format === "pdf"
      ? await exportOrderSnapshotsAsPdf(orders, title, templateRow, exchange, statementExportFilename(entityName, start, end, "pdf"))
      : await exportOrderSnapshotsAsExcel(orders, title, templateRow, exchange, statementExportFilename(entityName, start, end, "xlsx"), { includeReceiptSheet: true });
    if (ok) await markStatementDownloaded(statementExportType.value, entityName, start, end, snapshot);
    return;
  }
  const snapshot = {
    amountHKD: Number(exportRow.hkd || 0),
    amountRMB: Number(exportRow.rmb || exportRow.total || 0),
    recordCount: Number(exportRow.count || 0),
    snapshotReady: true
  };
  const ok = format === "pdf"
    ? await exportOrderRowsAsPdf(orders, title, templateRow, exchange)
    : await exportOrderRowsAsCsv(orders, title, templateRow, exchange);
  if (ok) await markStatementDownloaded(statementExportType.value, entityName, start, end, snapshot);
}

function parseVisualExportTemplate(item = selectedTemplate.value) {
  if (!item?.content) return null;
  try {
    const content = JSON.parse(item.content);
    if (content?.type !== "visual-export-template") return null;
    const columns = Array.isArray(content.columns) && content.columns.length
      ? content.columns
      : defaultTemplateColumns();
    return {
      ...content,
      columns: sortTemplateColumnsBySavedOrder(filterRemovedTemplateColumns(columns))
    };
  } catch {
    return null;
  }
}

function orderExportTemplateOptions() {
  return exportTemplateRows.value.length
    ? exportTemplateRows.value
    : [{ id: "default", name: "默认模板", content: "" }];
}

function supplierStatementTemplateOptions() {
  const genericTemplate = exportTemplateRows.value.find((item) => item.name === "通用模板");
  return genericTemplate
    ? [genericTemplate]
    : [{ id: "default", name: "通用模板", content: "" }];
}

function templateFormatLabel() {
  return "Excel / PDF";
}

async function ensureTemplateContent(item = selectedTemplate.value) {
  if (!item?.id || item.id === "default" || item.contentLoaded || item.content) return item;
  const fullItem = await templatesApi.getTemplate(item.id);
  templateRows.value = templateRows.value.map((row) => row.id === fullItem.id ? fullItem : row);
  if (selectedTemplateId.value === item.id) selectedTemplateId.value = fullItem.id;
  return fullItem;
}

function orderTemplateColumns(template = parseVisualExportTemplate()) {
  const columns = Array.isArray(template?.columns) && template.columns.length
    ? template.columns
    : defaultTemplateColumns();
  return sortTemplateColumnsBySavedOrder(filterRemovedTemplateColumns(columns))
    .filter((column) => column.visible !== false)
    .map((column) => ({
      key: column.key,
      label: column.label || column.key,
      fontSize: Number(column.fontSize || template?.tableFontSize || 11)
    }));
}

function orderExportValue(order, key) {
  const values = {
    dispatchNo: order.dispatchNo || "-",
    no: order.no,
    customer: order.customer,
    businessType: order.businessType,
    port: order.port,
    direction: order.direction,
    tonnage: order.tonnage,
    currency: order.currency,
    quantity: order.quantity,
    weight: order.weight,
    vehicleSource: order.vehicleSource,
    plate: order.plate,
    driver: order.driver,
    transportMode: normalizeTransportMode(order.transportMode || ""),
    supplier: order.supplier,
    loading: order.loading,
    unloading: order.unloading,
    date: order.date,
    receivableHKD: order.receivableHKD,
    receivableRMB: order.receivableRMB,
    status: order.status
  };
  return values[key] ?? order[key] ?? "";
}

function exportCustomers() {
  const rows = selectedCustomerIds.value.length
    ? visibleCustomers.value.filter((item) => selectedCustomerIdSet.value.has(String(item.id)))
    : visibleCustomers.value;
  const columns = customerPageColumns.value;
  exportCsv(
    `${activeCustomerListLabel.value}${selectedCustomerIds.value.length ? "已选" : "筛选"}导出-${todayInputValue()}.csv`,
    columns.map((column) => column.label),
    rows.map((item) => columns.map((column) => customerListDetailCellText(item, column.key)))
  );
  notify(selectedCustomerIds.value.length
    ? `已导出已选 ${rows.length} 个${activeCustomerListLabel.value}`
    : `已导出当前${activeCustomerListLabel.value}列表`
  );
}

async function deleteSelectedCustomer() {
  const targets = selectedCustomerIds.value.length
    ? visibleCustomers.value.filter((item) => selectedCustomerIdSet.value.has(String(item.id)))
    : (selectedCustomer.value ? [selectedCustomer.value] : []);
  if (targets.length === 0) {
    notify(`请先选择要删除的${activeCustomerListLabel.value}`);
    return;
  }
  if (!window.confirm(`确定删除 ${targets.length} 个${activeCustomerListLabel.value}？已有订单记录时系统会阻止删除。`)) return;
  try {
    for (const target of targets) {
      await customersApi.deleteCustomer(target.id);
    }
    const deletedIds = new Set(targets.map((item) => item.id));
    customerRows.value = customerRows.value.filter((item) => !deletedIds.has(item.id));
    selectedCustomerIds.value = [];
    selectedCustomerId.value = visibleCustomers.value[0]?.id || "";
    notify("已删除，相关审计已记录");
  } catch (error) {
    notify(error.message);
  }
}

function exportVehicleDriver() {
  if (activeVehicleTab.value === "车辆管理") {
    const rows = selectedVehiclePlates.value.length
      ? visibleVehicles.value.filter((item) => selectedVehiclePlateSet.value.has(String(item.plate)))
      : visibleVehicles.value;
    exportCsv(
      `车辆${selectedVehiclePlates.value.length ? "已选" : "筛选"}导出-${todayInputValue()}.csv`,
      ["车牌", "品牌", "型号", "车型", "大陆保险", "香港保险", "状态", "本月费用", "备注"],
      rows.map((item) => [item.plate, item.brand, item.model, item.type, item.mainlandInsuranceDate, item.hkInsuranceDate, item.status, item.monthlyCost, item.note])
    );
  } else {
    const rows = selectedDriverIds.value.length
      ? visibleDrivers.value.filter((item) => selectedDriverIdSet.value.has(String(item.id)))
      : visibleDrivers.value;
    exportCsv(
      `司机${selectedDriverIds.value.length ? "已选" : "筛选"}导出-${todayInputValue()}.csv`,
      ["类型", "司机", "电话", "身份证号", "驾驶证", "生日", "入职日期", "离职日期", "入职状态", "证件到期", "状态", "备注"],
      rows.map((item) => [item.type || "香港司机", item.name, item.phone, item.idNo, item.license, item.birthday, item.hireDate, item.leaveDate, driverEmploymentStatus(item), item.expireAt, item.status, item.note])
    );
  }
  notify(`已导出${activeVehicleTab.value}`);
}

function exportVehicleExpenses() {
  const config = activeVehicleExpenseConfig.value;
  const headers = ["名称"];
  if (config.type === "fuel") headers.push("加油升数", "加油时公里数", "加油站");
  headers.push("车牌", config.type === "annual" ? "时间范围" : "时间");
  if (config.type === "annual") headers.push("到期提醒");
  headers.push("币种", "金额", "分摊说明", "备注");
  exportCsv(
    `${config.title}导出-${todayInputValue()}.csv`,
    headers,
    visibleVehicleExpenses.value.map((item) => {
      const row = [item.name || config.defaultName || vehicleExpenseTypeLabel(item.type)];
      if (config.type === "fuel") row.push(item.fuelLiters || "", item.odometerKm || "", item.fuelStation || "");
      row.push(
        item.plate,
        vehicleExpenseDateText(item),
        ...(config.type === "annual" ? [vehicleExpenseExpiryText(item)] : []),
        currencyCodeDisplay(item.currency),
        item.amount,
        vehicleExpenseAllocationText(item),
        item.note
      );
      return row;
    })
  );
  notify(`已导出${config.title}`);
}

function exportLocalBackup() {
  const snapshot = {
    exportedAt: new Date().toISOString(),
    customers: customerRows.value,
    orders: orderRows.value,
    vehicles: vehicleRows.value,
    vehicleExpenses: vehicleExpenseRows.value,
    drivers: driverRows.value,
    driverWageRules: driverWageRuleRows.value,
    costCenterRates: costCenterRateRows.value,
    vehicleProfitExchangeRates: bossVehicleExchangeRateRows.value,
    feeItems: feeItemRows.value,
    freightRates: freightRateRows.value,
    templates: templateRows.value,
    rules: ruleRows.value,
    masterData: masterRows.value,
    accounts: accountRows.value
  };
  const blob = new Blob([JSON.stringify(snapshot, null, 2)], { type: "application/json;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `汉业数据备份-${todayInputValue()}.json`;
  link.click();
  URL.revokeObjectURL(url);
  notify("已生成本地备份文件");
}

