    feeItemRows.value = sortFeeItems(feeItemRows.value.map((row) => row.id === saved.id ? saved : row));
    editingFeeItemRowId.value = null;
    notify("收费项目已保存");
  } catch (error) {
    notify(error.message);
  }
}

function selectFeeItem(item) {
