            <div class="modal-body address-picker-body is-address-book">
              <div class="address-book-manager">
                <div class="address-book-toolbar">
                  <label>搜索地址
                    <input v-model.trim="locationPicker.keyword" placeholder="联系人 / 电话 / 详细地址 / 备注" />
                  </label>
                  <span>已选 {{ selectedAddressBookIds.length }} 项</span>
                  <button class="ghost-btn small" type="button" @click="toggleAllAddressBookSelection(!allVisibleAddressBookSelected)">
                    {{ allVisibleAddressBookSelected ? '取消全选' : '全选' }}
                  </button>
                  <button class="ghost-btn danger small" type="button" @click="deleteSelectedAddressBookEntries"><IconSvg name="trash" />批量删除</button>
                  <button class="primary-btn small" type="button" @click="startNewAddressBookEntry"><IconSvg name="plus" />新建地址</button>
                </div>
                <div v-if="addressBookFormOpen" class="address-book-form">
                  <label class="address-book-city-field">市<input v-model.trim="addressBookForm.city" list="address-book-city-options" placeholder="选择一级片区" @change="handleAddressBookCityChange" /></label>
                  <label class="address-book-district-field">区
                    <span class="searchable-select address-book-district-search" :class="{ 'is-open': addressBookDistrictPickerOpen, 'is-disabled': !addressBookForm.city }" @click.stop>
                      <input
                        :value="addressBookDistrictPickerOpen ? addressBookDistrictSearch : (addressBookForm.district || '')"
                        type="search"
                        autocomplete="off"
                        :placeholder="addressBookForm.city ? '选择二级片区' : '请先选择市'"
                        :disabled="!addressBookForm.city"
                        @focus="openAddressBookDistrictPicker"
                        @input="handleAddressBookDistrictInput"
                        @blur="closeAddressBookDistrictPicker"
                        @keydown.enter.prevent="confirmFirstAddressBookDistrictOption"
                        @keydown.esc.prevent="closeAddressBookDistrictPicker"
                      />
                      <button
                        type="button"
                        class="customs-business-company-toggle"
                        :disabled="!addressBookForm.city"
                        :title="addressBookDistrictPickerOpen ? '收起区列表' : '展开区列表'"
                        :aria-label="addressBookDistrictPickerOpen ? '收起区列表' : '展开区列表'"
                        @click.stop="toggleAddressBookDistrictPicker"
                      ><IconSvg :name="addressBookDistrictPickerOpen ? 'chevronUp' : 'chevronDown'" /></button>
                      <button
                        v-if="addressBookForm.city && addressBookForm.district"
                        type="button"
                        class="customs-business-company-clear"
                        title="清空区"
                        aria-label="清空区"
                        @click.stop="clearAddressBookDistrict"
                      ><IconSvg name="close" /></button>
                      <div v-if="addressBookDistrictPickerOpen && addressBookForm.city" class="searchable-select-dropdown address-book-district-dropdown">
                        <button
                          v-for="district in addressBookFilteredDistrictOptions"
                          :key="district"
                          type="button"
                          :class="{ active: district === addressBookForm.district }"
                          @mousedown.prevent="selectAddressBookDistrict(district)"
                        >
                          <strong>{{ district }}</strong>
                        </button>
                        <p v-if="addressBookFilteredDistrictOptions.length === 0" @mousedown.prevent="closeAddressBookDistrictPicker">暂无匹配片区</p>
                      </div>
                    </span>
                  </label>
                  <datalist id="address-book-city-options">
                    <option v-for="city in addressBookCityOptions" :key="city" :value="city">{{ city }}</option>
                  </datalist>
                  <label class="address-book-address-field">详细地址<input v-model.trim="addressBookForm.address" placeholder="详细地址" /></label>
                  <label class="address-book-contact-field">联系人<input v-model.trim="addressBookForm.contact" placeholder="联系人" /></label>
                  <label class="address-book-phone-field">电话<input v-model.trim="addressBookForm.phone" placeholder="电话 / 手机" /></label>
                  <label class="address-book-note-field">备注<input v-model.trim="addressBookForm.note" placeholder="楼栋、门牌、仓库名" /></label>
                  <button class="primary-btn address-book-save-btn" type="button" @click="saveAddressBookEntry"><IconSvg name="save" />{{ editingAddressBookId ? '保存修改' : '保存到联系人' }}</button>
                </div>
              </div>
              <div class="table-wrap address-picker-table-wrap">
                <table class="data-table compact">
                  <thead>
                    <tr>
                      <th>
                        <input
                          type="checkbox"
                          class="table-check"
                          :checked="allVisibleAddressBookSelected"
                          @change="toggleAllAddressBookSelection($event.target.checked)"
                        />
                      </th>
                      <th>市/区</th>
                      <th>详细地址</th>
                      <th>联系人</th>
                      <th>电话</th>
                      <th>备注</th>
                      <th>操作</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="option in addressBookListOptions" :key="option.key">
                      <td>
                        <input
                          v-if="option.source === '联系人'"
                          type="checkbox"
                          class="table-check"
                          :checked="selectedAddressBookIds.includes(option.id)"
                          @click.stop
                          @change="toggleAddressBookSelection(option.id, $event.target.checked)"
                        />
                      </td>
                      <td>{{ option.area || '-' }}</td>
                      <td class="address-picker-value">{{ option.address || option.value }}</td>
                      <td>{{ option.contact || '-' }}</td>
                      <td>{{ option.phone || '-' }}</td>
                      <td>{{ option.note || '-' }}</td>
                      <td class="row-actions">
                        <button v-if="option.source === '联系人'" class="icon-btn icon-only" type="button" title="编辑地址" aria-label="编辑地址" @click="editAddressBookEntry(option)"><IconSvg name="edit" /></button>
                        <button v-if="option.source === '联系人'" class="icon-btn icon-only danger" type="button" title="删除地址" aria-label="删除地址" @click="deleteAddressBookEntry(option.id)"><IconSvg name="trash" /></button>
                      </td>
                    </tr>
                    <tr v-if="addressBookListOptions.length === 0">
                      <td colspan="7">暂无地址，请先选择客户，或在上方新建地址。</td>
                    </tr>
                  </tbody>
                </table>
              </div>
              <div class="address-picker-actions">
                <button type="button" class="ghost-btn" @click="closeLocationPicker">取消</button>
                <button class="primary-btn" type="button" :disabled="selectedAddressBookIds.length === 0" @click="applySelectedAddressBookEntries"><IconSvg name="check" />确定</button>
              </div>
              <p class="address-picker-hint">地址来自当前客户的联系人；新建地址会同步到该客户联系人资料。</p>
            </div>
          </section>
        </div>
      </div>

      <div v-if="dispatchDuplicateModalOpen" class="modal-backdrop">
        <section class="modal-card compact-modal dispatch-copy-modal">
          <div class="modal-head">
            <h2>复制排车单 <span class="order-title-meta">已选 {{ dispatchDuplicateDraftRows.length }} 单</span></h2>
            <button type="button" class="icon-btn" @click="closeDispatchDuplicateModal"><IconSvg name="close" />关闭</button>
          </div>
          <div class="modal-body">
            <datalist id="dispatchDuplicatePlateOptions">
              <option v-for="vehicle in vehicleRows" :key="vehicle.plate" :value="vehicle.plate">{{ vehicle.type || vehicle.model || vehicle.brand || '车辆' }}</option>
            </datalist>
            <p class="modal-helper-text">请先核对复制内容，点击保存后才会生成新的排车单和待确认订单。</p>
            <div class="table-wrap dispatch-copy-table-wrap">
              <table class="data-table compact">
                <thead>
                  <tr>
                    <th>序号</th>
                    <th>原排车单</th>
                    <th>客户</th>
                    <th>车牌</th>
                    <th>装车时间</th>
                    <th>口岸</th>
                    <th>吨位</th>
                    <th>件数/板数</th>
                    <th>装 / 卸</th>
                    <th>排车状态</th>
                    <th>备注</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(row, index) in dispatchDuplicateDraftRows" :key="row.id">
                    <td>{{ index + 1 }}</td>
                    <td>
                      <strong>{{ row.sourceDispatchNo || '-' }}</strong>
                      <small>{{ row.sourceOrderNo || '-' }}</small>
                    </td>
                    <td>{{ partnerDisplayLabel(row.customer || '', '客户') || '-' }}</td>
                    <td><input v-model.trim="row.plate" list="dispatchDuplicatePlateOptions" placeholder="车牌" /></td>
                    <td>
                      <select v-model="row.loadTime" @change="handleDispatchDuplicateLoadTimeChange(row)">
                        <option value="">未定</option>
                        <option v-for="time in DISPATCH_LOAD_TIME_OPTIONS" :key="time" :value="time">{{ time }}</option>
                      </select>
                    </td>
                    <td>{{ row.port || '-' }}</td>
                    <td>{{ row.tonnage || '-' }}</td>
                    <td>{{ row.quantity || '-' }}</td>
                    <td>{{ dispatchOrderRouteText(row) }}</td>
                    <td>
                      <select v-model="row.status" :class="['dispatch-status-select', dispatchStatusClass(row.status)]" :disabled="isDispatchStatusSelectDisabled(row)">
                        <option v-if="!dispatchStatusOptionsForRow(row).includes(dispatchStatusValueForRow(row))" :value="dispatchStatusValueForRow(row)" hidden>{{ dispatchStatusValueForRow(row) }}</option>
                        <option v-for="status in dispatchStatusOptionsForRow(row)" :key="status" :value="status">{{ status }}</option>
                      </select>
                    </td>
                    <td><input v-model.trim="row.note" placeholder="备注" /></td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
          <div class="modal-actions">
            <button type="button" class="ghost-btn" @click="closeDispatchDuplicateModal">取消</button>
            <button type="button" class="primary-btn" :disabled="loading || !dispatchDuplicateDraftRows.length" @click="saveDuplicateDispatchRows"><IconSvg name="save" />保存复制</button>
          </div>
        </section>
      </div>

      <OrderModal
        :open="orderModalOpen"
        :editing="Boolean(editingOrderNo)"
        :customer="orderModalCustomerTitle"
        :order-no="orderModalTitleNo"
        :loading="loading"
        :title="orderAuditMode ? '审核订单' : orderViewMode ? '查看订单' : ''"
      :submit-label="orderAuditMode ? '确认审核' : '保存订单'"
      :submit-icon="orderAuditMode ? 'check' : 'save'"
      :show-submit="!orderViewMode"
      :submit-disabled="!orderAuditMode && hasMissingAdvanceFeeAmount()"
      @close="closeOrderModal"
      @submit="submitOrderModal"
	        @panel-click="dispatchMessageOpen = false; loadFeeTemplateMenuOpen = false; closeRouteTreeDropdown(); orderCustomerPickerOpen = false; orderSupplierPickerOpen = false; closeOrderFeeNamePicker()"
	      >
	      <template #headerActions>
	        <span v-if="orderModalCanMarkCharged" class="order-detail-charge-actions">
	          <span v-if="orderModalChargedAt" class="status-badge order-charged-date">{{ orderModalChargedAtDisplay }}</span>
	          <button
	            :class="['ghost-btn', 'small', { active: !orderModalChargedAt, danger: !!orderModalChargedAt }]"
	            type="button"
	            :disabled="orderChargeSaving"
	            @click="orderModalChargedAt ? cancelOrderModalCharge() : markOrderModalCharged()"
	          ><IconSvg :name="orderModalChargedAt ? 'refresh' : 'check'" />{{ orderModalChargedAt ? '取消收费' : '已收费' }}</button>
	        </span>
	      </template>
	          <div class="modal-body order-modal-review-body" :class="{ 'is-readonly': orderReadOnlyMode }">
	            <fieldset class="order-modal-readonly-fieldset" :disabled="orderReadOnlyMode">
            <div class="form-grid order-compact-grid order-layout-grid">
              <label class="order-compact-field hidden-order-customer">客户
                <span class="searchable-select" @click.stop>
                  <input
                    v-model.trim="orderCustomerKeyword"
                    placeholder="搜索并选择客户"
                    @focus="openOrderCustomerPicker"
                    @input="handleOrderCustomerInput"
                  />
                  <div v-if="orderCustomerPickerOpen" class="searchable-select-dropdown">
                    <button
                      v-for="customer in orderCustomerOptions"
                      :key="customer.id"
                      type="button"
                      :class="{ active: customer.id === orderForm.customerId }"
                      @click="selectOrderCustomer(customer)"
                    >
                      <strong>{{ customerOptionPrimaryDisplay(customer) }}</strong>
                    </button>
                    <p v-if="orderCustomerOptions.length === 0">没有匹配客户</p>
                  </div>
                </span>
              </label>
              <label class="order-compact-field">排车单号<input v-model.trim="orderForm.dispatchNo" :placeholder="generateDispatchNo(orderForm.date || todayInputValue())" /></label>
              <label class="order-compact-field">业务类型<select v-model="orderForm.businessType" @change="handleOrderBusinessTypeChange"><option value=""></option><option>运输</option><option>报关</option><option>运输+报关</option></select></label>
              <label class="order-compact-field">口岸<select v-model="orderForm.port"><option value=""></option><option>深圳湾海关</option><option>莲塘海关</option><option>文锦渡海关</option><option>大桥海关</option></select></label>
              <label class="order-compact-field">进出口<select v-model="orderForm.direction" @change="handleOrderDirectionChange"><option value=""></option><option>出口</option><option>进口</option></select></label>
              <label v-if="orderHasTransportFields" class="order-compact-field">吨位<select v-model="orderForm.tonnage" @change="scheduleAutoFreightSync"><option value=""></option><option v-for="item in TONNAGE_OPTIONS" :key="item">{{ item }}</option></select></label>
              <label class="order-compact-field">件数/板数<input v-model.trim="orderForm.quantity" inputmode="text" placeholder="例如：20件 / 4板" @input="scheduleAutoFreightSync" /></label>
              <label v-if="orderHasTransportFields" class="order-compact-field">重量<input v-model.trim="orderForm.weight" placeholder="例如：1200kg" /></label>
              <label v-if="orderHasCustomsFields" class="order-compact-field">报关单号<input v-model.trim="orderForm.customsNo" placeholder="报关单号" /></label>
              <label v-if="orderHasCustomsFields" class="order-compact-field">消费使用单位<input v-model.trim="orderForm.customsUnit" placeholder="消费使用单位" /></label>
              <label v-if="orderHasCustomsFields" class="order-compact-field">品名项数<input v-model.number="orderForm.customsItemCount" type="number" min="0" placeholder="例如：5" /></label>
              <label v-if="orderHasCustomsFields" class="order-compact-field">续页数量<input v-model.number="orderForm.customsPageCount" type="number" min="0" placeholder="例如：1" /></label>
              <label v-if="orderHasTransportFields" class="order-compact-field">车辆来源<select v-model="orderForm.vehicleSource" @change="handleOrderVehicleSourceChange"><option value=""></option><option>汉业物流</option><option>外派车辆</option></select></label>
              <label v-if="orderHasTransportFields && orderUsesOwnVehicle" class="order-compact-field">运输模式
                <select v-model="orderForm.transportMode" @change="handleOrderTransportModeChange">
                  <option v-for="mode in TRANSPORT_MODE_OPTIONS" :key="mode">{{ mode }}</option>
                </select>
              </label>
              <label v-if="orderHasTransportFields && orderUsesOwnVehicle && !orderUsesRelayDrivers" class="order-compact-field">香港司机
                <select v-model="orderForm.driver">
                  <option value=""></option>
                  <option v-for="driver in hongKongDriverOptions.length ? hongKongDriverOptions : activeDriverRows" :key="driver.id" :value="driver.name">{{ driver.name }}</option>
                </select>
              </label>
              <label v-if="orderHasTransportFields && orderUsesRelayDrivers" class="order-compact-field">香港司机
                <select v-model="orderForm.hkDriver">
                  <option value=""></option>
                  <option v-for="driver in hongKongDriverOptions.length ? hongKongDriverOptions : activeDriverRows" :key="driver.id" :value="driver.name">{{ driver.name }}</option>
                </select>
              </label>
              <label v-if="orderHasTransportFields && orderUsesRelayDrivers && !orderUsesDomesticTransfer" class="order-compact-field">大陆骑师
                <select v-model="orderForm.mainlandDriver">
                  <option value=""></option>
                  <option v-for="driver in mainlandDriverOptions.length ? mainlandDriverOptions : activeDriverRows" :key="driver.id" :value="driver.name">{{ driver.name }}</option>
                </select>
              </label>
              <label v-if="orderHasTransportFields && orderUsesDomesticTransfer" class="order-compact-field">国内车牌号
                <input v-model.trim="orderForm.mainlandDriver" placeholder="例如：粤B12345" />
              </label>
              <div v-if="orderHasTransportFields && orderUsesOutsourcedVehicle" class="order-outsourced-field">
                <label class="order-compact-field">
                  外派供应商
                  <span class="searchable-select order-supplier-search" @click.stop>
                    <input
                      v-model.trim="orderSupplierKeyword"
                      placeholder="输入供应商名称 / 编号搜索"
                      @focus="openOrderSupplierPicker"
                      @input="handleOrderSupplierInput"
                    />
                    <div v-if="orderSupplierPickerOpen" class="searchable-select-dropdown order-supplier-dropdown">
                      <button
                        v-for="supplier in orderSupplierOptions"
                        :key="supplier.id"
                        type="button"
                        :class="{ active: supplier.name === orderForm.supplier }"
                        @click="selectOrderSupplier(supplier)"
                      >
                        <strong>{{ customerShortDisplay(supplier) }}</strong>
                        <span>{{ supplier.name }} · {{ supplier.id }}</span>
                      </button>
                      <p v-if="orderSupplierOptions.length === 0">没有匹配外派供应商</p>
                    </div>
                  </span>
                </label>
                <label class="order-compact-field">
                  车牌
                  <input v-model.trim="orderForm.plate" placeholder="外派车牌" />
                </label>
              </div>
              <label v-if="orderHasTransportFields && orderUsesOwnVehicle" class="order-compact-field order-own-vehicle-field">车牌
                <select v-model="orderForm.plate">
                  <option value=""></option>
                  <option v-for="vehicle in vehicleRows" :key="vehicle.plate" :value="vehicle.plate">{{ vehicle.plate }}</option>
                </select>
              </label>
              <label v-if="orderHasTransportFields" class="order-compact-field order-location-field order-location-wide">装货
                <span class="location-input-row route-tree-wrap" @click.stop>
                  <button :class="['route-tree-trigger', { 'is-empty': !orderForm.loading, active: routeTreeDropdown.open && routeTreeDropdown.target === 'loading' }]" type="button" title="选择运费模板片区" @click="toggleRouteTreeDropdown('loading')">
                    <span>{{ orderForm.loading || '点击选择片区' }}</span>
                    <IconSvg name="chevronDown" />
                  </button>
                  <button class="table-op icon-only address-book-trigger" type="button" title="地址本列表" aria-label="地址本列表" @click.stop="closeRouteTreeDropdown(); openLocationPicker('loading', 'addressBook')"><IconSvg name="contacts" /></button>
                  <div v-if="routeTreeDropdown.open && routeTreeDropdown.target === 'loading'" class="route-tree-dropdown">
                    <div class="route-tree-panel">
                      <div class="route-tree-list">
                        <template v-for="level1 in routeTreeLevel1Options" :key="level1">
                          <button class="route-tree-node" :class="{ checked: routeTreeDropdown.level1 === level1 }" type="button" @click="selectRouteTreeLevel(1, level1)">
                            <span class="tree-check" :class="{ checked: routeTreeDropdown.level1 === level1 }"><IconSvg v-if="routeTreeDropdown.level1 === level1" name="check" /></span>
                            <span>{{ level1 }}</span>
                          </button>
                          <div v-if="routeTreeDropdown.level1 === level1" class="route-tree-children">
                            <button v-for="level2 in routeTreeLevel2Options" :key="level2" class="route-tree-node level-2" :class="{ checked: routeTreeDropdown.level2 === level2 }" type="button" @click="selectRouteTreeLevel(2, level2)">
                              <span class="tree-check" :class="{ checked: routeTreeDropdown.level2 === level2 }"><IconSvg v-if="routeTreeDropdown.level2 === level2" name="check" /></span>
                              <span>{{ level2 }}</span>
                            </button>
                            <div v-if="routeTreeDropdown.level2" class="route-tree-children">
                              <button v-for="level3 in routeTreeLevel3Options" :key="level3" class="route-tree-node level-3" :class="{ checked: routeTreeDropdown.level3 === level3 }" type="button" @click="selectRouteTreeLevel(3, level3)">
                                <span class="tree-check" :class="{ checked: routeTreeDropdown.level3 === level3 }"><IconSvg v-if="routeTreeDropdown.level3 === level3" name="check" /></span>
                                <span>{{ level3 }}</span>
                              </button>
                            </div>
                          </div>
                        </template>
                        <p v-if="routeTreeLevel1Options.length === 0" class="route-tree-empty">{{ routeTreeEmptyText }}</p>
                      </div>
                      <div class="route-tree-actions">
                        <span>{{ routeTreeValue || '未选择' }}</span>
                        <button class="primary-btn route-tree-confirm" type="button" @click="confirmRouteTreeSelection">确认选择</button>
                      </div>
                    </div>
                  </div>
                </span>
              </label>
              <label v-if="orderHasTransportFields" class="order-compact-field order-location-field order-location-wide">卸货
                <span class="location-input-row route-tree-wrap" @click.stop>
                  <button :class="['route-tree-trigger', { 'is-empty': !orderForm.unloading, active: routeTreeDropdown.open && routeTreeDropdown.target === 'unloading' }]" type="button" title="选择运费模板片区" @click="toggleRouteTreeDropdown('unloading')">
                    <span>{{ orderForm.unloading || '点击选择片区' }}</span>
                    <IconSvg name="chevronDown" />
                  </button>
                  <button class="table-op icon-only address-book-trigger" type="button" title="地址本列表" aria-label="地址本列表" @click.stop="closeRouteTreeDropdown(); openLocationPicker('unloading', 'addressBook')"><IconSvg name="contacts" /></button>
                  <div v-if="routeTreeDropdown.open && routeTreeDropdown.target === 'unloading'" class="route-tree-dropdown">
                    <div class="route-tree-panel">
                      <div class="route-tree-list">
                        <template v-for="level1 in routeTreeLevel1Options" :key="level1">
                          <button class="route-tree-node" :class="{ checked: routeTreeDropdown.level1 === level1 }" type="button" @click="selectRouteTreeLevel(1, level1)">
                            <span class="tree-check" :class="{ checked: routeTreeDropdown.level1 === level1 }"><IconSvg v-if="routeTreeDropdown.level1 === level1" name="check" /></span>
                            <span>{{ level1 }}</span>
                          </button>
                          <div v-if="routeTreeDropdown.level1 === level1" class="route-tree-children">
                            <button v-for="level2 in routeTreeLevel2Options" :key="level2" class="route-tree-node level-2" :class="{ checked: routeTreeDropdown.level2 === level2 }" type="button" @click="selectRouteTreeLevel(2, level2)">
                              <span class="tree-check" :class="{ checked: routeTreeDropdown.level2 === level2 }"><IconSvg v-if="routeTreeDropdown.level2 === level2" name="check" /></span>
                              <span>{{ level2 }}</span>
                            </button>
                            <div v-if="routeTreeDropdown.level2" class="route-tree-children">
                              <button v-for="level3 in routeTreeLevel3Options" :key="level3" class="route-tree-node level-3" :class="{ checked: routeTreeDropdown.level3 === level3 }" type="button" @click="selectRouteTreeLevel(3, level3)">
                                <span class="tree-check" :class="{ checked: routeTreeDropdown.level3 === level3 }"><IconSvg v-if="routeTreeDropdown.level3 === level3" name="check" /></span>
                                <span>{{ level3 }}</span>
                              </button>
                            </div>
                          </div>
                        </template>
                        <p v-if="routeTreeLevel1Options.length === 0" class="route-tree-empty">{{ routeTreeEmptyText }}</p>
                      </div>
                      <div class="route-tree-actions">
                        <span>{{ routeTreeValue || '未选择' }}</span>
                        <button class="primary-btn route-tree-confirm" type="button" @click="confirmRouteTreeSelection">确认选择</button>
                      </div>
                    </div>
                  </div>
                </span>
              </label>
              <label class="order-compact-field">订单日期<input v-model="orderForm.date" type="date" /></label>
              <label class="order-compact-field">状态<select v-model="orderForm.status"><option v-for="status in ORDER_STATUS_OPTIONS" :key="status">{{ status }}</option></select></label>
              <label class="order-compact-field order-compact-field-wide">备注<input v-model.trim="orderForm.remark" placeholder="订单备注" /></label>
              <div v-if="orderHasTransportFields" class="order-toggle-input">
                <label class="order-switch-field"><input v-model="orderForm.tripNoEnabled" type="checkbox" /><span>车次号</span></label>
                <input v-if="orderForm.tripNoEnabled" v-model.trim="orderForm.tripNo" placeholder="请输入车次号" />
              </div>
              <div v-if="orderHasTransportFields" class="order-toggle-input">
                <label class="order-switch-field"><input v-model="orderForm.sixSheetEnabled" type="checkbox" /><span>六联单号</span></label>
                <input v-if="orderForm.sixSheetEnabled" v-model.trim="orderForm.sixSheetNo" placeholder="请输入六联单号" />
              </div>
            </div>
            </fieldset>

            <div class="detail-tab-head order-detail-head">
              <div class="detail-tab-list">
                <button class="tab-btn" :class="{ active: activeOrderDetailTab === '收费项目' }" type="button" @click="activeOrderDetailTab = '收费项目'">收费项目</button>
                <button class="tab-btn" :class="{ active: activeOrderDetailTab === '订单附件' }" type="button" @click="activeOrderDetailTab = '订单附件'; loadOrderFiles().catch((error) => notify(error.message))">订单附件</button>
              </div>
              <div v-if="orderAttachmentUploadStatus" class="upload-status-pill" :class="`is-${orderAttachmentUploadTone}`" aria-live="polite">
                <span class="upload-status-dot" aria-hidden="true"></span>
                <span>{{ orderAttachmentUploadStatus }}</span>
              </div>
              <div class="modal-detail-actions">
                <div v-if="!orderReadOnlyMode && orderHasTransportFields" class="dispatch-popover-wrap" @click.stop>
                  <button class="ghost-btn" type="button" @click="dispatchMessageOpen = !dispatchMessageOpen"><IconSvg name="sparkles" />生成派车信息</button>
                  <div v-if="dispatchMessageOpen" class="dispatch-popover">
                    <div class="popover-head">
                      <strong>派车信息</strong>
                      <button class="ghost-btn small" type="button" @click="copyDispatchMessage"><IconSvg name="copy" />复制</button>
                    </div>
                    <textarea :value="dispatchMessage" readonly rows="9" />
                  </div>
                </div>
                <div v-if="!orderReadOnlyMode" class="template-load-wrap" @click.stop>
                  <span class="template-load-split">
                    <button class="ghost-btn" type="button" @click="loadLatestOrderTemplate">
                      <IconSvg name="refresh" />载入模板
                    </button>
                    <button class="ghost-btn template-load-arrow" type="button" title="选择模板" aria-label="选择模板" @click="loadFeeTemplateMenuOpen = !loadFeeTemplateMenuOpen">
                      <IconSvg name="chevronDown" />
                    </button>
                  </span>
                  <div v-if="loadFeeTemplateMenuOpen" class="template-load-menu">
                    <button class="template-load-option template-load-last" type="button" @click="loadLatestOrderTemplate">
                      <span class="template-load-row-icon"><IconSvg name="refresh" /></span>
                      <span class="template-load-text">
                        <strong>载入最后一个订单模板</strong>
                        <span>{{ latestOrderTemplateSource ? `${latestOrderTemplateSource.no} · ${latestOrderTemplateSource.date || '-'}` : '暂无可载入订单' }}</span>
                      </span>
                    </button>
                    <div v-for="(item, index) in orderFreightTemplateOptions" :key="item.id" class="template-load-option-row">
                      <button class="template-load-option" type="button" @click="loadSavedFeeTemplate(item)">
                        <span class="template-load-row-index">{{ index + 1 }}</span>
                        <span class="template-load-text">
                          <strong>{{ item.name }}</strong>
                          <span>{{ item.description || '订单运费模板' }}</span>
                        </span>
                        <span class="template-load-date">{{ String(item.updatedAt || item.createdAt || '').slice(0, 10) || '-' }}</span>
                      </button>
                      <button class="icon-btn icon-only" type="button" title="编辑模板" aria-label="编辑模板" @click.stop="editSavedFeeTemplate(item)"><IconSvg name="edit" /></button>
                      <button class="icon-btn icon-only" type="button" title="删除模板" aria-label="删除模板" @click.stop="deleteSavedFeeTemplate(item)"><IconSvg name="trash" /></button>
                    </div>
                    <button class="template-load-option template-load-default" type="button" @click="loadFeeTemplate">
                      <span class="template-load-row-icon"><IconSvg name="sparkles" /></span>
                      <span class="template-load-text">
                        <strong>默认收费项目</strong>
                        <span>按当前运费模板和收费项目自动生成</span>
                      </span>
                    </button>
                    <p v-if="orderFreightTemplateOptions.length === 0" class="template-load-empty">暂无已保存模板</p>
                  </div>
                </div>
                <button v-if="!orderReadOnlyMode && orderHasTransportFields" class="ghost-btn" type="button" @click="openSaveFreightTemplateModal"><IconSvg name="save" />保存运费模板</button>
              </div>
            </div>

            <div v-if="activeOrderDetailTab === '收费项目'" class="fee-table-wrap">
              <table class="data-table compact invoice-fee-table">
                <thead>
                  <tr>
                    <th class="invoice-seq-col">序号</th>
                    <th class="invoice-name-col">项目名称</th>
                    <th class="invoice-category-col">类别</th>
	                    <th class="invoice-qty-col">数量</th>
	                    <th class="invoice-price-col">单价</th>
	                    <th class="invoice-amount-col">金额</th>
	                    <th class="invoice-driver-col">归属</th>
	                    <th class="invoice-cost-col">成本</th>
	                    <th class="invoice-remark-col">备注</th>
	                    <th class="invoice-actions-col">操作</th>
                  </tr>
                </thead>
                <tbody>
                  <tr
                    v-for="(fee, index) in orderFees"
                    :key="orderFeeRowKey(fee, index)"
                    :class="{ 'company-self-pay-row': isCompanySelfPayFee(fee), 'other-expense-cost-row': isOtherExpenseCostFee(fee) }"
                  >
                    <td>{{ index + 1 }}</td>
		                    <td class="invoice-name-cell">
		                      <div class="fee-name-picker">
                            <span class="searchable-select order-fee-name-search" @click.stop>
                              <input
                                :value="orderFeeNamePickerOpenIndex === index ? orderFeeNameSearchKeyword : fee.name"
                                :title="companyCoveredFeeTooltip(fee)"
                                :placeholder="orderFeeNamePickerOpenIndex === index ? '搜索项目名称 / 类别 / 币种' : '请选择项目'"
                                :readonly="orderReadOnlyMode"
                                @focus="openOrderFeeNamePicker(index)"
                                @input="handleOrderFeeNameInput(index, $event)"
                                @keydown="handleOrderFeeNameKeydown(index, $event)"
                              />
                              <div v-if="orderFeeNamePickerOpenIndex === index" class="searchable-select-dropdown order-fee-name-dropdown">
                                <button
                                  v-for="item in orderFeeNameOptions"
                                  :key="item.id"
                                  type="button"
                                  @mousedown.prevent
                                  @click="chooseOrderFeeName(index, item)"
                                >
                                  <strong>{{ item.name }}</strong>
                                  <span>{{ feeItemCategoryLabel(item.category) }} · {{ currencyCodeDisplay(item.currency) }}</span>
                                </button>
                                <p v-if="orderFeeNameOptions.length === 0">暂无匹配的收费项目</p>
                              </div>
                            </span>
		                        <button v-if="!orderReadOnlyMode" class="table-op icon-only" type="button" aria-label="设置收费项目" title="设置收费项目" @click.stop="openFeeItemManager(index)"><IconSvg name="edit" /></button>
                        <button
                          v-if="!orderReadOnlyMode && editingOrderNo && fee.name"
                          class="fee-row-upload"
                          :class="{ 'is-uploading': orderAttachmentUploading }"
                          title="上传此收费项目的单据"
                          type="button"
                          @click="openOrderFeeUploadPanel(fee, index)"
                        >
                          <IconSvg name="paperclip" />
                        </button>
                        <button
                          v-else-if="!orderReadOnlyMode"
                          class="fee-row-upload is-disabled"
                          type="button"
                          title="保存订单并选择收费项目后可上传"
                          @click="notify(!editingOrderNo ? '请先保存订单，再上传收费项目附件' : '请先选择收费项目，再上传附件')"
                        >
                          <IconSvg name="paperclip" />
                        </button>
	                      </div>
                      <div
                        v-if="feeCategoryLabel(fee) === '代垫' || feeAttachmentRows(fee, index).length"
                        class="fee-inline-tools"
                        :class="{ 'has-address': feeCategoryLabel(fee) === '代垫' }"
                      >
                        <input
                          v-if="feeCategoryLabel(fee) === '代垫'"
                          v-model.trim="fee.advanceAddress"
                          class="fee-address-input"
                          type="text"
                          placeholder="输入发生地址"
                          :title="orderFeeAdvanceAddress(fee) || '输入发生地址'"
                          :disabled="orderReadOnlyMode"
                        />
                        <div class="fee-row-attachments">
                          <span
                            v-for="file in feeAttachmentRows(fee, index)"
                            :key="file.id"
                            class="fee-row-file-chip"
                          >
                            <span class="file-chip-name" :title="file.filename">{{ file.filename }}</span>
                            <button type="button" title="预览" @click="openStoredFile(file, 'preview')"><IconSvg name="eye" /></button>
                            <button type="button" title="下载" @click="openStoredFile(file, 'download')"><IconSvg name="download" /></button>
                            <button v-if="!orderReadOnlyMode" type="button" title="删除" @click="deleteFile(file, orderAttachmentRows)"><IconSvg name="trash" /></button>
                          </span>
                        </div>
                      </div>
	                      <input v-model.trim="fee.name" type="hidden" />
	                    </td>
                    <td class="invoice-category-cell">
                      <span
                        class="fee-category-badge"
                        :class="orderFeeBadgeClass(fee)"
                      >{{ orderFeeBadgeLabel(fee) }}</span>
                    </td>
                    <td class="invoice-qty-cell"><input v-model.number="fee.quantity" type="number" min="0" :disabled="orderReadOnlyMode" @input="syncFeeAmountFromQuantityOrUnitPrice(fee)" /></td>
                    <td class="invoice-price-cell"><input v-model.number="fee.unitPrice" type="number" min="0" step="0.01" :disabled="orderReadOnlyMode" @input="markFeeUnitPriceManual(fee); syncFeeAmountFromQuantityOrUnitPrice(fee)" /></td>
	                    <td class="invoice-amount-cell">
	                      <label class="fee-money-input">
	                        <input v-model.number="fee.amount" type="number" min="0" step="0.01" :disabled="orderReadOnlyMode" @input="markFeeAmountManual(fee, $event.target.value)" />
		                        <select v-model="fee.currency" :disabled="orderReadOnlyMode" @change="markFeeCurrencyManual(fee)"><option value=""></option><option value="港币">HKD</option><option value="人民币">RMB</option></select>
	                      </label>
	                    </td>
			                    <td class="invoice-driver-cell">
			                      <div class="fee-assignee-editor" :title="orderFeeAssigneeTitle(fee)">
			                        <input
			                          :value="orderFeeAssigneeInputValue(fee)"
			                          type="text"
			                          placeholder="自动归属"
			                          :disabled="orderReadOnlyMode || isCompanyCoveredFee(fee)"
			                          @input="handleOrderFeeAssigneeInput(fee, $event)"
		                        />
		                        <button
		                          v-if="!orderReadOnlyMode && orderFeeHasManualAssignee(fee) && !isCompanyCoveredFee(fee)"
		                          class="fee-assignee-reset"
		                          type="button"
		                          title="恢复自动归属"
		                          aria-label="恢复自动归属"
		                          @click="resetOrderFeeAssignee(fee)"
			                        >
			                          <IconSvg name="restore" />
			                        </button>
			                      </div>
			                    </td>
                    <td class="invoice-cost-cell">
                      <div
                        v-if="fee._costMultiCurrency && !fee._manualCost"
                        class="invoice-cost-breakdown"
                        :title="orderFeeCostTitle(fee)"
                      >
                        <strong>{{ orderFeeCostBreakdownDisplay(fee) }}</strong>
                      </div>
                      <label v-else class="invoice-cost-money-input">
                        <input
                          class="invoice-cost-input"
                          :value="fee.cost ?? 0"
                          type="number"
                          min="0"
                          step="0.01"
                          :title="orderFeeCostTitle(fee)"
                          :disabled="orderReadOnlyMode"
                          @input="setOrderFeeCost(fee, $event.target.value)"
                        />
                        <select
                          v-model="fee.costCurrency"
                          :disabled="orderReadOnlyMode"
                          :title="orderFeeCostTitle(fee)"
                          @change="setOrderFeeCostCurrency(fee, $event.target.value)"
                        >
                          <option value="港币">HKD</option>
                          <option value="人民币">RMB</option>
                        </select>
                      </label>
                    </td>
		                    <td class="invoice-remark-cell">
                          <input
                            v-model.trim="fee.remark"
                            :disabled="orderReadOnlyMode"
                            :placeholder="companyCoveredFeeDefaultRemark(fee) || '备注'"
                          />
                    </td>
                    <td class="invoice-actions-cell">
                      <span class="op-group">
                        <button
                          v-if="!orderReadOnlyMode"
                          class="table-op icon-only"
                          type="button"
                          aria-label="上移"
                          title="上移"
                          :disabled="index === 0"
                          @click="moveFeeRow(index, -1)"
                        >
                          <IconSvg name="chevronUp" />
                        </button>
                        <button
                          v-if="!orderReadOnlyMode"
                          class="table-op icon-only"
                          type="button"
                          aria-label="下移"
                          title="下移"
                          :disabled="index === orderFees.length - 1"
                          @click="moveFeeRow(index, 1)"
                        >
                          <IconSvg name="chevronDown" />
                        </button>
                        <button v-if="!orderReadOnlyMode && index === orderFees.length - 1" class="table-op icon-only" type="button" aria-label="新增行" @click="addFeeRow"><IconSvg name="plus" /></button>
                        <button v-if="!orderReadOnlyMode && orderFees.length > 1" class="table-op icon-only" type="button" aria-label="删除行" @click="removeFeeRow(index)"><IconSvg name="minus" /></button>
                      </span>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>

            <OrderAttachmentPanel
              v-else
              :order-no="editingOrderNo"
              :files="orderAttachmentRows"
              :uploading="orderAttachmentUploading"
              :accept="FILE_UPLOAD_ACCEPT"
              :format-size="fileSizeText"
              :readonly="orderReadOnlyMode"
              @upload="uploadOrderFile"
              @open-upload="openOrderFileUploadPanel"
              @disabled-upload="notify('请先保存订单，再上传附件')"
              @preview="openStoredFile($event, 'preview')"
              @download="openStoredFile($event, 'download')"
              @delete="deleteFile($event, orderAttachmentRows)"
              @recycle="openAttachmentRecycleBin"
            />

            <div class="order-modal-total">
              <strong>合计</strong>
              <span>港币 {{ Number(orderTotals.hkd || 0).toLocaleString() }} / 人民币 {{ Number(orderTotals.rmb || 0).toLocaleString() }}</span>
            </div>
          </div>

        <template #after>
        <div v-if="locationPicker.open" class="modal-backdrop nested-modal-backdrop" @click.self="closeLocationPicker" @click.stop>
          <section class="modal-card compact-modal address-picker-modal">
            <div class="modal-head">
              <div>
                <p class="eyebrow">{{ locationPicker.mode === 'addressBook' ? '客户联系人' : '运费模板一二三级目录' }}</p>
                <h2>{{ locationPickerTitle }}</h2>
              </div>
              <button type="button" class="icon-btn" @click="closeLocationPicker"><IconSvg name="close" />关闭</button>
            </div>
            <div class="modal-body address-picker-body" :class="{ 'is-address-book': locationPicker.mode === 'addressBook' }">
              <div v-if="locationPicker.mode === 'template'" class="template-location-picker">
                <label>一级目录
                  <select v-model="locationPicker.level1" @change="handleTemplateLocationLevelChange(1)">
                    <option value="">请选择一级目录</option>
                    <option v-for="item in templateLocationLevel1Options" :key="item" :value="item">{{ item }}</option>
                  </select>
                </label>
                <label>二级目录
                  <select v-model="locationPicker.level2" :disabled="!locationPicker.level1 || templateLocationLevel2Options.length === 0" @change="handleTemplateLocationLevelChange(2)">
                    <option value="">请选择二级目录</option>
                    <option v-for="item in templateLocationLevel2Options" :key="item" :value="item">{{ item }}</option>
                  </select>
                </label>
                <label>三级目录
                  <select v-model="locationPicker.level3" :disabled="!locationPicker.level2 || templateLocationLevel3Options.length === 0" @change="handleTemplateLocationLevelChange(3)">
                    <option value="">请选择三级目录</option>
                    <option v-for="item in templateLocationLevel3Options" :key="item" :value="item">{{ item }}</option>
                  </select>
                </label>
                <label class="template-location-detail">详细地址
                  <input v-model.trim="locationPicker.detail" placeholder="可选：楼栋、门牌、仓库名" @keyup.enter="applyTemplateLocationSelection" />
                </label>
                <button class="primary-btn" type="button" @click="applyTemplateLocationSelection">确定</button>
              </div>
              <div v-else class="address-book-manager">
                <div class="address-book-toolbar">
                  <label>搜索地址
                    <input v-model.trim="locationPicker.keyword" placeholder="联系人 / 电话 / 详细地址 / 备注" />
                  </label>
                  <span>已选 {{ selectedAddressBookIds.length }} 项</span>
                  <button class="ghost-btn small" type="button" @click="toggleAllAddressBookSelection(!allVisibleAddressBookSelected)">
                    {{ allVisibleAddressBookSelected ? '取消全选' : '全选' }}
                  </button>
                  <button class="ghost-btn danger small" type="button" @click="deleteSelectedAddressBookEntries"><IconSvg name="trash" />批量删除</button>
                  <button class="primary-btn small" type="button" @click="startNewAddressBookEntry"><IconSvg name="plus" />新建地址</button>
                </div>
                <datalist id="dispatch-location-city-options">
                  <option v-for="city in locationCityOptions" :key="city" :value="city">{{ city }}</option>
                </datalist>
                <div v-if="addressBookFormOpen" class="address-book-form">
                  <label class="address-book-city-field">市<input v-model.trim="addressBookForm.city" list="address-book-city-options" placeholder="选择一级片区" @change="handleAddressBookCityChange" /></label>
                  <label class="address-book-district-field">区
                    <span class="searchable-select address-book-district-search" :class="{ 'is-open': addressBookDistrictPickerOpen, 'is-disabled': !addressBookForm.city }" @click.stop>
                      <input
                        :value="addressBookDistrictPickerOpen ? addressBookDistrictSearch : (addressBookForm.district || '')"
                        type="search"
                        autocomplete="off"
                        :placeholder="addressBookForm.city ? '选择二级片区' : '请先选择市'"
                        :disabled="!addressBookForm.city"
                        @focus="openAddressBookDistrictPicker"
                        @input="handleAddressBookDistrictInput"
                        @blur="closeAddressBookDistrictPicker"
                        @keydown.enter.prevent="confirmFirstAddressBookDistrictOption"
                        @keydown.esc.prevent="closeAddressBookDistrictPicker"
                      />
                      <button
                        type="button"
                        class="customs-business-company-toggle"
                        :disabled="!addressBookForm.city"
                        :title="addressBookDistrictPickerOpen ? '收起区列表' : '展开区列表'"
                        :aria-label="addressBookDistrictPickerOpen ? '收起区列表' : '展开区列表'"
                        @click.stop="toggleAddressBookDistrictPicker"
                      ><IconSvg :name="addressBookDistrictPickerOpen ? 'chevronUp' : 'chevronDown'" /></button>
                      <button
                        v-if="addressBookForm.city && addressBookForm.district"
                        type="button"
                        class="customs-business-company-clear"
                        title="清空区"
                        aria-label="清空区"
                        @click.stop="clearAddressBookDistrict"
                      ><IconSvg name="close" /></button>
                      <div v-if="addressBookDistrictPickerOpen && addressBookForm.city" class="searchable-select-dropdown address-book-district-dropdown">
                        <button
                          v-for="district in addressBookFilteredDistrictOptions"
                          :key="district"
                          type="button"
                          :class="{ active: district === addressBookForm.district }"
                          @mousedown.prevent="selectAddressBookDistrict(district)"
                        >
                          <strong>{{ district }}</strong>
                        </button>
                        <p v-if="addressBookFilteredDistrictOptions.length === 0" @mousedown.prevent="closeAddressBookDistrictPicker">暂无匹配片区</p>
                      </div>
                    </span>
                  </label>
                  <datalist id="address-book-city-options">
                    <option v-for="city in addressBookCityOptions" :key="city" :value="city">{{ city }}</option>
                  </datalist>
                  <label class="address-book-address-field">详细地址<input v-model.trim="addressBookForm.address" placeholder="详细地址" /></label>
                  <label class="address-book-contact-field">联系人<input v-model.trim="addressBookForm.contact" placeholder="联系人" /></label>
                  <label class="address-book-phone-field">电话<input v-model.trim="addressBookForm.phone" placeholder="电话 / 手机" /></label>
                  <label class="address-book-note-field">备注<input v-model.trim="addressBookForm.note" placeholder="楼栋、门牌、仓库名" /></label>
                  <button class="primary-btn address-book-save-btn" type="button" @click="saveAddressBookEntry"><IconSvg name="save" />{{ editingAddressBookId ? '保存修改' : '保存到联系人' }}</button>
                </div>
              </div>
              <div v-if="locationPicker.mode !== 'addressBook'" class="address-picker-current">
                <strong>{{ locationPicker.mode === 'addressBook' ? '客户联系人地址' : '片区来自运费模板目录' }}</strong>
                <span>当前条件：{{ orderForm.direction || "未选进出口" }} / {{ orderForm.tonnage || "未选吨位" }}</span>
                <span>{{ locationPicker.mode === 'addressBook' ? '选择地址会写入装卸货地，联系人和电话会进入订单草稿。' : (templateLocationValue || '请先选择一级目录') }}</span>
              </div>
              <div v-if="locationPicker.mode === 'addressBook'" class="table-wrap address-picker-table-wrap">
                <table class="data-table compact">
                  <thead>
                    <tr>
                      <th>
                        <input
                          type="checkbox"
                          class="table-check"
                          :checked="allVisibleAddressBookSelected"
                          @change="toggleAllAddressBookSelection($event.target.checked)"
                        />
                      </th>
                      <th>市/区</th>
                      <th>详细地址</th>
                      <th>联系人</th>
                      <th>电话</th>
                      <th>备注</th>
                      <th>操作</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="option in addressBookListOptions" :key="option.key" @dblclick="applyAddressBookEntry(option)">
                      <td>
                        <input
                          v-if="option.source === '联系人'"
                          type="checkbox"
                          class="table-check"
                          :checked="selectedAddressBookIds.includes(option.id)"
                          @click.stop
                          @change="toggleAddressBookSelection(option.id, $event.target.checked)"
                        />
                      </td>
                      <td>{{ option.area || '-' }}</td>
                      <td class="address-picker-value">
                        {{ option.address || option.value }}
                      </td>
                      <td>
                        {{ option.contact || '-' }}
                      </td>
                      <td>{{ option.phone || '-' }}</td>
                      <td>{{ option.note || '-' }}</td>
                      <td class="row-actions">
                        <button class="icon-btn icon-only" type="button" title="使用地址" aria-label="使用地址" @click="applyAddressBookEntry(option)"><IconSvg name="check" /></button>
                        <button v-if="option.source === '联系人'" class="icon-btn icon-only" type="button" title="编辑地址" aria-label="编辑地址" @click="editAddressBookEntry(option)"><IconSvg name="edit" /></button>
                        <button v-if="option.source === '联系人'" class="icon-btn icon-only danger" type="button" title="删除地址" aria-label="删除地址" @click="deleteAddressBookEntry(option.id)"><IconSvg name="trash" /></button>
                        <button v-else class="icon-btn icon-only danger" type="button" title="删除历史地址" aria-label="删除历史地址" @click="hideHistoricalAddress(option)"><IconSvg name="trash" /></button>
                      </td>
                    </tr>
                    <tr v-if="addressBookListOptions.length === 0">
                      <td colspan="7">暂无地址，可在上方新建地址。</td>
                    </tr>
                  </tbody>
                </table>
              </div>
              <p class="address-picker-hint">{{ locationPicker.mode === 'addressBook' ? '地址来自当前客户联系人；新建或编辑会同步到该客户的联系人资料。双击或点勾选图标可使用地址。' : '一级选中后会展开二级，二级选中后会展开三级；不需要细分时可只选一级或二级。' }}</p>
            </div>
          </section>
        </div>
        <div v-if="saveFreightTemplateModalOpen" class="modal-backdrop nested-modal-backdrop" @click.self="closeSaveFreightTemplateModal" @click.stop>
          <form class="modal-card compact-modal" @submit.prevent="saveCurrentFeesAsTemplate">
            <div class="modal-head">
              <div>
                <p class="eyebrow">运费模板</p>
                <h2>保存运费模板</h2>
              </div>
              <button type="button" class="icon-btn" @click="closeSaveFreightTemplateModal"><IconSvg name="close" />关闭</button>
            </div>
            <div class="modal-body">
              <div class="form-grid">
                <label class="span-4">模板名称
                  <input v-model.trim="freightTemplateNameForm.name" autofocus placeholder="例如：深圳南山区 3T 人民币" />
                </label>
              </div>
              <p class="muted">保存当前订单的口岸、进出口、吨位、装卸货地和收费项目，后续可按模板名称管理和复用。</p>
            </div>
            <div class="modal-actions">
              <button type="button" class="ghost-btn" @click="closeSaveFreightTemplateModal">取消</button>
              <button class="primary-btn" type="submit"><IconSvg name="save" />保存模板</button>
            </div>
          </form>
        </div>
        </template>
        <template #actionsLeading>
          <button
            v-if="showOrderModalAuditAction"
            type="button"
            class="icon-btn success order-modal-audit-btn"
            :title="orderModalAuditActionTitle"
            :disabled="loading"
            @click="auditOrderFromOrderModal"
          >
            <IconSvg name="check" />审核
          </button>
          <button
            v-if="editingOrderNo && !orderReadOnlyMode && orderHasTransportFields"
            type="button"
            class="ghost-btn order-status-action-btn dispatch-status-exception"
            :disabled="loading || orderStatusActionDisabled('异常滞留')"
            @click="completeOrderFromOrderModal('异常滞留')"
          >
            <IconSvg name="minus" />异常滞留
          </button>
          <button
            v-if="editingOrderNo && !orderReadOnlyMode && orderHasTransportFields"
            type="button"
            class="ghost-btn order-status-action-btn dispatch-status-signed"
            :title="orderSignRequiredMessage || '标记为已签收'"
            :disabled="loading || orderStatusActionDisabled('已签收')"
            @click="completeOrderFromOrderModal('已签收')"
          >
            <IconSvg name="check" />已签收
          </button>
        </template>
      </OrderModal>

      <div v-if="feeItemManagerOpen" class="modal-backdrop nested-modal-backdrop" @click.self="closeFeeItemManager">
        <section class="modal-card compact-modal fee-item-manager-modal">
          <div class="modal-head">
            <div>
              <p class="eyebrow">收费项目</p>
              <h2>收费项目管理</h2>
            </div>
            <div class="modal-detail-actions">
              <button type="button" class="primary-btn small" @click="startNewFeeItem({ silent: true })"><IconSvg name="plus" />新增项目</button>
              <button type="button" class="icon-btn" @click="closeFeeItemManager"><IconSvg name="close" />关闭</button>
            </div>
          </div>
          <div class="modal-body fee-item-manager-body">
            <div class="fee-item-list-toolbar">
              <label class="fee-item-search-field">
                <IconSvg name="search" />
                <input v-model.trim="feeItemSearchKeyword" placeholder="搜索项目名称" />
              </label>
              <button v-if="feeItemSearchKeyword" class="ghost-btn small" type="button" @click="feeItemSearchKeyword = ''"><IconSvg name="close" />清空</button>
              <span class="fee-item-search-count">显示 {{ visibleFeeItemRows.length }} / {{ sortedFeeItemRows.length }} 个</span>
            </div>
            <form v-if="feeItemFormOpen" class="freight-template-toolbar fee-item-toolbar" :class="{ 'is-editing-record': feeItemForm.id }" @submit.prevent="saveFeeItem">
              <label>类别
                <select v-model="feeItemForm.category" @change="handleFeeItemCategoryChange(feeItemForm)">
                  <option v-for="category in FEE_ITEM_CATEGORY_OPTIONS" :key="category">{{ category }}</option>
                </select>
              </label>
              <label class="wide">项目名称<input ref="feeItemNameInput" v-model.trim="feeItemForm.name" placeholder="名称唯一，不可重复" /></label>
              <div class="fee-cost-source-field">
                <span>成本来源</span>
                <details class="fee-cost-source-select" :class="feeItemCostSourceSelectClass(feeItemForm)">
                  <summary>{{ feeItemCostSourceText(feeItemForm) }}</summary>
                  <div class="fee-cost-source-options">
                    <label v-for="source in FEE_ITEM_COST_SOURCE_OPTIONS" :key="source" :class="feeItemCostSourceClass(source)">
                      <input v-model="feeItemForm.costSources" type="checkbox" :value="source" @change="ensureFeeItemCostSources(feeItemForm)" />
                      <span>{{ source }}</span>
                    </label>
                  </div>
                </details>
              </div>
              <label>币种<select v-model="feeItemForm.currency"><option value="港币">HKD</option><option value="人民币">RMB</option></select></label>
              <label>默认金额<input v-model.number="feeItemForm.defaultAmount" type="number" min="0" /></label>
              <label>默认归属<select v-model="feeItemForm.defaultDriverRole"><option v-for="role in FEE_DRIVER_ROLE_OPTIONS" :key="role" :value="role">{{ FEE_DRIVER_ROLE_LABELS[role] }}</option></select></label>
              <button class="primary-btn small"><IconSvg name="save" />保存项目</button>
              <button class="ghost-btn small" type="button" @click="closeFeeItemForm">取消</button>
            </form>
            <div class="table-wrap fee-item-table-wrap modal-fee-item-table-wrap">
              <table class="fee-item-table">
                <thead>
                  <tr>
                    <th>序号</th>
                    <th>排序</th>
	                    <th>类别</th>
	                    <th>项目名称</th>
                      <th>成本来源</th>
		                    <th>币种</th>
		                    <th>默认金额</th>
		                    <th>默认归属</th>
	                    <th>操作</th>
                  </tr>
                </thead>
                <tbody>
                  <tr
                  v-for="(item, index) in visibleFeeItemRows"
                  :key="item.id"
                  title="双击选择收费项目"
                  :draggable="!feeItemSearchActive"
                  :class="{ selected: selectedFeeItem?.id === item.id, 'is-dragging': draggedFeeItemId === item.id }"
                  @dragstart="startFeeItemDrag(item)"
                  @dragover.prevent
                  @drop.prevent="dropFeeItem(item)"
                  @dragend="endFeeItemDrag"
                  @click="selectFeeItem(item)"
                  @dblclick="chooseFeeItemForOrder(item)"
                >
                    <td class="sequence-cell">{{ index + 1 }}</td>
                    <td class="drag-handle-cell">
                      <button class="icon-btn icon-only fee-item-drag-handle" type="button" title="拖动排序" aria-label="拖动排序" @click.stop>
                        <IconSvg name="list" />
                      </button>
                    </td>
                    <td>
                      <select v-if="editingFeeItemRowId === item.id" v-model="feeItemRowDraft.category" class="table-inline-input" @change="handleFeeItemCategoryChange(feeItemRowDraft)">
                        <option v-for="category in FEE_ITEM_CATEGORY_OPTIONS" :key="category">{{ category }}</option>
                      </select>
                      <span v-else :class="['fee-item-category-badge', feeItemCategoryClass(item.category)]">{{ feeItemCategoryLabel(item.category) }}</span>
                    </td>
                    <td>
                      <input v-if="editingFeeItemRowId === item.id" v-model.trim="feeItemRowDraft.name" class="table-inline-input" />
                      <template v-else>{{ item.name }}</template>
                    </td>
                    <td>
                      <details v-if="editingFeeItemRowId === item.id" class="fee-cost-source-select compact" :class="feeItemCostSourceSelectClass(feeItemRowDraft)" @click.stop @dblclick.stop>
                        <summary>{{ feeItemCostSourceText(feeItemRowDraft) }}</summary>
                        <div class="fee-cost-source-options">
                          <label v-for="source in FEE_ITEM_COST_SOURCE_OPTIONS" :key="source" :class="feeItemCostSourceClass(source)">
                            <input v-model="feeItemRowDraft.costSources" type="checkbox" :value="source" @change="ensureFeeItemCostSources(feeItemRowDraft)" />
                            <span>{{ source }}</span>
                          </label>
                        </div>
                      </details>
                      <span v-else class="fee-cost-source-chip-list">
                        <span
                          v-for="source in feeItemCostSourceTokens(item)"
                          :key="source"
                          :class="['fee-cost-source-chip', feeItemCostSourceClass(source)]"
                        >{{ source }}</span>
                      </span>
                    </td>
                    <td>
                      <select v-if="editingFeeItemRowId === item.id" v-model="feeItemRowDraft.currency" class="table-inline-input">
                        <option value="港币">HKD</option>
                        <option value="人民币">RMB</option>
                      </select>
                      <template v-else>{{ currencyCodeDisplay(item.currency) }}</template>
                    </td>
	                    <td>
	                      <input v-if="editingFeeItemRowId === item.id" v-model.number="feeItemRowDraft.defaultAmount" type="number" min="0" class="table-inline-input" />
	                      <template v-else>{{ Number(item.defaultAmount || 0).toLocaleString() }}</template>
	                    </td>
	                    <td>
	                      <select v-if="editingFeeItemRowId === item.id" v-model="feeItemRowDraft.defaultDriverRole" class="table-inline-input">
	                        <option v-for="role in FEE_DRIVER_ROLE_OPTIONS" :key="role" :value="role">{{ FEE_DRIVER_ROLE_LABELS[role] }}</option>
	                      </select>
	                      <template v-else>{{ FEE_DRIVER_ROLE_LABELS[item.defaultDriverRole || ''] }}</template>
	                    </td>
                    <td class="row-actions">
                      <template v-if="editingFeeItemRowId === item.id">
                        <button class="icon-btn icon-only" title="保存" aria-label="保存" @click.stop="saveFeeItemRow(item)"><IconSvg name="save" /></button>
                        <button class="icon-btn icon-only" title="取消" aria-label="取消" @click.stop="cancelFeeItemRowEdit"><IconSvg name="close" /></button>
                      </template>
                      <template v-else>
                        <button class="icon-btn icon-only" title="编辑" aria-label="编辑" @click.stop="startFeeItemRowEdit(item)"><IconSvg name="edit" /></button>
                        <button class="icon-btn icon-only danger" title="删除" aria-label="删除" @click.stop="deleteFeeItem(item)"><IconSvg name="trash" /></button>
                      </template>
                    </td>
                  </tr>
	                  <tr v-if="visibleFeeItemRows.length === 0">
		                    <td colspan="9" class="empty-action-cell">
                      <span>{{ feeItemSearchActive ? '未找到匹配项目' : '暂无收费项目' }}</span>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </section>
      </div>

      <div v-if="expiryReminderModalOpen" class="modal-backdrop">
        <section class="modal-card compact-modal expiry-reminder-modal">
          <div class="modal-head">
            <div>
              <p class="eyebrow">提醒中心</p>
              <h2>证件到期提醒</h2>
            </div>
            <button type="button" class="icon-btn" @click="deferExpiryReminderPopup"><IconSvg name="close" />关闭</button>
          </div>
          <div class="modal-body">
            <p class="expiry-reminder-modal-copy">以下项目首次进入 30 天倒计时或已过期，确认后本账号不再弹出这些提醒。</p>
            <div class="expiry-reminder-modal-list">
              <button
                v-for="row in expiryReminderUnacknowledgedRows"
                :key="row.key"
                type="button"
                :class="['expiry-reminder-modal-row', expiryReminderToneClass(row)]"
                @click="goExpiryReminderTarget(row)"
              >
                <span>
                  <strong>{{ row.entityName }}</strong>
                  <small>{{ row.entityLabel }} · {{ row.itemLabel }}</small>
                </span>
                <span>{{ inputDateLabel(row.expireDate) }}</span>
                <b>{{ expiryReminderStatusLabel(row) }}</b>
              </button>
            </div>
          </div>
          <div class="modal-actions">
            <button type="button" class="ghost-btn" @click="deferExpiryReminderPopup">查看提醒中心</button>
            <button type="button" class="primary-btn" :disabled="expiryReminderAcking" @click="acknowledgeExpiryReminders()">
              <IconSvg name="check" />{{ expiryReminderAcking ? '确认中' : '确认，不再弹出' }}
            </button>
          </div>
        </section>
      </div>

      <div v-if="vehicleModalOpen" class="modal-backdrop">
        <form class="modal-card" @submit.prevent="saveVehicle">
          <div class="modal-head">
            <h2>{{ editingVehiclePlate ? '编辑车辆' : '新增车辆' }}</h2>
            <button type="button" class="icon-btn" @click="vehicleModalOpen = false"><IconSvg name="close" />关闭</button>
          </div>
          <div class="modal-body">
            <div class="form-grid">
              <label>车牌<input v-model.trim="vehicleForm.plate" placeholder="粤Z1234港" /></label>
              <label>车辆品牌<input v-model.trim="vehicleForm.brand" /></label>
              <label>型号<input v-model.trim="vehicleForm.model" /></label>
              <label>车型<select v-model="vehicleForm.type"><option v-for="item in TONNAGE_OPTIONS" :key="item">{{ item }}</option></select></label>
              <label>购车日期<input v-model="vehicleForm.purchaseDate" type="date" /></label>
              <label>出厂日期<input v-model="vehicleForm.factoryDate" type="date" /></label>
              <label>大陆年审日期<input v-model="vehicleForm.mainlandReviewDate" type="date" /></label>
              <label>香港年审日期<input v-model="vehicleForm.hkReviewDate" type="date" /></label>
              <label>大陆保险到期<input v-model="vehicleForm.mainlandInsuranceDate" type="date" /></label>
              <label>香港保险到期<input v-model="vehicleForm.hkInsuranceDate" type="date" /></label>
              <label>保险到期提醒<input v-model.trim="vehicleForm.insuranceReminder" /></label>
              <label class="vehicle-insurance-upload">大陆保险单据
                <span class="vehicle-insurance-row">
                  <button class="file-upload-btn compact" type="button" @click="openVehicleInsuranceUploadPanel('大陆保险单据')"><IconSvg name="paperclip" />上传</button>
                  <span v-for="file in vehicleInsuranceFiles('大陆保险单据')" :key="file.id" class="fee-row-file-chip">
	                    <span class="file-chip-name" :title="file.filename">{{ file.filename }}</span>
                    <button type="button" title="预览" @click="openStoredFile(file, 'preview')"><IconSvg name="eye" /></button>
                    <button type="button" title="删除" @click="deleteFile(file, vehicleFileRows)"><IconSvg name="trash" /></button>
                  </span>
                </span>
              </label>
              <label class="vehicle-insurance-upload">香港保险单据
                <span class="vehicle-insurance-row">
                  <button class="file-upload-btn compact" type="button" @click="openVehicleInsuranceUploadPanel('香港保险单据')"><IconSvg name="paperclip" />上传</button>
                  <span v-for="file in vehicleInsuranceFiles('香港保险单据')" :key="file.id" class="fee-row-file-chip">
	                    <span class="file-chip-name" :title="file.filename">{{ file.filename }}</span>
                    <button type="button" title="预览" @click="openStoredFile(file, 'preview')"><IconSvg name="eye" /></button>
                    <button type="button" title="删除" @click="deleteFile(file, vehicleFileRows)"><IconSvg name="trash" /></button>
                  </span>
                </span>
              </label>
              <label>保养提醒<input v-model.trim="vehicleForm.maintenanceReminder" /></label>
              <label>证件状态<select v-model="vehicleForm.status"><option>正常</option><option>香港保险7天后到期</option><option>证件到期</option><option>费用异常</option></select></label>
              <label>本月费用<input v-model.number="vehicleForm.monthlyCost" type="number" min="0" /></label>
              <label class="span-2">备注<input v-model.trim="vehicleForm.note" /></label>
            </div>
          </div>
          <div class="modal-actions">
            <button type="button" class="ghost-btn" @click="vehicleModalOpen = false">取消</button>
            <button class="primary-btn" :disabled="loading"><IconSvg name="save" />保存车辆</button>
          </div>
        </form>
      </div>

      <div v-if="driverModalOpen" class="modal-backdrop">
        <form class="modal-card compact-modal" @submit.prevent="saveDriver">
          <div class="modal-head">
            <h2>{{ editingDriverId ? '编辑司机' : '新增司机' }}</h2>
            <button type="button" class="icon-btn" @click="driverModalOpen = false"><IconSvg name="close" />关闭</button>
          </div>
          <div class="modal-body">
            <div class="form-grid">
              <label>类型<input v-model.trim="driverForm.type" list="driver-type-options" placeholder="香港司机 / 大陆骑师" /></label>
              <datalist id="driver-type-options">
                <option v-for="type in driverTypeOptions" :key="type" :value="type" />
              </datalist>
              <label>姓名<input v-model.trim="driverForm.name" /></label>
              <label>电话<input v-model.trim="driverForm.phone" /></label>
              <label>身份证号<input v-model.trim="driverForm.idNo" @input="syncDriverBirthdayFromIdNo" /></label>
              <label>驾驶证<input v-model.trim="driverForm.license" /></label>
              <label>生日<input v-model="driverForm.birthday" type="date" /></label>
              <label>入职日期<input v-model="driverForm.hireDate" type="date" /></label>
              <label>离职日期<input v-model="driverForm.leaveDate" type="date" /></label>
              <label>入职状态
                <select v-model="driverForm.employmentStatus">
                  <option v-for="status in DRIVER_EMPLOYMENT_STATUS_OPTIONS" :key="status">{{ status }}</option>
                </select>
              </label>
              <label>证件到期<input v-model="driverForm.expireAt" type="date" /></label>
              <label>状态<select v-model="driverForm.status"><option>正常</option><option>30天内到期</option><option>资料待补</option></select></label>
              <label class="span-2">备注<input v-model.trim="driverForm.note" /></label>
            </div>
          </div>
          <div class="modal-actions">
            <button type="button" class="ghost-btn" @click="driverModalOpen = false">取消</button>
            <button class="primary-btn" :disabled="loading"><IconSvg name="save" />保存司机</button>
          </div>
        </form>
      </div>

      <div v-if="vehicleExpenseModalOpen" class="modal-backdrop" @click.self="closeVehicleExpenseModal">
        <form class="modal-card compact-modal vehicle-expense-modal" @submit.prevent="saveVehicleExpense">
          <div class="modal-head">
            <div>
              <p class="eyebrow">车辆支出</p>
              <h2>{{ editingVehicleExpenseId ? '编辑费用' : activeVehicleExpenseConfig.addLabel }}</h2>
            </div>
            <button type="button" class="icon-btn" @click="closeVehicleExpenseModal"><IconSvg name="close" />关闭</button>
          </div>
              <div class="modal-body">
            <div class="form-grid vehicle-expense-form-grid">
              <label v-if="vehicleExpenseForm.type === 'annual'">费用类型
                <select v-model="vehicleExpenseForm.name" required>
                  <option v-for="name in VEHICLE_ANNUAL_EXPENSE_NAMES" :key="name" :value="name">{{ name }}</option>
                </select>
              </label>
              <label v-else-if="vehicleExpenseForm.type === 'other'">名称
                <input v-model.trim="vehicleExpenseForm.name" placeholder="例如：停车费、过路费" required />
              </label>
              <label v-else>名称
                <input v-model.trim="vehicleExpenseForm.name" readonly />
              </label>
              <label v-if="vehicleExpenseForm.type === 'fuel'">加油升数
                <input v-model.number="vehicleExpenseForm.fuelLiters" type="number" min="0.1" step="0.1" placeholder="例如：68.5" required @input="vehicleExpenseFuelLastEdited = 'liters'; syncVehicleExpenseFuelFields('liters')" />
              </label>
              <label v-if="vehicleExpenseForm.type === 'fuel'">加油费
                <input v-model.number="vehicleExpenseForm.amount" type="number" min="0.1" step="0.1" required @input="vehicleExpenseFuelLastEdited = 'amount'; syncVehicleExpenseFuelFields('amount')" />
              </label>
              <label v-if="vehicleExpenseForm.type === 'fuel'">币种
                <select v-model="vehicleExpenseForm.currency">
                  <option value="人民币">RMB</option>
                  <option value="港币">HKD</option>
                </select>
              </label>
              <label v-if="vehicleExpenseForm.type === 'fuel'">每升单价
                <input v-model.number="vehicleExpenseForm.fuelPricePerLiter" type="number" min="0.1" step="0.1" placeholder="自动计算，也可手动输入" required @input="vehicleExpenseFuelLastEdited = 'price'; syncVehicleExpenseFuelFields('price')" />
              </label>
              <label v-if="vehicleExpenseForm.type === 'fuel'">加油时公里数
                <input v-model.number="vehicleExpenseForm.odometerKm" type="number" min="0.01" step="0.01" placeholder="例如：158320" required />
              </label>
              <label v-if="vehicleExpenseForm.type === 'fuel'">加油站
                <input v-model.trim="vehicleExpenseForm.fuelStation" placeholder="例如：中国石化、壳牌" />
              </label>
              <label>车牌
                <select v-model="vehicleExpenseForm.plate" required>
                  <option value="">请选择车牌</option>
                  <option v-for="vehicle in vehicleRows" :key="vehicle.plate" :value="vehicle.plate">{{ vehicle.plate }} · {{ vehicle.type || '车辆' }}</option>
                </select>
              </label>
              <label v-if="vehicleExpenseForm.type === 'annual'" class="span-2">时间范围
                <div class="vehicle-expense-range-inputs">
                  <input v-model="vehicleExpenseForm.startDate" type="date" required />
                  <span>至</span>
                  <input v-model="vehicleExpenseForm.endDate" type="date" required />
                </div>
              </label>
              <label v-else>时间
                <input v-model="vehicleExpenseForm.date" type="date" required />
              </label>
              <p v-if="vehicleExpenseForm.type === 'annual'" class="span-2 hint vehicle-expense-range-hint">建议按证件实际起止日期填写，到期前 30 天会自动提示。</p>
              <label v-if="vehicleExpenseForm.type !== 'fuel'">币种
                <select v-model="vehicleExpenseForm.currency">
                  <option value="人民币">RMB</option>
                  <option value="港币">HKD</option>
                </select>
              </label>
              <label v-if="vehicleExpenseForm.type !== 'fuel'">费用
                <input v-model.number="vehicleExpenseForm.amount" type="number" min="0.1" step="0.1" required @input="vehicleExpenseFuelLastEdited = 'amount'; syncVehicleExpenseFuelFields('amount')" />
              </label>
              <div class="vehicle-expense-receipt-panel span-2">
                <div class="vehicle-expense-receipt-head">
                  <strong>票据</strong>
                  <button
                    class="fee-row-upload vehicle-expense-receipt-upload"
                    :class="{ 'is-uploading': vehicleExpenseReceiptUploading, 'is-disabled': vehicleExpenseSaving || vehicleRows.length === 0 }"
                    title="上传票据"
                    aria-label="上传票据"
                    type="button"
                    :disabled="vehicleExpenseSaving || vehicleExpenseReceiptUploading || vehicleRows.length === 0"
                    @click="openVehicleExpenseReceiptUploadPanel"
                  >
                    <IconSvg name="paperclip" />
                  </button>
                </div>
                <div v-if="vehicleExpenseReceiptUploadStatus" class="upload-status-pill vehicle-expense-upload-status" :class="`is-${vehicleExpenseReceiptUploadTone}`" aria-live="polite">
                  <span class="upload-status-dot" aria-hidden="true"></span>
                  <span>{{ vehicleExpenseReceiptUploadStatus }}</span>
                </div>
                <p class="hint">优先支持 Excel 和 PDF，也支持图片，可一次选择多张；选择后立即上传。</p>
                <div v-if="vehicleExpenseReceiptRows.length" class="vehicle-expense-receipt-list">
                  <span
                    v-for="file in vehicleExpenseReceiptRows"
                    :key="`uploaded-${file.id}`"
                    class="fee-row-file-chip vehicle-expense-receipt-chip"
                    :title="file.filename"
                  >
                    <span class="vehicle-expense-receipt-name">{{ file.filename }}</span>
                    <button type="button" title="预览" @click="openStoredFile(file, 'preview')"><IconSvg name="eye" /></button>
                    <button type="button" title="下载" @click="openStoredFile(file, 'download')"><IconSvg name="download" /></button>
                    <button type="button" title="删除" @click="deleteFile(file, vehicleExpenseReceiptRows)"><IconSvg name="trash" /></button>
                  </span>
                </div>
                <p v-else class="vehicle-expense-receipt-empty">暂无票据</p>
              </div>
              <label class="span-2">备注
                <input v-model.trim="vehicleExpenseForm.note" placeholder="票据号、供应商或说明" />
              </label>
            </div>
          </div>
          <div class="modal-actions">
            <button type="button" class="ghost-btn" @click="closeVehicleExpenseModal">取消</button>
            <button class="primary-btn" type="submit" :disabled="vehicleExpenseSaving || vehicleExpenseReceiptUploading || vehicleRows.length === 0">
              <IconSvg name="save" />{{ vehicleExpenseSaving ? '保存中' : '保存费用' }}
            </button>
          </div>
        </form>
      </div>

	    <div v-if="recycleModalOpen" class="modal-backdrop">
	      <section class="modal-card compact-modal recycle-modal">
	        <div class="modal-head">
	          <h2>{{ recycleScope === 'all' ? '回收站' : '订单回收站' }}</h2>
	          <button type="button" class="icon-btn" @click="recycleModalOpen = false"><IconSvg name="close" />关闭</button>
          </div>
          <div class="modal-body">
            <div v-if="recycleScope === 'all'" class="recycle-tabs segmented" role="tablist" aria-label="回收站分类">
              <button
                type="button"
                :class="{ active: activeRecycleTab === 'orders' }"
                role="tab"
                :aria-selected="activeRecycleTab === 'orders'"
                @click="setRecycleTab('orders')"
              >订单</button>
              <button
                type="button"
                :class="{ active: activeRecycleTab === 'dispatchPlans' }"
                role="tab"
                :aria-selected="activeRecycleTab === 'dispatchPlans'"
                @click="setRecycleTab('dispatchPlans')"
              >排车单</button>
              <button
                type="button"
                :class="{ active: activeRecycleTab === 'customsBusiness' }"
                role="tab"
                :aria-selected="activeRecycleTab === 'customsBusiness'"
                @click="setRecycleTab('customsBusiness')"
              >报关业务</button>
              <button
                type="button"
                :class="{ active: activeRecycleTab === 'otherBusiness' }"
                role="tab"
                :aria-selected="activeRecycleTab === 'otherBusiness'"
                @click="setRecycleTab('otherBusiness')"
              >其他业务</button>
            </div>

            <div v-if="activeRecycleTab === 'orders'" class="recycle-section">
              <table class="data-table compact">
                <thead>
                  <tr>
                    <th>订单号</th>
                    <th>客户</th>
                    <th>日期</th>
                    <th>状态</th>
                    <th>操作人</th>
                    <th>操作</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="order in recycleRows" :key="order.no">
                    <td>{{ order.no }}</td>
                    <td>{{ order.customerShortName || partnerDisplayLabel(order.customer || '', '客户') || order.customer || '-' }}</td>
                    <td>{{ order.date }}</td>
                    <td>{{ order.status }}</td>
                    <td>{{ order.operatorName || '-' }}</td>
                    <td><button class="icon-btn success" @click="restoreOrder(order)"><IconSvg name="restore" />恢复</button></td>
                  </tr>
                  <tr v-if="recycleRows.length === 0">
                    <td colspan="6">{{ recycleScope === 'all' ? '暂无订单回收站数据' : '暂无回收站数据' }}</td>
                  </tr>
                </tbody>
              </table>
            </div>

            <div v-if="recycleScope === 'all' && activeRecycleTab === 'dispatchPlans'" class="recycle-section">
              <table class="data-table compact">
                <thead>
                  <tr>
                    <th>排车单号</th>
                    <th>订单号</th>
                    <th>客户</th>
                    <th>日期</th>
                    <th>删除时间</th>
                    <th>操作人</th>
                    <th>操作</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="row in dispatchRecycleRows" :key="row.id">
                    <td>{{ row.dispatchNo || '-' }}</td>
                    <td>{{ row.orderNo || '-' }}</td>
                    <td>{{ row.customerShortName || partnerDisplayLabel(row.customer || row.row?.customer || '', '客户') || '-' }}</td>
                    <td>{{ row.date || row.planDate || '-' }}</td>
                    <td>{{ row.deletedAt || '-' }}</td>
                    <td>{{ row.operatorName || '-' }}</td>
                    <td><button class="icon-btn success" type="button" @click="restoreDispatchRecycleRow(row)"><IconSvg name="restore" />恢复</button></td>
                  </tr>
                  <tr v-if="dispatchRecycleRows.length === 0">
                    <td colspan="7">暂无排车单回收站数据</td>
                  </tr>
                </tbody>
              </table>
            </div>

            <div v-if="recycleScope === 'all' && activeRecycleTab === 'customsBusiness'" class="recycle-section">
              <table class="data-table compact">
                <thead>
                  <tr>
                    <th>日期</th>
                    <th>报关单号</th>
                    <th>六联单号</th>
                    <th>客户</th>
                    <th>进出口</th>
                    <th>删除时间</th>
                    <th>操作人</th>
                    <th>操作</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="row in customsBusinessRecycleRows" :key="row.id">
                    <td>{{ row.date }}</td>
                    <td>{{ row.declarationNo }}</td>
                    <td>{{ row.sixSheetNo }}</td>
                    <td>{{ row.customerShortName || partnerDisplayLabel(row.company || '', '客户') || row.company }}</td>
                    <td>{{ row.direction }}</td>
                    <td>{{ row.deletedAt }}</td>
                    <td>{{ row.operatorName || '-' }}</td>
                    <td><button class="icon-btn success" type="button" @click="restoreCustomsBusiness(row)"><IconSvg name="restore" />恢复</button></td>
                  </tr>
                  <tr v-if="customsBusinessRecycleRows.length === 0">
                    <td colspan="8">暂无报关业务回收站数据</td>
                  </tr>
                </tbody>
              </table>
            </div>

            <div v-if="recycleScope === 'all' && activeRecycleTab === 'otherBusiness'" class="recycle-section">
              <table class="data-table compact">
                <thead>
                  <tr>
                    <th>日期</th>
                    <th>标题</th>
                    <th>客户</th>
                    <th>收入合计</th>
                    <th>成本合计</th>
                    <th>利润</th>
                    <th>删除时间</th>
                    <th>操作人</th>
                    <th>操作</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="row in otherBusinessRecycleRows" :key="row.id">
                    <td>{{ row.date }}</td>
                    <td>{{ row.title }}</td>
                          <td>{{ row.customerShortName || partnerDisplayLabel(row.customer || '', '客户') || row.customer }}</td>
                    <td>RMB {{ money(row.totalIncome) }}</td>
                    <td>RMB {{ money(row.totalCost) }}</td>
                    <td><strong>RMB {{ money(row.profit) }}</strong></td>
                    <td>{{ row.deletedAt }}</td>
                    <td>{{ row.operatorName || '-' }}</td>
                    <td><button class="icon-btn success" type="button" @click="restoreOtherBusiness(row)"><IconSvg name="restore" />恢复</button></td>
                  </tr>
                  <tr v-if="otherBusinessRecycleRows.length === 0">
                    <td colspan="9">暂无其他业务回收站数据</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
	      </section>
	    </div>

	    <div v-if="customsBusinessModalOpen" class="modal-backdrop">
	      <form class="modal-card compact-modal customs-business-modal" @click="closeCustomsBusinessCompanyPicker" @submit.prevent="saveCustomsBusiness">
	        <div class="modal-head">
	          <h2>
	            {{ copyingCustomsBusinessId ? '复制报关单' : (editingCustomsBusinessId ? '编辑报关业务' : '新增报关业务') }}
	            <span class="order-title-meta">{{ customsBusinessForm.date }}</span>
	          </h2>
	          <button type="button" class="icon-btn" @click="closeCustomsBusinessModal"><IconSvg name="close" />关闭</button>
	        </div>
	        <div class="form-grid customs-business-form-grid">
	          <label>日期<input v-model="customsBusinessForm.date" type="date" /></label>
	          <label>报关单号<input v-model.trim="customsBusinessForm.declarationNo" /></label>
	          <label>六联单号<input v-model.trim="customsBusinessForm.sixSheetNo" /></label>
	          <label class="span-2 customs-business-company-field">客户
	            <span class="searchable-select customs-business-company-combobox" @click.stop>
	              <IconSvg class="customs-business-company-search-icon" name="search" />
	              <input
	                :value="customsBusinessCompanySearch"
	                class="customs-business-company-input"
	                type="search"
	                placeholder="搜索并选择客户"
	                autocomplete="off"
	                @focus="openCustomsBusinessCompanyPicker"
	                @input="handleCustomsBusinessCompanyInput"
	                @keydown.enter.prevent="confirmFirstCustomsBusinessCompanyOption"
	                @keydown.esc.prevent="closeCustomsBusinessCompanyPicker"
	              />
	              <button
	                v-if="customsBusinessCompanySearch"
	                class="customs-business-company-clear"
	                type="button"
	                title="清空客户"
	                aria-label="清空客户"
	                @click="clearCustomsBusinessCompany"
	              ><IconSvg name="close" /></button>
	              <button
	                class="customs-business-company-toggle"
	                type="button"
	                title="展开客户列表"
	                aria-label="展开客户列表"
	                @click="customsBusinessCompanyPickerOpen ? closeCustomsBusinessCompanyPicker() : openCustomsBusinessCompanyPicker()"
	              ><IconSvg name="chevronDown" /></button>
	              <div v-if="customsBusinessCompanyPickerOpen" class="searchable-select-dropdown customs-business-company-dropdown">
	                <button
	                  v-for="customer in customsBusinessFilteredCustomerOptions"
	                  :key="customer.id"
	                  type="button"
	                  :class="{ active: String(customer.name || '').trim() === customsBusinessForm.company }"
	                  @click="selectCustomsBusinessCompany(customer)"
	                >
	                  <strong>{{ customerOptionPrimaryDisplay(customer) }}</strong>
	                </button>
	                <p v-if="customsBusinessFilteredCustomerOptions.length === 0">{{ customsBusinessCustomerOptions.length ? '暂无匹配客户' : '暂无客户' }}</p>
	              </div>
	            </span>
	          </label>
	          <label>进出口<select v-model="customsBusinessForm.direction"><option value=""></option><option>进口</option><option>出口</option><option>金二进口</option><option>金二出口</option></select></label>
	          <label>品名项数<input v-model.number="customsBusinessForm.itemCount" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'itemCount', $event)" /></label>
	          <label>续页<input v-model.number="customsBusinessForm.pageCount" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'pageCount', $event)" /></label>
	          <label>续页费<input v-model.number="customsBusinessForm.pageFee" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'pageFee', $event)" /></label>
	          <label>报关费<input v-model.number="customsBusinessForm.customsFee" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'customsFee', $event)" /></label>
	          <label>舱单费<input v-model.number="customsBusinessForm.manifestFee" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'manifestFee', $event)" /></label>
	          <label>报检费<input v-model.number="customsBusinessForm.inspectionFee" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'inspectionFee', $event)" /></label>
	          <label>查验费<input v-model.number="customsBusinessForm.checkFee" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'checkFee', $event)" /></label>
	          <label v-if="customsBusinessShowsVerificationFee">核注费<input v-model.number="customsBusinessForm.verificationFee" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'verificationFee', $event)" /></label>
	          <label>法检/3C商检<input v-model.number="customsBusinessForm.fajian3cFee" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'fajian3cFee', $event)" /></label>
	          <label>其他费用<input v-model.number="customsBusinessForm.otherFee" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(customsBusinessForm, 'otherFee', $event)" /></label>
	          <div class="span-4 customs-business-custom-fields">
	            <div class="customs-business-custom-head">
	              <span>自定义类目</span>
	              <button class="ghost-btn small" type="button" @click="addCustomsBusinessCustomField"><IconSvg name="plus" />新增类目</button>
	            </div>
	            <div v-if="customsBusinessForm.customFields.length" class="customs-business-custom-list">
	              <div v-for="(field, index) in customsBusinessForm.customFields" :key="index" class="customs-business-custom-row">
	                <label>类目名称<input v-model.trim="field.name" placeholder="类目名称" /></label>
	                <label>金额<input v-model.number="field.value" type="number" min="0" step="1" inputmode="numeric" @keydown="preventCustomsBusinessDecimalInput" @input="normalizeCustomsBusinessIntegerInput(field, 'value', $event)" /></label>
	                <button class="icon-btn icon-only danger" type="button" title="删除类目" aria-label="删除类目" @click="removeCustomsBusinessCustomField(index)">
	                  <IconSvg name="trash" />
	                </button>
	              </div>
	            </div>
	          </div>
	          <label>合计<input :value="money(customsBusinessFormTotal)" readonly /></label>
	          <label class="span-4">备注<textarea v-model.trim="customsBusinessForm.remark" rows="3" /></label>
	        </div>
	        <div class="modal-actions">
	          <button type="button" class="ghost-btn" @click="closeCustomsBusinessModal">取消</button>
	          <button type="submit" class="primary-btn" :disabled="customsBusinessSaving"><IconSvg name="save" />{{ customsBusinessSaving ? '保存中' : (copyingCustomsBusinessId ? '新增报关单' : (editingCustomsBusinessId ? '保存修改' : '保存报关业务')) }}</button>
	        </div>
	      </form>
	    </div>

